window.SEED_DECKS = [{"id":"d_880_term","name":"880 名词解释","desc":"材料科学基础 · 201 条名词","color":"#4a90d9","cards":[{"id":"t001","front":"空间点阵","back":"将晶体中原子或原子群抽象为几何点在三维空间作周期性规则排列所形成的空间阵列。空间点阵共有14种类型(14种布拉菲点阵),分为七大晶系。每个阵点代表一个或一组原子的等效位置,是描述晶体结构周期性的基本几何模型。空间点阵与晶体结构的区别在于:前者是抽象几何模型,后者是原子在空间的实际排列方式。","tags":["第一章 晶体结构","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t002","front":"晶体结构","back":"晶体中原子(离子或分子)在三维空间的具体排列方式。晶体结构 = 空间点阵 + 基元(每个阵点所代表的原子群)。描述晶体结构的基本参数包括晶格常数(a、b、c)和晶轴夹角(α、β、γ)。典型的金属晶体结构有面心立方(FCC)、体心立方(BCC)和密排六方(HCP)三种。","tags":["第一章 晶体结构"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t003","front":"晶胞","back":"空间点阵中最小的平行六面体重复单元,能充分反映点阵的对称性特征。晶胞的大小和形状由六个参数描述:三个棱边长度a、b、c(晶格常数)和三个棱边间夹角α、β、γ。晶胞在三维空间重复堆砌即可构成整个晶体。晶胞有素晶胞(仅含一个阵点)和复晶胞(含多个阵点)之分。","tags":["第一章 晶体结构","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t004","front":"配位数","back":"晶体中任一原子周围最近邻且等距离的原子数目。配位数是描述晶体结构紧密程度的重要参数。FCC的配位数为12,BCC为8(8个最近邻+6个次近邻,通常取最近邻),HCP为12(c/a=1.633时)。配位数越大,原子排列越紧密,致密度越高。","tags":["第一章 晶体结构","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t005","front":"致密度","back":"晶体中原子(视为刚性球)所占体积与晶胞总体积之比。致密度 = 晶胞内原子总体积 / 晶胞体积。FCC致密度为0.74,BCC为0.68,HCP为0.74(c/a=1.633时)。致密度反映了晶体中原子排列的紧密程度,影响材料的密度、扩散速率和力学性能。BCC中存在较大的八面体间隙,虽然致密度低于FCC,但为小原子(C、N)的扩散提供了通道。","tags":["第一章 晶体结构","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t006","front":"金属键","back":"金属原子间的一种化学结合键。金属原子失去外层价电子形成正离子,这些价电子为全体原子所共有形成\"电子气\",正离子与电子气之间的静电引力即为金属键。金属键无方向性和饱和性,使金属具有良好的导电性、导热性和塑性变形能力。金属键的强度(结合能)决定金属的熔点、弹性模量和热膨胀系数等性能。","tags":["第一章 晶体结构"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t007","front":"固溶体","back":"溶质原子溶入溶剂金属晶格中形成的单相均匀晶体,保持溶剂晶体结构类型。按溶质原子在晶格中的位置分为置换固溶体(溶质原子占据溶剂点阵位置)和间隙固溶体(溶质原子位于晶格间隙位置)。固溶体的性能通常介于组元之间,固溶强化是重要的强化手段。影响溶解度的因素由Hume-Rothery规则描述。","tags":["第一章 晶体结构","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t008","front":"置换固溶体","back":"溶质原子替代溶剂原子占据晶格结点位置而形成的固溶体。形成条件由Hume-Rothery规则决定:(1)原子尺寸差Δr<15%;(2)电负性差小;(3)电子浓度不超过极限值(一价FCC约1.36);(4)晶体结构相同。满足上述条件可形成无限固溶体(如Cu-Ni),否则溶解度有限。置换固溶体的晶格常数因溶质原子尺寸不同而发生变化。","tags":["第一章 晶体结构","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t009","front":"间隙固溶体","back":"小尺寸溶质原子(如C、N、H、B等)溶入溶剂金属晶格的四面体或八面体间隙位置形成的固溶体,保持溶剂晶体结构类型。间隙固溶体的溶解度有限,因为晶格间隙位置数量和尺寸有限。典型例子如C溶入γ-Fe中形成奥氏体(FCC八面体间隙),最大溶解度为2.11%。间隙固溶体的性能特点是显著提高强度和硬度(间隙固溶强化效果远大于置换固溶强化)。","tags":["第一章 晶体结构","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t010","front":"缺位固溶体","back":"在某些化合物(如金属间化合物)中,当其中一种组元的原子从正常点阵位置缺失而形成空位时,这种组成偏离化学计量比的相称为缺位固溶体。例如NiAl化合物中,当Al含量超过50%时,部分Ni位置出现空位以维持晶体结构稳定。缺位固溶体具有特殊的扩散和力学性能。","tags":["第一章 晶体结构"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t011","front":"电子化合物","back":"由电子浓度(价电子数/原子数)决定晶体结构类型的一类中间相。当电子浓度为3/2(21/14)时形成β相(BCC结构);电子浓度为21/13时形成γ相(复杂立方);电子浓度为7/4(21/12)时形成ε相(HCP结构)。典型例子有Cu-Zn系中的β黄铜(CuZn)、γ黄铜(Cu5Zn8)和ε黄铜(CuZn3)。电子化合物的成分可在一定范围内变化,具有金属性。","tags":["第一章 晶体结构"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t012","front":"间隙相(间隙化合物)","back":"过渡族金属元素与C、N、B、H等原子半径较小的非金属元素形成的化合物。当非金属原子半径与金属原子半径之比rx/rm<0.59时形成简单晶体结构的间隙相(如TiC、VC、NbC等,NaCl型结构),具有高熔点、高硬度的特点;当rx/rm>0.59时形成复杂晶体结构的间隙化合物(如Fe3C渗碳体,正交晶系)。间隙相/化合物与间隙固溶体的本质区别在于是否形成不同于溶剂的新晶体结构。","tags":["第一章 晶体结构"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t013","front":"超结构(有序固溶体)","back":"某些在高温下原子呈无序排列的固溶体,当温度降低到某一临界温度以下时,不同种类原子在点阵中呈现则的周期性排列,这种有序化的固溶体称为超结构或有序固溶体。典型例子有Cu3Au(Cu原子占据面心位置、Au原子占据角位置)和CuZn(β黄铜,BCC→CsCl型)。有序化使合金电阻率降低、硬度增高、塑性下降。","tags":["第一章 晶体结构"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t014","front":"拓扑密堆相","back":"由两种大小不同的原子通过适当配合,利用空间充填原理形成的具有极高致密度的中间相。原子排列仅由拓扑学因素(原子尺寸比)决定,配位数可高达14~16。典型例子有Laves相(如MgCu2、MgZn2)、σ相(如FeCr)和Frank-Kasper相。拓扑密堆相通常硬而脆,在高温合金中作为强化相存在,但也可能成为导致脆化的有害相(如不锈钢中的σ相)。","tags":["第一章 晶体结构"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t015","front":"肖脱基空位","back":"晶体内部原子从正常点阵位置迁移至晶体表面,在内部留下空位,这种空位称为肖脱基空位。肖脱基空位的形成不产生间隙原子,空位与表面新增原子配对。在离子晶体中,为保持电中性,正负离子空位成对出现。平衡空位浓度随温度升高呈指数增大:nv/n = A·exp(-Qf/kT),其中Qf为空位形成能。","tags":["第一章 晶体结构","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t016","front":"弗仑克尔空位","back":"晶体内部原子脱离正常点阵位置跃迁至晶格间隙中,同时形成一个空位和一个间隙原子,这种空位-间隙原子对称为弗仑克尔缺陷。弗仑克尔缺陷的形成不改变晶体体积(原子总数不变),但造成局部晶格畸变。在金属中弗仑克尔缺陷形成能高于肖脱基缺陷,因此金属中以肖脱基空位为主。在离子晶体和共价晶体中弗仑克尔缺陷较为常见。","tags":["第一章 晶体结构","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t017","front":"位错密度","back":"单位体积晶体中所含位错线的总长度,或穿过单位面积截面的位错线根数,单位为cm-2。退火态金属位错密度约为106~108 cm-2,强冷变形金属可达1011~1012 cm-2。位错密度是表征晶体中位错数量多少的物理量,与材料的力学性能密切相关--位错密度越高,强度越高(加工硬化),但塑性降低。","tags":["第一章 晶体结构","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t018","front":"刃型位错","back":"晶体中多余半原子面(刃口)终止在晶体内部形成的线缺陷。刃型位错的柏氏矢量b垂直于位错线方向。刃型位错有正负之分:正刃型位错的多余半原子面在滑移面上方,负刃型在下方。刃型位错可以滑移(沿滑移面运动,运动方向∥b)也可以攀移(垂直于滑移面运动,需空位扩散参与)。","tags":["第一章 晶体结构","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t019","front":"螺型位错","back":"晶体中原子面以螺旋阶梯方式排列形成的线缺陷。螺型位错的柏氏矢量b平行于位错线方向。螺型位错无多余半原子面,分为右旋和左旋两种。螺型位错只能滑移不能攀移(无多余半原子面),且可在包含位错线的任意晶面上滑移(交滑移),这是螺型位错的重要特征。","tags":["第一章 晶体结构","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t020","front":"混合位错","back":"晶体中位错线弯曲使不同部分具有不同特征--部分具有刃型特征(b⊥位错线)、部分具有螺型特征(b∥位错线),其余部分具有混合特征(b与位错线夹角介于0°和90°之间)。实际晶体中的位错多以混合位错形式存在,柏氏矢量b可分解为刃型分量be和螺型分量bs两部分。","tags":["第一章 晶体结构"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t021","front":"柏氏矢量","back":"描述位错引起的晶格畸变大小和方向的矢量,用b表示。柏氏矢量通过柏氏回路确定:在完整晶体和含位错晶体中分别作相同的闭合回路,后者不闭合所需的闭合矢量即为柏氏矢量。柏氏矢量具有守恒性--沿位错线不变,是位错的最基本特征量。位错的能量∝|b|2,b越小位错越稳定。单位位错的b为最密排方向上的最短点阵矢量。","tags":["第一章 晶体结构","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t022","front":"位错的滑移","back":"位错沿滑移面(包含位错线和柏氏矢量的平面)的运动。刃型位错滑移方向平行于b,螺型位错滑移方向垂直于b。滑移是位错保守运动--不涉及原子扩散,在切应力作用下即可进行。滑移所需临界分切应力(派-纳力)远小于理论剪切强度。位错滑移至晶体表面即形成滑移台阶,宏观表现为塑性变形。","tags":["第一章 晶体结构"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t023","front":"位错的攀移","back":"刃型位错(及混合位错的刃型分量)垂直于滑移面的运动,需借助空位或间隙原子的扩散来实现。正攀移:多余半原子面缩短(空位扩散至位错线);负攀移:多余半原子面伸长(空位从位错线扩散出去)。攀移是非保守运动,需要热激活,高温下更容易进行。螺型位错无多余半原子面,不能攀移。","tags":["第一章 晶体结构"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t024","front":"弗兰克-瑞德源","back":"一种位错增殖机制。一段两端被钉扎的位错线在切应力作用下弯曲,经历弓出→扩展→绕钉扎点旋转→相遇湮灭的过程,每次循环产生一个位错环并使原线段恢复,从而实现位错不断增殖。F-R源解释了为什么塑性变形中位错密度不降反升--变形使大量F-R源开动,产生大量新位错,导致加工硬化。","tags":["第一章 晶体结构","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t025","front":"派-纳力(Peierls-Nabarro力)","back":"位错在理想晶体中运动时所需克服的最小点阵阻力,是位错滑移的固有阻力。派-纳力τp = [2G/(1-ν)]·exp(-2πd/b),其中d为滑移面间距,b为柏氏矢量大小(滑移方向上的原子间距)。d越大、b越小则τp越小,滑移越容易。因此滑移通常发生在d最大(密排面)、b最小(密排方向)的滑移系上。派-纳力解释了不同晶体结构滑移系的差异。","tags":["第一章 晶体结构"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t026","front":"单位位错(全位错)","back":"柏氏矢量b等于晶体点阵中最短平移矢量(即一个点阵矢量)的位错。b为滑移方向上最近邻原子间距。滑移后原子占据的位置与滑移前完全等效,晶体结构完全恢复。FCC晶体中单位位错的b = a/2<110>,BCC中b = a/2<111>。单位位错滑移后不产生任何面缺陷。","tags":["第一章 晶体结构"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t027","front":"不全位错(部分位错)","back":"柏氏矢量b不等于单位点阵平移矢量(小于最短点阵矢量)的位错。不全位错滑移后在滑移面上留下堆垛层错。FCC中典型不全位错包括肖克莱不全位错(b=a/6<112>,可滑移)和弗兰克不全位错(b=a/3<111>,不可滑移)。不全位错与层错相关联,常出现在FCC低层错能金属的扩展位错中。","tags":["第一章 晶体结构"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t028","front":"堆垛层错","back":"晶体中密排面的正常堆垛顺序出现错排而形成的面缺陷。FCC正常堆垛为ABCABC...,若出现ABAB...或ABCACABC...即为层错。层错破坏了晶体的周期性但不产生晶格畸变(原子间距不变),仅改变次近邻关系。层错能是产生单位面积层错所需能量,影响扩展位错宽度和交滑移难易程度。层错能越低,扩展位错越宽,交滑移越困难。","tags":["第一章 晶体结构","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t029","front":"汤普森四面体","back":"描述FCC晶体中位错反应和扩展位错的几何图形工具。四面体的四个面代表FCC的四个{111}滑移面,六条棱边代表十二个<110>全位错的柏氏矢量方向,各面内从顶点到对面中点的连线代表肖克莱不全位错的柏氏矢量方向。汤普森四面体为分析FCC中位错分解、扩展位错和位错反应提供了直观的参照系。","tags":["第一章 晶体结构"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t030","front":"位错反应","back":"两个或多个位错相遇时柏氏矢量重新组合的过程。位错反应必须满足两个条件:(1)几何条件--反应前后柏氏矢量矢量和相等(∑b前=∑b后);(2)能量条件--反应后位错总能量降低(∑|b|2减小)。位错反应是形成Lomer-Cottrell锁(面角位错)、扩展位错等复杂位错组态的基本机制。","tags":["第一章 晶体结构","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t031","front":"扩展位错","back":"FCC晶体中一个全位错分解为两个肖克莱不全位错,中间夹一层堆垛层错的组态。如a/2[110]→a/6[211]+a/6[121]。两个不全位错间的斥力与层错能平衡决定了扩展位错宽度d。层错能越低,d越大。扩展位错需先束集成全位错才能交滑移,因此层错能低的金属交滑移困难,加工硬化率高。","tags":["第一章 晶体结构","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t032","front":"对称倾侧晶界","back":"由一系列等间距排列的同号刃型位错垂直排列构成的晶界。晶界两侧晶粒绕位错线轴相对转动θ角,位错间距D=b/[2sin(θ/2)]≈b/θ。θ<10°时为小角度晶界。对称倾侧晶界是最简单的小角度晶界模型,直观展示了晶界可用位错模型描述的基本思想。","tags":["第一章 晶体结构"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t033","front":"重合位置点阵","back":"两晶粒点阵相互穿插时,部分阵点位置重合形成的新周期性点阵。重合位置密度用Σ值表示:Σ=重合位置点阵单胞体积/原晶粒点阵单胞体积。Σ值越小,重合位置越多,晶界结构越有序,界面能越低。Σ=3的孪晶界即为典型的低能重合位置点阵晶界。","tags":["第一章 晶体结构"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t034","front":"共格界面","back":"两相界面两侧原子排列完全匹配、晶面一一对应的界面。共格界面两侧晶面间距可能略有差异,通过弹性应变维持共格关系。完全共格需两相晶体结构和晶格常数非常接近。共格界面的界面能最低。沉淀析出初期小尺寸析出相往往与基体保持共格关系,随析出相长大共格关系破坏。","tags":["第一章 晶体结构","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t035","front":"失配度","back":"描述两相晶格常数差异程度的参数,δ = |a1-a2|/a1(或Δa/a)。失配度是决定两相间形成何种界面的关键因素:δ<0.05时倾向于形成共格界面,δ=0.05~0.25时形成半共格界面(通过界面位错调节失配),δ>0.25时形成非共格界面。失配度越大,界面能越高,弹性应变能越大。","tags":["第一章 晶体结构","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t036","front":"非共格界面","back":"两相界面处原子排列完全不匹配,不存在一一对应关系的界面。非共格界面的原子结构类似于大角度晶界,界面能最高(约500~1000 mJ/m2)。非共格界面上原子键合较差、缺陷较多,往往是扩散的快速通道和优先形核位置。大尺寸析出相或第二相颗粒与基体之间常形成非共格界面。","tags":["第一章 晶体结构"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t037","front":"内吸附","back":"溶质原子或杂质原子在晶界、相界等晶体缺陷处富集(偏聚)的现象。驱动力是溶质原子在缺陷处的畸变能低于晶内完整区域。晶界偏聚的平衡浓度由公式Cg/C0=exp(ΔE/kT)描述,ΔE为偏聚能。内吸附对材料性能影响显著:晶界处P、S、Sb等杂质偏聚导致回火脆性;晶界处B的偏聚则改善高温合金晶界强度。","tags":["第一章 晶体结构"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t038","front":"表面能","back":"产生单位面积新表面所需做的可逆功,单位为J/m2。表面原子配位数低于内部,处于高能非平衡状态。表面能来源于表面原子的不饱和键(悬挂键)。金属表面能通常在1~3 J/m2范围。表面能影响晶体平衡外形(Wulff定理--低能面优先暴露)、吸附、催化活性和纳米材料的稳定性。表面是扩散快速通道,其扩散系数远大于体扩散。","tags":["第一章 晶体结构"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t039","front":"界面能","back":"晶体中两相之间(或同一相两晶粒之间)单位面积界面上的超额自由能,单位为J/m2。界面能来源于界面处原子排列不规则导致的键合不饱和和应变能。各类界面能大小顺序:共格界面 < 半共格界面 < 非共格界面 < 大角度晶界。界面能是形核(增加界面能)、晶粒长大(减小界面能)和相变过程的重要热力学参数。","tags":["第一章 晶体结构"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t040","front":"晶界能","back":"晶界处原子排列不规则、偏离平衡位置而具有的额外能量，等于形成单位面积新晶界所需的能量（界面能的一种）。来源：①晶界原子偏离正常点阵位置产生的畸变能；②晶界处键合被扭曲。晶界能随相邻晶粒取向差增大而升高，大角度晶界能趋于稳定值（约为表面能的1/3）。影响：晶界能是晶粒长大（减小总晶界面积）、第二相在晶界析出、晶界偏聚、腐蚀（沿晶界）等过程的驱动力。2024真题名词原题。","tags":["第一章 晶体结构","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t041","front":"凝固","back":"物质从液态转变为固态的过程。广义上包括结晶(液态→晶态固体)和玻璃化转变(液态→非晶态固体)。金属和合金的凝固通常是指结晶过程。凝固是材料制备(铸造、焊接、快速凝固等)的核心环节,凝固组织对材料的后续加工和使用性能有决定性影响。","tags":["第二章 凝固与结晶"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t042","front":"结晶","back":"液态金属(或合金)中原子从无规则排列转变为周期性规则排列(晶体)的过程。结晶需满足热力学条件--过冷度>0(ΔG<0),且经历形核和长大两个基本阶段。结晶与凝固在金属学科中常混用,严格而言结晶强调形成晶体的有序结构,凝固涵盖更广(包括非晶)。","tags":["第二章 凝固与结晶"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t043","front":"过冷","back":"液态金属冷却到理论结晶温度Tm以下仍不结晶的现象。过冷是结晶的必要条件--只有在过冷条件下,固相自由能低于液相自由能(ΔGv<0),结晶才能自发进行。过冷度(ΔT)越大,相变驱动力越大,形核越容易(临界晶核半径减小),但原子扩散能力降低,两者矛盾影响形核率。","tags":["第二章 凝固与结晶","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t044","front":"过冷度","back":"理论结晶温度Tm与实际结晶温度T之差:ΔT = Tm - T。过冷度是结晶的驱动力--ΔT越大,液-固两相自由能差|ΔGv|越大,临界晶核半径r*越小,临界形核功ΔG*越低。但ΔT过大时原子扩散能力下降,反而不利于形核。形核率N随过冷度先增后减,存在最佳过冷度区间。","tags":["第二章 凝固与结晶","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t045","front":"结构起伏(相起伏)","back":"液态金属中原子短程有序排列在大小和位置上随时间不断波动的现象。结构起伏是液态金属的固有特征,为结晶形核提供了必要的结构条件。在过冷液相中,大于临界晶核半径r*的结构起伏可成为稳定的晶核并继续长大。结构起伏的统计分布由Boltzmann因子exp(-ΔG/kT)决定。","tags":["第二章 凝固与结晶"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t046","front":"能量起伏","back":"系统中微观区域能量偏离统计平均值而瞬时波动的现象。能量起伏与结构起伏共同作用,使某些原子团可能克服形核能垒形成晶核。在非均匀形核中,现成表面(模壁、杂质颗粒等)降低了形核功ΔG*(降低因子S(θ):完全润湿θ=0时S(θ)=0;完全不润湿θ=180°时S(θ)=1),能量起伏的作用相对减小。","tags":["第二章 凝固与结晶","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t047","front":"均匀形核","back":"在均匀液相中完全依靠液体自身的结构起伏和能量起伏形成晶核的过程。均匀形核的临界形核功ΔG* ∝ 1/ΔT2,需要极大过冷度(约0.2Tm)才能实现可观测的形核率。实际生产中由于熔体中不可避免地存在外来质点和模壁等现成表面,均匀形核极少发生,金属结晶几乎全部为非均匀形核。","tags":["第二章 凝固与结晶","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t048","front":"非均匀形核","back":"晶核依附于液相中现成表面(模壁、杂质颗粒、未熔质点等)形成的形核方式。非均匀形核的临界形核功ΔG*不均匀 = ΔG*均匀 × S(θ),S(θ)为形状因子。当润湿角θ=0°时ΔG*不均匀=0(不需要形核功);θ=180°时ΔG*不均匀=ΔG*均匀。θ越小形核越容易。实际生产中通过添加孕育剂(变质处理)创造有利的非均匀形核条件以细化晶粒。","tags":["第二章 凝固与结晶","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t049","front":"临界晶核半径","back":"在给定过冷度下,能够稳定存在并继续长大的最小晶核半径,用r*表示。r* = 2σ/ΔGv,其中σ为比表面能,ΔGv为单位体积液固两相自由能差。当晶胚半径r < r*时,长大使系统自由能升高→晶胚消溶;r > r*时,长大使自由能降低→晶核稳定长大。过冷度越大,ΔGv越大,r*越小--越容易形核。","tags":["第二章 凝固与结晶","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t050","front":"临界晶核形核功","back":"形成临界晶核所需的最大附加能量(能量起伏),用ΔG*表示。ΔG* = 16πσ3/(3ΔGv2) ∝ 1/ΔT2。ΔG*对应于r=r*时ΔG曲线的极大值--晶胚越过此能垒后即能自发长大。非均匀形核的ΔG* = ΔG*均匀 × S(θ)(S(θ)<1),通过降低形核功促进形核。","tags":["第二章 凝固与结晶","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t051","front":"形核率","back":"单位体积液相中单位时间内形成的晶核数目,用N表示,单位为cm-3·s-1。N ∝ exp(-ΔG*/kT) × exp(-Qd/kT),其中第一个因子代表获得能量起伏的概率(随ΔT增大而增大),第二个因子代表原子扩散能力(随ΔT增大而减小)。两者矛盾使N-ΔT曲线呈C形--存在最大形核率对应的最佳过冷度。","tags":["第二章 凝固与结晶","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t052","front":"生长线速度","back":"晶体在垂直于固-液界面方向上单位时间内长大的距离,单位为cm/s。生长线速度取决于界面微观结构(光滑/粗糙)、过冷度和扩散能力。粗糙界面以连续长大方式生长,线速度大(∝ΔT);光滑界面需二维形核或以螺型位错台阶长大,线速度较小。生长线速度与形核率共同决定最终晶粒大小和形态。","tags":["第二章 凝固与结晶"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t053","front":"光滑界面","back":"在原子尺度上固-液界面是平滑的,原子附着优先在台阶或扭折位置进行的界面。光滑界面是生长速度较慢的界面类型。其生长机制需借助二维形核或螺型位错提供的永不消失台阶。典型的小平面生长材料(如Si、Ge、金属间化合物)具有光滑界面。光滑界面生长易形成规则外形的晶体或树枝晶。","tags":["第二章 凝固与结晶"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t054","front":"粗糙界面","back":"在原子尺度上固-液界面是粗糙的(约有50%的原子位置被占据),液相原子几乎可以在界面任何位置附着的界面。粗糙界面以连续长大(均匀附着)方式生长,生长速度快(正比于过冷度)。大多数金属的固-液界面为粗糙界面,结晶时形成非小平面(非规则外形)的晶粒形态。","tags":["第二章 凝固与结晶"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t055","front":"动态过冷度","back":"晶体长大过程中为使生长界面以一定速度推进所需的过冷度,即界面温度低于Tm的值。动态过冷度是晶体长大的驱动力。粗糙界面的动态过冷度很小(约0.01~0.05°C),生长速度快;光滑界面的动态过冷度大,生长速度慢。动态过冷度与晶体长大机制密切相关。","tags":["第二章 凝固与结晶"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t056","front":"柱状晶","back":"沿特定方向(通常垂直于模壁向内)择优生长形成的细长柱状晶粒。柱状晶在铸锭中位于表面细晶区以内、中心等轴晶区以外。柱状晶的生长方向平行于最大温度梯度方向(热流方向),晶体学上沿择优生长方向(FCC为<100>方向)。柱状晶使铸件产生各向异性,严重时形成穿晶组织降低性能,通常希望通过控制浇注条件促进等轴晶形成来抑制柱状晶过度生长。","tags":["第二章 凝固与结晶"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t057","front":"等轴晶","back":"各方向尺寸大致相等的粒状晶粒。等轴晶通常通过非均匀形核在铸锭中心区域形成(成分过冷使界面前沿大量形核)。等轴晶组织各向同性,力学性能均匀,是铸造中通常希望获得的组织形态。细化等轴晶的方法包括:降低浇注温度、增加过冷度、变质处理(添加孕育剂)、振动搅拌、快速凝固等。","tags":["第二章 凝固与结晶"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t058","front":"树枝状晶","back":"晶体沿特定晶体学方向择优生长形成树枝状形态的晶体。一次枝晶臂沿最大温度梯度方向生长,二次和三次枝晶臂在一次臂上垂直生长。树枝晶是铸造组织中最常见的晶体形态,根本原因是成分过冷使平面界面失稳。树枝晶的枝晶间距(一次间距λ1、二次间距λ2)是重要微观结构参数--λ2越小,力学性能越好。","tags":["第二章 凝固与结晶"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t059","front":"单晶","back":"整个固体材料由一块晶体组成,内部不存在晶界。单晶具有各向异性的特点--不同晶体学方向上的物理、力学性能显著不同(如弹性模量、屈服强度、导电性等)。制备方法包括Czochralski法(直拉法)和Bridgman法。单晶硅是大规模集成电路的基础材料,单晶高温合金涡轮叶片(定向凝固)消除了横向晶界,大幅提高耐高温性能。","tags":["第二章 凝固与结晶"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t060","front":"非晶态","back":"原子排列不具长程有序性的固态(原子排列类似液态但宏观上为固体)。非晶态合金(金属玻璃)通过极快速冷却(>106 K/s)抑制结晶而获得。非晶态无晶界、位错等缺陷,具有优异的强度(接近理论强度)、硬度、耐腐蚀性和软磁性能。非晶态在热力学上为亚稳态,加热到一定温度(晶化温度)会转变为晶态。","tags":["第二章 凝固与结晶"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t061","front":"微晶","back":"晶粒尺寸在微米级(通常<10μm)甚至纳米级(<100nm)的多晶体。微晶材料因晶粒极细,晶界体积分数大,表现出不同于粗晶材料的特殊性能--高强度和硬度(Hall-Petch效应显著)、良好的塑性(纳米晶可能出现反常的室温超塑性)。微晶可通过快速凝固、大变形+再结晶、机械合金化等途径制备。","tags":["第二章 凝固与结晶"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t062","front":"准晶","back":"具有长程有序(在衍射谱中呈尖锐布拉格峰)但不具平移周期性(不允许用单胞在空间重复填充)的固态。准晶具有传统晶体学不允许的五次、八次、十次和十二次旋转对称性。1984年Shechtman在急冷Al-Mn合金中首次发现准晶(获2011年诺贝尔化学奖)。准晶具有高硬度、低摩擦系数、低热导率等特殊性能,可用作表面涂层和不粘锅等。","tags":["第二章 凝固与结晶"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t063","front":"包晶反应（包晶转变）","back":"凝固过程中一定成分的液相与已结晶的固相在恒温下反应，生成另一个新固相的多相转变。铁碳相图中的包晶反应：L(0.53%C)+δ(0.09%C)→γ(0.17%C)，温度1495℃。特点：包晶反应需原子在固相中长程扩散，速度慢，常反应不完全形成包晶偏析（成分不均）。","tags":["第二章 凝固与结晶"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t064","front":"离异共晶","back":"共晶合金或近共晶成分合金凝固时，共晶体中两相分开生长、不形成规则共晶组织的现象。表现为其中一个相单独附着在先共晶相上生长，另一相则存在于晶界，共晶体的正常两相混合形态消失。常见于共晶量很少的合金（如钢中Fe3C呈网状分布于晶界）。原因：先共晶相表面为共晶第二相提供了优先生长位置。","tags":["第二章 凝固与结晶"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t065","front":"滞弹性","back":"材料在弹性范围内加载或卸载时应变滞后于应力的现象。滞弹性表现为应力-应变曲线形成一个闭合回线(滞后环),回线面积代表一个循环中消耗的能量(内耗)。滞弹性源于应力作用下点缺陷重新分布、间隙原子在应力场中的有序化、晶界滑动等弛豫过程。低碳钢的明显屈服现象(Cottrell气团)的物理本质即与滞弹性弛豫有关。","tags":["第三章 塑性变形"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t066","front":"滑移","back":"晶体的一部分相对于另一部分沿特定晶面(滑移面)和晶向(滑移方向)的平移滑动,是金属塑性变形的最主要方式。滑移面通常是密排面,滑移方向是密排方向。一组滑移面和该面上的一个滑移方向构成一个滑移系。FCC有12个{111}<110>滑移系,BCC有12~48个,HCP仅3~6个。滑移使大量位错运动至晶体表面形成宏观可见的滑移线(带)。","tags":["第三章 塑性变形","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t067","front":"孪生","back":"晶体在切应力作用下,一部分沿特定晶面(孪生面)和晶向(孪生方向)发生均匀切变,变形部分与未变形部分以孪生面为镜面对称的变形方式。孪生与滑移的本质区别:(1)孪生每次原子移动小于一个原子间距(非整数倍柏氏矢量),变形均匀;(2)孪生直接变形量小,但可改变晶体取向使不利滑移系变为有利取向,间接促进进一步滑移;(3)孪生通常发生在滑移困难时(HCP金属、低温BCC金属)。","tags":["第三章 塑性变形","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t068","front":"滑移带","back":"大量位错在平行滑移面上运动后在晶体表面形成的可见台阶。单个位错滑移至表面产生的台阶高度为一个柏氏矢量(约0.1nm量级),肉眼不可见。成百上千个位错在同一滑移面上滑移后累积形成滑移线(高度约10~100nm);多个平行滑移面上的滑移线聚集形成滑移带(间距约1~10μm)。滑移带是塑性变形的微观证据。","tags":["第三章 塑性变形"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t069","front":"加工硬化(形变强化)","back":"金属在塑性变形过程中流变应力(强度、硬度)随变形量增加而不断增大的现象。微观机制:变形使位错大量增殖(F-R源开动),位错密度从106~108 cm-2增至1011~1012 cm-2,位错间产生交割、缠结、塞积等交互作用,使位错运动阻力增大。加工硬化使进一步变形所需应力增大,是冷加工成形(拉拔、冲压、冷轧等)的工艺基础,同时也是重要的强化手段。","tags":["第三章 塑性变形"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t070","front":"形变织构","back":"多晶体在塑性变形过程中各晶粒的取向沿外力方向发生择优转动,使原本随机取向的晶粒趋于某一或某些特定取向的取向分布状态。形变织构使多晶体产生各向异性。主要类型:(1)丝织构--拉拔或挤压变形时各晶粒的特定晶向平行于轴线排列(FCC为<111>+<100>);(2)板织构--轧制时特定晶面和晶向平行于板面和轧向。织构对深冲性能(如制耳效应)影响显著。","tags":["第三章 塑性变形","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t071","front":"微观残余应力(第二类残余应力)","back":"在单个晶粒或几个晶粒范围内平衡的内应力,是变形后各晶粒或晶粒内部变形不均匀所致。微观残余应力来源于:(1)各晶粒取向不同导致的变形不均匀;(2)晶界阻碍位错运动造成的应力集中;(3)位错塞积群前端的高应力。微观残余应力是加工硬化的重要来源之一,在回复阶段可通过位错重排(多边形化)部分消除。","tags":["第三章 塑性变形"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t072","front":"宏观残余应力(第一类残余应力)","back":"在材料整体范围内(宏观尺度)自相平衡的内应力。来源包括:不均匀塑性变形(如喷丸、表面滚压使表面产生压应力)、不均匀热胀冷缩(如淬火热应力)、不均匀相变(如马氏体相变体积膨胀)。宏观残余应力对材料使用性能有重大影响:表面残余压应力提高疲劳强度,残余拉应力则促进应力腐蚀和疲劳裂纹扩展。","tags":["第三章 塑性变形"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t073","front":"割阶","back":"两个相交滑移面上的位错交割时,在位错线上产生一段长度等于另一滑移面间距的短段,当该短段位于原滑移面外时称为割阶。割阶的存在增加了位错运动的阻力(阻碍滑移),是加工硬化的微观机制之一。割阶可以是刃型或螺型特征,取决于交割位错的相对取向。","tags":["第三章 塑性变形"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t074","front":"扭折","back":"晶体在受到平行于滑移面的压应力(或垂直于滑移面的拉应力)时,滑移不能进行,局部区域发生晶格旋转而形成的一种不均匀塑性变形方式。扭折带是局部取向变化区域,位错在其中重排形成亚晶界。扭折常出现在HCP金属(滑移系少)和层状结构材料中,如Zn单晶受压时产生扭折带。","tags":["第三章 塑性变形"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t075","front":"交滑移","back":"螺型位错从原滑移面转移到另一个与之相交的滑移面上继续滑移的过程。因为螺型位错线平行于b,b与位错线都在交叉滑移面的交线上,所以任何包含位错线的面都可能是螺型位错的滑移面。交滑移对FCC金属的加工硬化行为影响显著--层错能越高,扩展位错宽度越小→越容易束集→交滑移越容易→加工硬化率越低。","tags":["第三章 塑性变形","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t076","front":"多滑移","back":"两个或多个滑移系同时在晶体中开动的现象。多滑移需要外加应力方向使多个滑移系的临界分切应力同时达到τc。多滑移导致不同滑移面上的位错交割、缠结和割阶形成,使加工硬化速率远高于单滑移阶段(第II阶段硬化率最高)。多滑移是理解单晶体加工硬化三阶段曲线的关键。","tags":["第三章 塑性变形"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t077","front":"取向因子(Schmid因子)","back":"描述外加应力方向相对于滑移系取向关系的参数:cosφ·cosλ,其中φ为滑移面法线与外力轴的夹角,λ为滑移方向与外力轴的夹角。滑移面上的分切应力τ=σ·cosφ·cosλ(Schmid定律),当τ达到临界分切应力τc时滑移开动。取向因子最大值为0.5(φ=λ=45°时),此时屈服应力最小。取向因子决定了多晶体各晶粒屈服顺序和变形不均匀性。","tags":["第三章 塑性变形"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t078","front":"脆性断裂","back":"断裂前几乎不发生明显宏观塑性变形(延伸率<2~5%)的断裂方式。脆性断裂的裂纹扩展速率极快(接近声速),断裂面垂直于最大正应力方向,断口呈光亮晶粒状(沿晶脆断)或河流花样(穿晶解理脆断)。BCC和HCP金属在低温、高应变速率下易发生脆性断裂。脆性断裂的微观机制主要为解理断裂--沿特定解理面(BCC为{100}面)的穿晶断裂。","tags":["第三章 塑性变形"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t079","front":"韧性断裂","back":"断裂前发生显著宏观塑性变形的断裂方式。韧性断裂过程:微孔在夹杂物或第二相颗粒处形核→微孔长大→微孔聚合(缩颈)→最终断裂。断口呈暗灰色纤维状,微观上为韧窝特征。韧性断裂是工程构件的主要断裂方式,断裂过程中吸收大量能量。材料的韧脆转变受温度、应变速率和应力状态(三轴应力)影响。","tags":["第三章 塑性变形"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t080","front":"解理","back":"晶体在正应力作用下沿特定低指数晶面(解理面)发生的穿晶脆性断裂。BCC金属的解理面为{100}面,HCP为{0001}基面。解理断裂的特征微观形貌为河流花样--解理裂纹跨越螺型位错时形成的台阶汇流图案。FCC金属一般不发生解理断裂(层错和位错运动协调性好,应力集中难以积累到解理所需的临界水平)。","tags":["第三章 塑性变形"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t081","front":"断裂韧性","back":"材料抵抗裂纹失稳扩展能力的力学性能指标,用平面应变断裂韧性KIC表示,单位为MPa·m1/2。KIC越大,含裂纹构件在给定应力下允许存在的临界裂纹尺寸越大--即材料越不容易发生脆性断裂。KIC是材料-裂纹几何-加载条件共同决定的参数,综合反映材料的强度和塑性。Griffith理论给出σf = √(2Eγ/πa),奠定了断裂力学的基础。","tags":["第三章 塑性变形"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t082","front":"纤维组织","back":"金属经冷塑性变形后，原等轴晶粒沿变形方向被拉长形成的组织。变形量很大时，晶界模糊难以分辨，呈纤维状条纹，称为纤维组织。变形夹杂物和第二相也被拉长形成流线（加工流线）。性能影响：纤维组织使材料沿纤维方向（变形方向）强度、塑性和韧性高于垂直方向，产生各向异性。用沿流线方向取样可提高零件承载能力（如曲轴）。","tags":["第三章 塑性变形"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t083","front":"回复","back":"冷变形金属在较低温度加热时,在光学显微组织发生可见变化之前,通过点缺陷消除和位错重排使部分性能(电阻率、内应力)恢复的过程。回复阶段位错密度基本不变,强度、硬度变化不大。主要变化:空位和间隙原子大量消除→电阻率显著下降;位错发生多边形化(攀移+滑移形成位错墙→亚晶)→内应力大部分消除。回复动力学特征为初始速率快、随后减慢。","tags":["第四章 回复再结晶","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t084","front":"再结晶","back":"冷变形金属加热到一定温度以上时,通过形核和长大形成新的无畸变等轴晶粒、完全取代冷变形组织的过程。驱动力为冷变形储存能(约占总变形能的1%~10%)。再结晶后位错密度从1011~1012 cm-2急剧降至106~108 cm-2,强度、硬度显著降低,塑性恢复至变形前水平。再结晶温度Tr≈(0.35~0.40)Tm(K),Tr受变形量、原始晶粒尺寸、退火温度和杂质元素等因素影响。","tags":["第四章 回复再结晶","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t085","front":"多边化","back":"回复后期位错通过攀移和滑移重排,由变形态的缠结网络重新排列为垂直于滑移面的低位错墙,形成亚晶界,将变形晶粒分割为多个取向略有差异的亚晶的过程。多边化是回复阶段最重要的组织变化--位错密度不显著降低但位错组态由高能缠结向低能的多边形亚晶转变,使弹性应变能降低,为后续再结晶提供形核位置。","tags":["第四章 回复再结晶","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t086","front":"二次再结晶(异常晶粒长大)","back":"再结晶完成后若继续加热,少数晶粒因晶界迁移率优势而急剧吞并周围正常晶粒异常长大的现象。二次再结晶不同于正常晶粒长大(均匀长大),其特征为:少数晶粒快速长大(可达mm甚至cm级),晶粒尺寸分布极不均匀,组织中出现异常的粗大晶粒。二次再结晶严重恶化材料力学性能(粗晶脆性),热处理中应避免。产生原因与第二相粒子的钉扎作用减弱(高温溶解或粗化)、织构和表面效应有关。","tags":["第四章 回复再结晶"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t087","front":"弓出形核","back":"再结晶的一种形核机制。当晶界两侧位错密度差异较大时,高位错密度一侧的亚晶界向低位错密度一侧弓出生长,形成由低位错密度区包围的再结晶核心。弓出形核通常发生在变形量较小(位错密度分布不均匀)的金属中,是再结晶形核的主要方式之一。弓出的驱动力是晶界两侧位错密度差引起的应变能差。","tags":["第四章 回复再结晶"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t088","front":"亚晶合并形核","back":"再结晶的一种形核机制。相邻亚晶通过亚晶界上位错的攀移和滑移使亚晶界消失,两个或多个亚晶合并为一个较大的亚晶。当合并后的亚晶尺寸超过临界晶核半径且与大角度晶界相邻时,该亚晶可通过大角度晶界的快速迁移长大成为再结晶晶核。亚晶合并形核多发生在变形量较大(位错分布较均匀)的金属中。","tags":["第四章 回复再结晶"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t089","front":"动态回复","back":"在热加工(变形温度高于再结晶温度)过程中同时发生的回复过程。变形产生位错增殖,同时螺型位错通过交滑移、刃型位错通过攀移发生重排和部分对消,位错密度达到动态平衡。动态回复导致流变曲线出现稳态流变(应力不再随应变增加),组织特征为含有亚晶的变形晶粒(动态多边形化)。高层错能金属(如Al、α-Fe)热加工时主要发生动态回复。","tags":["第四章 回复再结晶"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t090","front":"流线","back":"热加工(锻造、轧制、挤压等)过程中,铸锭中的夹杂物、第二相颗粒和枝晶偏析区域沿变形方向被拉长而形成的纤维状组织。流线在宏观酸浸后可肉眼观察到。流线使材料力学性能(强度、塑性、冲击韧性)沿流线方向和垂直于流线方向产生显著各向异性--沿流线方向性能最好。设计锻件时应使最大受力方向平行于流线方向。","tags":["第四章 回复再结晶"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t091","front":"带状组织","back":"热加工后钢材中出现的铁素体与珠光体沿变形方向交替排列的层状组织。带状组织的成因:钢液凝固时产生的枝晶偏析(Mn、P等元素在枝晶间偏聚)在热轧时沿变形方向延伸,冷却时先共析铁素体优先在贫Mn(贫合金元素)区域析出,珠光体在富Mn区域形成,形成黑白交替的带状。带状组织使钢材横向塑性和韧性降低,可通过扩散退火(均匀化)减轻。","tags":["第四章 回复再结晶"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t092","front":"再结晶激活能","back":"再结晶过程中原子跃迁所需克服的能垒,用Qt表示,单位为kJ/mol。Qt可通过不同温度下的再结晶完成时间t与温度T之间的Arrhenius关系(1/t∝exp(-Qt/RT))测定。再结晶激活能的大小反映了再结晶进行的难易程度,与自扩散激活能接近(说明再结晶由原子扩散控制),受溶质原子、第二相粒子和变形量等因素影响。","tags":["第四章 回复再结晶"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t093","front":"超塑性","back":"材料在特定条件下(合适的温度、极低的应变速率和细晶组织)表现出极大的延伸率(可达数百%~数千%)而不发生颈缩和断裂的现象。超塑性的条件:(1)温度>0.5Tm;(2)应变速率<10-3 s-1;(3)晶粒尺寸细小(<10μm)且稳定。超塑性变形的微观机制主要为晶界滑移+扩散蠕变协调(伴随晶粒旋转)。利用超塑性可一次成形复杂形状构件(如航空零部件),降低加工成本。","tags":["第四章 回复再结晶"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t094","front":"应变速率敏感系数","back":"描述材料流变应力对应变速率依赖程度的参数:m = d(lnσ)/d(lnε̇)。m值是表征超塑性的关键参数--m值越大,变形越均匀,颈缩越不容易发生(m>0.3时即呈现超塑性)。一般金属m<0.2(室温),超塑性状态下m可达0.5~0.8。m值高的材料在局部颈缩区域因应变速率增大→流变应力显著提高→变形转移至其他区域→变形均匀。","tags":["第四章 回复再结晶"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t095","front":"临界变形度","back":"再结晶后晶粒尺寸与冷变形量关系曲线中,使再结晶晶粒尺寸达到最大的特定小变形量(通常约2%~10%)。在该变形量下,变形储能不足以产生大量均匀形核,仅少数位置满足形核条件→形核率极低→最终晶粒极粗大。临界变形度在热处理工艺中必须避免!消除临界变形度粗晶的方法是增大变形量(例如大于15%~20%),确保再结晶后获得细晶组织。","tags":["第四章 回复再结晶","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t096","front":"动态再结晶","back":"热加工（高于再结晶温度的变形）过程中，与变形同时发生或在变形间隔内发生的再结晶。与静态再结晶的区别在于它发生在变形当中，材料同时受加工硬化和再结晶软化的交替作用，应力-应变曲线呈稳态流变。发生条件：层错能低、扩散慢的金属（如铜、奥氏体钢）在较高温度、较低应变速率下易发生动态再结晶；层错能高的金属（铝、铁素体钢）热变形时以动态回复为主。组织特征：晶粒细小等轴、位错密度保持在中等水平（约10^8~10^9/cm^2）。2023真题名词原题。","tags":["第四章 回复再结晶","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t097","front":"扩散流量","back":"单位时间内通过垂直于扩散方向单位截面积的扩散物质总量(原子数或质量),用J表示,单位为原子数/(m2·s)或kg/(m2·s)。扩散流量是描述扩散快慢的标量(一维扩散)或矢量(三维扩散),由Fick第一定律和Fick第二定律描述。扩散流量是理解渗碳、渗氮、脱碳、氧化、烧结等材料高温过程的基础物理量。","tags":["第五章 扩散"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t098","front":"扩散通量","back":"与扩散流量含义相同,均指单位时间通过单位面积的扩散物质量,用J表示。在三维情况下扩散通量为矢量,方向沿浓度梯度负方向(Fick第一定律:J = -D·dC/dx)。扩散通量的大小取决于扩散系数D和浓度梯度dC/dx(稳态扩散),或由Fick第二定律的非稳态解描述。","tags":["第五章 扩散"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t099","front":"恒稳态扩散(稳态扩散)","back":"系统中各点浓度不随时间变化的扩散状态,即∂C/∂t = 0。稳态扩散条件下通过任意截面的扩散通量J为常数,由Fick第一定律描述:J = -D·dC/dx。薄壁渗碳管、扩散氢渗透膜等工程问题在长时间运行后可近似视为稳态扩散。稳态扩散问题的求解最简单--只需确定浓度分布C(x)后代入Fick第一定律即可。","tags":["第五章 扩散"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t100","front":"非恒稳态扩散(非稳态扩散)","back":"系统中各点浓度随时间变化的扩散状态,即∂C/∂t ≠ 0。非稳态扩散由Fick第二定律描述:∂C/∂t = D·∂2C/∂x2(D为常数时)。三种典型初始/边界条件下的解析解:(1)半无限长恒定表面浓度扩散(误差函数解C=Cs·erfc[x/(2√Dt)])--渗碳过程;(2)薄膜源扩散(高斯解)--示踪原子实验;(3)扩散偶(Boltzmann-Matano法)。非稳态扩散是实际热处理扩散问题的普遍状态。","tags":["第五章 扩散"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t101","front":"扩散激活能","back":"原子从一个平衡位置跃迁至相邻平衡位置所需克服的最小能垒,用Q表示,单位为kJ/mol或eV。扩散系数与温度满足Arrhenius关系:D = D0·exp(-Q/RT)。Q可通过测定不同温度下的D值,以lnD对1/T作图(直线斜率=-Q/R)求得。间隙扩散的Q较小(仅需克服点阵膨胀能,如C在γ-Fe中Q≈142kJ/mol),置换扩散(空位机制)的Q较大(需空位形成能+跃迁能)。扩散激活能是理解扩散微观机制的核心参数。","tags":["第五章 扩散","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t102","front":"全渗层深度","back":"化学热处理(如渗碳)中,从工件表面到心部原始成分处(浓度与基体相同)的总距离。全渗层深度 = 渗层深度(有效渗层深度)+ 过渡层深度。在渗碳工艺中,全渗层深度由Fick第二定律的误差函数解估算:x ≈ √(Dt),在一定温度和气氛条件下由扩散系数D和保温时间t决定。全渗层深度与有效渗层深度(通常以含碳量0.40%处为界)的概念不同。","tags":["第五章 扩散"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t103","front":"定浓度渗层深度(有效渗层深度)","back":"化学热处理中,从工件表面到某一规定浓度(如渗碳层的含碳量0.40%处)的距离。用误差函数解计算:C(x,t)=Cs·erfc[x/(2√Dt)],给定C(x,t)值可反求x。在渗碳工艺中,有效渗层深度=表面至含碳量0.40%(或某约定值)的垂直距离。它是衡量渗碳效果和制定渗碳工艺的关键参数,取决于温度、时间、碳势和钢种。","tags":["第五章 扩散"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t104","front":"上坡扩散","back":"溶质原子从低浓度区向高浓度区扩散的反常扩散现象。上坡扩散的根本原因:扩散的驱动力不是浓度梯度而是化学位梯度(∂μ/∂x)。当化学位梯度与浓度梯度方向相反时即发生上坡扩散。典型例子:(1)Spinodal分解(浓度起伏放大);(2)弹性应力梯度引起的扩散(大原子向拉应力区偏聚、小原子向压应力区偏聚);(3)晶界偏聚(溶质原子在晶界的化学位低于晶内);(4)电场/温度梯度作用下的扩散。","tags":["第五章 扩散","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t105","front":"短路扩散","back":"原子沿晶体缺陷(晶界、位错、自由表面)的扩散,因这些缺陷通道的扩散激活能远低于体扩散(晶格扩散),扩散速度快2~4个数量级以上,故称“短路扩散”。三种短路扩散通道的扩散系数排序:D表面 > D晶界 > D位错 > D体。温度越低,短路扩散的相对贡献越大(体扩散与短路扩散的Q不同)。细晶材料、薄膜材料和低温下短路扩散的重要性尤为突出。","tags":["第五章 扩散","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t106","front":"反应扩散","back":"扩散过程中伴随有新相生成的扩散。当扩散组元超过固溶体溶解度极限时,在界面上形成化合物(中间相)层。反应扩散的特点是扩散层中浓度分布不连续--每个相区对应一定的浓度范围,相界面处浓度跃变。典型例子:(1)钢的渗碳在表面形成Fe3C层(碳超出γ-Fe溶解度时);(2)钢的渗氮形成ε-Fe2-3N和γ'-Fe4N等化合物层;(3)金属氧化--氧化层生长(同时涉及离子扩散+电子传导+界面反应)。","tags":["第五章 扩散","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t107","front":"α-Fe","back":"铁在912°C以下的BCC同素异构体。α-Fe的晶格常数为0.286nm,配位数8,致密度0.68。α-Fe的八面体间隙虽比γ-Fe大(数量少但单个尺寸大),但间隙分布不利于碳原子的进入--碳在α-Fe中的最大溶解度仅0.0218%(727°C时),室温下仅约0.0008%。α-Fe在770°C以下具有铁磁性(Curie点)。α-Fe中固溶少量碳或其它元素即为铁素体。","tags":["第六章 固态相变"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t108","front":"铁素体(F或α)","back":"碳溶入α-Fe(BCC)中形成的间隙固溶体。铁素体的含碳量极低(最大0.0218%),力学性能接近纯铁--强度低(σb≈250MPa)、硬度低(≈80HB)、塑性好(δ≈50%)。铁素体在室温下稳定存在,是亚共析钢室温平衡组织的主要组成相之一。铁素体为体心立方结构,低温下具有铁磁性。","tags":["第六章 固态相变"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t109","front":"γ-Fe","back":"铁在912~1394°C之间的FCC同素异构体。γ-Fe的晶格常数为0.357nm(高温下),配位数12,致密度0.74。γ-Fe的八面体间隙虽比α-Fe小(数量多但单个尺寸小),但其FCC结构中的八面体间隙为正八面体对称,适合碳原子进入--碳在γ-Fe中的最大溶解度达2.11%(1148°C)。γ-Fe无铁磁性。γ-Fe中固溶碳即为奥氏体--钢热处理的核心相。","tags":["第六章 固态相变"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t110","front":"奥氏体(A或γ)","back":"碳溶入γ-Fe(FCC)中形成的间隙固溶体。奥氏体的最大溶碳量为2.11%(1148°C),具有FCC结构,塑性好(易塑性变形),无铁磁性。奥氏体是钢在高温下存在的相,是大多数热处理工艺的起始相--加热至奥氏体区后通过不同冷却方式获得不同组织(珠光体、贝氏体、马氏体等),从而实现组织调控。奥氏体化温度是热处理的核心工艺参数。","tags":["第六章 固态相变"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t111","front":"渗碳体(Fe3C)","back":"铁与碳形成的间隙化合物,含碳量6.69%,正交晶系复杂晶体结构。Fe3C硬度极高(≈800HV)、极脆(延伸率≈0%),是铁碳合金中最主要的强化相。Fe3C在热力学上为亚稳相--在高温长时间保温可分解为铁和石墨(Fe3C→3Fe+C)。Fe3C在珠光体中呈层片状(与铁素体交替排列),在回火索氏体中呈细小粒状(回火时间充分时球化)。","tags":["第六章 固态相变"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t112","front":"石墨","back":"碳的稳定态同素异构体,六方层状结构。在铁碳合金中石墨是稳定相(与渗碳体相比)。灰铸铁中碳以石墨片状存在--石墨尖端为应力集中源→灰铸铁抗拉强度低,但石墨良好的润滑性和吸振性使其广泛用于机床床身、发动机缸体等。球墨铸铁(石墨球化处理)大幅提高了强度和塑性,是重要的工程结构材料。","tags":["第六章 固态相变"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t113","front":"一次渗碳体","back":"从液相中直接结晶析出的渗碳体,形态为粗大板条状。在Fe-Fe3C相图中,过共晶白口铸铁(C>4.3%)从液相冷却时,先在液相中结晶出一次渗碳体,剩余液相在1148°C发生共晶转变形成莱氏体。一次渗碳体粗大而脆,使材料极脆,无直接使用价值--白口铸铁通常作为炼钢原料或经退火获得可锻铸铁。","tags":["第六章 固态相变"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t114","front":"二次渗碳体","back":"从奥氏体中析出的渗碳体(沿奥氏体晶界网状析出)。过共析钢(0.77%~2.11%C)从奥氏体区缓冷时,沿Acm线析出先共析二次渗碳体(网状)。网状二次渗碳体沿晶界分布使晶界脆化→材料冲击韧性严重下降。消除网状二次渗碳体的方法:正火(空冷加快冷却速度→抑制网状析出→得细片状珠光体+少量半连续渗碳体)或球化退火(使渗碳体球化成粒状)。","tags":["第六章 固态相变"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t115","front":"三次渗碳体","back":"从铁素体中析出的微量渗碳体。铁素体中碳的溶解度随温度降低而减小(从727°C的0.0218%降至室温约0.0008%),过剩碳以三次渗碳体形式沿铁素体晶界或晶内位错线析出。三次渗碳体量极少,对力学性能影响通常可忽略,但在深冲用低碳薄板钢中三次渗碳体沿晶界的析出会导致时效脆化。","tags":["第六章 固态相变"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t116","front":"珠光体(P)","back":"铁素体(α)与渗碳体(Fe3C)的机械混合物,是含碳量0.77%的奥氏体在727°C发生共析转变(γ→α+Fe3C)的产物。典型形态为铁素体与渗碳体层片状交替排列(层状珠光体)。珠光体片间距取决于过冷度--过冷度越大片间距越小,按粗细分为珠光体(>0.4μm)、索氏体(0.2~0.4μm)、屈氏体(<0.2μm)。珠光体强度较高(≈800MPa),综合力学性能介于铁素体和渗碳体之间。","tags":["第六章 固态相变"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t117","front":"莱氏体(Ld)","back":"含碳量4.3%的铁碳合金在1148°C发生共晶转变(L→γ+Fe3C)的产物,是奥氏体与渗碳体的机械混合物。室温莱氏体(变态莱氏体Ld')中的奥氏体已转变为珠光体。莱氏体组织中含有大量连续分布的渗碳体→极硬极脆→白口铸铁的特征组织。白口铸铁因韧性极差不能用于承受冲击的构件,但在耐磨件中有应用。","tags":["第六章 固态相变"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t118","front":"变态莱氏体(Ld')","back":"莱氏体中共晶奥氏体在冷却过程中转变为珠光体后的室温组织--珠光体+渗碳体的混合物。变态莱氏体保留了莱氏体的原始共晶形貌(渗碳体连续基体+分布于其中的珠光体岛)。变态莱氏体是白口铸铁的室温组织特征--组织中含有大量渗碳体,硬度极高,脆性极大。","tags":["第六章 固态相变"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t119","front":"工业纯铁","back":"含碳量低于0.0218%的铁碳合金。室温组织为铁素体+少量三次渗碳体。工业纯铁具有高磁导率、高塑性、低强度,主要用于电磁材料(继电器、电磁铁芯等),在机械结构中很少用作承载件。工业纯铁也是理解铁碳相图中单相铁素体区(α区)的典型材料。","tags":["第六章 固态相变"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t120","front":"亚共析钢","back":"含碳量为0.0218%~0.77%的钢。室温平衡组织为先共析铁素体+珠光体。随含碳量增加,珠光体比例增大(从0%到100%),强度硬度升高。典型代表:20钢(C≈0.2%,渗碳用)、45钢(C≈0.45%,调质用)、65Mn(C≈0.65%,弹簧用)。亚共析钢淬火加热温度=Ac3+30~50°C(完全奥氏体化后淬火,避免铁素体软点)。","tags":["第六章 固态相变"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t121","front":"共析钢","back":"含碳量为0.77%的钢。室温平衡组织为100%珠光体(层片状)。共析钢含碳量恰好等于共析点,奥氏体在727°C全部转变为珠光体,无先共析相。共析钢热处理后硬度高但韧性较差,典型应用为钢轨、高强钢丝等耐磨件。T8钢(含碳约0.8%)为接近共析成分的碳素工具钢。共析钢淬火加热温度=Ac1+30~50°C。","tags":["第六章 固态相变"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t122","front":"过共析钢","back":"含碳量为0.77%~2.11%的钢。室温平衡组织为先共析二次渗碳体(网状)+珠光体。随含碳量增加,网状二次渗碳体增多,脆性显著增大。过共析钢主要用于工模具(高硬度、高耐磨性要求),典型代表:T10钢(C≈1.0%)、T12钢(C≈1.2%)、GCr15轴承钢。过共析钢淬火加热温度=Ac1+30~50°C(不完全淬火--保留粒状渗碳体提高耐磨性)。","tags":["第六章 固态相变"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t123","front":"白口铸铁","back":"含碳量为2.11%~6.69%的铁碳合金,凝固时发生共晶转变,碳主要以渗碳体形式存在,断口呈银白色。白口铸铁硬度极高(>450HB),脆性极大,切削加工困难,不能用于承受冲击的构件。主要用途:耐磨件(如磨球、衬板)、可锻铸铁的坯料(经石墨化退火使渗碳体分解为团絮状石墨→得到可锻铸铁)。","tags":["第六章 固态相变"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t124","front":"灰口铸铁","back":"含碳量为2.5%~4.0%的铁碳合金,适当控制成分和冷却速度使碳主要以片状石墨存在,断口呈灰色。灰口铸铁的基体组织可为铁素体、珠光体或铁素体+珠光体。石墨片的存在使其具有优良的铸造性、减振性、耐磨性和切削加工性,但抗拉强度和塑性低。广泛用于发动机缸体、机床床身、泵壳等。通过变质处理可得球墨铸铁(球状石墨),综合力学性能大幅提升。","tags":["第六章 固态相变"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t125","front":"宏观偏析","back":"在铸锭(或大铸件)宏观范围内的化学成分不均匀性,可通过宏观化学分析或酸浸低倍检验检测。宏观偏析包括正常偏析(正偏析)、反常偏析(反偏析)和比重偏析。宏观偏析使铸件性能不均匀,严重恶化力学性能和耐腐蚀性。通过控制浇注条件、电磁搅拌、随后的扩散退火(均匀化退火)等措施可减轻。","tags":["第六章 固态相变"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t126","front":"正常偏析(正偏析)","back":"凝固过程中,由于先凝固的固相溶质含量低于液相(分配系数k0<1时),溶质被推至界面前沿液相中,随凝固进行后凝固部分的溶质浓度越来越高,形成从表面向中心逐渐升高的浓度分布。正偏析产生的原因是溶质分配系数k0≠1。正偏析可通过扩散退火(高温长时间保温使溶质均匀化扩散)有效减轻。","tags":["第六章 固态相变"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t127","front":"反常偏析(反偏析)","back":"铸锭表面溶质浓度反而高于内部的异常偏析现象。反偏析的产生原因:(1)凝固收缩在表面和枝晶间产生负压,将富溶质母液从内部沿枝晶通道吸至表面;(2)凝固过程中表面产生裂纹,富溶质液体渗出填充。反偏析常见于锡青铜等凝固温度范围宽的合金中。反偏析难以用均匀化退火消除,需从铸造工艺参数控制入手。","tags":["第六章 固态相变"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t128","front":"比重偏析","back":"由于初生相与剩余液相之间存在密度差,初生相在重力作用下上浮或下沉形成的宏观成分不均匀。如过共晶铸铁中石墨上浮(密度小)、铅青铜中铅下沉(密度大)。防止措施:加快冷却速度(减小上浮/下沉时间)、搅动、加入变质剂改变初生相形态。比重偏析在凝固后期形成,一旦产生无法通过后续处理消除。","tags":["第六章 固态相变"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t129","front":"显微偏析","back":"在晶粒或枝晶尺度范围内的化学成分不均匀性,需借助显微镜和微区成分分析(如EPMA电子探针)才能检测。显微偏析包括胞状偏析、枝晶偏析和晶界偏析。显微偏析产生的原因是不平衡凝固--固相中扩散不充分导致晶粒内部成分不均匀。显微偏析可通过扩散退火(均匀化)在固相中通过短程扩散有效消除。","tags":["第六章 固态相变"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t130","front":"胞状偏析","back":"胞状组织(胞状晶)的胞壁与胞内部之间的成分差异。胞状凝固时胞壁处溶质浓度高于胞内部(或低于,取决于k0)。胞状偏析的尺度为胞尺寸(μm级),通过扩散退火可有效消除。胞状偏析是枝晶偏析的特殊形态(无二次枝晶臂时),与成分过冷引起的界面失稳密切相关。","tags":["第六章 固态相变"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t131","front":"枝晶偏析(晶内偏析)","back":"单个枝晶内部化学成分的不均匀性--先凝固的枝晶轴部溶质含量低,后凝固的枝晶间区域溶质含量高。枝晶偏析是凝固过程中固相扩散不充分(非平衡凝固)导致的。典型例子:钢锭中Mn、P、S在枝晶间偏聚。枝晶偏析可通过后续扩散退火(均匀化退火--高温长时间加热使溶质在固相中短程扩散)有效消除。枝晶偏析是带状组织的起源。","tags":["第六章 固态相变"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t132","front":"晶界偏析","back":"溶质原子或杂质元素在晶界处的富集(偏聚)。晶界偏析分为平衡偏析和非平衡偏析两种。平衡偏析由晶界处溶质化学位低于晶内驱动--温度越高偏析程度越小。晶界偏析对材料性能影响极大:(1)回火脆性--P、Sb、Sn等杂质在晶界偏聚降低晶界结合力;(2)晶间腐蚀--不锈钢中Cr23C6沿晶界析出使晶界附近贫Cr;(3)硼在晶界的偏聚则可提高高温合金的晶界强度。","tags":["第六章 固态相变"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t133","front":"上贝氏体","back":"过冷奥氏体在贝氏体转变区上部（约550~350℃）形成的组织，由大致平行排列的过饱和铁素体板条与条间断续分布的粗大碳化物（渗碳体）组成，光学显微镜下呈羽毛状。形成温度较高，碳扩散距离长，碳化物在铁素体条间析出。力学性能：碳化物粗大且分布于条间，易造成条间脆性裂纹，强度和韧性都较差，工程上应避免。与下贝氏体（针状、碳化物细小弥散、强韧兼备）相对。","tags":["第六章 固态相变","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t134","front":"伪共析（伪共析组织）","back":"非共析成分的钢以较快速度冷却（过冷度较大）进入共析转变区时，先共析相来不及析出（或析出量不足），过冷奥氏体在共析成分转变区间全部转变为珠光体型组织的现象。所得组织称为伪共析组织。如亚共析钢（0.4%C）正火冷速较快时先共析铁素体减少，珠光体量超过按杠杆定律计算的平衡值。冷速越大、过冷度越大，伪共析区越宽，组织越细（索氏体化）。","tags":["第六章 固态相变"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t135","front":"索氏体（S）","back":"细片状珠光体，片间距约0.2~0.4μm，过冷度大于形成普通珠光体时的共析转变产物。索氏体比珠光体更细密，强度硬度高于珠光体（约25~35HRC），塑性韧性也较好。索氏体可通过正火（空冷）或铅浴等温淬火获得，常用于高强钢丝、弹簧等。崔忠圻书中将索氏体、屈氏体、珠光体统称为珠光体型组织，三者仅为片间距不同。","tags":["崔忠圻补充"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t136","front":"屈氏体（T）","back":"极细片状珠光体，片间距<0.2μm，在较大过冷度下的共析转变产物。硬度约35~45HRC，强度高但塑性较索氏体低。屈氏体通常在油冷或较大过冷度等温淬火时获得。在光学显微镜下因极细而呈黑色团状，无法分辨层片结构，需借助电子显微镜分辨。","tags":["崔忠圻补充"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t137","front":"回火马氏体","back":"淬火马氏体在低温回火（≤200℃）时的分解产物。马氏体中过饱和碳以ε碳化物（Fe₂.₄C）形式析出，马氏体正方度降低但仍保留板条或片状形态。回火马氏体的硬度较淬火态略有降低，但内应力部分消除、韧性提高。高碳钢低温回火后获得回火马氏体组织，用于要求高硬度高耐磨性的工模具。","tags":["崔忠圻补充"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t138","front":"回火屈氏体","back":"淬火钢在中温回火（300~500℃）时获得的组织——铁素体基体上分布极细粒状渗碳体。ε碳化物已转变为稳定的Fe₃C渗碳体，马氏体正方度完全消失。回火屈氏体具有高的弹性极限和良好的强韧性配合，广泛用于弹簧钢（如65Mn、60Si2Mn）的热处理。","tags":["崔忠圻补充"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t139","front":"回火索氏体","back":"淬火钢在高温回火（500~650℃）时获得的组织——铁素体基体（已再结晶为等轴晶粒）上均匀分布细小粒状渗碳体。与回火屈氏体相比，渗碳体颗粒已明显球化和长大。回火索氏体具有良好的综合力学性能，是调质处理的目标组织，广泛用于承受交变载荷的结构件（轴类、连杆、齿轮等）。","tags":["崔忠圻补充"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t140","front":"过冷奥氏体","back":"冷却到A₁温度以下仍未发生转变的奥氏体。过冷奥氏体在热力学上处于亚稳态，具有向稳定组织转变的倾向。其稳定性取决于温度和合金元素含量——C曲线鼻温附近（约550℃）最不稳定。过冷奥氏体在不同温度下发生不同类型转变：高温区→珠光体；中温区→贝氏体；低温区（Ms以下）→马氏体。","tags":["崔忠圻补充","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t141","front":"残余奥氏体","back":"淬火冷却至室温（或Mf以下）后仍保留在钢中的未转变奥氏体。产生原因：马氏体转变不完全——当温度降至Mf点以下转变停止，但Mf可低于室温。含碳量越高，Ms和Mf越低，残余奥氏体越多。残余奥氏体降低钢的硬度和耐磨性，可使用深冷处理（冷至Mf以下）使其继续转变。","tags":["崔忠圻补充","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t142","front":"Ms点与Mf点","back":"Ms点：过冷奥氏体开始转变为马氏体的最高温度。Mf点：马氏体转变基本完成的温度。Ms点主要取决于奥氏体的化学成分——含碳量越高Ms点越低（约从500℃降至室温以下）。除Co和Al外，大多数合金元素均降低Ms点。Ms~Mf区间范围决定马氏体转变特征和残余奥氏体量。","tags":["崔忠圻补充","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t143","front":"TTT曲线（过冷奥氏体等温转变曲线/C曲线）","back":"表示过冷奥氏体在不同温度下等温转变开始和结束时间（及转变量）与温度关系的曲线，因形状似字母C得名。是制定等温热处理工艺（等温淬火、等温退火、分级淬火）的基本依据。C曲线鼻温（约550℃）处过冷奥氏体最不稳定。合金元素（除Co外）使C曲线右移→提高过冷奥氏体稳定性→提高淬透性。","tags":["崔忠圻补充","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t144","front":"CCT曲线（连续冷却转变曲线）","back":"表示过冷奥氏体在不同冷却速度下连续冷却时的转变产物和转变温度范围的曲线。比TTT曲线更接近实际热处理条件，是制定淬火、正火、退火等连续冷却工艺的直接依据。与TTT曲线相比，CCT曲线向右下方偏移——连续冷却时转变被推迟。CCT曲线上可读出临界冷却速度Vk。","tags":["崔忠圻补充"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t145","front":"临界冷却速度（Vk）","back":"使过冷奥氏体在连续冷却过程中不发生高温扩散型转变而全部过冷至Ms点以下发生马氏体转变的最小冷却速度。Vk越小→钢的淬透性越好→越容易获得全马氏体组织。合金元素（除Co外）降低Vk值，提高淬透性。Vk是衡量钢淬透性的基本参数。","tags":["崔忠圻补充","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t146","front":"淬火临界直径（D₀）","back":"钢在某种淬火介质中冷却时，心部恰好能获得50%马氏体的最大圆棒直径。D₀是衡量钢淬透性的实用工程指标——D₀越大，淬透性越好。D₀取决于钢的化学成分和奥氏体晶粒度。崔忠圻详细讨论了淬透性带和淬透性对选材的工程意义。常用顶端淬火试验（Jominy试验）测定淬透性。","tags":["崔忠圻补充"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t147","front":"第一类回火脆性（不可逆回火脆性）","back":"淬火钢在250~400℃温度区间回火时出现的冲击韧性显著降低现象。具有不可逆性——一旦发生，重新加热至该温度区间以上也无法恢复韧性。产生原因与回火过程中碳化物沿马氏体板条界或片界析出有关。避免方法：避免在该温度区间回火，或采用等温淬火替代淬火+回火。","tags":["崔忠圻补充","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t148","front":"第二类回火脆性（可逆回火脆性）","back":"淬火钢在450~650℃高温回火后缓慢冷却时出现的冲击韧性降低现象。具有可逆性——重新加热至600℃以上后快冷可消除。产生原因：P、Sb、Sn、As等杂质元素在原奥氏体晶界偏聚，降低晶界结合力。Mo、W可抑制。防止措施：回火后快冷；选用含Mo或W的钢种；提高钢的纯净度。","tags":["崔忠圻补充","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t149","front":"完全退火","back":"将亚共析钢加热至Ac₃以上30~50℃，保温后随炉缓慢冷却至室温的热处理工艺。目的：细化晶粒、消除内应力和加工硬化、降低硬度以利于切削加工。加热至完全奥氏体化温度后炉冷获得近平衡组织——先共析铁素体+珠光体。仅适用于亚共析钢（过共析钢若加热至Acm以上缓冷会析出网状二次渗碳体）。","tags":["崔忠圻补充"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t150","front":"球化退火","back":"将过共析钢（或共析钢）加热至Ac₁以上20~30℃保温适当时间后，极慢冷却或在A₁以下20~30℃等温后炉冷的热处理工艺。目的：使层片状渗碳体和网状二次渗碳体球化为粒状渗碳体——降低硬度、改善切削加工性、为淬火做好组织准备。球化后组织为粒状珠光体。是工模具钢预处理的标准工艺。","tags":["崔忠圻补充"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t151","front":"去应力退火","back":"将工件加热至500~650℃（低于A₁），保温一定时间后缓冷至室温的热处理工艺。目的：消除铸造、锻造、焊接、冷加工和机加工过程中产生的残余内应力，稳定尺寸，防止后续加工或使用中变形开裂。过程中不发生相变，仅通过原子短程扩散消除弹性应变。","tags":["崔忠圻补充"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t152","front":"扩散退火（均匀化退火）","back":"将铸锭或铸件加热至高温（通常1050~1200℃，远高于Ac₃），长时间保温（数小时至数十小时）后缓冷的热处理工艺。目的：通过高温长时扩散消除或减轻铸锭中的枝晶偏析和宏观偏析，使成分均匀化。温度高、时间长、成本高，且会导致奥氏体晶粒粗化——通常需在均匀化后进行一次完全退火或正火以细化晶粒。","tags":["崔忠圻补充"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t153","front":"再结晶退火","back":"将冷变形金属加热至再结晶温度以上适当温度保温，使变形组织发生再结晶——形成新的无畸变等轴晶粒——然后缓冷的热处理工艺。目的：消除加工硬化、恢复塑性、便于进一步冷加工。退火温度=再结晶温度Tᵣ+100~200℃。不改变晶格类型，不涉及相变，是冷加工工序间的软化热处理。","tags":["崔忠圻补充"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t154","front":"正火","back":"将钢加热至Ac₃（亚共析钢）或Acm（过共析钢）以上30~50℃，保温后在静止空气中冷却的热处理工艺。目的：(1)低碳钢——提高硬度改善切削加工性；(2)中碳钢——细化晶粒为淬火做准备；(3)过共析钢——消除网状二次渗碳体。正火冷却速度比退火快，获得的珠光体更细密（索氏体型），硬度更高。","tags":["崔忠圻补充"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t155","front":"表面淬火","back":"利用快速加热（感应加热、火焰加热等）使工件表层快速奥氏体化后立即淬火冷却，使表层获得马氏体组织而心部保持原始组织的热处理工艺。实现'表硬里韧'的性能组合——表层高硬度高耐磨性+心部高韧性。常用方法：感应加热表面淬火、火焰加热表面淬火。适用于中碳钢（0.40~0.50%C）和球墨铸铁的齿轮、轴类、导轨等零件。","tags":["崔忠圻补充","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t156","front":"渗碳","back":"将低碳钢工件置于富碳活性介质中，加热到奥氏体区温度（通常920~950℃）保温，使碳原子渗入工件表层的化学热处理工艺。渗碳后表面含碳量提高至0.8%~1.1%C，心部仍保持低碳。渗碳后淬火+低温回火——表面获得高碳回火马氏体（高硬度高耐磨性）+心部为低碳马氏体或铁素体（高韧性）。广泛用于齿轮、凸轮轴等耐磨零件。","tags":["崔忠圻补充","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t157","front":"渗氮（氮化）","back":"将工件置于含氮活性介质中，加热至500~570℃保温，使氮原子渗入工件表层的化学热处理工艺。表层形成高硬度的合金氮化物层（Fe₂₋₃N、Fe₄N及AlN、CrN等），硬度可达1000HV以上且红硬性好。渗氮温度低（铁素体区），无需后续淬火——工件变形极小。适用于含Al、Cr、Mo等合金元素的渗氮钢（38CrMoAl）。缺点是渗层较薄、周期长。","tags":["崔忠圻补充","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t158","front":"碳氮共渗","back":"在渗碳气氛中同时加入氨气，使碳和氮同时渗入工件表层的化学热处理工艺。温度（820~880℃）低于渗碳温度，共渗层兼有渗碳层深和渗氮层硬的特点。氮的渗入降低了奥氏体化温度、提高了淬透性。碳氮共渗后直接淬火+低温回火，获得含氮马氏体表层——比单纯渗碳层具有更高的耐磨性和疲劳强度。广泛用于汽车齿轮等大批量零件。","tags":["崔忠圻补充"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t159","front":"固溶处理","back":"将合金加热至单相固溶体区温度保温，使第二相充分溶入基体形成固溶体，然后快速冷却（淬火）抑制第二相析出而获得过饱和固溶体的热处理工艺。是时效硬化的前提——固溶后获得过饱和固溶体（软态、塑性好），随后时效使第二相弥散析出实现强化。典型应用：铝合金（固溶+时效）、奥氏体不锈钢（固溶处理获得单相奥氏体提高耐腐蚀性）。","tags":["崔忠圻补充"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t160","front":"时效（时效硬化）","back":"过饱和固溶体在室温或加热到一定温度保温过程中，溶质原子偏聚（GP区形成）→过渡相析出→平衡相析出的过程，伴随硬度和强度显著提高（时效硬化），随后出现过时效（硬度下降）。分为自然时效（室温）和人工时效（加热）。是可热处理强化铝合金（如Al-Cu系2024）和部分高温合金的主要强化手段。峰值时效对应GP区+过渡相共存的最佳强化状态。","tags":["崔忠圻补充"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t161","front":"GP区（Guinier-Preston区）","back":"过饱和固溶体在时效初期，溶质原子在基体特定晶面上偏聚形成的微小富溶质区（厚度仅几个原子层，直径约几nm）。GP区与基体保持完全共格关系，通过共格应变场阻碍位错运动产生强化。是时效过程的第一阶段——随温度升高或时间延长向过渡相→平衡相演变。GP区强化是Al-Cu合金自然时效的主要机制——Cu原子在{100}α上偏聚形成盘状GP区。","tags":["崔忠圻补充"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t162","front":"调质处理","back":"淬火+高温回火的双重热处理工艺。淬火获得马氏体组织，高温回火（550~650℃）使马氏体分解、碳化物球化、铁素体再结晶，最终获得回火索氏体。调质处理获得优良的综合力学性能（高强度+高韧性），是承受交变载荷的中碳钢和中碳合金钢结构件最常用的热处理工艺。45钢和40Cr钢为典型调质钢。","tags":["崔忠圻补充","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t163","front":"柯肯达尔效应（Kirkendall效应）","back":"在扩散偶中，由于两种组元的扩散系数不等，原始界面（惰性标记物所在平面）向扩散快的一侧移动的现象。是扩散由空位机制控制的直接证据——扩散较快组元一侧空位流入多于流出，产生净空位流，空位凝聚形成孔隙（柯肯达尔孔洞）。柯肯达尔效应的重要意义：证明扩散以空位机制为主，否定了直接交换机制。","tags":["崔忠圻补充","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t164","front":"Cottrell气团（明显屈服现象）","back":"间隙溶质原子（C、N）在位错周围形成的偏聚气氛。间隙溶质原子与刃型位错的弹性应力场发生交互作用——溶质原子被吸引至刃型位错下方的膨胀区，形成'气团'钉扎位错。要使位错从气团中脱钉需要额外应力→出现上屈服点；脱钉后在较低应力下运动→下屈服点。Cottrell气团机制解释了低碳钢的明显屈服现象和屈服平台（Lüders带），也是应变时效的微观机制。","tags":["崔忠圻补充"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t165","front":"应变时效","back":"冷变形后的低碳钢在室温放置或低温加热后，强度（特别是屈服强度）升高、塑性降低的现象。微观机制：冷变形使位错脱钉（消除屈服平台），随后C、N原子扩散至位错处重新形成Cottrell气团→位错再次被钉扎→屈服现象恢复且屈服强度提高。应变时效使深冲钢板冲压后出现表面不平整（拉伸应变痕），是汽车用IF钢（无间隙原子钢）开发的原因。","tags":["崔忠圻补充"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t166","front":"同素异构转变","back":"同一元素（或化合物）在不同温度或压力下具有不同晶体结构的现象。铁是最典型的例子：α-Fe（BCC，<912℃）→γ-Fe（FCC，912~1394℃）→δ-Fe（BCC，1394~1538℃）。同素异构转变是钢铁热处理的基础——利用铁的同素异构转变通过对加热和冷却的控制来获得不同组织，从而实现性能调控。Fe的同素异构转变属于一级相变——有体积变化（γ→α膨胀约1%）。","tags":["崔忠圻补充"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t167","front":"红硬性（高温硬度）","back":"材料在高温下保持高硬度的能力。是高速钢和硬质合金最重要的性能指标之一——刀具在高速切削时刀尖温度可达500~600℃，需在此温度下仍保持足够硬度。高速钢（如W18Cr4V）经淬火+多次高温回火（560℃）后，由于合金碳化物（W₂C、VC等）的弥散析出硬化（二次硬化），在600℃左右仍可保持HRC60以上的高硬度。","tags":["崔忠圻补充"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t168","front":"蠕变","back":"材料在恒定应力（低于屈服应力）和恒定温度（通常>0.3Tm）下随时间延长持续发生缓慢塑性变形的现象。典型蠕变曲线分为三个阶段：减速蠕变→恒速蠕变（稳态蠕变速率最小）→加速蠕变（至断裂）。蠕变是高温构件（蒸汽管道、燃气轮机叶片、核反应堆部件）的主要失效方式。提高抗蠕变性能的途径：提高熔点、增加晶界强化元素、引入弥散强化相。","tags":["崔忠圻补充"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t169","front":"调幅分解（Spinodal分解）","back":"过饱和固溶体在溶解度曲线内（拐点线以内）的不稳定区，成分起伏自发增幅、连续分解为成分周期性波动的两相（结构相同、成分不同）的无形核-长大型相变。特点：无形核过程、无清晰相界面、成分按正弦波长连续变化、分解速度由互扩散控制。与脱溶（形核长大型）的区别：脱溶需要克服形核功、新相成分固定；调幅分解无形核功、两相成分连续变化。","tags":["崔忠圻补充"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t170","front":"临界变形量（临界变形度）","back":"使再结晶后获得极限粗大晶粒的冷变形量，约为2%~10%。原因：变形量小于临界值时，储存能少、再结晶形核率极低，少量晶核长大后形成异常粗大晶粒；超过临界变形量后，储存能增大、形核率激增，晶粒反而细化。工程意义：避开临界变形量退火可防止晶粒粗化（如深冲钢板二次轧制避开临界变形量）。2023真题名词原题。","tags":["崔忠圻补充","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t171","front":"奥氏体化","back":"将钢加热至临界温度（Ac3或Ac1）以上保温，使原始组织全部或部分转变为奥氏体的过程。奥氏体化是几乎所有热处理的第一步，包括形核、长大、剩余渗碳体溶解和均匀化四个阶段。奥氏体的成分、晶粒度直接影响后续冷却转变产物的组织和性能。","tags":["热处理工艺"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t172","front":"起始晶粒度","back":"奥氏体转变刚刚完成时的晶粒大小，即奥氏体化刚刚结束、尚未开始长大时的晶粒度。起始晶粒度取决于形核率与长大速度之比：形核率越大、长大速度越小，起始晶粒越细。原始组织越细（相界面越多），起始晶粒越细。","tags":["热处理工艺"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t173","front":"本质晶粒度","back":"钢在930°C保温3~8小时后测得的奥氏体晶粒大小，反映钢奥氏体晶粒长大的倾向。用Al脱氧的钢（含AlN）及含Ti、V、Nb等元素的钢，弥散的氮化物、碳化物质点钉扎晶界，抑制晶粒长大，为本质细晶粒钢；反之，用Si、Mn脱氧的钢为本质粗晶粒钢。本质晶粒度是钢的固有特性，与实际热处理无关。","tags":["热处理工艺","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t174","front":"实际晶粒度","back":"钢在具体热处理或热加工条件下实际获得的奥氏体晶粒大小。实际晶粒度取决于本质晶粒度和实际加热温度、保温时间。实际晶粒越细，转变后组织越细，钢的强度和韧性越好。检验标准为晶粒度等级（1~8级，8级最细）。","tags":["热处理工艺"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t175","front":"奥氏体晶粒长大","back":"奥氏体化温度过高或保温时间过长时，晶界迁移使小晶粒合并成大晶粒的过程。驱动力为总的界面能下降。晶粒粗化导致淬火后马氏体粗大、韧性下降、淬裂倾向增大。Ti、V、Al等元素形成的弥散质点阻碍晶界迁移，细化晶粒；Mn、P促进晶粒长大。","tags":["热处理工艺"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t176","front":"连续加热奥氏体化","back":"快速加热（感应加热、激光加热）条件下，奥氏体在连续升温过程中形成。特点：转变温度高（过热度大）、速度快、起始晶粒细，但均匀化不足（碳化物溶解不充分），需注意保温时间控制。高频感应加热淬火即利用此原理获得细小奥氏体晶粒。","tags":["热处理工艺"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t177","front":"不完全退火","back":"将钢加热至Ac1~ Ac3（亚共析钢）或Ac1~ A{cm}（过共析钢）之间，保温后缓冷的退火工艺。组织未完全奥氏体化（保留部分先共析相），主要用于过共析钢降低硬度、消除应力。球化退火实质上是不完全退火的一种。","tags":["热处理工艺"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t178","front":"等温退火","back":"将钢加热至奥氏体化温度后，较快冷至A1以下某一温度（珠光体转变区）等温保持，使奥氏体等温转变为珠光体，然后空冷的退火工艺。与普通退火相比，等温退火转变在恒温下进行、组织均匀、周期显著缩短，特别适用于合金钢（C曲线右移，普通退火周期长）。","tags":["热处理工艺"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t179","front":"正火与退火的组织差异（派生考点）","back":"同一钢种正火与退火的组织类型相同（先共析相+珠光体型组织），但正火因冷却快、过冷度大：珠光体片间距更细（索氏体化）、先共析铁素体量略少（共析成分点移动）、晶粒更细。因此正火态强度硬度略高于退火态，塑性韧性略低。","tags":["热处理工艺"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t180","front":"淬火","back":"将钢加热至Ac3或Ac1以上适当温度，保温后以大于临界冷却速度Vk的速度快速冷却，使过冷奥氏体在Ms以下转变为马氏体（或等温转变为下贝氏体）的热处理工艺。淬火是强化钢的最重要手段，与回火配合使用。淬火加热温度：亚共析钢Ac3+30~50°C（完全奥氏体化）；过共析钢Ac1+30~50°C（不完全奥氏体化，保留粒状渗碳体）。","tags":["热处理工艺","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t181","front":"临界冷却速度（$V_k$）","back":"使过冷奥氏体在连续冷却过程中不发生扩散型转变（珠光体、贝氏体转变）而全部过冷至Ms以下转变为马氏体的最小冷却速度。Vk对应CCT曲线上与转变开始线鼻部相切的冷却曲线。Vk越小，钢的淬透性越好。合金元素（除Co外）增大过冷奥氏体稳定性，使C曲线右移，降低Vk。","tags":["热处理工艺"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t182","front":"淬透性","back":"钢在淬火时获得淬硬层（马氏体层）深度的能力，即钢被淬透的难易程度。其本质是过冷奥氏体的稳定性，取决于C曲线的位置：C曲线越右，Vk越小，淬透性越好。影响因素：合金元素（除Co外均提高淬透性）、奥氏体成分均匀性、奥氏体晶粒度（粗晶粒淬透性好）、未溶第二相（降低淬透性）。测量方法：Jominy端淬试验、临界直径D0。","tags":["热处理工艺","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t183","front":"淬硬性","back":"钢淬火后所能达到的最高硬度，即马氏体的硬度。淬硬性主要取决于马氏体的含碳量：含碳量越高，晶格畸变越大，硬度越高。合金元素对淬硬性影响不大。淬透性与淬硬性是两个独立概念：高碳钢淬硬性高但淬透性可能很差（如T12）；低碳合金钢淬硬性低但淬透性可很好。","tags":["热处理工艺","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t184","front":"临界直径（$D_0$）","back":"钢在某种淬火介质中冷却时，心部恰好获得50%马氏体的最大圆柱试样直径。D0是衡量淬透性的实用工程指标——D0越大淬透性越好。同一钢种在不同介质中D0不同（水中大于油中）。理想临界直径D0'指在理想淬火介质（冷却速度无穷大）中的临界直径。","tags":["热处理工艺"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t185","front":"端淬试验（Jominy试验）","back":"标准淬透性试验：将phi25times100mm的标准试样加热奥氏体化后，对末端喷水冷却，然后沿试样纵向测量各点硬度，绘制硬度-距端面距离曲线（淬透性曲线）。距端面越远冷却速度越慢，硬度越低。曲线平缓表示淬透性好，陡降表示淬透性差。","tags":["热处理工艺"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t186","front":"单液淬火","back":"将奥氏体化的工件在一种淬火介质中冷却到底的淬火方法。优点是操作简单；缺点是水淬变形开裂倾向大，油淬硬度不足。适用于形状简单的碳钢（水/盐水中）和合金钢（油中）零件。","tags":["热处理工艺"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t187","front":"双液淬火","back":"将奥氏体化的工件先在冷却能力强的介质（水）中快冷至稍高于Ms（约300~400°C，C曲线鼻部以下），立即转入冷却能力弱的介质（油）中缓冷至室温的淬火方法。既保证避开珠光体转变区，又减小马氏体转变区的组织应力，防止变形开裂。适用于形状复杂的碳钢件。关键：在水中停留的时间要掌握准确。","tags":["热处理工艺"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t188","front":"分级淬火","back":"将奥氏体化的工件淬入温度略高于或略低于Ms点的盐浴（或碱浴）中，保温适当时间（使工件内外温度均匀），然后取出空冷的淬火方法。工件在盐浴中温度均匀后，马氏体转变在空冷（缓慢）条件下进行，组织应力小，变形开裂倾向显著减小。适用于形状复杂、变形要求严格的小型零件（刀具、模具）。","tags":["热处理工艺"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t189","front":"等温淬火","back":"将奥氏体化的工件淬入Ms点以上（贝氏体转变区，通常250~400°C）的盐浴中，等温保持足够时间使奥氏体转变为下贝氏体，然后取出空冷的淬火方法。所得下贝氏体组织强度高、韧性好（强韧兼备），且变形极小、无淬火开裂危险。适用于弹簧、齿轮、丝锥等要求强韧性的中小件。等温时间需大于贝氏体转变孕育期+完成时间。","tags":["热处理工艺","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t190","front":"淬火内应力（热应力与组织应力）","back":"热应力：淬火冷却时工件截面温差引起的不均匀收缩产生的内应力——冷却后期表面受压、心部受拉。组织应力：马氏体转变时表层与心部相变不同时性（表层先转变膨胀）产生的内应力——表层受拉、心部受压。淬火裂纹主要由组织应力引起（发生在Ms以下的快冷阶段）。分级、等温淬火可减小组织应力。","tags":["热处理工艺"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t191","front":"淬火缺陷：氧化、脱碳与过热、过烧","back":"氧化：钢在氧化性气氛中加热时表面形成氧化铁皮，造成金属损耗。脱碳：表层碳被氧化烧损，含碳量降低，淬火后表面硬度不足。防止：盐浴加热、保护气氛、真空加热。过热：加热温度过高使奥氏体晶粒粗大，淬火后马氏体粗大、韧性下降——可通过正火或退火补救。过烧：温度接近固相线，晶界氧化甚至局部熔化——不可补救，只能报废。","tags":["热处理工艺"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t192","front":"深冷处理（冷处理）","back":"将淬火到室温的钢继续冷却到Mf点以下（通常-70~-80°C干冰或-196°C液氮），使残余奥氏体继续转变为马氏体的工艺。高碳钢Mf低于室温，淬火后残余奥氏体多，影响硬度和尺寸稳定性。深冷处理提高硬度、耐磨性并稳定尺寸，用于精密量具、滚动轴承、油泵偶件等。","tags":["热处理工艺"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t193","front":"回火","back":"将淬火钢加热至Ac1以下某一温度，保温适当时间后冷却到室温的热处理工艺。目的：消除或降低淬火残余应力、稳定组织与尺寸、调整力学性能（获得强度与韧性的合理配合）。淬火+回火是不可分割的最终热处理。按温度分为低温（150~250°C）、中温（350~500°C）、高温（500~650°C）回火。","tags":["热处理工艺","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t194","front":"第一类回火脆性（低温回火脆性）","back":"淬火钢在250~400°C温度区间回火时出现的冲击韧性显著下降现象，又称不可逆回火脆性。其特征是：一旦发生，重新加热到更高温度回火也无法消除（不可逆）。产生原因与该温度区间碳化物沿马氏体板条界/片界析出及杂质元素（P、S等）的晶界偏聚有关。防止措施：避开该温度区间回火；改用等温淬火获得下贝氏体。","tags":["热处理工艺"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t195","front":"第二类回火脆性（高温回火脆性）","back":"淬火钢在450~650°C回火后缓慢冷却（或在该温度长时间保温）时出现的冲击韧性下降现象，又称可逆回火脆性。其特征是可逆：已脆化的钢重新加热到600°C以上短时保温后快冷可恢复韧性。产生原因：P、Sb、Sn、As等杂质元素在原奥氏体晶界偏聚，降低晶界结合力。防止措施：回火后快冷（油冷或水冷）；钢中加入Mo（0.3%~0.5%）或W抑制偏聚；提高钢的纯净度。","tags":["热处理工艺"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t196","front":"回火稳定性（抗回火性）","back":"淬火钢在回火过程中抵抗硬度下降（软化）的能力。合金元素溶入马氏体后，通过阻碍碳扩散和碳化物聚集长大，推迟软化进程，使合金钢在相同回火温度下保持更高硬度。Cr、Mo、W、V等强碳化物形成元素提高回火稳定性效果显著。回火稳定性高的钢可在更高温度回火获得相同硬度，因而韧性更好。","tags":["热处理工艺"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t197","front":"二次硬化","back":"含W、Mo、V等强碳化物形成元素的高合金钢（如高速钢），在500~600°C回火时，因析出弥散的W2C、Mo2C、VC等特殊碳化物，以及残余奥氏体转变为马氏体，使硬度不降反升的现象。二次硬化是高速钢获得红硬性（高温下保持高硬度）的基础。高速钢的典型工艺：1270~1280°C淬火+560°C三次回火。","tags":["热处理工艺","必背"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t198","front":"红硬性（热硬性）","back":"材料在高温下长期保持高硬度的能力。刀具高速切削时刀刃温度可达500~600°C，要求材料在该温度下仍保持HRC60以上。红硬性来源于合金碳化物（W2C、VC等）的高温稳定性——即二次硬化效应。高速钢（W18Cr4V）和硬质合金具有优良红硬性，而碳素工具钢完全不具备。","tags":["热处理工艺"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t199","front":"感应加热表面淬火","back":"利用电磁感应原理，交变电流通过感应器在工件表层产生感应电流（涡流），由于集肤效应电流集中于表层，使表层快速加热奥氏体化，随后喷水（或浸油）冷却的表面淬火方法。电流频率越高，集肤效应越强，淬硬层越浅：高频（200~300kHz）0.5~2mm；中频（2.5~10kHz）2~8mm；工频（50Hz）10~20mm。特点是加热速度快、晶粒细、变形小、易实现自动化。广泛用于齿轮、轴类件。","tags":["热处理工艺"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t200","front":"化学热处理","back":"将工件置于含有活性介质的容器中加热保温，使介质分解出的活性原子被工件表面吸附并扩散进入表层，改变表层的化学成分与组织，从而获得所需性能的热处理工艺总称。由分解、吸收、扩散三个基本过程组成。按渗入元素分为渗碳、渗氮、碳氮共渗、渗金属等。特点是表层不仅改变组织还改变成分，强化效果比单纯表面淬火更深入持久。","tags":["热处理工艺"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"t201","front":"复合热处理","back":"将两种或多种热处理工艺组合，使工件获得单一工艺难以达到的综合性能。例如：渗碳+高频淬火（表面更高硬度）、渗氮+整体淬火、淬火+深冷+回火（精密件尺寸稳定化）。复合热处理是现代热处理发展的重要方向。","tags":["热处理工艺"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0}]},{"id":"d_880_qa","name":"880 简答论述","desc":"材料科学基础 · 107 题（带星标）","color":"#3fb950","cards":[{"id":"q001","front":"1.1 简述晶体、空间点阵与晶体结构的区别与联系","back":"晶体是原子（离子、分子）在三维空间呈周期性规则排列的固体。空间点阵是将晶体中原子或原子群抽象为几何点（阵点）后形成的周期性空间阵列，共有14种布拉菲点阵。晶体结构是指原子在空间的实际具体排列方式。\n\n联系：晶体结构 = 空间点阵 + 基元（每个阵点所代表的原子群）。空间点阵是抽象几何模型，只反映周期性；晶体结构是实际原子排列，既反映周期性又反映具体原子种类与位置。同一空间点阵可对应多种晶体结构（如FCC点阵既可排列Cu也可排列金刚石结构）。","tags":["第一章 金属与合金的晶体结构","2星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q002","front":"1.2 比较面心立方（FCC）、体心立方（BCC）、密排六方（HCP）三种典型金属晶体结构","back":"特征 | FCC | BCC | HCP\n————————————————————\n晶胞原子数 | 4 | 2 | 6（或3）\n配位数 | 12 | 8 | 12（c/a=1.633时）\n致密度 | 0.74 | 0.68 | 0.74\n密排面/方向 | 111/<110> | 无真正密排面 | 基面(0001)\n滑移系（独立） | 12 | 12~48 | 3（基面）\n间隙（八面体） | 1个/晶胞 | 6个（较小） | —\n\n要点：(1)FCC与HCP致密度相同（0.74），均为密排结构，差别在于密排面堆垛方式（FCC为ABCABC，HCP为ABAB）；(2)BCC致密度较低（0.68），配位数8；(3)FCC塑性最好（密排面多+层错能低），HCP塑性最差（滑移系少）；(4)FCC与BCC的八面体间隙位置与大小不同，影响间隙原子溶解度与扩散。","tags":["第一章 金属与合金的晶体结构","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q003","front":"1.3 说明配位数与致密度的含义，并计算FCC结构的配位数与致密度","back":"配位数（CN）：晶体中任一原子周围最近邻且等距离的原子数目。致密度（K）：晶胞中原子所占体积与晶胞总体积之比，K=_原子V_晶胞。\n\nFCC计算：晶胞原子数n=8×18+6×12=4；原子半径r与晶格常数a关系：密排方向<110>上原子相切，4r=2a，即r=2/4a。K=4×43π r^3/a^3=4×43π(2a/4)^3a^3=2π/6≈0.74。配位数12（12个最近邻原子）。","tags":["第一章 金属与合金的晶体结构","2星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q004","front":"1.4 简述Hume-Rothery规则的主要内容及对固溶体溶解度的影响","back":"Hume-Rothery规则是判断置换固溶体溶解度的经验规律，四个因素：\n\n• 原子尺寸因素（最主要）：溶剂与溶质原子半径差Δ r<15%时有利于形成大溶解度甚至无限固溶体；Δ r越大溶解度越小。\n\n• 电负性因素：两元素电负性差越大，越易形成稳定化合物而非固溶体，溶解度降低。\n\n• 电子浓度因素：电子浓度e/a超过极限值（一价FCC约1.36，一价BCC约1.48）时固溶体不稳定，溶解度受限。\n\n• 晶体结构因素：溶剂与溶质晶体结构相同才可能形成无限固溶体（如Cu-Ni均FCC）。\n\n结论：四因素需综合考虑，尺寸与结构满足且电负性差小、电子浓度许可时可形成无限固溶体，否则为有限固溶体。","tags":["第一章 金属与合金的晶体结构","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q005","front":"1.5 比较固溶体与化合物的主要区别","back":"项目 | 固溶体 | 化合物\n——————————————\n晶体结构 | 保持溶剂晶格类型 | 形成新晶体结构\n成分范围 | 可变（连续范围） | 固定或很窄（化学计量比）\n性能 | 与基体相近，强度略高 | 与组元截然不同（硬脆等）\n结合键 | 金属键为主 | 金属键+共价键/离子键\n\n联系：二者都是合金中的相；固溶体保留溶剂结构，化合物结构全新。固溶强化是重要强化手段；化合物（如渗碳体、金属间化合物）硬而脆，可作强化相。","tags":["第一章 金属与合金的晶体结构","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q006","front":"1.6 比较间隙固溶体与间隙化合物的异同","back":"相同点：(1)都由小尺寸非金属原子（C、N、H、B）与金属组成；(2)都存在间隙原子。\n\n不同点：\n\n• 间隙固溶体：溶质原子溶于溶剂晶格间隙中，保持溶剂晶体结构；溶解度有限（如C在γ-Fe中最大2.11%）；固溶体性能与基体接近。\n\n• 间隙化合物：形成新的晶体结构（如Fe_3C为正交结构），成分按比例；当r_x/r_m<0.59时形成简单结构间隙相（TiC、VC，NaCl型），>0.59时形成复杂结构间隙化合物（Fe_3C）；硬而脆，是钢中主要强化相。\n\n判断标志：是否保持溶剂晶格类型——保持为固溶体，改变为化合物。","tags":["第一章 金属与合金的晶体结构","2星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q007","front":"1.7 简述固溶强化的机理、影响因素及其特点","back":"定义：溶质原子溶入基体形成固溶体使强度硬度升高的现象。\n\n机理：溶质原子尺寸与基体不同引起晶格畸变，畸变应力场与位错弹性应力场发生交互作用，阻碍位错运动；间隙原子还可形成柯氏气团钉扎位错，均使位错运动阻力增大。\n\n影响因素：(1)溶质浓度越高强化越强（Δσ∝ C或C^1/2）；(2)原子尺寸差越大强化越强；(3)间隙固溶强化远大于置换固溶强化（畸变更大）；(4)电负性差增大强化增强。\n\n特点：强度、硬度升高，塑性、韧性有所下降（位错运动受阻）。与细晶强化不同，固溶强化不能同时提高塑性与强度。","tags":["第一章 金属与合金的晶体结构","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q008","front":"1.8 比较刃型位错与螺型位错的主要特征","back":"特征 | 刃型位错 | 螺型位错\n————————————————\n几何模型 | 多余半原子面终止于晶内 | 原子面呈螺旋阶梯排列\n柏氏矢量b | 垂直于位错线 | 平行于位错线\n滑移方式 | 只能沿包含b的特定滑移面滑移 | 可在含位错线的任意晶面滑移（交滑移）\n攀移 | 能攀移（需扩散） | 不能攀移\n运动方向 | 滑移方向∥ b | 滑移方向⊥ b\n位错线形状 | 可为直线/曲线 | 直线（纯螺）\n\n联系：实际位错多为混合位错，可分解为刃型分量与螺型分量；二者均引起晶格畸变，能量∝|b|^2。","tags":["第一章 金属与合金的晶体结构","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q009","front":"1.9 什么是柏氏矢量？说明其性质与意义","back":"定义：通过柏氏回路确定的、描述位错引起晶格畸变大小与方向的矢量，记为b。在完整晶体中作闭合回路，含位错晶体中同一回路不闭合，从终点到起点的闭合矢量即为b。\n\n性质：(1)b为整数个点阵矢量（单位位错为最短点阵矢量）；(2)守恒性：同一根位错线上各点b相同，与回路途径无关；(3)b不随位错运动改变。\n\n意义：(1)表征位错强度（畸变程度），位错能量∝|b|^2；(2)判断位错类型（b⊥线为刃型，b∥线为螺型）；(3)位错反应需满足几何条件∑ b_前=∑ b_后与能量条件∑|b|^2减小。","tags":["第一章 金属与合金的晶体结构","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q010","front":"1.10 位错滑移与攀移有何区别？","back":"• 滑移：位错沿滑移面（含位错线与b的平面）的运动。刃型位错滑移方向∥ b，螺型⊥ b。滑移是保守运动（不涉及原子扩散），在切应力作用下即可发生，所需临界切应力小，是塑性变形的主要机制。滑移后晶体表面产生台阶。\n\n• 攀移：刃型位错（及混合位错的刃型分量）垂直于滑移面的运动。攀移是非保守运动，需借助空位或间隙原子的扩散（正攀移：空位迁移至多余半原子面底缘使其缩短；负攀移：原子迁移至位错线使其伸长）。攀移需热激活，高温下显著；螺型位错无多余半原子面，不能攀移。\n\n意义：攀移是高温回复（多边形化）、位错绕过障碍的重要方式。","tags":["第一章 金属与合金的晶体结构","2星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q011","front":"1.11 简述位错的Frank-Read源增殖机制","back":"一段两端被固定（钉扎）的位错线，在切应力作用下发生弯曲：\n\n• 位错线两端被钉扎，在外力下弓出弯曲；\n\n• 曲率半径逐渐减小至最小值（位错线呈半圆，对应最大阻力）；\n\n• 继续弓出，位错线绕两端点旋转并相互接近；\n\n• 两侧位错线段相遇后抵消（异号相消），产生一个完整位错环并恢复原始位错段；\n\n• 重复上述过程，不断放出位错环——位错增殖。\n\n意义：解释了塑性变形过程中位错密度不降反升（由10^6~10^8增至10^11~10^12cm^-2）的原因，是加工硬化的微观基础。","tags":["第一章 金属与合金的晶体结构","2星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q012","front":"1.12 为什么实际金属的强度远低于理论强度？","back":"理论剪切强度约为τ_th≈G/2π~G/30（约10^4MPa量级），而实际金属屈服强度仅为G/10^3~G/10^4（约10~100MPa），相差2~4个数量级。\n\n原因：理论强度假设晶体中原子同时整体滑动（同步切变），所需应力极大；实际晶体中存在位错，塑性变形通过位错的逐步滑移实现（每次只移动一个原子间距），所需切应力小得多（派-纳力远小于理论值）。位错的存在使晶体\"分层滑移\"，大大降低了变形抗力。\n\n推论：(1)无位错晶须强度接近理论值；(2)强化手段的本质都是阻碍位错运动（固溶、细晶、第二相、加工硬化）。","tags":["第一章 金属与合金的晶体结构","2星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q013","front":"1.13 简述晶体缺陷的分类及其对材料性能的影响","back":"按几何维度分三类：\n\n• 点缺陷：空位、间隙原子、杂质原子、置换原子。影响：与扩散密切相关（空位是扩散载体）；影响电阻率、密度；高温平衡空位浓度n/N=Ae^-Q/kT。\n\n• 线缺陷：位错。影响：决定塑性变形能力（滑移载体）；影响强度（阻碍与增殖）；影响扩散（管道效应）；影响相变（形核位置）。\n\n• 面缺陷：晶界、相界、孪晶界、堆垛层错、自由表面。影响：晶界处原子排列紊乱、能量高——是扩散快速通道、相变形核优先位置、阻碍位错运动（细晶强化根源）；晶界偏聚影响韧性（回火脆性）。\n\n总论：缺陷破坏理想周期性，提高能量；利用缺陷可强化（位错、晶界），也可控制扩散与相变。","tags":["第一章 金属与合金的晶体结构","2星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q014","front":"1.14 简述小角度晶界与大角度晶界的结构与性能差异","back":"小角度晶界（θ<10^°）：由位错组成——对称倾侧晶界由同号刃型位错垂直排列构成（D=b/θ），扭转晶界由螺型位错网络构成。晶界能较低（γ=γ_0θ(A-θ)），原子排列接近完整晶体。位错密度随θ增大而增大。\n\n大角度晶界（θ>10^°）：原子排列紊乱，可视为约2~3个原子层厚的过渡区，不能用位错模型描述。晶界能高且与θ关系不大（约500~600 mJ/m^2）。某些特殊取向（重合位置点阵，如3孪晶界）晶界能较低。\n\n性能差异：大角度晶界扩散系数大（扩散快通道）、界面能高、对位错阻碍强（细晶强化）、易发生偏聚；小角度晶界以上性质均较弱。","tags":["第一章 金属与合金的晶体结构","2星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q015","front":"1.15 什么是超结构（有序固溶体）？其形成对性能有何影响","back":"定义：某些固溶体在高温下原子无序排列，缓冷至临界温度以下时，不同原子在点阵中呈规则周期性排列，这种有序化的固溶体称为超结构（有序固溶体），如Cu_3Au、CuZn（β黄铜）。\n\n特征：有序化是扩散型相变，有序度随温度降低而增大；存在有序化转变温度（临界温度），高于该温度无序。\n\n对性能影响：(1)电阻率显著降低（电子散射减少）；(2)硬度、强度升高（反相畴界阻碍位错运动）；(3)塑性下降、脆性增大（有序相中位错运动需成对进行）；(4)对磁性、耐蚀性有影响。","tags":["第一章 金属与合金的晶体结构","1星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q016","front":"1.16 简述表面能与界面能的含义及界面能大小的比较","back":"表面能：产生单位面积新表面所需做的可逆功（J/m^2）。表面原子配位数低于内部，存在不饱和键，能量较高。金属表面能约1~3 J/m^2。\n\n界面能：两相（或两晶粒）之间单位面积界面的超额自由能，来源于界面原子排列紊乱引起的畸变能与化学键不匹配能。\n\n大小比较：共格界面（最低）< 半共格界面 < 非共格界面 < 大角度晶界 < 自由表面（最高）。界面能是形核（需形成界面增加能量）、晶粒长大（界面能降低是驱动力）的重要热力学量。","tags":["第一章 金属与合金的晶体结构","1星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q017","front":"1.17 简述共格界面、半共格界面与非共格界面的区别","back":"共格界面：界面两侧晶面一一对应、原子完全匹配，靠弹性应变维持。仅当两相晶格常数相近（失配度<5%）时存在，界面能最低。如GP区与基体的界面。\n\n半共格界面：晶面大部分匹配，失配由界面位错补偿（=5%~25%），界面能中等。如θ'相与基体界面。\n\n非共格界面：原子排列完全不匹配，无对应关系（>25%），界面能最高（约500~1000 mJ/m^2），类似大角度晶界。如平衡相θ相与基体界面。\n\n意义：脱溶析出过程中，随析出相长大，界面由共格→半共格→非共格转变，界面能增大、共格应变能变化，影响强化效果（过时效机制之一）。","tags":["第一章 金属与合金的晶体结构","2星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q018","front":"2.1 什么是过冷与过冷度？说明结晶的驱动力","back":"过冷：液态金属冷却到理论结晶温度T_m以下仍不结晶的现象。实际结晶温度T_n低于T_m。\n\n过冷度：Δ T=T_m-T_n，是结晶的推动力。\n\n驱动力：结晶的热力学条件是液-固两相自由能差Δ G=G_S-G_L<0。由Δ G=Δ HΔ T/T_m可知：只有过冷（Δ T>0）时Δ G<0，结晶才能自发进行。过冷度越大，自由能差越大，驱动力越强。过冷是结晶的必要条件，也是形核与长大的共同驱动力。","tags":["第二章 纯金属的结晶","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q019","front":"2.2 均匀形核与非均匀形核的异同点？为什么实际生产中几乎不发生均匀形核","back":"相同点：(1)都以过冷度为驱动力；(2)都经历形核与长大两个阶段；(3)都需要结构起伏与能量起伏；(4)都存在临界晶核半径r^*与临界形核功Δ G^*；⑤形核率都随过冷度先增后减。\n\n不同点：\n\n项目 | 均匀形核 | 非均匀形核\n—————————————————\n形核位置 | 液相内部各处等概率 | 依附现成表面（模壁、杂质、未熔质点）\n形核功 | Δ G^*_均=16πσ^3/3Δ G_v^2 | Δ G^*_非=Δ G^*_均· S(θ)，S(θ)<1\n所需过冷度 | 极大（约0.2T_m） | 较小（约0.02T_m）\n\n其中S(θ)=(2+θ)(1-θ)^2/4为润湿角因子，θ越小形核越易。\n\n实际生产不发生均匀形核的原因：熔体中总存在大量模壁、杂质颗粒等现成表面，非均匀形核形核功远小于均匀形核，优先发生；均匀形核所需的极大过冷度（0.2T_m）在生产中无法实现。","tags":["第二章 纯金属的结晶","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q020","front":"2.3 推导临界晶核半径与临界形核功，并说明其意义","back":"设球形晶核半径r，则形成该晶核引起的自由能变化：\n\nΔ G=-4/3π r^3Δ G_v+4π r^2σ\n\n其中Δ G_v为单位体积液固自由能差（驱动力，正数），σ为比表面能。第一项（体积项）为负、随r^3变化；第二项（界面项）为正、随r^2变化。\n\n对r求导并令为零：dΔ G/dr=-4π r^2Δ G_v+8π rσ=0，得\n\nr^*=2σ/Δ G_v, Δ G^*=16πσ^3/3Δ G_v^2\n\n又Δ G_v=Δ H_mΔ T/T_m，故r^*∝1/Δ T，Δ G^*∝1/Δ T^2。\n\n意义：(1)r<r^*的晶胚长大使Δ G升高而消溶；r>r^*的晶核长大使Δ G降低而稳定长大；(2)过冷度增大，r^*与Δ G^*减小，形核越易；(3)非均匀形核通过降低形核功促进形核（润湿角θ小）。","tags":["第二章 纯金属的结晶","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q021","front":"2.4 简述形核率与过冷度的关系（C形曲线）","back":"形核率N（单位体积单位时间形成的晶核数）：\n\nN=K(-Δ G^*/kT)(-Q/kT)\n\n第一项为形核功因子：Δ G^*∝1/Δ T^2，过冷度增大使形核功减小，该项增大（形核概率增大）；第二项为扩散因子：过冷度增大使原子扩散能力下降（Q为扩散激活能），该项减小。\n\n两因子竞争导致N-Δ T曲线呈C形：开始随Δ T增大N增大，达最大值后随Δ T继续增大N下降。存在最大形核率对应的过冷度。\n\n意义：解释了深过冷（快速凝固）时形核率反而降低的现象；实际结晶中通过控制过冷度控制晶粒度。","tags":["第二章 纯金属的结晶","2星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q022","front":"2.5 简述晶体长大的三种机制（界面类型与长大方式）","back":"按固-液界面微观结构分为两类：\n\n• 粗糙界面（非小平面界面）——连续长大：界面原子层约一半位置被占据，液相原子可直接附着于界面任意位置，界面垂直方向连续推进。长大速度大，所需动态过冷度小（10^-2℃量级），金属多为粗糙界面。\n\n• 光滑界面（小平面界面）：界面原子规则排列，原子只能附着于台阶处。两种方式：\n\n• 二维形核长大：在界面上先形成单原子厚度的二维晶核，再沿台阶横向扩展。所需过冷度大，长大慢。\n\n• 螺型位错台阶长大：螺型位错在界面露头处提供永不消失的台阶，原子沿螺旋台阶不断附着。所需过冷度比二维形核小，是光滑界面的主要长大方式。\n\n总结：粗糙界面连续长大最快；光滑界面中螺型位错台阶长大优于二维形核。长大方式决定晶体形态（树枝晶、规则外形等）。","tags":["第二章 纯金属的结晶","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q023","front":"2.6 什么是成分过冷？说明其形成条件及对晶体生长形态的影响","back":"定义：合金凝固时，固-液界面前沿液相因溶质富集使液相线温度升高（实际凝固温度升高），当实际温度梯度小于液相线温度梯度时，界面前沿出现局部过冷区域，称为成分过冷。\n\n形成条件（判据）：\n\nG/R<mC_0(1-k_0)/k_0D\n\n即：温度梯度G小、凝固速度R大、液相线斜率m大、原始成分C_0高、分配系数k_0<1（偏离1越远越大）、扩散系数D小，越易产生成分过冷。\n\n对生长形态的影响（成分过冷增大时）：\n平面状界面→胞状界面→胞状树枝晶→树枝状晶→等轴晶（内部形核）。成分过冷越大，界面越不稳定，枝晶越发达，最终导致等轴晶形成。","tags":["第二章 纯金属的结晶","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q024","front":"2.7 简述树枝状晶的形成原因","back":"直接原因：成分过冷使固-液界面失稳。\n\n过程：(1)结晶开始时界面为平面状；(2)界面前沿产生成分过冷区，平面界面失稳，凸起进入过冷液相；(3)凸起尖端生长快（过冷度大、散热好），形成一次枝晶轴（沿择优生长方向，FCC为<100>）；(4)一次轴侧面也处于过冷状态，产生二次枝晶臂；⑤二次臂上还可长出三次臂，形成树枝状晶体。\n\n促进条件：凝固速度大、温度梯度小、合金成分范围宽（两相区宽）。树枝晶是铸态金属的典型组织，枝晶间存在偏析（枝晶偏析）。","tags":["第二章 纯金属的结晶","2星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q025","front":"2.8 铸锭的宏观组织三晶区及其形成原因","back":"铸锭由表及里依次为：\n\n• 表面细晶区（激冷区）：浇注时表层金属与模壁接触，过冷度极大，非均匀形核率高，形成细小等轴晶。\n\n• 柱状晶区：表面细晶形成后，模壁温度升高，散热方向单一（垂直模壁），细晶中取向有利的晶粒（一次轴沿散热方向）择优生长，晶粒相互竞争排挤，形成垂直于模壁的柱状晶。\n\n• 中心等轴晶区：凝固后期，中心剩余液相温度均匀、过冷度小，同时在液相中形成大量枝晶碎粒等形核质点，非均匀形核形成等轴晶。\n\n影响因素：浇注温度、模壁冷却能力、金属性质。提高浇注温度、增大模壁冷却速度有利于柱状晶；降低浇注温度、加变质剂、搅拌有利于等轴晶。","tags":["第二章 纯金属的结晶","2星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q026","front":"2.9 柱状晶与等轴晶的性能特点比较","back":"柱状晶：晶粒长轴平行于散热方向（热流方向），存在择优取向（铸造织构），性能各向异性——沿柱轴方向强度、塑性较好，垂直方向较差；柱状晶交界处（中心线）聚集低熔点杂质与缩松，形成脆弱面（热裂、裂纹易沿此发生）。铸件中不希望出现贯穿性柱状晶。\n\n等轴晶：晶粒各方向尺寸相近，无择优取向，性能各向同性，无脆弱交界区，力学性能均匀；但组织较疏松（枝晶间缩松多），致密度略低。\n\n应用：(1)对要求各向同性、承受多向载荷的铸件希望获得等轴晶（细化方法：降低浇注温度、变质处理、振动搅拌）；(2)定向凝固制备单晶叶片利用柱状晶/单晶特性。","tags":["第二章 纯金属的结晶","2星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q027","front":"2.10 细化铸锭（铸件）晶粒的途径有哪些？","back":"形核率越大、长大速度越小，晶粒越细。细化途径：\n\n• 增大过冷度：降低浇注温度、加快冷却速度（金属模、水冷），使形核率大增，晶粒细化（快速凝固获得微晶甚至非晶）。\n\n• 变质处理（孕育处理）：向熔体加入形核剂（变质剂），提供大量现成表面促进非均匀形核，使晶粒细化。如钢中加Ti、V、Al、Nb形成高熔点碳化物/氮化物作为形核核心；铸铁加硅铁、硅钙孕育。\n\n• 振动与搅拌：机械振动、电磁搅拌、超声振动使枝晶破碎，破碎晶粒成为新晶核，细化等轴晶。\n\n• 动态晶粒细化：浇注时搅动（如旋转磁场），促进中心等轴晶。\n\n本质：提高形核率N、抑制长大速度v，使N/v增大，晶粒细化（d∝[3]v/N）。","tags":["第二章 纯金属的结晶","2星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q028","front":"2.11 什么是单晶、非晶态、微晶、准晶？","back":"单晶：整个固体由一块晶体组成，无晶界，性能呈各向异性。用直拉法（Czochralski）、区域熔炼等制备，用于半导体、单晶高温合金叶片等。\n\n非晶态（金属玻璃）：原子排列无长程有序，类似液态的冻结。通过急冷（>10^6K/s）抑制结晶获得。强度接近理论值、耐蚀性好、软磁性能优，但脆性大、热稳定性差。\n\n微晶：晶粒尺寸为微米甚至纳米级的多晶体。通过快速凝固、大变形+再结晶等获得，强度硬度高（细晶强化显著）。\n\n准晶：具有长程有序但不具平移周期性，允许五次、八次、十次、十二次旋转对称的固态。1984年Shechtman在急冷Al-Mn合金中发现（2011年诺贝尔化学奖）。硬度高、摩擦系数低。","tags":["第二章 纯金属的结晶","1星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q029","front":"2.12 简述动态过冷度的概念及与界面结构的关系","back":"动态过冷度：晶体以一定速度长大时，界面处实际温度低于平衡凝固温度T_m的差值，是晶体长大的直接驱动力。\n\n与界面结构关系：(1)粗糙界面以连续长大方式生长，原子容易附着，所需动态过冷度极小（约0.01~0.05℃），长大速度大（v∝Δ T_k）；(2)光滑界面需二维形核或借助螺型位错台阶，原子附着困难，所需动态过冷度大（可达1~2℃以上），长大速度小。\n\n意义：动态过冷度的大小反映了不同界面结构长大难易程度，决定了生长速度与晶体形态。","tags":["第二章 纯金属的结晶","1星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q030","front":"2.13 铁碳相图三条水平线的反应式、温度与成分","back":"铁碳相图三条水平线（从左到右）：\n\n① 包晶线（1495℃）：L(0.53%C) + δ(0.09%C) → γ(0.17%C)。包晶转变中液相与已结晶的δ固溶体反应生成奥氏体。因反应需碳原子在固相中长程扩散，常反应不完全。\n\n② 共晶线（1148℃）：L(4.3%C) → γ(2.11%C) + Fe3C(6.69%)，即莱氏体Ld。发生在含碳2.11%~6.69%的铁碳合金（白口铸铁区）。\n\n③ 共析线（727℃，A1线）：γ(0.77%C) → α(0.0218%C) + Fe3C，即珠光体P。所有含碳>0.0218%的铁碳合金缓冷时都要经过此转变。\n\n记忆要点：包晶1495/共晶1148/共析727；共析钢组织全P、亚共析先析α、过共析先析网状Fe3CⅡ。","tags":["第二章 纯金属的结晶","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q031","front":"2.14 某白口铸铁含碳3.5%，写出平衡凝固过程，并计算室温组织组成物相对量","back":"判断：2.11%<3.5%<4.3%，属亚共晶白口铸铁。\n\n凝固过程：L → 先结晶初生奥氏体γ初；冷至1148℃剩余液相(4.3%C)共晶转变 L → γ+Fe3C 形成莱氏体Ld；继续冷却初生γ沿Acm析出二次渗碳体，727℃时γ共析转变为珠光体P。\n\n室温组织：珠光体P + 二次渗碳体Fe3CⅡ + 变态莱氏体Ld'(P+Fe3CⅡ)。\n\n杠杆定律计算：\n共晶温度1148℃：初生奥氏体 w(γ初)=(4.3-3.5)/(4.3-2.11)=0.8/2.19≈36.5%；莱氏体 w(Ld)=(3.5-2.11)/2.19≈63.5%。\n初生奥氏体冷至727℃前析出Fe3CⅡ，727℃余下γ(0.77%)全部转变为P：w(P in γ初)=(6.69-2.11)/(6.69-0.77)≈77.4%，Fe3CⅡ≈22.6%。\n室温汇总：w(P)≈36.5%×77.4%+63.5%×(莱氏体中P分数)，w(Fe3CⅡ)按两处析出合计，w(Ld')直接由63.5%换算。答题要点：写出共晶温度和室温两次杠杆，数值精确计算。","tags":["第二章 纯金属的结晶","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q032","front":"2.15 什么是包晶偏析？说明其成因及防止方法","back":"包晶偏析：包晶转变（如铁碳合金1495℃ L+δ→γ）反应不完全，新生γ包在δ相外面阻止碳原子继续扩散，使转变后奥氏体成分不均（内贫碳外富碳）的现象。\n\n成因：包晶反应需碳原子穿过新生γ层长程扩散，速度慢；实际冷却速度下反应未达平衡就中断。\n\n防止/消除：扩散退火（均匀化退火，高温长时间保温使成分均匀化）；钢液浇注时控制成分避开包晶点或加快结晶减小包晶反应量。","tags":["第二章 纯金属的结晶","1星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q033","front":"2.16 什么是离异共晶？举例说明其成因及对性能的影响","back":"离异共晶：共晶转变中两相不形成正常共晶混合组织，而是各自分开生长、共晶体形态消失的现象。通常发生在共晶量很少的合金中。\n\n成因：先共晶相的表面为共晶中另一相提供了现成的优先生长面，使其直接附着在先共晶相上生长；剩余共晶相单独留在晶界。\n\n典型例子：含碳0.6%~2.11%的钢中，共晶体中的Fe3C呈网状/断续网状分布于奥氏体晶界。\n\n对性能影响：网状Fe3C沿晶界连续分布分隔基体，使钢脆性增大、强度下降——这正是过共析钢网状渗碳体危害的组织来源，需正火消除。","tags":["第二章 纯金属的结晶","1星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q034","front":"3.1 比较滑移与孪生的异同点","back":"相同点：(1)都是切应力作用下的切变过程；(2)都不改变晶体结构类型；(3)都是塑性变形的基本方式；(4)都是位错或原子协调运动的结果。\n\n不同点：\n\n项目 | 滑移 | 孪生\n————————————\n晶体学特征 | 沿滑移面/滑移方向（密排面/方向） | 沿孪生面/孪生方向，孪生区与基体镜面对称\n原子位移 | 位移量为b的整数倍，变形集中于滑移带 | 每层原子位移与距孪生面距离成正比（非整数倍），变形均匀\n变形量 | 大（主要变形方式） | 小（直接变形量小）\n所需应力 | 较小（临界分切应力低） | 较大\n发生条件 | 滑移系易于开动时 | 滑移困难时（HCP、低温BCC、高应变速率）\n取向变化 | 不改变晶粒取向 | 改变取向（孪生区转向新取向）\n\n孪生的特殊作用：直接变形量小，但可改变晶体取向，使不利取向变为有利取向，诱发进一步滑移，间接促进塑性变形。","tags":["第三章 金属的塑性变形","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q035","front":"3.2 什么是临界分切应力？写出Schmid定律并说明其应用","back":"临界分切应力（τ_c）：使滑移系开动所需的最小分切应力。它是晶体材料的固有属性，与外力大小、方向无关，与晶体结构、纯度、温度有关。\n\nSchmid定律：τ=σλ，其中σ为外加正应力，为滑移面法线与外力轴夹角，λ为滑移方向与外力轴夹角，λ称为取向因子（Schmid因子）。当τ=τ_c时滑移开始，此时：\n\nσ_s=τ_c/λ\n\n取向因子最大值为0.5（=λ=45^°时），此时屈服应力最小。\n\n应用：(1)解释单晶体屈服应力的各向异性（取向不同强度不同）；(2)多晶体中各晶粒取向因子不同，变形先后不一；(3)判断软取向与硬取向。","tags":["第三章 金属的塑性变形","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q036","front":"3.3 简述滑移系与金属塑性变形能力的关系","back":"滑移系：一个滑移面与该面上一个滑移方向构成一个滑移系。滑移面通常是密排面，滑移方向是密排方向。\n\n各晶体结构滑移系：FCC：111<110>共12个；BCC：110,112,123<111>共12~48个（随温度升高滑移面增多）；HCP：基面(0001)<1120>共3个（高温时柱面、锥面滑移系增多）。\n\n与塑性关系：(1)滑移系数量多，塑性变形能力强——FCC与BCC滑移系多，塑性好；HCP滑移系少，塑性差（如锌、镁易脆断）。(2)仅数量多不够，还需考虑滑移面间距（d大则派-纳力小）：FCC密排面间距大、滑移阻力小，故FCC塑性优于BCC；(3)独立滑移系须满足von Mises准则（≥5个独立滑移系）才能协调多晶体变形，FCC和BCC满足，HCP室温不满足（需孪生辅助）。","tags":["第三章 金属的塑性变形","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q037","front":"3.4 简述加工硬化（形变强化）的机理、特点及应用","back":"定义：金属塑性变形时随变形量增大，强度硬度升高、塑性韧性下降的现象。\n\n机理：(1)变形使位错大量增殖（F-R源开动），位错密度由10^6~10^8增至10^11~10^12cm^-2；(2)位错间发生交割（形成割阶）、缠结、塞积等交互作用，位错运动阻力增大；(3)位错缠结形成胞状结构，进一步阻碍位错运动。故继续变形需更大应力。\n\n特点：强度提高、塑性下降、电阻率略升；可通过再结晶退火消除。\n\n应用：(1)冷变形强化（冷轧、冷拔、冲压件强度提高）；(2)保证冷加工成形工艺可行（防止局部颈缩：已变形处强度提高，变形转移）；(3)利用\"应变硬化指数n\"评价板材成形性能。","tags":["第三章 金属的塑性变形","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q038","front":"3.5 简述塑性变形对金属组织与性能的影响","back":"组织变化：(1)晶粒沿变形方向拉长，形成纤维组织（大变形时）；(2)晶粒内部产生滑移带、形变带；(3)位错密度显著增大，形成位错胞状结构；(4)各晶粒转动形成形变织构；⑤出现微观/宏观残余应力。\n\n性能变化：(1)强度、硬度升高，塑性、韧性下降（加工硬化）；(2)出现各向异性（织构使性能方向性）；(3)电阻率升高、耐蚀性下降（位错增多、内应力增大）；(4)内应力存在，工件易变形开裂（需去应力退火）。\n\n其他：变形储存能（约占总变形功的1%~10%）是后续回复再结晶的驱动力。","tags":["第三章 金属的塑性变形","2星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q039","front":"3.6 什么是形变织构？说明其产生原因、类型及影响","back":"定义：多晶体塑性变形后，各晶粒取向由随机分布转变为择优取向分布的状态。\n\n产生原因：变形时各晶粒在外力作用下转动，滑移系逐步转向与外力最有利的取向，最终大量晶粒取向趋于一致。\n\n类型：(1)丝织构：拉拔、挤压时某特定晶向平行于轴线（FCC为<111>+<100>，BCC为<110>）；(2)板织构：轧制时某晶面平行于板面、某晶向平行于轧向（如110<112>）。\n\n影响：(1)性能各向异性——深冲板材沿不同方向性能不同，形成\"制耳\"（凸耳）缺陷；(2)可利用织构获得所需性能（变压器硅钢片轧向磁导率最高，利用高斯织构）；(3)再结晶后形成再结晶织构。","tags":["第三章 金属的塑性变形","2星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q040","front":"3.7 简述金属断裂的基本类型","back":"按断裂前塑性变形量分：\n\n• 韧性断裂：断裂前发生明显宏观塑性变形。过程：微孔在夹杂物/第二相处形核→长大→聚合→断裂。断口呈暗灰色纤维状，微观为韧窝。吸收能量大。\n\n• 脆性断裂：断裂前几乎无宏观塑性变形，突然断裂。断口平齐光亮，穿晶解理断口有河流花样，沿晶脆断断口呈冰糖状。BCC、HCP金属低温、高应变速率下易发生。\n\n按断裂路径分：\n\n• 穿晶断裂：裂纹穿过晶粒内部（解理、韧窝）。\n\n• 沿晶断裂：裂纹沿晶界扩展（晶界弱化：偏聚、脆性相、回火脆性）。\n\n影响因素：温度（韧脆转变）、应力状态（三向拉应力促进脆断）、应变速率、晶粒大小、杂质偏聚。","tags":["第三章 金属的塑性变形","2星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q041","front":"3.8 简述细晶强化（Hall-Petch关系）的机理及特点","back":"Hall-Petch关系：σ_s=σ_0+kd^-1/2，d为晶粒直径，σ_0、k为常数。晶粒越细，屈服强度越高。\n\n机理（位错塞积理论）：晶界阻碍位错运动，位错在晶界处塞积，塞积群前端产生应力集中。晶粒越细：(1)晶界面积越大，位错运动受阻越强；(2)塞积群中位错数目越少，应力集中越小，需更大外应力才能使相邻晶粒位错源开动——强度提高。\n\n同时提高塑性韧性的原因：细晶材料变形可分散到更多晶粒中进行，变形均匀，应力集中小，裂纹不易萌生，断裂前可承受更大变形量——塑性、韧性也提高。\n\n特点：细晶强化是唯一能同时提高强度与塑性韧性的强化方式；其他强化（固溶、第二相、加工硬化）均使塑性下降。","tags":["第三章 金属的塑性变形","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q042","front":"3.9 比较四种强化机制（固溶、细晶、第二相、加工硬化）","back":"强化方式 | 本质 | 强度 | 塑性 | 其他特点\n——————————————————————————\n固溶强化 | 溶质原子畸变场阻碍位错 | | | 间隙原子强化效果大\n细晶强化 | 晶界阻碍位错+塞积 | | | 唯一同时强化+增塑\n第二相强化 | 颗粒阻碍位错（切过/绕过） | | | 可兼得部分韧性\n加工硬化 | 位错增殖、交割缠结 | | | 可恢复（再结晶退火）\n\n要点：(1)四种方式本质都是阻碍位错运动；(2)细晶强化特殊之处在于同时提高强度与塑性；(3)实际材料常多种强化并用（如合金钢=固溶+细晶+第二相+加工硬化）；(4)强化程度：第二相与细晶效果显著，固溶中等，加工硬化可调范围大。","tags":["第三章 金属的塑性变形","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q043","front":"3.10 为什么FCC金属的塑性通常优于BCC金属？","back":"(1)滑移系与密排面：FCC有12个111<110>滑移系，滑移面为密排面、滑移方向为密排方向，面间距大、点阵阻力（派-纳力）小，滑移容易；BCC虽滑移系多达12~48个，但无真正的密排面，滑移面间距小、派-纳力大，滑移困难。\n\n(2)堆垛与层错：FCC密排面以ABCABC堆垛，层错能较低（如Cu、Al），位错易分解为扩展位错，面上滑移容易；BCC位错核心复杂，低温下螺型位错运动阻力大。\n\n(3)交滑移能力：BCC螺型位错易交滑移，虽有利变形协调，但低温时位错难以启动；FCC（高层错能如Al）也能交滑移，变形协调好。\n\n(4)温度敏感性：FCC从低温到高温均有足够独立滑移系满足von Mises准则，塑性好；BCC低温下位错运动阻力剧增，出现脆性断裂（韧脆转变），塑性急剧下降。","tags":["第三章 金属的塑性变形","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q044","front":"3.11 简述单晶体塑性变形应力-应变曲线的三个阶段","back":"单晶体（FCC）拉伸曲线分三个阶段：\n\n• 第I阶段（易滑移阶段）：只有一个滑移系开动（单滑移），位错自由滑移，加工硬化率低（θ_I小），滑移线长而均匀分布。\n\n• 第II阶段（线性硬化阶段）：多个滑移系开动（多滑移），位错交割形成割阶、缠结，产生Lomer-Cottrell锁等障碍，位错塞积，加工硬化率最高且近似常数（θ_II≈ G/300），滑移线短而密。\n\n• 第III阶段（抛物线硬化阶段）：动态回复起作用，螺型位错交滑移使部分位错相互抵消（异号湮灭），硬化率逐渐降低，出现波浪状滑移带。\n\n影响因素：晶体取向（第I阶段长度）、温度（升高使各阶段硬化率降低）、层错能（低层错能金属交滑移困难，第III阶段推迟，硬化率高）。","tags":["第三章 金属的塑性变形","1星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q045","front":"3.12 什么是交滑移？说明其对塑性变形的影响","back":"定义：螺型位错从一个滑移面转移到另一个与之相交的滑移面上继续滑移的过程。因螺型位错的b与位错线平行，包含位错线的任何晶面都可成为其滑移面，故螺型位错可以交滑移（刃型位错不能）。\n\n扩展位错与交滑移：FCC中全位错常分解为扩展位错（两个不全位错夹一层错），扩展位错不能直接交滑移，需先束集为全位错才能交滑移。层错能越高，扩展位错越窄，束集越易，交滑移越容易。\n\n对塑性变形的影响：(1)交滑移是位错绕过障碍（攀移之外的另一种方式）的途径，促进变形继续进行；(2)交滑移使位错在异号相遇时相互抵消，产生动态回复，降低加工硬化率（第III阶段硬化率下降）；(3)层错能低的金属（如奥氏体不锈钢、黄铜）交滑移难，加工硬化率高，冷加工强化效果好。","tags":["第三章 金属的塑性变形","2星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q046","front":"3.13 简述多晶体塑性变形的特点","back":"• 变形不均匀性：各晶粒取向不同，取向因子不同，滑移先后不一，先变形的晶粒受周围晶粒约束，变形分布不均，产生内应力。\n\n• 晶界的强化作用：晶界原子排列紊乱、阻碍位错运动，位错在晶界塞积——晶粒细、晶界多、强度高（Hall-Petch）；晶界附近变形量小于晶内（竹节现象：多晶体拉伸时晶界处呈竹节状凸起）。\n\n• 变形协调性（von Mises准则）：任意晶粒的任意变形必须与相邻晶粒协调，需至少5个独立滑移系同时开动。FCC、BCC满足，HCP不满足（需孪生辅助）。\n\n• 屈服点现象：低碳钢等出现上、下屈服点（柯氏气团钉扎位错），多晶体比单晶体明显。\n\n• 塑性变形以滑移为主，孪生为辅；变形产生织构、内应力。","tags":["第三章 金属的塑性变形","2星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q047","front":"3.14 什么是柯氏气团？说明低碳钢明显屈服现象的原因","back":"柯氏气团（Cottrell气团）：间隙溶质原子（C、N）与刃型位错弹性交互作用，偏聚在位错线附近（膨胀区）形成的溶质原子气团。溶质原子使位错能量降低，钉扎位错。\n\n明显屈服现象：低碳钢拉伸时出现上屈服点（应力突然下降）与下屈服点（应力平台）的现象。\n\n机理：(1)退火态C、N原子形成柯氏气团钉扎位错，位错被钉扎，开动需较大应力——上屈服点；(2)一旦挣脱气团，位错在较低应力下运动——下屈服点；(3)挣脱气团的位错在相邻滑移面相继开动，形成吕德斯带（屈服伸长），应力-应变出现平台。\n\n影响因素：温度（升高消除屈服现象——原子扩散脱离气团）、变形速度（高应变速率屈服现象明显）、含碳量（间隙原子越多越明显）。","tags":["第三章 金属的塑性变形","2星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q048","front":"3.15 什么是von Mises判据？多晶体塑性变形为什么需要至少5个独立滑移系","back":"von Mises判据：多晶体（各晶粒取向不同、变形需相互协调）发生任意形状的均匀塑性变形，至少需要5个独立滑移系。\n\n原因：均匀变形可用6个应变分量描述（εx、εy、εz、γxy、γyz、γzx），因塑性变形体积不变（εx+εy+εz=0），独立应变分量只有5个；每个滑移系只能提供1个独立切应变，故需≥5个独立滑移系才能满足变形协调。\n\n应用：FCC（12个滑移系{111}<110>）和BCC（{110}<111>等12个以上）均满足，塑性好；HCP滑移系少（基面滑移仅3个），多晶变形难以协调，塑性差、需孪生辅助调整取向。这解释了镁合金室温塑性差、需加热成形的原因。","tags":["第三章 金属的塑性变形","2星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q049","front":"4.1 冷变形金属加热时发生哪三个阶段？说明各阶段的驱动力与组织性能变化","back":"冷变形金属储存变形能，加热时依次发生：\n\n• 回复（较低温度）：驱动力为变形储存能。组织：点缺陷大量消失、位错重排（多边形化形成亚晶），位错密度基本不变。性能：电阻率显著下降（点缺陷消除），内应力大部分消除，强度硬度变化不大。动力学：回复速率初始快、逐渐减慢。\n\n• 再结晶（较高温度）：驱动力为变形储存能。组织：通过形核长大形成新的无畸变等轴晶粒，完全取代变形组织，位错密度由10^11~10^12骤降至10^6~10^8cm^-2。性能：强度硬度显著下降，塑性韧性显著回升，基本恢复至变形前水平。\n\n• 晶粒长大（更高温度）：驱动力为界面能降低（总晶界面积减小）。组织：晶界迁移，晶粒均匀长大或异常长大（二次再结晶）。性能：强度、塑性均下降（粗晶脆性），表面能下降。\n\n记忆：三个阶段驱动力：储存能→储存能→界面能。","tags":["第四章 回复与再结晶","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q050","front":"4.2 简述回复过程的微观机制与性能变化","back":"微观机制（回复由多种机制组成，低温到高温依次）：\n\n• 点缺陷消除（低温回复，约0.1~0.3T_m）：空位与间隙原子复合或迁移至晶界、表面消失，空位浓度降低。\n\n• 位错重新排列（中温回复，约0.3~0.5T_m）：位错滑移、攀移，异号位错对消，位错重排成稳定组态——多边形化形成亚晶界。\n\n• 亚晶长大（高温回复）：亚晶界迁移、合并，亚晶尺寸增大。\n\n性能变化：(1)电阻率显著下降（点缺陷散射减小——最敏感）；(2)内应力大部分消除（位错重新排列）；(3)强度硬度变化很小（位错密度基本不变）；(4)密度、导热性等部分恢复。\n\n应用：去应力退火（回复处理）——保留冷变形强化效果的同时消除内应力（如冷拉弹簧钢丝去应力退火）。","tags":["第四章 回复与再结晶","2星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q051","front":"4.3 简述再结晶过程及其影响因素","back":"再结晶：冷变形金属加热到一定温度后，通过形核与长大形成新的无畸变等轴晶粒取代变形组织的过程。\n\n形核方式：(1)亚晶合并形核（变形量大、位错分布均匀时）；(2)亚晶界弓出形核（变形量小、位错密度不均时）；(3)原有大角度晶界弓出。\n\n长大：大角度晶界向变形区迁移，吞并变形组织，直至全部转变。\n\n影响因素：\n\n• 变形量：变形量越大，储存能越高，再结晶驱动力越大，再结晶温度越低，晶粒越细；存在临界变形度（约2%~10%）使再结晶晶粒极粗。\n\n• 退火温度：温度越高再结晶越快（Arrhenius关系），再结晶晶粒越粗。\n\n• 保温时间：时间越长，再结晶越完全，晶粒越粗。\n\n• 原始晶粒尺寸：原始晶粒越细，形核位置越多，再结晶后晶粒越细。\n\n• 合金元素与杂质：溶质原子和第二相质点阻碍晶界迁移，提高再结晶温度、细化晶粒。\n\n• 变形温度：变形温度影响储存能与回复程度。","tags":["第四章 回复与再结晶","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q052","front":"4.4 什么是再结晶温度？说明其影响因素","back":"定义：经大变形的金属在1小时内完成再结晶（再结晶体积分数达95%以上）所需的最低退火温度，T_r≈0.35~0.40T_m（K）。\n\n影响因素：\n\n• 变形量：变形量越大，储存能越高，再结晶温度越低；变形量小（低于临界变形度）时再结晶温度高甚至不发生。\n\n• 原始晶粒尺寸：原始晶粒越细，形核位置多，再结晶温度越低。\n\n• 合金元素与杂质：溶质原子（尤其间隙原子）与第二相质点钉扎晶界，阻碍形核长大，提高再结晶温度（如纯铁T_r≈450℃，含少量碳后升至600℃以上）。\n\n• 加热速度：加热速度影响回复程度，回复多则储存能少，再结晶温度升高。\n\n• 退火时间：时间延长使所需温度降低（定义1小时）。","tags":["第四章 回复与再结晶","2星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q053","front":"4.5 什么是临界变形度？说明其产生原因及避免方法","back":"定义：再结晶后晶粒尺寸与变形量关系中，使再结晶晶粒尺寸达到最大的变形量（通常2%~10%），又称临界变形度。\n\n产生原因：变形量很小时储存能低，形核驱动力小，但储存能分布不均——少数形核位置（如晶界三叉点）储存能较高可以形核，而大部分区域不能形核，导致形核率极低；同时晶粒长大驱动力（储存能）虽小但仍能驱动少数晶核长大，结果形核少、长大充分——晶粒极粗大。\n\n危害：粗大晶粒使强度塑性显著下降（粗晶脆性），是热处理缺陷。\n\n避免方法：(1)冷变形量避开临界变形度范围（一般>15%~20%）；(2)若已产生临界变形度粗晶，可通过再次较大变形+再结晶退火细化，或正火细化。","tags":["第四章 回复与再结晶","2星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q054","front":"4.6 简述再结晶后晶粒长大方式及控制方法","back":"两种长大方式：\n\n• 正常晶粒长大（均匀长大）：晶粒尺寸分布窄，长大均匀。驱动力为总界面能降低。晶界迁移由曲率驱动（小晶粒被大晶粒吞并），长大速度v∝1/D。\n\n• 异常晶粒长大（二次再结晶）：少数晶粒（晶界迁移率特别高或被钉扎释放）急剧长大，吞并周围正常晶粒，形成粗细极不均匀组织。危害大。\n\n控制方法：(1)控制退火温度与时间（避免过高过长）；(2)利用第二相质点钉扎晶界（弥散质点阻碍迁移，抑制长大——AlN、VC等；质点粗化/溶解后钉扎失效）；(3)控制杂质含量（微量杂质选择性偏聚可钉扎晶界）；(4)临界变形度避开；⑤织构控制（利用定向长大）。","tags":["第四章 回复与再结晶","2星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q055","front":"4.7 动态回复与动态再结晶有何区别？","back":"动态回复/再结晶：变形在再结晶温度以上进行时，回复/再结晶与变形同时发生的软化过程。\n\n区别：\n\n项目 | 动态回复 | 动态再结晶\n—————————————————\n发生条件 | 高层错能金属（Al、α-Fe） | 低层错能金属（Cu、Ni、γ-Fe）\n机制 | 位错交滑移、攀移、对消 | 反复形核长大\n流变曲线 | 稳态流变（应力饱和） | 多次波动（软化-硬化交替）\n组织特征 | 亚晶结构（多边形化） | 等轴晶+锯齿晶界\n储存能 | 低（回复充分） | 高\n\n联系：两者都是热加工（锻造、轧制、挤压）中的软化机制，共同降低变形抗力；变形后立即冷却可保留动态组织，缓冷则发生静态再结晶/亚动态再结晶。","tags":["第四章 回复与再结晶","2星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q056","front":"4.8 什么是再结晶织构？说明其产生及影响","back":"定义：再结晶后形成的择优取向组织（再结晶织构）。\n\n产生原因：(1)定向形核：再结晶核心在变形织构中特定取向区域优先生成；(2)定向长大：晶界迁移率与取向差有关，特定取向差（如40°<111>取向差迁移率最大）的晶核长大最快，择优长大。\n\n类型：退火织构（再结晶织构）与形变织构相对应，如铜型、黄铜型、立方织构等。\n\n影响：(1)深冲板材产生制耳；(2)立方织构（100<001>）可改善变压器硅钢片磁性；(3)影响材料各向异性。可通过控制变形量、退火工艺、合金元素调控织构。","tags":["第四章 回复与再结晶","1星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q057","front":"4.9 简述冷变形金属的性能变化规律（变形量与性能关系）","back":"随冷变形量增大：\n\n• 强度硬度：单调升高（加工硬化），开始阶段升高快，后趋缓（与位错密度、胞状结构饱和有关）。\n\n• 塑性（延伸率、断面收缩率）：单调下降。\n\n• 韧性（冲击韧性）：显著下降。\n\n• 电阻率：升高（晶格畸变增强电子散射）；电阻温度系数下降。\n\n• 密度：略有下降（空位、位错增多）。\n\n• 耐蚀性：下降（内应力大、位错露头处易腐蚀）。\n\n• 磁性：矫顽力增大、磁导率下降（内应力、位错阻碍磁畴转动）。\n\n总结规律：加工硬化规律（强度升、塑性降）；内应力与储存能增大；性能出现方向性（织构）。","tags":["第四章 回复与再结晶","1星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q058","front":"5.1 写出Fick第一定律与第二定律，并说明其物理意义与应用","back":"Fick第一定律（稳态扩散）：\n\nJ=-DdC/dx\n\nJ为扩散通量（单位时间通过单位面积的物质质量/原子数），D为扩散系数（m^2/s），dC/dx为浓度梯度。负号表示扩散方向为浓度降低方向。物理意义：扩散通量与浓度梯度成正比。适用：浓度不随时间变化的稳态扩散（如薄壁渗碳管稳态渗碳）。\n\nFick第二定律（非稳态扩散）：\n\n C/ t=D^2 C/ x^2\n\n适用：浓度随时间变化的非稳态扩散。两个典型解：\n\n• 恒定表面浓度（渗碳）：C(x,t)=C_s[1-erf(x/2√(Dt))]——渗碳层深度x≈√(Dt)；\n\n• 薄膜源（示踪扩散）：高斯解。\n\n意义：(1)是扩散问题的基本方程；(2)工程应用：渗碳层深度预测、均匀化退火时间、扩散焊等。","tags":["第五章 固体中的扩散","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q059","front":"5.2 固体中扩散的微观机制有哪些？说明各机制的特点","back":"• 间隙机制：小尺寸间隙原子（C、N、H、O）从一个间隙位置跃迁到相邻间隙位置。不需空位参与，激活能较小（仅需克服点阵弹性畸变），扩散快——间隙固溶体扩散的主要机制。\n\n• 空位机制：原子跃迁到相邻空位位置，等价于空位反向运动。需空位存在（空位形成能+跃迁能），激活能较大——置换固溶体（纯金属自扩散、置换原子扩散）的主要机制。\n\n• 直接交换机制：相邻两原子直接互换位置。需两原子同时跳动、局部畸变大、激活能极高，实际不参与。\n\n• 环形交换机制：n个原子环形旋转交换位置（如面心立方中n=4）。激活能低于直接交换但仍较高，仅在特殊情况下（如某些合金）有贡献，一般可忽略。\n\n• 晶界扩散、表面扩散、位错扩散（短路扩散）：沿缺陷通道的扩散，激活能低、速度快，低温时贡献突出。\n\n柯肯达尔效应证明：置换扩散以空位机制为主（直接交换不能解释界面移动）。","tags":["第五章 固体中的扩散","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q060","front":"5.3 什么是柯肯达尔效应？说明其意义","back":"定义：将Cu与黄铜（Cu-Zn合金）焊合（或Cu-Ni扩散偶）加热扩散后，原始界面（以惰性标记丝标记）向Zn含量高的一侧（黄铜侧）移动的现象。\n\n原因：两种组元的扩散系数不同（D_Zn>D_Cu），Zn向Cu侧扩散通量大于Cu向黄铜侧通量，形成净原子流从黄铜侧流向Cu侧。为保持体积不变，空位反向流动（从Cu侧流向黄铜侧），过剩空位凝聚成孔洞（柯肯达尔孔洞），界面整体向黄铜侧移动。\n\n意义：(1)证明置换扩散以空位机制为主（直接交换机制无法解释界面移动）；(2)说明两种组元扩散系数不等是普遍现象；(3)工程上：扩散焊、渗镀、高温服役合金中柯肯达尔孔洞会削弱结合强度（需控制）。","tags":["第五章 固体中的扩散","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q061","front":"5.4 写出Arrhenius方程并说明影响扩散的因素","back":"Arrhenius方程：D=D_0(-Q/RT)，D_0为扩散常数（频率因子），Q为扩散激活能，R为气体常数。 D= D_0-Q/R·1/T—— D与1/T成线性，斜率-Q/R。\n\n影响因素：\n\n• 温度（最主要）：温度升高，原子振动加剧、空位浓度增大，D指数增大。温度每升100℃，D可增大数倍。\n\n• 晶体结构：致密度低的结构间隙大、扩散激活能小，扩散快。α-Fe（BCC）自扩散系数比γ-Fe（FCC）大约两个数量级。碳在α-Fe中扩散比γ-Fe快。\n\n• 晶体缺陷：晶界、位错、表面是短路扩散通道，激活能低、速度快（晶界扩散比体扩散快2~4个数量级）。晶粒越细扩散越快。\n\n• 合金元素：影响基体结合力与空位浓度。强碳化物形成元素（Cr、Mo、W、V）降低碳的扩散系数；某些元素改变扩散激活能。\n\n• 固溶体类型：间隙原子扩散激活能小（如C在γ-Fe中Q≈142kJ/mol），置换原子（空位机制）激活能大，扩散慢几个数量级。\n\n• 应力、磁场等外场：应力梯度可产生上坡扩散（化学位梯度驱动）。","tags":["第五章 固体中的扩散","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q062","front":"5.5 什么是上坡扩散？说明其驱动力及产生条件","back":"定义：溶质原子从低浓度区向高浓度区扩散的反常扩散现象（扩散方向与浓度梯度方向相反）。\n\n驱动力：扩散的普遍驱动力是化学位梯度（自由能梯度）而不是浓度梯度：J=-Mdμ/dx。当化学位梯度方向与浓度梯度方向相反时，发生上坡扩散。\n\n产生条件（典型情况）：\n\n• 弹性应力场：大原子向拉应力区偏聚，小原子向压应力区偏聚（晶界偏聚、刃型位错周围气团——柯氏气团本质）。\n\n• Spinodal（调幅）分解：成分起伏放大，富溶质区更富、贫溶质区更贫。\n\n• 电场/温度梯度：带电粒子在电场中迁移。\n\n• 表面能作用：小颗粒溶质向大颗粒扩散（Ostwald熟化——过时效机理）。\n\n意义：说明扩散驱动力本质是化学位差，浓度梯度不是唯一判据。","tags":["第五章 固体中的扩散","2星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q063","front":"5.6 什么是短路扩散？简述其特点与应用","back":"定义：原子沿晶体缺陷（自由表面、晶界、位错）的扩散，因激活能低、速度快而称短路扩散（快速扩散通道）。\n\n特点：(1)激活能关系：Q_表<Q_晶界<Q_位错<Q_体；(2)扩散系数：D_表>D_晶界>D_位错>D_体，晶界扩散比体扩散快2~4个数量级；(3)温度越低，短路扩散的相对贡献越大（体扩散激活能大，低温衰减快；短路通道激活能小，低温仍活跃）；(4)晶粒越细、缺陷越多，短路扩散贡献越大。\n\n应用与影响：(1)粉末冶金烧结中表面/晶界扩散促进致密化；(2)晶界扩散导致晶界迁移与晶粒长大；(3)晶界扩散引起晶界成分变化（偏聚）；(4)薄膜与纳米材料中短路扩散显著；⑤低温渗碳、渗氮依赖短路扩散。","tags":["第五章 固体中的扩散","2星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q064","front":"5.7 什么是反应扩散？举例说明其特点","back":"定义：扩散过程中伴随新相形成（化学反应的扩散）。当扩散组元浓度超过基体固溶度极限时，在表面形成新相层（化合物层），如渗碳时的Fe_3C层、渗氮时的氮化物层、金属氧化时的氧化膜。\n\n特点：(1)扩散层中浓度分布不连续——相界面处浓度发生突变（各相区成分对应相图相区）；(2)扩散层由表及里按相图相区顺序排列（如Fe-N系：ε相→γ'相→α相）；(3)新相层形成后，进一步扩散需通过已形成的相层，扩散速率受相层厚度控制（抛物线规律：x^2=kt）；(4)层数取决于相图与扩散时间。\n\n应用：渗碳、渗氮、氧化、镀层、半导体掺杂等；理解表面处理层的组织与性能。","tags":["第五章 固体中的扩散","2星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q065","front":"5.8 举例说明扩散在材料制备与处理中的应用","back":"• 化学热处理（渗碳、渗氮、碳氮共渗）：依靠碳/氮原子向钢内扩散形成强化层——扩散是渗层形成的基础。\n\n• 均匀化退火（扩散退火）：依靠原子扩散消除枝晶偏析，成分均匀化；退火时间t∝ x^2/D。\n\n• 烧结：粉末颗粒间通过表面/晶界扩散与体扩散形成结合（粉末冶金、陶瓷烧结）。\n\n• 焊接与扩散焊：原子扩散形成冶金结合（尤其固态扩散焊）。\n\n• 半导体掺杂与集成电路：杂质扩散控制P-N结深度。\n\n• 合金化与表面处理：渗金属（渗铝、渗铬）提高表面性能。\n\n• 蠕变与高温性能：高温下位错攀移、晶界滑动依赖扩散，扩散是蠕变控制因素。\n\n• 相变：扩散型相变（奥氏体化、珠光体转变）由原子扩散控制。","tags":["第五章 固体中的扩散","2星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q066","front":"5.9 简述扩散第一定律与第二定律在渗碳中的应用（渗碳层深度计算）","back":"气体渗碳可视为恒定表面碳浓度的非稳态扩散，用Fick第二定律误差函数解：\n\nC(x,t)-C_0/C_s-C_0=1-erf(x/2√(Dt))\n\nC_s为表面碳浓度（由气氛碳势决定），C_0为原始含碳量。\n\n关键结论：\n\n• 渗碳层深度x∝√(Dt)——时间增加4倍，渗层只加深2倍；温度升高（D指数增大）显著加速渗碳。\n\n• 提高温度比延长保温时间更有效：927℃1027℃（D增大3倍）相当于保温时间延长数倍。\n\n• 工艺上：渗碳温度920~950℃，保温时间由层深要求决定；实际生产中通过调节碳势、温度、时间控制渗层深度与碳浓度分布。","tags":["第五章 固体中的扩散","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q067","front":"6.1 固态相变与液态结晶有何异同？固态相变有何特点？","back":"相同点：(1)都需过冷（过热度）提供驱动力；(2)都经历形核与长大；(3)都受扩散控制（扩散型相变）。\n\n固态相变的特点：\n\n• 存在母相晶体结构——新相在母相内形核，两者间存在晶体学取向关系与共格/半共格界面。\n\n• 弹性应变能参与：新相与母相比容不同（体积变化）受周围母相约束，产生弹性应变能，相变驱动力部分消耗于应变能。\n\n• 易在晶体缺陷处形核：晶界、位错、空位处能量高，形核优先。\n\n• 切变型相变：马氏体相变为无扩散切变，新旧相保持严格位向关系，表面浮凸。\n\n• 过渡相：常先形成亚稳过渡相（如GP区、θ''、θ'），再向平衡相转变。\n\n• 扩散困难：固态扩散慢，相变速率低，易保留亚稳组织（如淬火马氏体、过饱和固溶体）。","tags":["第六章 固态相变及热处理原理","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q068","front":"6.2 过冷奥氏体在冷却过程中发生哪几种转变？写出各自温度区间与产物","back":"共析钢过冷奥氏体（A_1=727℃以下）随冷却温度不同发生三种转变：\n\n转变 | 温度区间 | 类型 | 产物\n———————————————————\n珠光体转变 | A_1~550℃ | 扩散型（Fe、C都扩散） | 珠光体（铁素体+渗碳体层片）\n贝氏体转变 | 550℃~ M_s | 半扩散型（Fe切变、C扩散） | 贝氏体（铁素体+碳化物）\n马氏体转变 | <M_s | 无扩散型（切变） | 马氏体（过饱和α'）\n\n补充：(1)珠光体按过冷度分为珠光体P（λ>0.4μm）、索氏体S（0.2~0.4μm）、屈氏体T（λ<0.2μm）；(2)贝氏体分上贝氏体（550~350℃，羽毛状）与下贝氏体（350℃~ M_s，针状）；(3)马氏体分板条（低碳，位错亚结构）与片状（高碳，孪晶亚结构）；(4)转变温度越低、过冷度越大，产物越细、硬度越高。","tags":["第六章 固态相变及热处理原理","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q069","front":"6.3 简述TTT曲线（C曲线）的含义、特征及应用","back":"含义：过冷奥氏体等温转变曲线（TTT曲线），纵轴温度、横轴时间（对数），表示过冷奥氏体在各温度等温时转变开始线与终了线及转变量。\n\n特征：(1)呈\"C\"形——高温区（A_1~550℃）为珠光体转变，低温区（550℃~ M_s）为贝氏体转变；(2)鼻尖（约550℃）孕育期最短、转变最快，过冷奥氏体最不稳定；(3)M_s水平线以下为马氏体转变区（变温形成，与时间无关）；(4)合金元素（除Co外）使C曲线右移（提高过冷奥氏体稳定性）；⑤碳含量影响C曲线位置与M_s。\n\n应用：(1)制定等温热处理工艺（等温淬火、等温退火、分级淬火）；(2)定性分析连续冷却转变（需用CCT更精确）；(3)判断钢的淬透性（C曲线越靠右，淬透性越好）。","tags":["第六章 固态相变及热处理原理","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q070","front":"6.4 简述CCT曲线与TTT曲线的区别及临界冷却速度","back":"CCT曲线：过冷奥氏体连续冷却转变曲线（CCT），表示不同冷却速度下连续冷却时转变的起止温度与产物。\n\n与TTT的区别：(1)冷却方式不同：TTT为等温，CCT为连续冷却；(2)CCT曲线整体向右下方偏移（连续冷却时转变被推迟至更低温度、更长时间）；(3)连续冷却时贝氏体转变区缩小甚至消失（中碳钢空冷难获得贝氏体）——CCT只有珠光体区与马氏体区；(4)CCT可直接读临界冷却速度V_k。\n\n临界冷却速度V_k：使过冷奥氏体不发生珠光体（及贝氏体）转变而全部转变为马氏体的最小冷却速度（CCT曲线与珠光体转变线相切的冷却速度）。V_k越小，淬透性越好。\n\n应用：CCT是制定淬火、正火、退火工艺的直接依据。","tags":["第六章 固态相变及热处理原理","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q071","front":"6.5 简述珠光体相变（共析转变）的机制","back":"共析转变：γ(0.77%C)→α(0.02%C)+Fe_3C(6.69%C)——扩散型相变，产物为铁素体与渗碳体交替的层片状组织（珠光体）。\n\n形核：优先在奥氏体晶界（能量高、成分与结构起伏有利）形核。晶核多为渗碳体（或铁素体），一个晶核可同时向两侧生长出两相。\n\n协同长大：渗碳体片前沿的奥氏体贫碳，为铁素体析出提供条件；铁素体片前沿的奥氏体富碳，又促进渗碳体析出——两相交替向奥氏体内推进（“接力”式协同长大）。碳通过扩散由铁素体前沿输运至渗碳体前沿。\n\n片间距：由过冷度决定：λ∝1/Δ T。过冷度大，片间距小，相界面多，强度硬度高（P/S/T差别）。\n\n控制因素：碳在奥氏体中的扩散（扩散控制型相变）。","tags":["第六章 固态相变及热处理原理","2星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q072","front":"6.6 简述马氏体相变的主要特征","back":"• 无扩散性（切变型）：原子以协调切变方式迁移，相邻原子相对位移不超过一个原子间距，无成分变化，转变可在极低温度快速进行。\n\n• 表面浮凸：切变使预先抛光的试样表面产生浮凸（宏观标志）。\n\n• 严格位向关系：K-S关系111_γ∥110_α'、<110>_γ∥<111>_α'；N-W关系等。\n\n• 转变不完全性：存在残余奥氏体——M_f低于室温时淬火后残留未转变奥氏体。\n\n• 变温形成：在M_s~ M_f间随温度降低连续进行（冷却即转变，恒温不转变——等温马氏体除外）。\n\n• 转变速度极快：片状马氏体形成时间约10^-7s。\n\n• 新相为体心正方（BCT）：含碳量越高正方度c/a越大。\n\n• 可逆性：某些合金（如NiTi）马氏体可逆转变回奥氏体（形状记忆效应）。","tags":["第六章 固态相变及热处理原理","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q073","front":"6.7 比较板条马氏体与片状马氏体的形态、亚结构与性能","back":"项目 | 板条马氏体 | 片状马氏体\n——————————————————\n含碳量 | 低碳（<0.6%C） | 高碳（>1.0%C）\n形态 | 板条束状（平行板条集团） | 透镜片状（针状，互成角度）\n亚结构 | 高密度位错（位错型） | 微细孪晶（孪晶型）\nM_s点 | 高（>300℃） | 低（可低于室温）\n转变特点 | 板条间小角度晶界 | 片间大角度晶界，先形成片分割奥氏体\n性能 | 强而韧（强度高+韧性好） | 硬而脆（硬度极高、韧性差）\n\n本质联系：含碳量决定M_s高低，M_s决定切变协调方式——低碳M_s高，位错滑移协调切变（位错型）；高碳M_s低，孪生协调切变（孪晶型）。\n\n工程意义：低碳低合金钢淬火获得板条马氏体（强韧）；高碳钢淬火得片状马氏体（硬脆），需回火改善韧性；中碳钢为两者混合。","tags":["第六章 固态相变及热处理原理","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q074","front":"6.8 影响$M_s$点的主要因素有哪些？","back":"• 化学成分（最主要）：\n\n• 含碳量：C升高M_s显著降低（约每1%C降低约300℃）——碳固溶强化奥氏体、增大切变阻力，高碳钢M_s可降至室温以下；\n\n• 合金元素：除Co、Al外，多数合金元素（Mn、Cr、Ni、Mo、Si等）均降低M_s。\n\n• 奥氏体化条件：温度升高、保温延长使奥氏体成分均匀、晶粒粗大，M_s略升高（晶界减少、切变阻力减小）；未溶碳化物使奥氏体含碳量降低，M_s升高。\n\n• 冷却速度：一般影响不大，但超高速冷却可抑制碳扩散使M_s略降（碳来不及偏聚）。\n\n• 应力与塑性变形：拉应力、压应力促进马氏体转变，升高M_s；弹性应变也升高M_s；塑性变形可诱发马氏体（形变诱发马氏体，M_d）。\n\n意义：M_s决定淬火后马氏体形态、残余奥氏体量与性能。","tags":["第六章 固态相变及热处理原理","2星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q075","front":"6.9 简述贝氏体转变的特点及上、下贝氏体的比较","back":"转变特点（半扩散型）：(1)铁素体以切变方式形成（铁原子不扩散，与母相保持共格）；(2)碳原子发生扩散（转变温度高于M_s，碳可扩散）——过饱和碳从铁素体中析出碳化物或扩散至奥氏体；(3)转变温度介于珠光体与马氏体之间（550℃~ M_s）。\n\n上、下贝氏体比较：\n\n项目 | 上贝氏体 | 下贝氏体\n————————————————\n形成温度 | 550~350℃ | 350℃~ M_s\n形态 | 羽毛状（铁素体板条间分布断续条状渗碳体） | 针状（铁素体针内弥散细粒状/短条状碳化物）\n碳化物位置 | 板条之间 | 铁素体针内\n碳化物形态 | 断续条状（较粗） | 细小弥散\n性能 | 强度低、韧性差（碳化物粗大易开裂） | 强韧性好（细碳化物弥散强化）\n\n应用：等温淬火获得下贝氏体——强韧性配合好、变形开裂小，用于弹簧、齿轮、工模具。","tags":["第六章 固态相变及热处理原理","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q076","front":"6.10 简述过饱和固溶体脱溶分解的过程（GP区→过渡相→平衡相）","back":"过饱和固溶体（固溶处理+淬火获得）在时效时脱溶析出，产物按顺序演变：\n\n• GP区：时效初期，溶质原子在基体特定晶面偏聚形成的富溶质微区。无独立晶体结构（与基体相同），与基体完全共格，尺寸仅几纳米（几个原子层厚）。共格应变场阻碍位错运动——开始强化。\n\n• 过渡相（亚稳相）：GP区长大、有序化后形成有独立晶体结构的亚稳相，与基体共格或半共格（如Al-Cu合金的θ''、θ'相）。强化效果最强（峰值时效组织）。\n\n• 平衡相：继续时效，过渡相转变为平衡相（如θ相CuAl_2），与基体非共格，颗粒粗化（Ostwald熟化），共格应变丧失，间距增大——过时效，强度下降。\n\n完整序列（Al-Cu）：过饱和α→GP区→θ''→θ'→θ(CuAl_2)。\n驱动力：过饱和固溶体与平衡态的化学自由能差。","tags":["第六章 固态相变及热处理原理","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q077","front":"6.11 简述时效硬化（脱溶强化）的机制及时效曲线","back":"强化机制（位错与析出相交互作用）：\n\n• 切过机制：析出相细小、共格、可变形时，位错切过颗粒。需克服：共格应变场阻力、界面能（化学）阻力、模量差阻力（及有序化阻力）。随颗粒长大，切割阻力增大，强度升高（欠时效阶段）。\n\n• 绕过机制（Orowan）：析出相粗大、非共格、不可变形时，位错绕过颗粒留下位错环。强化量Δτ=Gb/L（L为颗粒间距）——颗粒越粗、间距越大，强化越小（过时效阶段）。\n\n时效曲线（硬度-时间）：欠时效（硬度升，切过）→峰值时效（切过与绕过临界，硬度最高）→过时效（硬度降，绕过+颗粒粗化）。\n\n温度影响：温度升高，扩散加快，时效加速，峰值提前但峰值硬度降低（颗粒易粗化）；自然时效（室温）慢而峰值高。\n\n影响因素：固溶温度（决定过饱和度）、时效温度与时间、合金成分。","tags":["第六章 固态相变及热处理原理","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q078","front":"6.12 什么是调幅分解？与一般脱溶有何区别？","back":"定义：过饱和固溶体在Spinodal（不稳分解）线以内成分范围内，不需形核，通过成分起伏直接放大（上坡扩散）自发分解为成分周期性调制的两相混合组织的分解方式。\n\n特征：(1)无临界形核与形核功——成分微小起伏即使系统自由能降低；(2)上坡扩散（溶质由低浓度向高浓度扩散）；(3)两相成分连续变化至平衡值，界面模糊弥散；(4)两相保持共格，组织为周期性的富溶质/贫溶质交替结构。\n\n与一般脱溶（形核长大型）区别：\n\n项目 | 一般脱溶 | 调幅分解\n————————————————\n形核 | 需要（有形核功） | 不需要\n自由能曲线 | ^2G/ C^2>0（亚稳） | ^2G/ C^2<0（不稳）\n成分变化 | 突变（新相平衡成分） | 连续渐进\n扩散方向 | 下坡扩散 | 上坡扩散\n\n实例：Al-Zn合金、Fe-Cr合金、Cu-Ni-Sn等。","tags":["第六章 固态相变及热处理原理","2星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q079","front":"6.13 简述淬透性与淬硬性的区别及影响因素","back":"淬硬性：钢淬火后马氏体能达到的最高硬度。主要取决于马氏体的含碳量（C含量越高，过饱和度越大、晶格畸变越强，硬度越高）；合金元素影响小。\n\n淬透性：钢淬火时获得淬硬层（马氏体层）深度的能力，即钢被淬透的难易程度。取决于过冷奥氏体的稳定性（C曲线位置）：C曲线越靠右、V_k越小，淬透性越好。\n\n影响因素（淬透性）：\n\n• 合金元素：除Co外均提高淬透性（推迟珠光体、贝氏体转变，如Mn、Cr、Ni、Mo、Si、B微量即显著）；\n\n• 奥氏体晶粒度：晶粒粗大减少晶界形核位置，提高淬透性；\n\n• 奥氏体化温度与均匀性：温度高、成分均匀，淬透性提高；\n\n• 未溶第二相：未溶碳化物促进形核，降低淬透性。\n\n举例：T12高碳钢淬硬性高（含碳1.2%）但淬透性差；40CrNiMo淬硬性中等（0.4%C）但淬透性优异——两者是独立概念，不可混淆。","tags":["第六章 固态相变及热处理原理","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q080","front":"6.14 简述铁碳相图中各特征点、线、区及典型成分","back":"特征点：A（纯铁熔点1538℃）、C（共晶点1148℃、4.3%C）、E（碳在γ中最大溶解度1148℃、2.11%C）、G（γα同素异构点912℃）、P（碳在α中最大溶解度727℃、0.0218%C）、S（共析点727℃、0.77%C）、F（渗碳体6.69%C）。\n\n特征线：A_3（GS线，γ开始析出α）、A_cm（ES线，γ开始析出Fe_3C）、A_1（PSK线，共析线727℃）、A_cm共晶线ECF（1148℃）。\n\n相区：液相L、γ奥氏体区、α铁素体区、两相区（L+γ、L+Fe_3C、γ+α、γ+Fe_3C、α+Fe_3C）、Fe_3C渗碳体。\n\n典型成分分类：工业纯铁（<0.0218%C）、钢（0.0218~2.11%C：亚共析<0.77%、共析0.77%、过共析>0.77%）、白口铸铁（2.11~6.69%C：亚共晶<4.3%、共晶4.3%、过共晶>4.3%）。\n\n基本转变：共析转变Lγα+Fe_3C（727℃）、共晶转变Lγ+Fe_3C（1148℃）。","tags":["第六章 固态相变及热处理原理","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q081","front":"6.15 用杠杆定律计算亚共析钢室温组织组成（举例0.45\\%C钢）","back":"杠杆定律：两相区中，两相（或两组织）的相对量按\"杠杆\"反比分配：w_α=C_β-C_0/C_β-C_α。\n\n例：0.45%C亚共析钢缓冷至室温，组织为先共析铁素体（α，0.0218%C近似0.02%）与珠光体（P，0.77%C）：\n\nw(α)=0.77-0.45/0.77-0.02×100%=0.32/0.75≈42.7%\n\nw(P)=0.45-0.02/0.77-0.02×100%=0.43/0.75≈57.3%\n\n过共析钢（如1.2%C）：组织为二次渗碳体（Fe_3C_II，沿晶界网状）与珠光体：\n\nw(Fe_3C_II)=1.2-0.77/6.69-0.77×100%≈7.3%, w(P)≈92.7%\n\n要点：(1)杠杆定律适用于两相/两组织平衡共存；(2)组织组成物与相组成物要区分（室温相组成：α+Fe_3C）；(3)注意杠杆端点取对应成分点。","tags":["第六章 固态相变及热处理原理","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q082","front":"6.16 简述亚共析钢、共析钢、过共析钢的室温平衡组织及转变过程","back":"共析钢（0.77%C）：冷至A_1（727℃）时全部奥氏体发生共析转变γ_0.77→α_0.02+Fe_3C，室温组织为100%珠光体（层片状α+Fe_3C）。\n\n亚共析钢（0.0218%~0.77%C）：(1)冷至A_3线开始析出先共析铁素体（沿奥氏体晶界），随温度降低铁素体量增多，剩余奥氏体含碳量沿A_3线升高；(2)至727℃时剩余奥氏体达0.77%，发生共析转变；(3)室温组织=先共析铁素体（白色块状）+珠光体（层片状）。含碳量越高珠光体越多。\n\n过共析钢（0.77%~2.11%C）：(1)冷至A_cm线开始沿奥氏体晶界析出二次渗碳体（网状）；(2)至727℃剩余奥氏体（0.77%C）共析转变；(3)室温组织=网状二次渗碳体+珠光体。含碳量越高二次渗碳体越多。\n\n性能规律：亚共析钢含碳量升高强度升高（珠光体增多）但塑性韧性下降；过共析钢网状渗碳体使脆性显著增大。","tags":["第六章 固态相变及热处理原理","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q083","front":"6.17 简述渗碳体的形态及其对钢性能的影响","back":"渗碳体（Fe_3C，6.69%C，正交晶系）硬而脆（硬度约800HB，塑性近零），是钢中主要强化相。形态不同影响不同：\n\n• 层片状（珠光体/索氏体/屈氏体）：片间距越小强度越高（相界面多阻碍位错）。共析渗碳体使钢强度硬度显著高于铁素体。\n\n• 粒状（球状）：球化退火获得，粒状渗碳体对基体割裂小，强韧性配合好，切削性好（粒状珠光体）。\n\n• 网状（沿晶界）：过共析钢缓冷沿晶界析出，割裂晶界、严重降低冲击韧性，需正火消除。\n\n• 一次渗碳体（液相析出，粗大板条）：白口铸铁中，极硬脆。\n\n• 二次渗碳体（γ中析出）、三次渗碳体（α中析出，微量）：前者网状有害，后者量极少。\n\n总结：渗碳体是钢强度的主要贡献者，但形态与分布决定韧塑性——细、匀、粒状有利；粗、网、连续有害。","tags":["第六章 固态相变及热处理原理","2星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q084","front":"6.18 含碳量对碳钢力学性能的影响规律","back":"亚共析钢（0.0218~0.77%C）：随含碳量增加，珠光体量增多：强度、硬度升高，塑性、韧性下降。因为珠光体（α+Fe_3C层片）强度远高于铁素体。\n\n过共析钢（0.77~2.11%C）：随含碳量增加，网状二次渗碳体增多：硬度继续升高，但强度开始下降（约1.0%C后）、塑性韧性急剧下降（网状渗碳体割裂晶界，脆性大）。\n\n总结规律：(1)硬度随含碳量单调升高；(2)强度先升后降（约0.8~1.0%C达峰值）；(3)塑性、韧性单调下降；(4)焊接性、锻造性下降，切削性在0.4~0.6%C最佳（中碳钢综合性能好，应用最广）。\n\n原因本质：渗碳体量增加（强化）与渗碳体形态恶化（网状、粗大）竞争的结果。","tags":["第六章 固态相变及热处理原理","2星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q085","front":"6.19 共析钢三种热处理对比：完全退火、正火、淬火+低温回火的组织与性能","back":"① 完全退火（Ac1以上30~50℃长时保温、随炉缓冷）：组织为层片状珠光体P，片间距较大。性能：硬度强度最低（约180HB），塑性好。用途：改善铸锻组织缺陷、降低硬度便于切削。\n\n② 正火（Ac1以上30~50℃保温、空冷）：冷速较快、过冷度较大，组织为细片状珠光体（索氏体S）。性能：强度硬度比退火高（约230HB）。用途：提高硬度与切削性、作不太重要零件的最终热处理、为淬火作组织准备。\n\n③ 淬火+低温回火（Ac1以上保温、水/油快冷得马氏体M+残余奥氏体，再150~250℃回火）：组织为回火马氏体M回。性能：硬度最高（HRC60+）耐磨，脆性较大。用途：刀具、量具、轴承等高硬度耐磨场合。\n\n关键逻辑链：冷却速度（炉冷→空冷→水冷）决定转变产物（P→S→M），组织决定性能（软韧→较强→高硬脆）。","tags":["第六章 固态相变及热处理原理","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q086","front":"7.1 简述钢的奥氏体化（加热转变）过程及影响因素","back":"奥氏体化四阶段：\n\n• 奥氏体形核：优先在铁素体/渗碳体相界面处形核（成分与结构起伏有利、能量高）。\n\n• 奥氏体长大：奥氏体同时向铁素体侧与渗碳体侧推进——碳在铁素体中扩散快、在奥氏体中扩散慢，长大受碳在奥氏体中扩散控制（奥氏体前沿碳浓度差驱动）。\n\n• 剩余渗碳体溶解：铁素体先消失，剩余渗碳体继续溶入奥氏体（碳化物溶解）。\n\n• 奥氏体均匀化：碳在奥氏体中继续扩散，成分均匀化（需保温）。\n\n影响因素：\n\n• 加热温度与速度：温度越高、速度越快，转变越快（扩散加速、过热度大）。\n\n• 原始组织：片状珠光体（相界面多）比粒状珠光体奥氏体化快；组织越细越快。\n\n• 合金元素：Cr、Mo、W、V等强碳化物形成元素减慢奥氏体化（碳化物稳定难溶）；Co、Ni加快；合金元素还影响碳的扩散与均匀化。\n\n• 保温时间：保证均匀化。","tags":["第七章 钢的热处理工艺","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q087","front":"7.2 什么是本质晶粒度与实际晶粒度？说明其意义","back":"本质晶粒度：钢在930℃保温3~8小时后奥氏体的晶粒度，反映奥氏体晶粒长大的倾向（钢的固有特性）。本质细晶粒钢：930℃仍保持细晶（用Al脱氧，AlN弥散质点钉扎晶界；或含Ti、V、Nb）；本质粗晶粒钢：930℃晶粒明显长大（Mn、P促进长大）。\n\n实际晶粒度：钢在具体热处理工艺条件下获得的奥氏体晶粒度，取决于本质晶粒度与实际加热温度、时间。\n\n意义：(1)本质晶粒度是选材依据（要求热处理变形小、韧性好的零件选本质细晶粒钢）；(2)实际晶粒度决定淬火后马氏体粗细与性能——晶粒越细，马氏体越细，强韧性越好；(3)过热（实际晶粒粗大）可通过正火补救。","tags":["第七章 钢的热处理工艺","2星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q088","front":"7.3 简述退火的种类、目的及适用范围","back":"退火：钢加热到适当温度保温后缓慢冷却（炉冷）的热处理，目的为软化、细化晶粒、消除应力、均匀成分。\n\n种类：\n\n• 完全退火：加热至Ac_3+30~50℃，炉冷。用于亚共析钢铸锻件——细化晶粒、消除内应力、降低硬度改善切削性。\n\n• 不完全退火：加热至Ac_1+30~50℃（两相区），炉冷。用于过共析钢降低硬度消除应力（不改变渗碳体形态）。\n\n• 等温退火：加热奥氏体化后快冷至A_1以下等温，使珠光体等温转变。用于合金钢（C曲线右移，普通退火周期长）——组织均匀、周期短。\n\n• 球化退火：加热至Ac_1+20~30℃保温后缓冷或等温，使渗碳体球化。用于过共析钢（工具钢、轴承钢）——降低硬度、改善切削性、为淬火准备（粒状碳化物淬火变形小）。\n\n• 去应力退火：加热至500~650℃（低于Ac_1）保温缓冷。无相变，消除内应力——铸锻焊件、精密件。\n\n• 再结晶退火：冷变形金属加热至再结晶温度以上，消除加工硬化恢复塑性——冷轧/冷拔中间退火。\n\n• 扩散退火（均匀化）：加热至1050~1200℃长时间保温，消除枝晶偏析——合金钢锭。晶粒粗大，需后续细化。","tags":["第七章 钢的热处理工艺","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q089","front":"7.4 比较正火与退火的区别及应用选择","back":"项目 | 退火 | 正火\n————————————\n冷却方式 | 炉冷（最慢） | 空冷（较快）\n过冷度 | 小 | 较大\n组织 | 珠光体型（较粗） | 索氏体型（较细）\n硬度强度 | 较低 | 较高\n内应力 | 小 | 较大\n周期成本 | 长、高 | 短、低\n\n应用选择：\n\n• 低碳钢：用正火（退火太软粘刀，正火提高硬度改善切削性）。\n\n• 中碳钢：正火可作淬火前预备热处理（细化晶粒）；要求软化彻底用退火。\n\n• 过共析钢：正火消除网状二次渗碳体（空冷抑制网状析出），再球化退火；不宜完全退火（网状渗碳体恶化）。\n\n• 大型铸锻件、形状复杂件：用退火（正火应力大易变形开裂）。\n\n• 普通结构件：正火可直接作最终热处理（性能要求不高时）。","tags":["第七章 钢的热处理工艺","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q090","front":"7.5 为什么过共析钢采用球化退火而不进行完全退火？","back":"原因：(1)完全退火需加热至A_cm以上（完全奥氏体化），缓冷时二次渗碳体沿奥氏体晶界呈网状析出——网状渗碳体割裂基体、严重降低冲击韧性，恶化性能；(2)球化退火加热至Ac_1+20~30℃（略高于A_1），保留大量未溶渗碳体颗粒作为形核核心，缓冷/等温时渗碳体以粒状析出并长大——获得粒状珠光体。\n\n球化退火的目的：(1)降低硬度（粒状珠光体硬度低于片状），改善切削加工性；(2)为淬火做准备：粒状渗碳体淬火加热时溶解均匀、残余颗粒提高耐磨性，且淬火变形开裂倾向小；(3)消除网状渗碳体（先经正火消除后球化）。\n\n应用：碳素工具钢（T8、T10、T12）、轴承钢（GCr15）等过共析钢的预备热处理。","tags":["第七章 钢的热处理工艺","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q091","front":"7.6 简述淬火的定义、加热温度选择原则及淬火方法","back":"定义：将钢加热到临界温度以上保温，以大于临界冷却速度V_k冷却，获得马氏体（或下贝氏体）组织的热处理工艺。\n\n加热温度选择：\n\n• 亚共析钢：Ac_3+30~50℃（完全淬火）——必须完全奥氏体化，否则淬火组织中残留铁素体（软点），硬度不足。\n\n• 共析钢、过共析钢：Ac_1+30~50℃（不完全淬火）——过共析钢保留部分粒状渗碳体（提高耐磨性、稳定性），避免加热过高（晶粒粗大、脱碳、淬裂）。\n\n淬火方法：\n\n• 单液淬火：水中或油中冷到底。简单，但水淬变形开裂大、油淬可能硬度不足。\n\n• 双液淬火：先水冷至M_s附近（避开珠光体区），立即转入油中冷至室温。减小组织应力，适合形状复杂碳钢件。\n\n• 分级淬火：淬入略高于M_s的盐浴，待内外温度均匀后取出空冷。马氏体在缓冷中形成，应力小、变形小，适合小尺寸精密件。\n\n• 等温淬火：淬入M_s以上的盐浴等温，获得下贝氏体。强韧性好、变形极小，适合弹簧、齿轮、工模具。","tags":["第七章 钢的热处理工艺","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q092","front":"7.7 简述淬火时常见缺陷及其防止措施","back":"• 氧化与脱碳：加热时表面氧化（氧化皮）与脱碳（表层碳烧损，硬度不足）。防止：盐浴炉、保护气氛（氮气、甲醇裂解气）、真空炉、涂料保护。\n\n• 过热与过烧：过热=加热过高晶粒粗大（淬火后马氏体粗大、韧性差，可正火补救）；过烧=接近液相线，晶界氧化熔化（报废）。防止：严格控制加热温度与时间。\n\n• 变形与开裂：热应力+组织应力叠加（组织应力为主，发生在M_s以下快冷区）。防止：合理选材与设计（壁厚均匀、避免尖角）、预热、分级/等温淬火、及时回火。\n\n• 硬度不足（软点）：表面不清洁、冷却不均、加热不足（铁素体残留）。防止：表面清理、搅拌冷却介质、正确加热。\n\n• 残余奥氏体过多：高碳钢淬火后残余奥氏体多（M_f低于室温），硬度低、尺寸不稳定。防止：深冷处理（冷至M_f以下）。","tags":["第七章 钢的热处理工艺","2星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q093","front":"7.8 简述回火的目的及淬火钢回火时的组织转变过程","back":"回火目的：(1)消除淬火残余应力（防止变形开裂）；(2)稳定组织与尺寸；(3)调整力学性能（在强度与韧性间获得合理配合）。淬火+回火是不可分割的最终热处理。\n\n回火四阶段（淬火钢加热回火时）：\n\n• 马氏体分解（80~200℃）：过饱和碳以ε碳化物（Fe_2.4C）弥散析出，马氏体正方度下降，得到回火马氏体（M'）。硬度略降，韧性改善。\n\n• 残余奥氏体转变（200~300℃）：残余奥氏体分解为回火马氏体或下贝氏体。\n\n• 碳化物转变（250~400℃）：ε碳化物转变为Fe_3C渗碳体，得到回火屈氏体。硬度进一步降低，弹性极限较高。\n\n• 碳化物长大与铁素体再结晶（>400℃）：渗碳体球化长大，铁素体再结晶为等轴晶，得到回火索氏体。强度降低、塑性韧性提高，综合力学性能好。","tags":["第七章 钢的热处理工艺","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q094","front":"7.9 比较低温回火、中温回火、高温回火的温度、组织与用途","back":"类型 | 温度 | 组织 | 性能与用途\n————————————————————\n低温回火 | 150~250℃ | 回火马氏体 | 高硬度高耐磨、内应力部分消除；工模具、渗碳件、轴承、量具\n中温回火 | 350~500℃ | 回火屈氏体 | 高弹性极限、一定韧性；弹簧、发条、锻模\n高温回火 | 500~650℃ | 回火索氏体 | 良好综合力学性能（强韧配合）；轴、齿轮、连杆、螺栓（调质件）\n\n要点：(1)调质处理=淬火+高温回火，结构件最常用；(2)回火温度越高，强度硬度越低、塑性韧性越高；(3)避开250~400℃回火（第一类回火脆性区）；(4)高温回火后快冷防止第二类回火脆性。","tags":["第七章 钢的热处理工艺","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q095","front":"7.10 比较第一类回火脆性与第二类回火脆性","back":"项目 | 第一类（低温）回火脆性 | 第二类（高温）回火脆性\n——————————————————————————————\n温度 | 250~400℃ | 450~650℃\n可否逆 | 不可逆（一旦发生重新加热不能消除） | 可逆（重新加热至600℃以上快冷可消除）\n产生原因 | 碳化物沿马氏体板条/片界析出（ε碳化物转变）及杂质偏聚 | P、Sb、Sn、As等杂质在奥氏体晶界偏聚，降低晶界结合力\n断口特征 | 沿晶/准解理 | 沿晶（冰糖状）\n防止措施 | 避免在该温度回火；用等温淬火替代 | 回火后快冷（油冷/水冷）；加入Mo、W（0.3~0.5%）；提高钢纯净度\n\n记忆：第一类\"不可救\"（避开），第二类\"可救\"（快冷+Mo）。","tags":["第七章 钢的热处理工艺","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q096","front":"7.11 简述调质处理及其应用","back":"定义：淬火+高温回火（500~650℃）的双重热处理工艺。\n\n工艺：(1)淬火：亚共析钢加热至Ac_3+30~50℃，水冷或油冷获得马氏体（中碳钢以板条马氏体为主）；(2)高温回火：500~650℃保温后冷却（注意防第二类回火脆性，含Mo钢可空冷，否则回火后快冷），获得回火索氏体。\n\n组织：回火索氏体——铁素体基体（等轴晶）上均匀分布细小粒状渗碳体。\n\n性能：强度、硬度适中（如45钢调质后σ_b≈650MPa，硬度220~250HB），塑性韧性良好，综合力学性能优良——\"强韧兼备\"。\n\n应用：承受交变载荷与冲击载荷的结构件：轴类、齿轮、连杆、螺栓、曲轴等；也作为表面淬火、渗氮的预备热处理。典型钢种：45钢、40Cr、42CrMo。\n\n对比：调质（回火索氏体）优于正火（层片状索氏体）——粒状渗碳体对基体割裂小，强韧性配合更好。","tags":["第七章 钢的热处理工艺","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q097","front":"7.12 简述回火稳定性与二次硬化","back":"回火稳定性（抗回火性）：淬火钢在回火过程中抵抗硬度下降的能力。合金元素（尤其Cr、Mo、W、V等强碳化物形成元素）溶入马氏体后：(1)阻碍碳扩散；(2)推迟碳化物形核聚集长大——使软化推迟，同样回火温度下硬度更高。回火稳定性高的钢可在更高温度回火而保持较高硬度，获得更好韧性。\n\n二次硬化：含W、Mo、V等强碳化物形成元素的高合金钢（高速钢）在500~600℃回火时，硬度不降反升的现象。原因：(1)回火时从马氏体中析出弥散细小的特殊碳化物（W_2C、Mo_2C、VC等）产生强烈弥散强化；(2)回火冷却时残余奥氏体转变为马氏体（二次淬火）。二者共同作用使硬度回升。\n\n意义：二次硬化是高速钢红硬性（600℃保持HRC60以上）的基础；高速钢采用1270~1280℃淬火+560℃多次回火获得二次硬化效果。","tags":["第七章 钢的热处理工艺","2星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q098","front":"7.13 简述表面淬火的原理、方法及适用钢种","back":"原理：快速加热使表层迅速奥氏体化（心部仍为室温组织），随即快速冷却——表层获得马氏体（高硬度高耐磨），心部保持原组织（强韧性好），实现\"表硬里韧\"。\n\n方法：\n\n• 感应加热表面淬火：交变电流感应涡流（集肤效应）加热表层。频率越高淬硬层越浅：高频（200~300kHz）0.5~2mm、中频（2.5~10kHz）2~8mm、工频（50Hz）10~20mm。加热快（秒级）、效率高、变形小、易自动化——齿轮、轴、曲轴等大批量件。\n\n• 火焰加热表面淬火：氧-乙炔火焰加热表层后喷水冷却，淬硬层2~8mm。设备简单灵活，质量不易精确控制——大型件、单件小批（大齿轮、轧辊）。\n\n适用钢种：中碳钢（0.40~0.50%C）与中碳合金钢（40、45、40Cr、42CrMo）、球墨铸铁。低碳钢表面淬火硬度不足，高碳钢心部脆。\n\n预备热处理：正火或调质（保证心部性能）；表面淬火后低温回火（180~200℃）消除应力。","tags":["第七章 钢的热处理工艺","2星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q099","front":"7.14 比较渗碳与渗氮的工艺特点及应用","back":"项目 | 渗碳 | 渗氮（氮化）\n————————————————\n渗入元素 | C | N\n温度 | 920~950℃（奥氏体区） | 500~570℃（铁素体区）\n适用钢种 | 低碳钢/低碳合金钢（20、20Cr、20CrMnTi） | 含Al、Cr、Mo的渗氮钢（38CrMoAlA）\n介质 | 气体渗碳（煤油+甲醇/丙烷）等 | 氨气（分解产生活性N）\n表面组织 | 高碳马氏体+碳化物 | 氮化物层（Fe_2-3N、Fe_4N、AlN、CrN）\n渗后处理 | 必须淬火+低温回火 | 不需热处理（温度低无相变）\n硬度 | 58~62HRC | 1000~1200HV（更高）\n变形 | 较大 | 极小（渗后直接使用）\n红硬性 | 一般 | 好（500~600℃保持高硬度）\n渗层深度 | 0.5~2mm | 0.1~0.6mm（薄）\n周期 | 数小时~十几小时 | 数十小时（长）\n应用 | 齿轮、凸轮轴、活塞销（外硬内韧） | 精密齿轮、主轴、模具、阀门（耐磨+变形小）\n\n共同点：都是化学热处理（分解-吸收-扩散三过程）；都实现\"表硬里韧\"。","tags":["第七章 钢的热处理工艺","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q100","front":"7.15 简述化学热处理的基本过程及应用","back":"定义：将工件置于活性介质中加热保温，使活性原子渗入表层改变其化学成分与组织，获得所需性能的热处理工艺（渗碳、渗氮、碳氮共渗、渗金属等）。\n\n三个基本过程：\n\n• 分解：活性介质在高温下分解产生活性原子（如2NH_3→2[N]+3H_2；CH_4→[C]+2H_2）。\n\n• 吸收：活性原子被工件表面吸附并溶入表层（形成固溶体或化合物）。\n\n• 扩散：渗入原子向内部扩散形成渗层（Fick定律控制，渗层深度x∝√(Dt)）。\n\n影响因素：温度（加速分解与扩散）、时间、介质活性（碳势/氮势）、钢的成分。\n\n应用：(1)渗碳：齿轮、凸轮轴（外硬内韧）；(2)渗氮：精密件（变形小、硬度高）；(3)碳氮共渗：汽车齿轮（温度低、性能好）；(4)渗金属（渗铝抗氧化、渗铬耐磨耐蚀）。","tags":["第七章 钢的热处理工艺","2星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q101","front":"7.16 简述高速钢（W18Cr4V）的热处理工艺及特点","back":"预备热处理：球化退火——降低硬度（便于切削加工）、消除锻造应力、为淬火准备组织。\n\n最终热处理：\n\n• 淬火：1270~1280℃高温淬火（油冷或分级/等温淬火）。温度高是为了使W、Mo、V的碳化物充分溶解于奥氏体（保证淬火后马氏体中合金元素含量，为二次硬化做准备）；晶粒虽粗化（4~5级）但可接受。\n\n• 回火：560℃回火3次（每次1小时）。目的：(1)二次硬化——析出W_2C、VC等弥散特殊碳化物，硬度回升至63~66HRC；(2)残余奥氏体在回火冷却时转变为马氏体（二次淬火），多次回火逐步消除残余奥氏体（稳定尺寸）；(3)消除应力。\n\n组织：回火马氏体+粒状碳化物+少量残余奥氏体。\n\n性能特点：高硬度（63~66HRC）、高红硬性（600℃仍保持60HRC以上）、高耐磨性——用于高速切削刀具。","tags":["第七章 钢的热处理工艺","2星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q102","front":"7.17 简述滚动轴承钢GCr15的热处理工艺","back":"GCr15（含碳约1.0%，含铬1.5%）为过共析钢，要求高硬度、高耐磨、高疲劳强度与尺寸稳定。\n\n工艺路线：\n\n• 预备热处理：球化退火（Ac_1+20~30℃缓冷/等温）——粒状珠光体，降低硬度改善切削性，为淬火准备。\n\n• 淬火：830~850℃加热（油冷）——获马氏体+粒状碳化物+残余奥氏体。温度控制严格（过高晶粒粗大、残余A多；过低硬度不足）。\n\n• 低温回火：150~160℃——回火马氏体+粒状碳化物，硬度61~65HRC，消除应力。\n\n• （精密轴承）附加处理：冷处理（-60~-80℃）减少残余奥氏体、稳定尺寸；精磨后时效处理（130~150℃时效）稳定尺寸。\n\n组织：回火马氏体+细小均匀粒状碳化物+少量残余奥氏体。粒状碳化物保证耐磨性，回火马氏体保证硬度与疲劳强度。","tags":["第七章 钢的热处理工艺","1星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q103","front":"7.18 简述弹簧钢的热处理及性能要求","back":"性能要求：高的弹性极限与屈服比（σ_s/σ_b）、高的疲劳强度、一定韧性。\n\n典型钢种：65Mn、60Si2Mn（中碳高锰/高硅弹簧钢）。\n\n热处理工艺：\n\n• 淬火：Ac_3+30~50℃（约840~880℃），油冷（截面大的水淬油冷）——获马氏体。\n\n• 中温回火：380~480℃——获回火屈氏体（铁素体基体+极细粒状渗碳体），具有高的弹性极限与屈强比。\n\n特点：(1)采用中温回火而非高温回火——高温回火虽韧性好但弹性极限不足；(2)回火温度须避开第一类回火脆性区（250~400℃）；(3)表面质量重要（脱碳、划伤降低疲劳强度）；(4)大型弹簧可等温淬火获得下贝氏体（强韧性更好）；⑤喷丸强化提高疲劳寿命。\n\n组织：回火屈氏体（弹性极限最高）。","tags":["第七章 钢的热处理工艺","1星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q104","front":"7.19 简述奥氏体不锈钢的固溶处理及作用","back":"固溶处理：将奥氏体不锈钢（如304、1Cr18Ni9Ti）加热至1050~1100℃（单相奥氏体区），保温后快速水冷的热处理工艺。\n\n作用：\n\n• 获得单相奥氏体组织：加热时碳化物（Cr_23C_6）等溶入奥氏体，快冷抑制其重新析出，室温获得均匀单相奥氏体。\n\n• 提高耐蚀性：消除晶界贫铬（Cr_23C_6沿晶界析出使晶界附近贫Cr，导致晶间腐蚀），恢复耐蚀性。\n\n• 软化：消除冷加工硬化，便于加工成形。\n\n• 均匀化成分组织。\n\n注意：固溶处理是\"软化\"不是\"强化\"；快冷必须足够快（水冷），缓冷会使碳化物析出重新产生晶间腐蚀倾向；含稳定化元素（Ti、Nb）钢种可进行稳定化处理进一步防止晶间腐蚀。","tags":["第七章 钢的热处理工艺","1星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q105","front":"7.20 简述铸铁的石墨化及灰口铸铁、球墨铸铁的组织性能","back":"石墨化：铸铁中碳以石墨形式析出的过程。铸铁按石墨形态分：灰口铸铁（片状石墨）、球墨铸铁（球状石墨）、可锻铸铁（团絮状）、蠕墨铸铁（蠕虫状）。\n\n灰口铸铁：组织=钢基体（铁素体/珠光体）+片状石墨。石墨强度极低（近零）、割裂基体、尖端应力集中——抗拉强度低、塑性差；但石墨赋予：优良减振性、耐磨性（石墨润滑）、切削性、铸造性（流动性好、收缩小）。应用：机床床身、发动机缸体、泵体。\n\n球墨铸铁：通过球化处理（加Mg、RE）使石墨呈球状，石墨对基体割裂作用大大减小。强度接近钢（如QT450-10抗拉450MPa、延伸率10%），兼有钢的强度与铸铁的工艺性。应用：曲轴、连杆、齿轮箱、阀门。\n\n基体控制：通过热处理（正火、退火、等温淬火）可调节基体为铁素体、珠光体、贝氏体（奥-贝球铁ADI性能优异）。","tags":["第七章 钢的热处理工艺","1星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q106","front":"7.21 简述合金元素在钢中的主要作用","back":"• 强化铁素体（固溶强化）：Mn、Si、Cr、Ni等溶入铁素体产生固溶强化，提高强度硬度（Si、Mn强化效果显著）。\n\n• 形成碳化物：强碳化物形成元素（Ti、V、Nb、W、Mo、Cr）形成稳定碳化物——提高硬度耐磨性、阻碍奥氏体晶粒长大（细化晶粒）、二次硬化（W、Mo、V）。\n\n• 提高淬透性：除Co外均使C曲线右移，降低V_k，提高淬透性（Mn、Cr、Ni、Mo、Si、微量B）。\n\n• 细化晶粒：Al（AlN）、Ti、V、Nb等形成弥散质点钉扎晶界，细化奥氏体晶粒。\n\n• 提高回火稳定性与抗回火脆性：Cr、Mo、W、V推迟回火软化；Mo、W抑制第二类回火脆性。\n\n• 改善特殊性能：Ni提高低温韧性；Cr提高耐蚀性（不锈钢）；W、Mo、V提高红硬性（高速钢）；Si、Mn提高淬透性且Si提高弹性极限。\n\n• 扩大/缩小相区：Ni、Mn扩大奥氏体区（奥氏体钢）；Cr、Si、Ti缩小奥氏体区（铁素体钢）。","tags":["第七章 钢的热处理工艺","2星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0},{"id":"q107","front":"7.22 表硬里韧工艺设计：亚共析钢零件表面高硬度耐磨、心部综合性能好的完整热处理路线","back":"路线：锻造 → 调质 → 表面淬火 → 低温回火。（顺序不可颠倒）\n\n第一步 调质（心部性能保证）：淬火——加热至Ac3+30~50℃（约840℃）充分奥氏体化，快冷得马氏体M；高温回火——500~650℃，得回火索氏体S回（铁素体基体+细粒状Fe3C）。心部强韧兼备。\n\n第二步 表面淬火（表层硬化）：感应加热表层至Ac3以上（心部温度仍在高温回火区不发生相变），迅速水淬，表层得马氏体。\n\n第三步 低温回火（消应力防剥落）：150~250℃，表层马氏体→回火马氏体M回，消除表面淬火残余应力防止剥落，保持高硬度。\n\n最终：表层回火马氏体（高硬耐磨）+ 心部回火索氏体（强韧），即表硬里韧。\n\n易错点：若先表面淬火后调质，调质高温（>500℃）会把表层马氏体重新回火软化——顺序颠倒即全盘皆输（真题两年重复考点）。","tags":["第七章 钢的热处理工艺","3星"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0}]},{"id":"d_politics","name":"政治 · 一页纸","color":"#e11d48","v":5,"desc":"帕拉迪宇一页纸 · 317 张（文字版校订）","cards":[{"id":"c001","front":"==马恩第一个无产阶级政党==\n马克思和恩格斯建立的第一个无产阶级政党：\n{{共产主义者同盟}}","back":"","tags":["一页纸","马恩第一个无产阶级政党"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c002","front":"==上层建筑==\n在意识形态中居于核心地位，\n发挥主导作用的是{{政治法律思想}}\n政治上层建筑的核心{{国家政权}}","back":"","tags":["一页纸","上层建筑"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c003","front":"==人的本质==\n人的本质是一切社会关系的总和","back":"","tags":["一页纸","人的本质"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c004","front":"==世界的物质统一性原理==\n{{世界的物质统一性原理是}}\n辩证唯物主义最基本最核心的观点\n马克思主义的基石","back":"","tags":["一页纸","世界的物质统一性原理"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c005","front":"==理解政治经济学的枢纽🇷🇺🚁==\n{{✅牢二枢纽}}\n理解政治经济学的{{枢纽}}：\n{{劳}}动{{二}}重性理论\n{{⚠️}}辨析：\n马克思经济学说的核心内容和基石是：\n剩余价值理论","back":"","tags":["一页纸","理解政治经济学的枢纽🇷🇺🚁"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c006","front":"==改造主观世界的核心==\n改造世界包括改造客观世界和改造主观世界\n改造主观世界的核心是{{改造世界观}}","back":"","tags":["一页纸","改造主观世界的核心"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c007","front":"==唯物史观和剩余价值学说==\n{{唯物史观和剩余价值学说是}}\n社会主义由空想变为科学的两大基石\n马克思一生的两个伟大发现","back":"","tags":["一页纸","唯物史观和剩余价值学说"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c008","front":"==实践的三个基本特征==\n客观实在性（直接现实性）：\n实践是人类改造世界的客观物质活动\n它虽然是人类有目的、有意识的行为\n但{{本质}}上是客观的、物质的活动。\n{{能够引起客观世界的某种变化}}\n{{可以把人脑中观念的存在变为现实的存在（直接现实性）}}\n自觉能动性：\n人的实践活动是一种有目的、有意识的活动\n目的性是能动性的主要表现\n社会历史性：\n实践从一开始就是社会性的活动。\n作为实践主体的人总是处在一定社会关系中，\n任何人的活动都离不开与社会的联系。","back":"","tags":["一页纸","实践的三个基本特征"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c009","front":"==空想社会主义==\n空想社会主义的发展经历了三个阶段\n即16—17世纪的早期空想社会主义、\n18世纪的空想平均共产主义、\n19世纪初期批判的空想社会主义\n与之对应的资本主义生产方式发展所经历的阶段是\n{{家庭手工业、工场手工业和机器大工业三个阶段}}\n⚠️马克思主义与空想社会主义的根本区别在于\n是否坚持{{科学}}的立场、观点和方法","back":"","tags":["一页纸","空想社会主义"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c010","front":"==物质世界的二重化==\n物质世界的二重化指的是，\n人类改造世界的实践活动使世界发生了二重分化，\n即从自然界中分化出人类社会\n从客观世界中分化出主观世界","back":"","tags":["一页纸","物质世界的二重化"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c011","front":"==科学社会主义的核心命题==\n{{✅是2必}}\n是资本主义{{必}}然灭亡\n社会主义{{必}}然胜利\n科学社会主义基本原则之所以是正确的，就在于\n揭示了资本主义生产方式的基本矛盾\n阐明了社会主义代替资本主义的历史必然性\n一个错误说法\n必须不断{{修正}}科学社会主义原则 {{✗错误}}\n必须始终坚持科学社会主义基本原则 ✔️正确\n反对任何背离科学社会主义基本原则的错误倾向 ✔️正确","back":"","tags":["一页纸","科学社会主义的核心命题"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c012","front":"==六个寓于==\n{{价}}值{{寓}}于使用价值之中{{（J>S）驾驭}}\n{{必}}然性{{寓}}于偶然性之中{{（B>O）碧玉}}\n{{斗}}争性{{寓}}于同一性之中{{（D>T）斗鱼}}\n{{绝}}对性{{寓}}于相对性质中{{（J>X）绝育}}\n{{普}}遍性{{寓}}于特殊性之中{{（P>T）璞玉}}\n{{共}}性{{寓}}于个性之中{{（G=G）公寓}}\n🔺寓于的前面一定是绝对的东西，无条件的要寓于有条件的","back":"","tags":["一页纸","六个寓于"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c013","front":"==目标==\n人的发展是一个社会历史过程，既包括人类整体的发展，也包括人类个体的发展。 人的发展指人的体力、智力、个性和交往能力等的发展，其中{{最根本的是人的自由程度的提高}}\n马克思主义追求的{{根本}}价值目标，共产主义社会的{{根本}}特征，{{现代化的最终目标}}：\n{{实现人的自由全面的发展}}\n人类认识世界和改造世界的{{根本}}目标：{{认识必然和争取自由}}\n最高理想和最终目标：{{实现共产主义}}\n马克思主义的活的灵魂：{{对具体情况作具体分析}}","back":"","tags":["一页纸","目标"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c014","front":"==对立统一规律==\n对立统一规律是\n{{唯物辩证法的实质和核心}}\n这是因为：\n1️⃣他揭示了事物普遍联系的根本内容和变化发展的内在动力从根本上回答的事物为什么会发展的问题\n2️⃣它是贯穿质量互变规律否定之否定规律以及唯物辩证法基本范畴的中心线索也是理解这些规律和范畴的钥匙\n3️⃣他提供了人们认识世界和改造世界的根本方法—矛盾分析方法","back":"","tags":["一页纸","对立统一规律"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c015","front":"==社会存在==\n社会存在包括3方面内容\n❶自然地理环境\n❷人口因素\n❸物质生产方式（决定因素）\n⚠️社会存在和发展的基础及{{决定}}力量：{{物质生产方式}}\n物质生产方式又分为2方面内容\n❶生产力（决定因素、生产的物质内容）\n❷生产关系（生产的社会形式）","back":"","tags":["一页纸","社会存在"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c016","front":"==人类认识==\n人类认识包括知识性认识与评价性认识两个方面\n{{知识性认识}}以客观事物及其规律为对象\n以客体本身的属性、关系和发展过程为反映内容\n{{追求客体“是什么”，以求“真”为认识目的}}\n其{{中评价性认识}}也就是价值评价\n价值评价则以客体和主体之间的价值关系为反映内容\n主体的意向、愿望和要求包含在其中\n{{追求“应该怎样”，以求“善”和“美”为认识目的}}","back":"","tags":["一页纸","人类认识"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c017","front":"==马克思主义的基本特征==\n马克思主义的{{本质属性}}：{{人民性}}\n马克思主义理论区别于其他理论的{{根本特征}}（显著特征）：{{实践性}}\n{{马克思主义}}首要的，基本的观点：{{实践的观点}}\n⚠️马克思主义的基本特征一句话概括：\n{{科}}学性与革{{命}}性的统一（{{科命}}）","back":"","tags":["一页纸","马克思主义的基本特征"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c018","front":"==马克思主义的三大组成部分==\n{{马克思主义哲学是基础和方法}}\n马克思主义{{政}}治{{经}}济学是{{主体内容}}\n{{科学社会主义是目的和归宿}}\n《德意志意识形态》标志着{{马哲的诞生}}\n《资本论》标志着{{政经的诞生}}\n{{《共产党宣言》}}标志着科社的诞生和整个马克思主义的诞生\n{{《反杜林论》}}首次将马克思主义以三个组成部分的形式进行了全面阐述\n⚠️马克思主义科学的世界观和方法论基础是{{辩证唯物主义和历史唯物主义}}","back":"","tags":["一页纸","马克思主义的三大组成部分"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c019","front":"==马克思主义相关著作（1）==\n《{{德法}}年鉴》完成了从唯心主义向唯物主义从革命民主主义向共产主义的{{转变}}为创立马克思主义奠定了思想前提➡️{{德法两转变}}\n《神圣{{家族}}》是{{马}}克思{{恩}}格斯合著的{{第一}}部著作 批判黑格尔维新 论述历史唯物➡️{{马恩第一家族}}\n《{{德}}意志意识形态》首次系统阐述了{{历史}}唯物主义的基本观点➡️{{德历史}}\n《{{共}}产党宣言》发表标志着马克思主义的{{公}}开问世➡️{{公共}}\n《{{资}}本论》被称为“{{工}}人阶级的圣经”➡️{{工资}}\n《{{法}}兰西内战》科学总结了{{巴黎}}公社的历史经验➡️{{法}}国{{巴黎}}\n《{{哥}}达纲领批判》对未来社会从制度发展阶段以及分配等方面作了原则{{构想}}➡️{{哥够香}}\n《反{{杜}}林论》全面阐述了马克思主义理论体系 被称为马克思主义的“{{百}}科全书”➡️{{百度}}","back":"","tags":["一页纸","马克思主义相关著作"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c020","front":"==马克思主义相关著作（2）==\n恩格斯去世前，为马克思的《1848年至1850年的法兰西阶级斗争》写的导言中\n1.社会主义革命的胜利将是一个长期的过程\n2.利用资产阶级民主和普选权的重要性\n3.在重视合法斗争的同时，没有否定暴力革命的作用，恩格斯晚年没有放弃革命\n{{❌(伯恩施坦)修正主义}}: 反对无产阶级革命，主张通过和平的{{议会斗争}}和改良措施，使资本主义“和平长入”社会主义","back":"","tags":["一页纸","马克思主义相关著作"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c021","front":"==资本主义的新变化-二战后（1）==\n生产资料所有制：（二战后）\n{{国家}}资本所有制形成并发挥重要作用\n{{法人}}资本所有制崛起并成为居{{主导地位}}的资本所有制形式\n法人资本所有制有两种形式：\n—是企业法人资本所有制，二是机构法人资本所有制\n⚠️辨析\n在资本主义发展的{{初期}}占主导地位的所有制形式是{{私人资本所有制}}\n19世纪末20世纪初，\n{{私人股份资本所有制}}取代私人资本所有制成为占主导地位的所有制形式\n⚠️辨析\n私人股份所有制：所有权和控制权不再统一\n法人资本所有制：狠狠独揽大权\n劳资关系和分配关系（二战后）\n❶职工参与决{{策}}、❷终身{{雇}}佣、❸职工持{{股}}、❹社会福利的普及化与全{{民}}化\n{{✅策雇股民}}","back":"","tags":["一页纸","资本主义的新变化-二战后"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c022","front":"==资本主义的新变化-二战后（2）==\n政治制度（二战后）\n❶{{政}}治制度出现多元化的趋势，{{公}}民权利有所扩大\n❷{{法}}治建设得到重视和加强\n❸{{改}}良主义政党在政治舞台上的影响日益扩大\n{{✅政治制度多元化，公民权利有扩大；法治在重视加强，改良主义要说话}}","back":"","tags":["一页纸","资本主义的新变化-二战后"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c023","front":"==资本主义的新变化-二战后（3）==\n社会阶层和阶级结构（二战后）\n❶有所有权的{{资本家}}一般{{不}}再{{直}}接{{经营}}和管理企业\n❷{{高}}级{{职}}业{{经理}}成为大公司经营活动的{{实}}际{{控}}制者\n❸{{知}}识型和{{服}}务型劳动者的数量{{不断增加，劳动}}方式发生了{{新变化}}\n{{✅资本家不直经营，实控是高职经理，知服在不断增加，劳动发生新变化}}","back":"","tags":["一页纸","资本主义的新变化-二战后"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c024","front":"==资本主义的新变化-二战后（4）==\n二战以来，资本主义国家开始对经济进行全面干预。{{但是，}}从20世纪70年代起，\n随着资本主义经济陷入滞胀和新自由主义思潮的泛滥，西方国家普遍走上：\n{{强化市场调节、弱化政府干预的道路}}","back":"","tags":["一页纸","资本主义的新变化-二战后"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c025","front":"==资本主义的新变化-二战后（5）==\n西方国家普遍走上强化市场机制、弱化政府干预的道路\n与此同时，经济危机呈现新的特点，包括：\n❶去工业化和产业空心化日趋严重，产业竞争力下降\n❷经济高度金融化，虚拟经济与实体经济严重脱节\n❸财政严重债务化，债务危机频繁爆发\n❹两极分化和社会对立加剧\n❺经济增长乏力，发展活力不足，周期性危机与结构性危机交织在一起\n❻金融危机频发，全球经济屡受打击","back":"","tags":["一页纸","资本主义的新变化-二战后"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c026","front":"==资本主义的新变化-世界大变局下==\n当今世界正经历一场百年未有之大变局\n资本主义国家内部的矛盾和冲突表现为：\n{{❶}}经济发展失调、{{❷}}政治体制失灵、{{❸}}社会融合机制失效\n经济发展失调表现为：\n❶{{虚}}拟经济与{{实}}体经济发展{{失衡}}、❷{{福}}利风险增加、❸{{债}}务负担沉重\n政治体制失灵表现为：\n❶西式选举往往难以选贤、❷政党利益可能凌驾于国家利益之上\n❸“民主陷阱”会阻碍国家治理、❹传统精英政治走向衰落，民粹主义思潮泛起\n社会融合机制失效表现为：\n{{❶社会极端思潮抬头、❷社会流动性退化}}\n❸社会{{矛盾激化}}，“{{群体}}性{{事件}}”增多","back":"","tags":["一页纸","资本主义的新变化-世界大变局下"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c027","front":"==资本主义的新变化-当代（21世纪以来）==\n进入21世纪以来，资本主义呈现出一些新变化、新特征，表现在：\n❶{{科}}技{{创}}新加速资本主义{{生产}}方式{{变}}化\n❷国际{{金}}融{{垄}}断资本主义影响日益{{显}}现（{{最突出}}）\n❸{{社}}会{{阶}}级层级结构呈现{{复杂化}}多样化\n❹发达{{资}}本主义{{国}}家凭借优势，在世界{{推}}行{{霸权}}主义和强权政治\n{{✅科创生产变，金垄最突显；阶级复杂化，资国推霸权}}\n科技创新加速资本主义生产方式变化：\n❶产业结构的调整\n❷生产组织和劳动形式的变化\n❸新经济形态的出现\n国际金融资本的垄断最突出表现在：\n❶金融垄断寡{{头}}化、❷金融垄断国{{际}}化\n❸经济{{虚}}拟化产业空{{心}}化\n✅空心瓜果\n{{👩空虚的国际寡妇}}\n🐔偷鸡{{心虚/虚空}}鸡头（你干嘛 哎哟）\n⚠️ 金融垄断资本形成{{壮大}}的重要制度条件：\n金融自由化与金融创新\n✅在金融垄断资本的推动下\n虚拟经济越来越脱离实体经济","back":"","tags":["一页纸","资本主义的新变化-当代（21世纪以来）"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c028","front":"==资本主义工资（1）==\n资本主义工资表现为劳动的价值或价格 这是一种假象\n实际上 工人出卖的不是劳动 劳动不是商品 工人出卖的是劳动力 劳动力是商品\n因此{{资本主义工资的本质是}}劳动{{力}}的价值或价格 而不是劳动的价值或价格\n资本在流通中创造了新价值是因为：{{劳动力成为商品}}\n标志着简单商品生产发展到资本主义商品生产的新阶段：{{劳动力成为商品}}\n资本的本质：{{资本是能够带来剩余价值的价值}}\n资本在运动过程中：{{采取货币、生产资料、商品等物质形态}}\n商品特有的社会属性：{{价值}}","back":"","tags":["一页纸","资本主义工资"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c029","front":"==资本主义工资（2）==\n关于劳动力的正确说法\n劳动力价值的构成包含{{历史}}的和{{道德}}的因素\n劳动力商品的使用价值是价值的源泉\n劳动力自身的价值{{不是}}转移到新产品中去，{{而是}}再生产出来的\n劳动力商品与其他商品一样，它的市场{{价格也受供求关系影响}}\n劳动力商品在使用价值上的突出特点是\n能够在消费过程中能够创造超过劳动力价值的新的价值\n一个干扰选项：\n劳动者获得的工资远远小于劳动力的价值 {{✘错误}}\n资本主义制度下，工人的工资{{是}}劳动力的价值或价格 {{✔️正确}}","back":"","tags":["一页纸","资本主义工资"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c030","front":"==资本主义劳动过程==\n资本主义劳动过程的特点是\n第一，工人在资本家的{{监督}}下劳动，他们的劳动隶属于资本家；\n第二，劳动的成果或者产品{{全部归资本家}}所有。\n🚩资本主义条件下，{{劳动是否具有生产性}}，{{取决于}}\n{{能否为资本家带来剩余价值}}","back":"","tags":["一页纸","资本主义劳动过程"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c031","front":"==垄断（1）==\n{{1️⃣垄断价格}}\n垄断高价是指{{卖的贵}}\n{{垄断低价}}是指{{买的便宜}}，即进原材料便宜，正常价卖\n{{⚠️垄断高价和垄断低价都是赚钱的价格，}}\n{{不会低于原材料价格，也抵消不了}}\n✅垄断价格产生之后，\n{{从全社会看商品的价格总额等于商品的价值总额}}","back":"","tags":["一页纸","垄断"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c032","front":"==垄断（2）==\n✅{{垄断利润的形成，关键在于}}垄断组织在经济生活中起了决定性作用。\n第一，垄断没有消除产生竞争的经济条件。\n第二，垄断必须通过竞争来维持。\n第三，社会生产是复杂多样的，任何垄断组织都不可能把包罗万象的社会生产全部包下来。\n在竞争手段上，自由竞争主要运用经济手段，垄断条件下的竞争除了采取各种形式的经济手段外，还采取非经济的手段。\n{{2️⃣垄断的形成}}\n垄断是在自由竞争中形成的\n是作为自由竞争的{{对立面}}产生的","back":"","tags":["一页纸","垄断"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c033","front":"==垄断（3）==\n垄断并不能消除竞争，反而使竞争变得更加复杂和激烈\n第一，垄断{{没有消除}}产生竞争的{{经济条件}}。\n第二，垄断必须{{通过竞争来维持}}\n第三，社会生产是复杂多样的，任何垄断组织都{{不可能}}把包罗万象的社会生产全部包下来\n{{3️⃣垄断组织}}\n最简单的、初级的垄断组织形式\n{{短期价格协定}}\n早期的国际垄断同盟的主要形式\n{{国际卡特尔}}\n当代国际垄断同盟的主要形式\n{{国家垄断资本主义的国际联盟（如：西方七国集团）}}","back":"","tags":["一页纸","垄断"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c034","front":"==金融寡头控制形式==\n1️⃣金融寡头在{{经济}}领域实现统治的形式是{{“参与制”（股票）}}\n2️⃣金融寡头在{{政治}}领域中实现对{{国家机器}}的控制主要是通过\n{{同政府的“个人联合”}}\n3️⃣金融寡头左右和{{影响内政外交与社会生活}}主要是通过：\n{{建立政策咨询机构，掌握新闻、科教、文化等}}","back":"","tags":["一页纸","金融寡头控制形式"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c035","front":"==垄断资本向世界范围扩展的基本形式==\n{{✅垄扩借产品}}\n{{垄}}断资本向世界范围{{扩}}展的基本形式：\n{{借}}贷资本输出\n生{{产}}资本输出\n商{{品}}资本输出\n⚠️辨析：\n资本在循环过程中的三种职能：\n货币资本\n生产资本\n商品资本","back":"","tags":["一页纸","垄断资本向世界范围扩展的基本形式"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c036","front":"==金融资本形成的主要途径==\n{{✅金铲铲/金灿灿/金子人}}\n{{金}}融联系\n{{资}}本{{参}}与\n{{人事参与}}","back":"","tags":["一页纸","金融资本形成的主要途径"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c037","front":"==生产资本的划分方式==\n1.根据资本是否增值（是否带来{{剩余价值}}）\n{{不变资本，可变资本}}\n2.根据在资本循环中的不同职能\n{{货币资本，生产资本，商品资本}}\n3.根据资本周转方式不同\n{{固定资本，流动资本}}","back":"","tags":["一页纸","生产资本的划分方式"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c038","front":"==生产力==\n生产力分为3部分：\n❶劳动资料\n其中{{生产工具}}是区分{{社会经济时代}}的客观依据\n❷劳动对象\n现实生产的必要前提\n❸劳动者\n生产力中最活跃的因素\n⚠️劳动资料和劳动对象合称生产资料","back":"","tags":["一页纸","生产力"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c039","front":"==社会再生产的核心问题==\n{{社会再生产的核心问题是社会总产品的实现问题,}}\n即社会总产品的价值补偿和实物补偿问题。\n{{✅生孩子👶（再生产）之前我要补偿补偿她}}\n以至于社会总产品的实现，\n即实物替换和价值补偿难以顺利进行，\n最严重的就是{{引发经济危机}}","back":"","tags":["一页纸","社会再生产的核心问题"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c040","front":"==源泉==\n价值的唯一源泉：{{抽象劳动}}\n使用价值的源泉：{{具体劳动}}\n价值的源泉：劳动力商品的使用价值（即劳动）\n剩余价值产生的唯一源泉是：{{雇佣劳动者的剩余劳动}}\n资本主义扩大再生产的源泉：{{资本积累}}\n资本积累的源泉：{{剩余价值}}","back":"","tags":["一页纸","源泉"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c041","front":"==资本周转快慢==\n影响资本周转快慢的因素有很多关键的因素有两个：\n1️⃣资本周转的时{{间}}\n{{2️⃣生产资本的固定资本和流动资本的}}构{{成}}\n{{✅}}狗屎","back":"","tags":["一页纸","资本周转快慢"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c042","front":"==资本积累==\n{{资本积累的唯一源泉就是剩余价值}}\n资本积累是资本主义扩大再生产的源泉\n资本积累导致了资本主义社会的两极分化\n资本积累的扩大会导致资本有机构成提高进而产生失业问题\n资本积累是资本主义社会失业现象产生的根源\n资本积累是资本主义制度走向灭亡的自我否定因素\n{{❗❗❗}}\n在资本主义生产过程中，资本有机构成的提高是一般趋势，这是由资本的本性决定的。\n因为资本在不断增大，\n{{资本有机构成一直在增加，看到说减少的就是错的}}\n资本原始积累过程的基础是{{用暴力手段剥夺农民土地}}","back":"","tags":["一页纸","资本积累"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c043","front":"==私人劳动和社会劳动（1）==\n1️⃣资本主义的基本矛盾：\n{{生产社会化和生产资料资本主义私人占有之间的矛盾}}","back":"","tags":["一页纸","私人劳动和社会劳动"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c044","front":"==私人劳动和社会劳动（2）==\n2️⃣私有制基础上商品经济的基本矛盾 ：\n{{私人劳动和社会劳动的矛盾}}\n✓决定着商品经济的本质及发展过程\n✓商品经济其他一切矛盾的基础\n✓决定着商品生产者的命运\n{{⚠️马克思劳动价值论揭示了商品经济的基本矛盾}}\n3️⃣商品的使用价值和价值的矛盾、\n生产商品的具体劳动和抽象劳动的矛盾，\n{{根源于}}私人劳动和社会劳动的矛盾。\n4️⃣社会形态更替归根结底是社会基本矛盾运动的结果，\n生产力的发展具有最终的决定意义\n5️⃣在以私有制为基础的商品经济中\n商品生产者的劳动既是具有社会性质的{{社会劳动}}\n又是具有私人性质的{{私人劳动}}\n{{商品生产者的劳动的社会性质是由社会分工决定的}}\n6️⃣具体劳动能否还原为抽象劳动，在{{根本上}}取决于\n{{私人劳动和社会劳动能否实现统一}}","back":"","tags":["一页纸","私人劳动和社会劳动"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c045","front":"==私人劳动和社会劳动（3）==\n7️⃣如果生产的产品不能用于交换，通过货币这一中介完成交换实现其价值，那么对商品占有者而言是毫无意义的。\n所以需要将私人劳动转化为社会劳动，而这需要用货币通过商品交换来实现","back":"","tags":["一页纸","私人劳动和社会劳动"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c046","front":"==社会==\n在社会生产中，\n【{{生产力}}】是生产的【{{物质内容}}】，\n【{{生产关系}}】是生产的【{{社会形式}}】，\n二者构成【{{社会的生产方式}}】。\n社会形态更替{{归根结底}}是【{{社会基本矛盾}}运动】的结果，\n其中， 生产力的发展具有最终的决定意义。\n社会历史发展的{{根本}}动力：{{社会基本矛盾}}\n{{🚩}} 资本主义经济危机具有周期性\n{{这是由资本主义基本矛盾运动的阶段性决定的}}","back":"","tags":["一页纸","社会"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c047","front":"==货币的本质和职能==\n货币的本质: 固定充当一般等价物的商品\n货币的五种基本职能:\n①{{价值尺度}}：观念中的货币。（关键词：标价）\n②{{流通手段}}：即时交易。（关键词：买）\n③{{贮藏手段}}：贮存。（关键词：必须是足值的货币）\n④{{支付手段}}：提前或延后交易。（关键词：{{债务 赋税 工资 租金}}）\n⑤{{世界货币}}：货币职能在世界范围内的扩展。（关键词：汇率）\n货币最基本的职能：{{价值尺度和流通手段}}✅是“甲流”\n{{🚩}} 经济危机的抽象的一般的可能性首先是由\n{{货币作为流通手段和支付手段引起的}}","back":"","tags":["一页纸","货币的本质和职能"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c048","front":"==价值规律的作用==\n价值规律在市场配置资源过程中的作用表现在：\n(1)自发地调节生产资料和劳动力在社会各生产部门之间的分配比例。\n(2)自发地刺激社会生产力的发展。\n(3)自发地调节社会收入的分配。\n{{❌自发地调节雇佣工人与资本家之间的利益再分配（错误）}}\n比如资本家压榨数学答疑，让答疑干活多但是发工资少，\n这种现象不会被价值规律所调节","back":"","tags":["一页纸","价值规律的作用"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c049","front":"==超额和相对剩余价值==\n在资本主义商品生产条件下，\n{{单个资本家}}改进技术、改善管理的{{主观动机}}是追求{{超额}}剩余价值，\n但其{{客观后果则是整个社会各个生产部门的劳动生产率普遍提高}}，导致生活资料的价值下降和补偿劳动力价值的必要劳动时间缩短，而剩余劳动时间相对延长，{{整个资本家阶级普遍获得更多的相对剩余价值}}。\n✅助记：\n超额对应原因，个别\n相对对应结果，社会","back":"","tags":["一页纸","超额和相对剩余价值"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c050","front":"==劳动生产率（1）==\n{{1️⃣劳动生产率}}指的是劳动者生产使用价值的效率。\n它的高低可以用{{单位劳动时间内}}生产的商品数量来测量，\n也可以用{{单位商品中}}所耗费的劳动时间来测量。\n{{✅通俗理解方式}}\n第一种：单位时间内，你做得多不多？\n有人一分钟一个，有人一分钟一亿个。\n第二种：单位商品，你多久做出来？你做得快不快？\n有人一秒钟就做一个，有人一小时才做一个。","back":"","tags":["一页纸","劳动生产率"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c051","front":"==劳动生产率（2）==\n{{2️⃣}}商品的价值是凝结在商品中的无差别的一般人类劳动，\n价值量是由劳动者生产商品所耗费的劳动量决定的，\n而劳动量则按照劳动时间来计量。\n因此，在单位劳动时间内，劳动者耗费的劳动量不变，生产的价值总量也不变。\n3️⃣影响劳动生产率的主要因素\n劳动者的平均劳动熟练程度\n科学技术的发展水平及其在生产中的应用程度\n生产过程的社会结合\n生产资料的规模和效能以及自然条件等","back":"","tags":["一页纸","劳动生产率"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c052","front":"==不变资本和可变资本（1）==\n根据资本在{{剩余价值生产中}}所起的不同作用\n{{可以将资本划分为不变资本与可变资本}}","back":"","tags":["一页纸","不变资本和可变资本"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c053","front":"==不变资本和可变资本（2）==\n不变资本 (c):\n以{{生产资料}}形态存在的资本\n{{这部分资本在生产过程中，不改变自己的价值量，不发生增殖}}\n不变资本的价值是具体劳动转移到新产品中{{（可一次转移，也可多次转移）}}","back":"","tags":["一页纸","不变资本和可变资本"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c054","front":"==不变资本和可变资本（3）==\n可变资本 (v)：\n用来{{购买劳动力}}的那部分资本\n{{剩余价值}}是由可变资本雇佣的劳动者创造的\n可变资本的价值是工人的劳动再生产出来的（可变资本是工人干活干出来的）\n【剩余价值】是雇佣工人所创造并被资本家无偿占有的超过劳动力价值的那部分价值，是雇佣工人剩余劳动的凝结\n资本的技术构成：\n由生产的技术水平所决定的{{生产资料}}和{{劳动力}}之间的比例。\n{{（几台烤箱 + 多少面粉 VS 几个面包师傅）}}\n资本的价值构成：\n{{不变资本}}（c）和{{可变资本}}（v）之间的比例。\n{{（买烤箱和面粉花了多少钱 VS 给师傅发了多少工资）}}","back":"","tags":["一页纸","不变资本和可变资本"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c055","front":"==不变资本和可变资本（4）==\n资本的有机构成：\n由资本的技术构成决定并反映技术构成变化的资本{{价值}}构成，即{{c}}：{{v}}。\n（花钱的比例(c:v)，是由烤箱和师傅的搭配方式决定的）\n在资本主义生产过程中\n资本{{有机}}构成的提高是一般趋势，这是由资本的本性决定的","back":"","tags":["一页纸","不变资本和可变资本"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c056","front":"==不变资本和可变资本（5）==\n展开理解，当面包老板升级设备时：\n他的技术构成提高了（{{机器⚙️}}多了先进了，需要的{{师傅👨🍳}}少了）。\n这个变化必然导致他的{{价值}}构成也提高了\n（买{{机器的钱}}的比例，相对于{{工资}}的比例，大大增加了）。\n我们就说，他的面包店的资本有{{有机}}成提高了。\n（拓展：整个社会资本{{有机}}构成普遍提高会形成相对过剩人口）\n⚠️\n{{技术变，价值变，有机也就变}}\n{{技术不变，价值变，有机就不变}}\n{{⚠️失业无法消除}}","back":"","tags":["一页纸","不变资本和可变资本"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c059","front":"==政经计算（1）==\n不变资本C 可变资本V 剩余价值M\n{{投资=成本=C+V}}\n{{有机构成C比V}}\n{{剩余价值率M比V}}\n{{利润=M}}","back":"","tags":["一页纸","政经计算"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c060","front":"==政经计算（2）==\n⚠️蓝色是已知条件，{{红色为所求}}\n某资本家投资100万元，\n其中既包括不变资本(c)也包括可变资本(v),即c+v=100万元。\n{{其预付资本的有机构成是3:1}},资本有机构成公式是c:v,即c:v=3:1,\n结合前文已知c+v=100万元，则不变资本c为75万元，可变资本v为25万元。\n该资本家每次投资的剩余价值率为200%,即m/v=200%,\n则每次投资的剩余价值m为50万元。\n利润与剩余价值在量上是一样的，故该{{资本家每次投资的利润}}为50万元。","back":"","tags":["一页纸","政经计算"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c061","front":"==绝对和相对剩余价值计算（1）==\n✔️绝对剩余价值生产方法，比较大胆，总的工作时间延长。\n✔️相对剩余价值生产方法，比较隐蔽，工作日时间不变。\n⚠️绝对剩余价值的生产和相对剩余价值的生产都是依靠{{延长工人的剩余劳动时间}}获得的。\n{{剩余价值率=剩余劳动时间÷必要劳动时间}}\n若原工作时间8小时，必要劳动时间4小时，剩余劳动时间4小时\n采用【绝对剩余价值】生产方法，使剩余劳动时间延长2小时\n延长劳动时间:8+2\n剩余价值率=6(总时长为10剪掉必要的4)÷4×100%=150%","back":"","tags":["一页纸","绝对和相对剩余价值计算"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c062","front":"==绝对和相对剩余价值计算（2）==\n采用【相对剩余价值】生产方法，使剩余劳动时间延长2小时\n(通过技术在总时长不变的情况下缩短必要劳动时间)\n必要劳动时间=4-2\n剩余价值率=6(8-2)÷2×100%=300%","back":"","tags":["一页纸","绝对和相对剩余价值计算"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c063","front":"==列宁（1）==\n1️⃣列宁指出，\n资本主义发展到帝国主义，在经济生活中起决定作用的是{{垄断组织}}\n2️⃣列宁提出：\n社会主义革命可以首先在一个或者几个国家获得{{胜利}}","back":"","tags":["一页纸","列宁"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c064","front":"==列宁（2）==\n3️⃣在俄国社会主义革命取得胜利的初期，特别是实行新经济政策期间，\n列宁对苏维埃俄国如何建设社会主义进行了深刻的理论思考，\n提出了许多精辟的论述：\n1、把建设社会主义作为一个长期探索、不断实践的过程；\n2、把大力发展生产力、提高劳动生产率放在首要地位；\n3、在多种经济成分并存的条件下，利用商品、货币和市场发展经济；\n4、利用资本主义建设社会主义。\n列宁还指出了：\n马克思主义执政党建设的极端重要性.\n阐明了思想建设和文化建设的重要意义.\n提出了加强国家政权建设和发扬社会主义民主的一系列措施。","back":"","tags":["一页纸","列宁"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c065","front":"==列宁（3）==\n4️⃣\n列宁在被人们称为“政治遗嘱”的文章和书信中，\n对十月革命以来所走过的道路进行了深入的思考，\n提出了建设社会主义的新构想。这些思想主要包括：\n用合作社的形式将农民引向社会主义道路；\n发展大工业，实现工业化和电气化；\n学习和利用资本主义{{一切有价值}}的东西；\n进行文化革命，大力发展文化教育事业；\n进行党和国家机构的改革，努力提高干部的素质和能力；\n必须反对官僚主义，健全社会主义民主和法制；\n维护党的团结，特别是党中央领导核心的团结；\n这些构想具有重要意义。","back":"","tags":["一页纸","列宁"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c066","front":"==战时共产主义与新经济政策（1）==\n战时共产主义：{{余粮收集制、取消商品货币关系}}\n——更好的供给军队作战\n{{新经济政策（列宁）}}：恢复商品货币关系，发展资本主义\n——战后迅速活跃经济\n🚩新经济政策的主要特征是发展商品经济\n苏联模式（斯大林）：{{农业合作化}}\n——进一步发展社会主义\n{{⚠️列宁为社会主义奠定了基础，但列宁并未发展社会主义}}","back":"","tags":["一页纸","战时共产主义与新经济政策"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c067","front":"==战时共产主义与新经济政策（2）==\n新经济政策（和战时作比较）\n1️⃣{{农业}}：粮食税制取代余粮收集制\n不再全部收走，交完税了多的归你，允许农民自由出卖余粮\n2️⃣{{工业}}：\n1.部分恢复私营经济\n允许私人经营中小企业，但关系国家命脉的企业仍归国家所有\n2.实行国家资本主义\n采取租让制和租借制，允许外资企业管理国家暂时无力经营的企业\n3️⃣{{贸易}}：{{允许自由贸易}}（废除了国家配给和国家贸易垄断制）\n4️⃣{{分配}}：实行按劳分配\n5️⃣{{流通}}：恢复商品货币关系","back":"","tags":["一页纸","战时共产主义与新经济政策"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c068","front":"==巴黎公社（1）==\n1871年爆发的巴黎公社革命，\n是第一国际精神的产儿，\n是无产阶级{{夺取政权}}的第一次伟大尝试。\n特别是采取了两项重要措施，用以防止国家机关工作人员由社会公仆变为社会主人：\n一是规定所有公职人员无论职位高低，实行全面的选举制和撤换制；\n二是取消高薪制，规定任何工作人员年薪不得超过熟练工人的工薪水平。","back":"","tags":["一页纸","巴黎公社"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c069","front":"==巴黎公社（2）==\n✅要点：\n{{1️⃣巴黎公社建立的是政权，不是政党}}\n{{2️⃣防止公仆变主人的两项措施与人相关，即人的工资和职位，取消高薪，选举撤换}}\n⚠️辨析：{{俄国十月革命}}才建立苏维埃大会制度\n{{3️⃣}}巴黎公社革命源于民族矛盾和阶级斗争激化，\n{{不是第一国际发动和领导}}，只是受第一国际精神影响。","back":"","tags":["一页纸","巴黎公社"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c070","front":"==一个错误说法==\n理论联系实际，不是实践符合理论\n用实践套理论＝本本主义{{✗错误}}\n例如：马克思主义的中国化就是使中国的每一实践都与马克思主义理论相符合{{✗错误}}\n用实践发展理论，理论联系实际＝中国化{{✔️正确}}\n马克思主义的中国化，使之在其{{每一}}表现中带着中国的特性✔️正确","back":"","tags":["一页纸","一个错误说法"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c071","front":"==看似生涩其实正确的说法马克思等经典作家原话==\n“人的意识不仅反映客观世界，并且创造客观世界”-列宁 {{✔️正确 肖八5-1}}\n“世界不会满足人，人决心以自己的行动来改变世界。”-列宁 {{✔️正确}}\n“人体解剖对于猴体解剖是一把钥匙” -马克思{{✔️正确 真题25-2}}\n“资产阶级不对生产工具和生产关系进行革命就不能生存”-《共产党宣言》 {{✔️正确 真题25-21}}\n“观念的东西不外是移入人脑并经过人脑改造过的物质的东西而已”-马克思 {{✔️正确真题24-18}}\n{{⚠️只是说法正确，还要看是否符合题干}}","back":"","tags":["一页纸","看似生涩其实正确的说法马克思等经典作家原话"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c072","front":"==生涩迷惑干扰项（1）==\n劳动者获得的工资远远小于劳动力的价值 {{✘错误}}\n资本主义制度下，工人的工资{{是}}劳动力的价值或价格 {{✔️正确}}\n观念的东西可以{{自发地}}变为客观现实 {{✘错误}}\n观念的东西{{必须通过实践}}才能变为客观现实 {{✔️正确}}\n雇佣工人与资本家形成人身依附的关系 {{✘错误}}\n资本家与雇佣工人的关系不是完全占有，也不是人身依附\n而是基于劳动者人身自由基础上的“平等”关系 {{✔️正确}}\n价值规律是资本主义社会特有的经济规律 {{✘错误}}\n在我国，我们也要遵循价值规律 {{✔️正确}}\n规律在一定条件下可以改变 {{✘错误}}\n正确认识、利用和创造规律 {{✘错误}}\n规律是客观的，不能改变、创造、改造、消灭 {{✔️正确}}\n发挥主观能动性去创造联系 {{✘错误}}\n联系是事物本身固有的 {{✔️正确}}\n经济文化落后的国家不可能跨越一种或多种社会形态 {{✘错误}}\n社会形态的更替可以跨越向前发展，也可以停滞、反复、倒退 {{✔️正确}}\n无产阶级政党是工人阶级全体成员的组织 {{✘错误}}\n无产阶级政党是无产阶级的先锋队 {{✔️正确}}\n工会是工人阶级全体成员的组织 {{✔️正确}}\n真理和谬误是绝对对立的 {{✘错误}}\n真理和谬误只有在确定的范围内才是绝对对立的 {{✔️正确}}\n任何成功的实践都是必然性与偶然性的统一 {{✘错误}}\n任何成功的实践都是真理尺度和价值尺度的统一，是合规律性和合目的性的统一 {{✔️正确}}","back":"","tags":["一页纸","生涩迷惑干扰项"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c073","front":"==生涩迷惑干扰项（2）==\n自然界已经成为人类社会的一部分 {{✘错误}}\n自然界与人类社会不是截然分开的，而是交叉重叠和相互作用的 {{✔️正确}}\n科学研究可以直接得出真理性认识 {{✘错误}}\n实践是检验认识的真理性的唯一标准 {{✔️正确}}\n马克思主义是现成方案/一套标准/有四海皆准模式 {{✘错误}}\n推进马克思主义中国化时代化 {{✔️正确}}\n人口因素和自然地理环境是……的决定因素 {{✘错误}}\n人口因素和自然地理环境只能是重要影响因素，不是决定因素 {{✔️正确}}\n科技革命已成为推动社会历史进步的根本动力 {{✘错误}}\n人民群众始终是推动社会历史进步的根本动力 {{✔️正确}}\n人类的求知欲是认识的最终目的 {{✘错误}}\n认识能力的提升是为了获得理性认识 {{✘错误}}\n实践是认识的目的 {{✔️正确}}\n马克思首次提出了劳动创造价值的观点 {{✘错误}}\n在马克思之前，已经有人提出了劳动创造价值的观点 {{✔️正确}}\n垄断组织操纵价格带来的结果是整个社会商品的价值不再由生产它们的社会必要劳动时间决定 {{✘错误}}\n整个社会商品的价值仍然是由生产它们的社会必要劳动时间决定的 {{✔️正确}}\n精神文化条件对于人民群众创造历史的活动有着首要的、决定性的影响 {{✘错误}}\n{{经济条件}}对于人民群众创造历史的活动有着首要的、决定性的影响 {{✔️正确}}\n整个物质世界的时空是客观的、有限的 {{✘错误}}","back":"","tags":["一页纸","生涩迷惑干扰项"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c074","front":"==生涩迷惑干扰项（3）==\n整个物质世界的时空是无限的 {{✔️正确}}\n文化作为一种特殊的精神力量能直接转化为物质成果 {{✘错误}}\n文化作为一种精神力量，需要通过{{社会实践这一中介}}才能转化为物质力量。 {{✔️正确}}\n自然物质的存在和功能依赖于人们对它的认识 {{✘错误}}\n自然物质的存在是客观的，不依赖于人们对它的认识 {{✔️正确}}\n事物经过否定之否定的过程向原来出发点回复 {{✘错误}}\n否定之否定阶段{{仿佛}}是向原来出发点的“回复”，但这是在{{更高阶段}}的“回复” {{✔️正确}}\n智能机器可以取代或超越人类智能 {{✘错误}}\n人工智能不能取代或超越人类智能 {{✔️正确}}\n机器人已经真正具备自立、自主、自觉的社会活动 {{✘错误}}\n机器人从根本上说是机器而不是人类，它不可能真正具备自立、自主、自觉的社会活 {{✔️正确}}\n意识的产生可以脱离人脑这一物质器官 {{✘错误}}\n意识是人脑这样一种特殊物质的机能和属性 {{✔️正确}}\n客体能否满足主体需要，是由人的主观愿望决定的 {{✘错误}}\n客体能否满足主体需要，是由客体客观存在的性质、属性等决定 {{✔️正确}}\n国际金融危机是经济全球化发展的必然产物 {{✘错误}}\n国际金融危机不是经济全球化发展的必然产物，而是金融资本过度逐利、金融监管严重缺失的结果 {{✔️正确}}\n{{人类可以打破对自然界的依赖关系而获得绝对的自由✘错误}}","back":"","tags":["一页纸","生涩迷惑干扰项"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c075","front":"==生涩迷惑干扰项（4）==\n人对一定问题的判断越是自由，这个判断的内容所具有的必然性就越大{{✔️正确}}","back":"","tags":["一页纸","生涩迷惑干扰项"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c076","front":"==生涩迷惑干扰项（5）==\n只有充分发挥主观能动性，才能实现{{超越}}社会发展阶段的自由{{✘错误}}\n古代社会的人再发挥主观能动性，也造不出斐济杯✈️，因为社会发展阶段没到，缺乏科技、工业基础\n自由不能“超越阶段”，必须基于当前的社会条件\n正确认识历史发展方向是社会历史存在和发展的前提{{✘错误}}\n认识在存在前，典型的唯心主义观点\n现实的人及其活动是社会历史存在和发展的前提{{✔️正确}}\n{{每一个人}}都是历史的创造者{{✘错误}}\n人民群众是历史的创造者{{✔️正确}}\n历史规律只有通过人的有目的、有意识的活动才能实现{{✔️正确}}\n人们在自己选定的条件下创造历史{{✘错误}}","back":"","tags":["一页纸","生涩迷惑干扰项"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c077","front":"==生涩迷惑干扰项（6）==\n马克思指出：“人们自己创造自己的历史，但是他们并不是随心所欲地创造，并不是在他们自己选定的条件下创造，而是在直接碰到的、既定的、从过去承继下来的条件下创造。{{✔️正确}}\n认识是对客观世界的{{直观}}反映{{✘错误}}\n认识是对客观世界的能动反映{{✔️正确}}\n认识可以超前于直接的实践{{✔️正确}}\n认识{{先于}}人的实践经验{{✘错误}}\n认识是自己头脑里{{固有}}的{{✘错误}}\n在认识活动中避免{{任何}}非理性因素的作用{{✘错误}}\n不能全盘否定非理性因素，有时候非理性因素有积极促进的作用\n在实践中不断{{推翻}}以往的真理并建立新的真理{{✘错误}}\n真理不能被推翻，只能被不断的补充和发展，完善{{✔️正确}}\n评价结果有正确与错误之分，价值评价有科学与非科学之分{{✔️正确}}\n探索未知世界的科学实验是人类最基本的实践活动{{✘错误}}\n物质生产实践是人类最基本的实践活动{{✔️正确}}\n人的认识能力以人的感觉器官生理阈限为界限{{✘错误}}\n盲人也能认识世界，霍金这一块\n人工智能是人的意识能动性的一种特殊表现，可以延伸和拓展人类能力 ✓正确\n人工智能已经真正具备了一定的社会属性 {{✗错误}}","back":"","tags":["一页纸","生涩迷惑干扰项"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c078","front":"==清末新政==\n清末新政的内容之一\n“裁撤绿营，建立新军”\n{{⚠️撤绿立新 清末新政}}","back":"","tags":["一页纸","清末新政"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c079","front":"==同盟会起义==\n{{✅大黄花}}\n同盟会发动的影响最{{大}}的起义：\n{{黄花}}岗起义\n（又称广州起义 广州三二九起义）\n⚠️同盟会成立后发动的第一次武装起义：萍浏醴起义\n⚠️三元里人民的抗英斗争是中国近代史上中国人民第一次大规模的反侵略武装斗争\n🚩同盟会的成立，标志中国资产阶级民主革命进入了一个新的阶段","back":"","tags":["一页纸","同盟会起义"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c080","front":"==“边疆危机”==\n{{19世纪70至80年代}}\n列强从侵占中国周边邻国发展到蚕食中国边疆地区\n使中国陷入“边疆危机”","back":"","tags":["一页纸","“边疆危机”"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c081","front":"==列强侵略的方式==\n军事侵略：\n首先和主要的侵略方式是进行军事侵略\n政治控制：\n控制中国政府或培植代理人，操纵中国的内政、外交\n{{镇压}}中国人民的反抗\n经济掠夺：\n操纵中国的经济命脉\n文化渗透：\n其目的是宣扬殖民主义{{奴化思想}}\n麻醉中国人民的{{精神}}\n摧毁中国人的民族{{自尊心和自信心}}","back":"","tags":["一页纸","列强侵略的方式"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c082","front":"==戊戌维新==\n戊戌维新运动是\n{{中国民族资产阶级}}登上政治舞台的第一次表演\n以维新运动为起点\n{{资产阶级新文化开始打破封建文化独占文化阵地的局面}}","back":"","tags":["一页纸","戊戌维新"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c083","front":"==洋务运动==\n1️⃣洋务派提出“自强”“求富”的主张（也是目标）\n通过所掌握的国家权力集中力量{{优先发展军事工业}}\n洋务运动的指导思想（冯桂芬提出）\n“中学为体，西学为用”\n2️⃣洋务运动失败的主要原因：\n洋务运动具有{{封}}建性{{（决定）}}\n洋务运动对列强具有{{依}}赖性\n洋务企业的管理具有{{腐}}朽性\n{{✅缝衣服}}\n3️⃣中国近代化和近代教育的起点运动\n洋务派创办的新式企业其管理基本上仍是封建衙门式的\n洋务派兴办洋务事业首先是为了购买和制造洋枪洋炮以镇压农民起义","back":"","tags":["一页纸","洋务运动"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c084","front":"==论战（1）==\n{{1️⃣维新派与守旧派的论战}}","back":"","tags":["一页纸","论战"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c085","front":"==论战（2）==\n{{是近代中国资产阶级思想与封建主义思想的第一次正面交锋}}\n论战所涉及的领域十分广泛，\n进一步开阔了新型知识分子的眼界，解放了人们长期受到束缚的思想。\n通过论战，西方资产阶级社会政治学说在中国得到进一步的传播，\n戊戌变法运动的帷幕随之拉开。","back":"","tags":["一页纸","论战"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c086","front":"==论战（3）==\n维新派与守旧派论战内容：\n要不要变法（{{中心}}）；\n要不要兴民权、设议院、实行君主立宪（后来变法中没有采纳）；\n要不要废八股、改科举和兴西学。（注意不是废科举，清末“新政”才废除科举）\n{{维新派与洋务派分歧的实质}}是要不要学习西方的政治制度与思想文化\n⚠️ 维新派技术思想都学，洋务派只学技术不学思想\n{{2️⃣维新派与革命派的论战}}\n这次论战划清了{{革命}}与{{改良}}的界限，\n传播了民主革命思想，促进了革命形势的发展\n但同时也暴露了革命派在思想理论方面的弱点，即不敢反帝反封建。\n内容：\n要不要以革命手段推翻清王朝（这是双方论战的{{焦点}}）\n要不要推翻帝制，实行共和\n要不要社会革命","back":"","tags":["一页纸","论战"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c090","front":"==中国早期信仰马克思主义的人物的队伍==\n{{✅骨干是主体}}\n中国早期信仰马克思主义的人物的队伍主要是由三种人组成的其{{主体}}部分是:\n五四爱国运动的左翼{{骨干}}","back":"","tags":["一页纸","中国早期信仰马克思主义的人物的队伍"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c091","front":"==五四运动==\n五四运动的直接导火线：{{巴黎和会上中国外交的失败}}\n关于“五四运动”的几个正确说法\n是在新的时代条件和社会历史条件下发生的\n标志着马克思主义开始与中国工人运动的结合\n新民主主义革命的开端\n中华民族自鸦片战争以来的第一次全面觉醒\n标志着中国青年成为推动中国社会变革的急先锋\n“外争主权、内除国贼”","back":"","tags":["一页纸","五四运动"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c092","front":"==十月革命==\n1️⃣十月革命使中国人看到了民族解放的新希望\n2️⃣十月革命推动中国先进分子把目光从西方转向东方，\n从资产阶级民主主义转向社会主义，{{但并不是全社会所有人的普遍共识}}\n3️⃣十月革命的胜利，实现了社会主义{{从理想到现实}}的伟大飞跃\n开辟了人类历史的新纪元，苏维埃俄国成为世界上第一个社会主义国家","back":"","tags":["一页纸","十月革命"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c093","front":"==新文化运动（1）==\n新文化运动是一场前所未有、空前深刻的思想解放运动","back":"","tags":["一页纸","新文化运动"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c094","front":"==新文化运动（2）==\n新文化运动的倡导者\n1️⃣ 以{{进化论}}观点和{{个性解放思想}}为主要武器，\n{{2️⃣ 猛烈抨击以孔子}}为代表的“往圣先贤”,\n（通过批判孔学，动摇了封建正统思想的统治地位，在中国社会掀起一股思想解放的潮流。）\n{{⚠️新文化运动的倡导者批判孔学，是为了给中国发展资本主义扫清障碍。（屁孔发紫）}}\n{{3️⃣ 大力提倡新道德}}、反对旧道德，{{提倡新文学}}、反对旧文学，包括提倡白话文、反对文言文。{{提倡民主}}、反对专制，{{提倡科学}}、反对迷信盲从\n4️⃣ 五四以前的新文化运动的倡导者就已经把{{改造国民性}}置于优先地位\n五四运动以前的新文化运动局限性：\n提倡资产阶级民主主义\n离开革命实践去把改造国民性置于优先\n没有马克思主义的批判精神，看问题很片面\n五四以前的{{新文化运动时期，}}中国{{还没有马克思主义}}，后来十月革命给中国送来了马克思主义\n{{五四以后的新文化运动}}则发展到了一个新阶段\n马克思主义开始逐步地在思想文化领域中发挥指导作用","back":"","tags":["一页纸","新文化运动"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c095","front":"==李大钊==\n1️⃣率先在中国大地上举起马克思主义旗帜\n2️⃣{{《法俄革命之比较观》}}向中国人民第一次{{正确地}}阐述了十月革命的性质\n{{3️⃣《庶民的胜利》《布尔什维主义的胜利》}}\n深刻揭露了第一次世界大战的本质{{热情歌颂}}了十月革命和布尔什维主义的胜利\n4️⃣{{《我的马克思主义观》}}明确地把马克思主义称为世界改造原动的学说 并且对马克思的唯物史观 剩余价值学说和阶级斗争理论作了比较系统的介绍 这表明 {{李大钊已经成为中国的第一个马克思主义者}}\n《我的马克思主义观》也{{标志着}}马克思主义在中国进入一个比较{{系统}}的传播阶段","back":"","tags":["一页纸","李大钊"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c096","front":"==孙中山==\n孙中山\n第一个响亮喊出{{“振兴中华”}}的口号\n{{创立兴中会（第一个）、同盟会}}\n{{提出民族、民权、民生的三民主义}}\n领导了辛亥革命\n1911年，在他领导和影响下，震惊世界的辛亥革命取得成功，\n{{推翻了清王朝统治，结束了统治中国几千年的君主专制制度}}\n坚决反对军阀分裂割据\n坚定维护民主共和制度和国家完整统一\n中国共产党成立后，孙中山先生同中国共产党人真诚合作\n在中国共产党帮助下，把旧三民主义发展为{{新三民主义}}\n{{实行联俄、联共、扶助农工三大政策}}\n反帝反封建的民主革命\n{{改组}}中国国民党\n{{推动}}北伐战争取得胜利\n（北伐战争是在孙中山逝世之后发生的，{{不由孙中山发动}}）\n把反帝反封建的民主革命推向前进\n毛泽东同志对孙中山的评价\n把三民主义纲领、统一战线政策、艰苦奋斗精神并称为孙中山先生\n“留给我们的最中心最本质最伟大的遗产”\n“对于中华民族最伟大的贡献”。","back":"","tags":["一页纸","孙中山"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c097","front":"==新旧三民主义（1）==\n🚩旧三民主义：\n{{1️⃣驱除鞑虏，恢复中华}}\n2️⃣创立民国\n3️⃣平均地权","back":"","tags":["一页纸","新旧三民主义"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c098","front":"==新旧三民主义（2）==\n⚠️旧三民主义的{{局限}}：\n民族主义的局限性\n没有从正面鲜明地提出反对帝国主义的主张\n没有保证广大劳动群众在国家中的地位\n民生主义指的是“平均地权”，其局限性表现在\n没有正面触及封建土地所有制，不能满足广大农民的土地要求\n🚩新三民主义：","back":"","tags":["一页纸","新旧三民主义"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c099","front":"==新旧三民主义（3）==\n1️⃣民族：突出反帝内容，对外实行民族独立，对内主张民族平等\n2️⃣民权：民主权利“为一般平民所共有”，不应为“少数人所得私”\n3️⃣民生：平均地权和节制资本（后又提出耕者有其田）并提出改善工农生活状况\n{{⚠️三民无主}}\n新旧三民主义，都是民族，民生，民权。从来没有民主，有民主就错\n{{⭕新三民主义的政纲同中国共产党在民主革命阶段的纲领基本一致，}}\n{{因而有了国共合作的政治基础❗❗❗}}","back":"","tags":["一页纸","新旧三民主义"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c100","front":"==维新派和辛亥革命对比==\n{{⭐维新派}}\n🌧️有利于民主思想在中国的传播，有利于人们的思想解放\n🌧️把顽固的封建主义思想壁垒打开了一个缺口\n🌧️形成了广泛的文化革新运动\n🌧️以维新运动为起点资产阶级新文化{{开始打破封建文化独占文化阵地的局面}}\n🌧️这对中国近代教育的发展起了积极的推动作用\n{{⭐辛亥革命}}\n⛄结束了中国延续两千多年的封建君主专制制度\n⛄建立了中国历史上第一个资产阶级共和政府\n⛄使{{民主共和}}的观念开始深入人心","back":"","tags":["一页纸","维新派和辛亥革命对比"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c101","front":"==孙中山挽救共和的努力及其受挫（1）==\n① 孙中山发动武装反袁的“二次革命”\n② 组织中华革命党。\n③ 蔡锷等在云南组织“护国军”，形成护国运动\n④ 孙中山“护法”运动及其失败\n孙中山并没有找到中国的真正出路。{{中国的旧民主主义革命已经陷入纶境}}，中国民族资产阶级再也不能领导中国革命前进了。\n护法运动的失败，标志着旧民主主义革命的终结\n⚠️使孙中山认识到“南与北如一丘之貉”，\n想依靠南方军阀来反对北洋军阀行不通的事件是\n{{护法运动}}","back":"","tags":["一页纸","孙中山挽救共和的努力及其受挫"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c102","front":"==孙中山挽救共和的努力及其受挫（2）==\n{{旧民主主义革命的终结和新民主主义革命的开端}}\n1️⃣护法运动的失败不仅是孙中山个人的失败\n也标志着整个中国民族资产阶级领导的{{旧民主主义革命的终结}}\n2️⃣五四运动成为中国革命的新阶段即{{新民主主义革命}}阶段的{{开端}}","back":"","tags":["一页纸","孙中山挽救共和的努力及其受挫"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c103","front":"==孙中山挽救共和的努力及其受挫（3）==\n⚠️无产阶级的领导权是中国革命的中心问题，也是新民主主义革命理论的核心问题。\n区别新、旧两种不同范畴的民主主义革命的根本标志是，\n革命的领导权是掌握在无产阶级手中还是掌握在资产阶级手中。\n一定要注意，虽然“新民主主义革命”有个“新”字，\n但其性质依然是资产阶级民主主义革命(由社会性质、革命对象、革命任务等决定)。\n但是，中国革命已不是旧式的、一般的资产阶级民主主义革命，而是新式的、特殊的资产阶级民主主义革命。","back":"","tags":["一页纸","孙中山挽救共和的努力及其受挫"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c104","front":"==辛亥革命==\n辛亥革命之所以失败，从根本上说，是因为\n在帝国主义时代，在半殖民地半封建的中国，{{资本主义的建国方案行不通}}\n毛泽东说辛亥革命\"只把一个皇帝赶跑\"是指{{反帝反封建的革命任务没有完成}}\n南京临时政府在《告友邦书》中，企图以承认清政府的不平等条约和外债来换取列强承认。所以{{《中华民国临时约法》是承认清政府与列强签订的一系列不平等条约的}}。","back":"","tags":["一页纸","辛亥革命"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c105","front":"==西安事变==\n西安事变的和平解决\n成为时局转换的{{枢纽}}\n{{十年内战局面基本结束}}\n国内和平{{初步实现}}","back":"","tags":["一页纸","西安事变"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c106","front":"==《陕甘宁边区施政纲领》==\n1941年5月中共中央批准颁布\n全面体现了中国共产党关于{{根据地建设的基本方针}}\n{{抗日根据地建设}}的首要的、根本的任务是{{政权建设}}","back":"","tags":["一页纸","《陕甘宁边区施政纲领》"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c107","front":"==抗战期间战役总结（1）==\n✅{{正}}态分布\n抗战爆发后中国正面战场取得的首次重大胜利：\n{{台}}儿庄大捷（国民党 正面战场 1938）","back":"","tags":["一页纸","抗战期间战役总结"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c108","front":"==抗战期间战役总结（2）==\n百团大战\n是以{{破袭敌人交通线}}为主要目的的战斗\n是一次大规模的进攻和反“扫荡”战役\n全民族抗战以来{{八路军在华北}}发动的\n{{规模最大 持续时间最长的战略性进攻战役}}\n沉重打击了日军的“囚笼政策”\n巩固了华北抗日根据地\n百团大战的历史壮举\n充分展现了我们党在全民族抗战中的{{中流砥柱}}作用\n充分展现了党领导的人民战争的磅礴力量\n热点：2025年7月7日习近平在参观百团大战纪念馆\n平型关大捷\n{{全民族抗战开始以来}}中国军队的第一个大胜利","back":"","tags":["一页纸","抗战期间战役总结"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c109","front":"==一二·九运动==\n公开{{揭露了日本}}吞并华北进而侵略全中国的{{阴谋}}\n为抗日战争和中国革命事业{{准备了一大批骨干力量}}\n{{打击了国民党}}政府的妥协退让政策，极大地促进了中华民族的{{觉醒}}\n{{标志着中国人民抗日救亡民族运动新高潮的到来}}","back":"","tags":["一页纸","一二·九运动"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c110","front":"==抗日战争的胜利==\n抗日战争的胜利是\n中华民族从近代以来{{陷入深重危机}}走向{{伟大复兴}}的历史{{转折点}}\n近代以来中华民族反抗外敌入侵的第一次完全胜利\n二战胜利成果的集中体现是\n{{以联合国为核心的国际体系}}\n伟大抗战精神\n天下兴亡、匹夫有责的爱国情怀\n视死如归、宁死不屈的民族气节\n不畏强暴、血战到底的英雄气概\n百折不挠、坚忍不拔的必胜信念\n中国赢得抗日战争胜利的主要原因是\n决定因素：以爱国主义为核心的民族精神\n关键：中国共产党的中流砥柱作用\n重要法宝：全民族抗战\n世界所有爱好和平力量的{{同情和支持}}\n历史上承认中国收回台湾的国际文件：\n开罗宣言、波茨坦公告、日本投降书、中日联合声明（1972年）\n✅菠萝投降声明/日本偷菠萝\n{{抗日战争取得完全胜利的重要标志是}}\n中国政府在台湾举行受降仪式，台湾以及澎湖列岛由中国收回","back":"","tags":["一页纸","抗日战争的胜利"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c111","front":"==游击战争==\n独立自主的游击战争\n是抗日战争中时间{{最长}}、战斗战役持续不断的一场{{特殊战略大会战}}\n是人民军队发挥政治优势和军事优势{{最好}}的作战形式\n是坚持持久抗战、最终彻底战胜日本侵略者的{{唯一}}正确的政治军事方针\n（此处看到最好，唯一别纠结直接选，就是对的）\n在战略防御阶段\n国民党正面战场的正规战是主要的\n敌后游击战是{{辅助}}的\n在战略相持阶段\n敌后游击战争成为{{主要}}的抗日作战方式","back":"","tags":["一页纸","游击战争"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c112","front":"==抗日战争时间点==\n{{起点}}，局部抗战的开始：1931{{九一八}}事变\n{{新高潮}}的到来：1935{{“一二·九”}}运动\n提出了党的抗日民族统一战线的新政策\n1935年12月，瓦窑堡会议\n提出党的基本策略任务是建立广泛的抗日民族统一战线\n《停战议和一致抗日通电》\n1936年5月，毛泽东、朱德联名发布的文件\n{{放弃反蒋口号}}\n“逼蒋抗日”总方针\n1936年9月1日，中共中央明确提出党的总方针\n十年{{内战}}的局面由此{{结束}}：1936.12{{西安事变的和平解决}}\n进入{{全民族抗战}}时期：1937.7七七{{卢沟桥}}事变\n《中国共产党抗日救国十大纲领》\n和《中共中央关于目前形势与党的任务的决定》\n洛川会议（1937.8）通过的文件\n{{标志着党的全面抗战路线的正式形成}}\n抗日{{统一战线正式形成}}：1937.9\n《中共中央为公布国共合作宣言》\n蒋介石发表实际上承认共产党合法地位的谈话\n1939年7月，中国共产党明确提出\n“坚持抗战到底，反对中途妥协”\n“巩固国内团结，反对内部分裂”\n“力求全国进步，反对向后倒退”","back":"","tags":["一页纸","抗日战争时间点"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c113","front":"==《义勇军进行曲》==\n《义勇军进行曲》之所以发出“中华民族到了最危险的时候”的呐喊\n{{最重要的原因}}是日本大举侵华，妄图把中国变为其独占的殖民地","back":"","tags":["一页纸","《义勇军进行曲》"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c114","front":"==精神辨析==\n{{五四精神：}}爱国进步 民主 科学\n（五四精神的{{核心}}是{{爱国主义}}）\n黄埔精神：{{爱国 革命}}","back":"","tags":["一页纸","精神辨析"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c115","front":"==革命的几个问题==\n中国革命的首要问题：{{分清敌友}}\n{{中国革命的中心问题是无产阶级领导权}}\n国{{民}}革命的{{中心问题}}是{{农民问题}}\n中国革命的基本问题：{{农民问题}}\n资产阶级民主革命的中心问题：土地革命","back":"","tags":["一页纸","革命的几个问题"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c116","front":"==秋收起义与南昌起义==\n1️⃣区别：\n✳️秋收起义：【{{工农革命军}}】的旗帜\n南昌起义：【{{国民革命军}}】的旗帜\n✳️秋收起义不仅是军队的行动，\n而且有数量众多的工农武装参加。\n2️⃣联系：\n{{✳️秋收起义的目标}}是攻打中心城市长沙{{。}}\n在攻打中心城市受挫后，\n毛泽东果断改变计划，\n决定向敌人控制比较薄弱的农村转移。\n这一点与南昌起义是相同的{{。}}\n✳️南昌起义和秋收起义都是\n中国共产党独立领导的革命战争","back":"","tags":["一页纸","秋收起义与南昌起义"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c117","front":"==中国革命能坚持和发展的原因==\n在大革命失败、白色恐怖极其严重的条件下\n中国革命之所以能够得到坚持和发展\n根本原因就在于中国共产党\n{{紧紧地依靠农民 领导农民进行了土地制度的革命}}","back":"","tags":["一页纸","中国革命能坚持和发展的原因"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c118","front":"==觉醒==\n中日甲午战争 1895\n台湾被日本侵占，帝国主义列强掀起瓜分中国的狂潮，\n中国人开始有了{{普遍}}的民族意识{{觉醒}}\n戊戌维新运动 1898\n推动中华民族的觉醒\n五四运动 1919\n中华民族自鸦片战争以来的第一次{{全面觉醒}}\n一二·九运动\n{{打击了国民党}}政府的妥协退让政策，\n极大地促进了中华民族的{{觉醒}}","back":"","tags":["一页纸","觉醒"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c119","front":"==土地政策（1）==\n{{✅康熙底线心存贞洁}}\n土{{地}}革命时期：{{限}}制富农\n{{抗}}日战争时期：减租减{{息}}\n{{解}}放战争时期：{{征}}收富农多余土地\n{{新}}中国成立初期：保{{存}}富农经济\n社会主义改造时期：从限制富农到逐步消灭富农\n1️⃣土地革命时期：\n{{《兴国土地法》}}将“没收一切土地〞改为“{{没收一切公共土地及地主阶级的土地}}〞这是一个原则性的改正\n2️⃣抗日战争时期：\n抗战时期并没有“废除”封建剥削","back":"","tags":["一页纸","土地政策"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c120","front":"==土地政策（2）==\n3️⃣解放战争时期：\n❶“五四指示”\n改“减租减息”为“耕者有其田”\n向废除封建剥削制度过渡\n❷《中国土地法大纲》\n“乡村中一切地主的土地及公地，由乡村农会接收”，分配给{{无地或少地}}的农民。","back":"","tags":["一页纸","土地政策"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c121","front":"==土地政策（3）==\n4️⃣新中国成立后\n❶《中华人民共和国土地改革法》\n废除地主阶级封建剥削的土地所有制，实行农民的土地所有制\n{{保存}}富农经济的政策\n❷ 社会主义改造时期\n{{从限制富农到逐步消灭富农}}","back":"","tags":["一页纸","土地政策"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c122","front":"==中国陷入军阀割据局面的原因==\n在1916年袁称帝败亡后，中国陷军阀割据原因主要是\n中国主要是{{地方性的农业经济}}而没有形成统一的资本主义市场\n{{帝国主义国家在中国采取划分势力范围的分裂剥削政策}}","back":"","tags":["一页纸","中国陷入军阀割据局面的原因"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c123","front":"==制度确立的时间==\n人民代表大会制度作为新中国的{{根本政治制度}}正式确立\n{{以1954年一届人大为标志}}\n标志着中国的新型政党制度的确立\n（中国共产党领导的多党合作和政治协商制度）\n{{1949年9月中国人民政治协商会议第一届全体会议的召开}}\n标志着社会主义制度的确立\n社会主义改造的完成","back":"","tags":["一页纸","制度确立的时间"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c124","front":"==工人罢工运动==\n中国工人运动的第一个高潮（海员到京汉）\n1922.1{{香港海员—起点}}\n1922.9安源{{路}}矿—完全{{胜}}利\n1922.10{{开滦五矿—非完全胜利}}\n{{1923.2京汉铁路—终点（高潮）}}\n持续时间{{最长}}的罢工：\n1925-1926{{省港大罢工}}\n{{✅慕容云海是起点 张翰是终点六胜五不胜 省港最长}}","back":"","tags":["一页纸","工人罢工运动"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c125","front":"==近代斗争失败原因==\n近代以后中国人民的反帝反封建斗争之所以屡遭挫折和失败\n{{最重要}}的原因就是\n{{没有}}先进的坚强的政{{党}}作为凝聚力量的领导{{核心}}\n中国共产党的诞生，从根本上改变了这种局面","back":"","tags":["一页纸","近代斗争失败原因"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c126","front":"==延安整风运动（1）==\n✅尊师{{重教}}\n延安整风运动的{{重}}点是{{教}}条主义\n⚠️整风运动最{{主要}}的任务:{{反对主观主义}}\n整风运动中{{第一个}}重要的问题:{{学风问题}}\n（思想方法问题、对马主义态度问题、工作态度问题）","back":"","tags":["一页纸","延安整风运动"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c127","front":"==延安整风运动（2）==\n延安整风的意义\n(1)全党党员端正了思想路线，增强了运用马克思主义的立场、观点、方法解决中国革命实际问题的自觉性和能力。\n(2)整风运动是一场伟大的思想解放运动。\n{{是一次深刻的马克思主义思想教育运动}}\n(3)一切从实际出发、理论联系实际、实事求是的马克思主义{{思想路线，在全党范围确立}}。\n🚩提出的对待犯错误同志的正确方针：\n{{“惩前毖后、治病救人”}}","back":"","tags":["一页纸","延安整风运动"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c128","front":"==统一战线辨析==\n{{大革命后}}因为汪蒋叛变，民资跟小资跟国民党跑了只剩下工人和农民留在共产党，故此时是{{工农民主统一战线}}❗\n{{解放战争时期}}我们争求尽可能的人民（除了工农也包括富农，民资等）与国民党进行最终决战，此时形成{{人民民主统一战线}}❗","back":"","tags":["一页纸","统一战线辨析"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c129","front":"==政权性质（1）==\n土地革命战争时期建立的苏维埃政权的性质\n{{工农民主专政}}","back":"","tags":["一页纸","政权性质"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c130","front":"==政权性质（2）==\n中华苏维埃共和国是中国历史上第一个全国性的工农民主政权\n是中国共产党在局部地区执政的重要尝试\n扩大了党和红色政权的影响，\n一定程度上加强了对处于被分割状态的各根据地的中枢指挥作用，\n推动了各根据地的政权、经济、文化教育和党的自身建设，\n开创了土地革命战争新局面\n抗日战争时期建立的政权的性质\n{{是抗日民族统一战线性质的政权}}\n是一切赞成{{抗日}}又赞成{{民主}}的人们的政权\n解放战争时期建立的政权的性质\n{{各个革命阶级的联合专政}}\n新中国成立初期建立的政权的性质\n{{人民民主专政}}","back":"","tags":["一页纸","政权性质"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c131","front":"==正确说法和错误说法==\n中国共产党所领导的改革开放\n{{从一开始就}}具有明确的社会主义方向 ✔️正确\n中国早期的马克思主义者\n{{已在}}实际上初步形成了马克思主义应当与中国具体实际相结合的思想 ✔️正确\n中国早期的马克思主义者\n{{一开始就}}坚持了马克思主义中国化的革命原则和正确方向 {{✗错误}}","back":"","tags":["一页纸","正确说法和错误说法"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c132","front":"==长征（1）==\n开启了中国共产党为实现民族独立、人民解放而斗争的新的伟大进军\n中央红军进行长征的直接原因\n红军在第五次{{反“围剿”}}作战中遭到{{失败}}\n红军已{{无在原地扭转}}战局的可能","back":"","tags":["一页纸","长征"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c133","front":"==长征（2）==\n长征的胜利\n{{极大地促进了党在政治上和思想上的成熟}}\n{{是中国革命转危为安的关键}}\n实现了中国共产党和中国革命事业从挫折走向胜利的伟大转折\n长征一结束，中国革命的新局面就开始了\n长征精神为中国革命不断从胜利走向胜利提供了强大精神动力\n中央红军突围以来最壮烈、最关键的一仗{{湘江战役}}\n四渡赤水战役取得了红军战略转移中具有决定意义的胜利\n直罗镇战役彻底粉碎了国民党反动派对陕甘苏区的第三次“围剿”，\n为党中央奠基西北打开了新局面\n⚠️长征实现了中国共产党和中国革命事业从挫折走向胜利的伟大转折","back":"","tags":["一页纸","长征"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c134","front":"==解放战争（1）==\n标志着人民解放战争战略进攻的{{序幕}}由此揭开：{{三路大军相互策应}}\n（刘邓晋冀鲁豫野战军、陈粟华东野战军、陈谢晋冀鲁豫野战军）\n为{{打败蒋介石}}、建立新中国奠定了深厚的{{群众基础}}的是{{土地制度改革}}\n⚠️土地制度改革是从根本上摧毁中国封建制度根基的社会大变革","back":"","tags":["一页纸","解放战争"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c135","front":"==解放战争（2）==\n从1947年3月至6月，人民解放军经过4个月的内线作战，努力打退国民党军的重点进攻，并在东北、热河、冀东、豫南等地开始局部反攻。人民解放军在这一阶段的作战标志着\n从根本上粉碎了国民党统治集团的{{速战速决计划}}\n{{三大战役后}}国民党赖以维持其反动统治的{{主要军事力量}}基本上被摧毁","back":"","tags":["一页纸","解放战争"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c136","front":"==中间路线==\n抗日战争胜利后，某些民主党派的领导人曾经鼓吹“中间路线”，\n企图在国共对立的纲领之外寻找第三条道路。他们主张：\n在政治上，“必须实现英美式的民主政治”，但不准地主官僚资本家操纵；\n在经济上，“应当实行改良的资本主义”，但不容官僚买办资本横行。\n实行的方法，则是走和平改良的道路\n他们所提倡的，是{{资产阶级共和国}}的方案，\n{{他们所主张的，实质上是旧民主主义的道路。}}\n但是，中国在战后面临的是两种命运、两个前途的尖锐斗争。\n{{客观形势}}决定了中国没有走中间路线的余地。","back":"","tags":["一页纸","中间路线"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c137","front":"==党对军队的绝对领导（1）==\n{{✅Fa男鸡弯腚鼓}}\n{{党对军队的绝对领导}}\n{{发}}端于{{南}}昌起义\n奠{{基}}于三{{湾}}改编\n{{定}}型于{{古}}田会议\n南昌起义 1927.8.1\n打响了武装{{反抗国民党}}反动派的{{第一枪}}，\n{{党独立领导革命战争、创建人民军队和武装夺取政权的开端}}\n党对军队绝对领导的根本原则和制度的{{发端}}","back":"","tags":["一页纸","党对军队的绝对领导"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c138","front":"==党对军队的绝对领导（2）==\n{{三}}湾改编 1927.9-10\n从{{组织}}上确立了党对军队的领导\n建设无产阶级领导的{{新}}型人民军队的{{重要开端}}\n党对军队绝对领导的根本原则和制度的{{奠基}}\n确立了支部建在连上的原则和制度\n{{✅三星}}","back":"","tags":["一页纸","党对军队的绝对领导"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c139","front":"==党对军队的绝对领导（3）==\n{{古田}}会议 1929.12\n{{确立了思想建党、政治建军原则}}\n{{规定红军是一个执行革命的政治任务的武装集团}}\n创造性地解决了在农村环境中、 在党组织和军队以农民为主要成分的条件下，\n如何保持党的无产阶级{{先锋}}队性质和建设党领导的新型人民{{军队}}的重大问题。\n{{古田会议决议是}}\n❶ 中国共产党和红军建设的{{纲领性文献}}\n❷ 是党和人民军队建设史上的{{重要里程碑}}\n党对军队绝对领导的根本原则和制度的{{定型}}\n{{✅古田先锋军队}}\n遵义会议 1935\n事实上确立了毛泽东在党中央和红军的领导地位\n长征 1934-1936\n开启了中国共产党为实现民族独立、人民解放而斗争的新的伟大进军","back":"","tags":["一页纸","党对军队的绝对领导"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c141","front":"==萌芽（3）==\n第一次国内革命战争（大革命）时期，\n以下著作中关于新民主主义革命的基本思想的提出，\n标志着毛泽东思想开始萌芽。","back":"","tags":["一页纸","萌芽"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c142","front":"==萌芽（4）==\n(1) 1925年12月{{《中国社会各阶级分析》}}：\n①分析了各阶级在革命中的作用和地位\n②提出“谁是我们的敌人？谁是我们的朋友”这个革命的首要问题\n{{即分清敌友是革命的首要问题}}\n以往的斗争之所以成效甚少，一个重要的原因，\n就在于不能团结真正的朋友，以攻击真正的敌人。\n(2) 1926年9月{{《国民革命与农民运动》}}：\n{{指出“农民问题乃国民革命的中心问题”}}\n“所谓国民革命运动，其大部分即是农民运动”\n(3) 1927年3月{{《湖南农民运动考察报告》}}:\n为了答复当时党内外对于农民革命斗争的责难而写的\n总结辛亥革命失败原因:国民革命需要一个大的农村变动","back":"","tags":["一页纸","萌芽"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c143","front":"==思想汇总==\n20世纪50年代中期至60年代中期\n根据世界形势的发展，毛泽东提出两个{{“中间地带”}}战略思想\n20世纪70年代前期\n毛泽东针对当时国际形势的变化逐渐形成了关于{{“三个世界划分”}}的战略思想\n{{更多毛提出的思想：}}（⚠️注意别和邓混淆）\n{{1️⃣社会主义社会矛盾学说 2️⃣没有调查，没有发言权}}\n{{3️⃣我们要坚持用马克思主义之“矢”去射中国革命之“的”}}\n毛泽东在探索走中国工业化道路时，提出了\n以农业为基础，以工业为主导，以农轻重为序发展国民经济的总方针，\n以及一整套{{“两条腿走路”}}的工业化发展思路","back":"","tags":["一页纸","思想汇总"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c144","front":"==其他人提出的思想==\n“三个主体、三个补充”-陈云\n{{国家}}经营和{{集体}}经营是工商业的{{主体}}，{{个体}}经营是{{补充}}\n{{计划生产}}是工农业生产的{{主体}}，{{自由生产}}是计划生产的{{补充}}\n{{国家市场}}是它的{{主体}}，{{自由市场}}是国家市场的{{补充}}\n八大提出“三个主体、三个补充”-这一思想\n为克服苏联模式弊端提供了重要启示\n对突破苏联模式，探索经济体制改革的道路具有重要指导意义\n“不唯上、不唯书、只唯实，交换、比较、反复”-陈云\nps：2025年是陈云诞辰120周年，习近平发表了重要讲话。\n“三个主体、三个补充”是党的八大陈云提出的。\n{{地主不分田，富农分坏田”}}—王明“左”倾教条主义错误","back":"","tags":["一页纸","其他人提出的思想"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c145","front":"==党的三大优良作风==\n{{✅实群批}}\n理论联系{{实}}际\n密切联系{{群}}众\n批评与自我{{批}}评\n{{⚠️1945七大《论联合政府》}}","back":"","tags":["一页纸","党的三大优良作风"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c146","front":"==新民主主义革命三大法宝==\n{{✅战斗党}}\n统一{{战}}线\n武装{{斗}}争\n{{党}}的建设\n{{⚠️1939《发刊词》}}","back":"","tags":["一页纸","新民主主义革命三大法宝"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c147","front":"==统一战线==\n{{中国革命必须建立最广泛的统一战线，这是由}}\n1️⃣中国半殖民地半封建社会的{{阶级}}状况所决定的\n2️⃣中国革命的长期性、残酷性及其发展的{{不平衡性}}所決定的\n⚠️辨析：\n{{半殖民地半封建的中国社会交织在一起的诸多矛盾，}}\n决定的是建立最广泛的统一战线的{{可能性}}，而不是必要性。\n决定必要性的是阶级 ，不平衡\n✅必须选国情，可能选矛盾","back":"","tags":["一页纸","统一战线"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c148","front":"==抗日民族统一战线与“三三制”原则（1）==\n{{1️⃣抗日⺠族统一战线的策略总方针:}}\n{{发展进步势力,争取中间势力,孤立顽固势力}}\n依靠中间势力 {{✘错误}}","back":"","tags":["一页纸","抗日民族统一战线与“三三制”原则"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c149","front":"==抗日民族统一战线与“三三制”原则（2）==\n{{进步势力:}}工人、农⺠和城市小资产阶级\n{{中间势力:}}⺠族资产阶级、开明绅士和地方实力派\n{{顽固势力}}:大地主、大资产阶级的抗日派,\n即以蒋介石集团为代表的国⺠党亲英美派\n⚠️\n1.中国共产党对顽固派贯彻{{又联合又斗争}}的政策方针。\n2.在同顽固派作斗争时，坚持{{有理、有利、有节}}的原则。","back":"","tags":["一页纸","抗日民族统一战线与“三三制”原则"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c150","front":"==抗日民族统一战线与“三三制”原则（3）==\n{{2️⃣“三三制”原则（}}抗日根据地的政权建设）：\n{{共产党员、党外进步人士和中间派各占 1/3}}\n共产党员:代表工人和农⺠\n党外进步人士:代表小资产阶级\n{{中间派:}}代表⺠族资产阶级和开明绅士{{(无地方实力派)}}","back":"","tags":["一页纸","抗日民族统一战线与“三三制”原则"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c151","front":"==抗日民族统一战线与“三三制”原则（4）==\n与第一次{{国民革命统一战线}}相比较，抗日民族统一战线具有{{新的特点}}\n第一，具有{{广}}泛的{{民族}}性和复杂的阶级矛盾。{{（广民族）}}\n第二，国共双方{{有政}}权的合作，也有{{军}}队的合作。{{（有政军）}}\n{{第三，没有协商一致的共同纲领。（无共纲）}}\n⚠️两次合作的{{相同}}点：主要斗争形式是{{武装斗争}}","back":"","tags":["一页纸","抗日民族统一战线与“三三制”原则"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c152","front":"==工农武装割据（1）==\n{{✅武弟弟}}\n土{{地}}革命\n{{武}}装斗争\n根据{{地}}建设\n{{中国革命走农村包围城市、武装夺取政权的道路，}}\n{{根本在于处理好土地革命、武装斗争、农村革命根据地建设三者之间的关系。}}","back":"","tags":["一页纸","工农武装割据"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c153","front":"==工农武装割据（2）==\n{{土地革命}}是中国革命的{{基本内容}}；\n{{武装斗争}}是中国革命的{{主要形式}}，是农村根据地建设和土地革命的强有力保证；\n{{农村革命根据地}}是中国革命的{{战略阵地}}，是进行武装斗争和开展土地革命的依托。\n在党的领导下，\n实现了土地革命、武装斗争、农村革命根据地建设三者的密切结合和有机统一。","back":"","tags":["一页纸","工农武装割据"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c154","front":"==工农武装割据（3）==\n⚠️{{农村革命根据地}}能够在中国长期存在和发展的\n{{根本原因：}}中国是一个政治、经济、文化发展{{极不平衡}}的{{半殖民地半封建}}的大国\n{{客观原因：}}良好的{{群众基础}}和革命形势的继续向前发展\n{{主观原因：}}相当力量正式红军的存在及党制定正确的政策","back":"","tags":["一页纸","工农武装割据"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c155","front":"==毛泽东思想活的灵魂==\n{{✅是群主}}\n实事求{{是}}\n{{群}}众路线\n独立自{{主}}\n{{⚠️1981年6月27日十一届六中全会}}\n{{《关于建国以来党的若干历史问题的决议》}}\n⚠️实事求是是\n{{毛泽东思想的基本点}}\n{{毛泽东思想的精髓}}\n党的思想路线的核心\n党的根本思想路线\n{{⚠️群众路线是}}\n我们党的生命线和根本工作路线\n{{我们党永葆青春活力和战斗力的重要传家宝}}\n{{⚠️独立自主是}}\n中华民族的优秀传统\n{{中华民族精神之魂}}\n中国共产党中华人民共和国立党立国的重要原则\n独立自主的探索和实践精神是\n{{我们党全部理论和实践的立足点}}\n党和人民事业不断从胜利走向胜利的根本保证","back":"","tags":["一页纸","毛泽东思想活的灵魂"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c156","front":"==马克思主义中国化（1）==\n{{✅}}马克思主义中国化{{三次飞跃（成果）}}\n1️⃣{{中共七大}}确立{{毛泽东思想}}为党的指导思想{{（第一次）}}\n2️⃣中国特色社会主义理论体系改革开放后{{（第二次）}}\n3️⃣习近平新时代中国特色社会主义思想{{（新的飞跃 非第三次）}}","back":"","tags":["一页纸","马克思主义中国化"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c157","front":"==马克思主义中国化（2）==\n✅马克思主义中国化的{{两次结合（过程）}}\n1️⃣马克思主义同{{中国革命}}实际的结合\n{{正式提出命题}}六届六中全会《论新阶段》{{⚠️共产党成立就开始了}}\n2️⃣马克思主义同{{中国社会主义建设}}实际的结合\n1956《论十大关系》\n{{🚩六六结合➡️七大飞跃➡️五六结合➡️改革飞跃}}","back":"","tags":["一页纸","马克思主义中国化"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c158","front":"==马克思主义中国化（3）==\n⚠️关于结合完成问题\n{{1️⃣20世纪30年代}}马克思主义与中国实际第一次相结合\n{{“第一次结合”}}即实行马克思主义同中国新民主主义革命结合\n这一任务是{{完成了}}的，{{形成了}}毛泽东思想，{{取得了}}新民主主义革命的胜利","back":"","tags":["一页纸","马克思主义中国化"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c159","front":"==马克思主义中国化（4）==\n2️⃣1956年社会主义基本制度在中国确立的时候\n毛泽东明确提出了把马克思列宁主义基本原理同中国具体实际进行{{“第二次结合”}}\n但是，毛泽东{{没有完成}}这一任务，邓小平也{{没有完成}}第二次结合\n事实上“三个代表”重要思想、科学发展观等都属于马克思主义与中国实际的第二次结合的范畴，\n因此{{不能说}}邓小平同志完成了马克思主义与中国实际的第二次结合\n{{⚠️两个结合}}\n1️⃣把马克思主义基本原理同{{中国具体实际}}相结合\n2️⃣把马克思主义基本原理同{{中华优秀传统文化}}相结合\n❗️❗️❗️\n{{毛泽东思想无改革中国特色社会主义理论体系无革命}}\n{{马克思主义中国化时代化都有}}\n马克思主义中国化时代化\n{{魂脉}}—马克思主义\n{{根脉}}—中华优秀传统文化","back":"","tags":["一页纸","马克思主义中国化"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c160","front":"==马克思主义中国化（5）==\n⚠️更多“飞跃”、“跨越”关键词补充\n完成社会主义革命，确立社会主义基本制度\n中华民族由不断衰落到根本扭转命运、持续走向繁荣富强的伟大飞跃\n全面建成小康社会\n从大幅落后于时代到{{大踏步}}赶上时代的{{新跨越}}","back":"","tags":["一页纸","马克思主义中国化"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c163","front":"==会议大观（1）==\n{{一大党二大二反}}\n{{三大国共要合作}}\n{{国民一大合作成}}\n{{四大领导工农盟}}\n{{五大争取革命权}}\n{{八七枪杆出政权}}\n{{古田军队要增强}}\n{{遵义军事与组织}}\n{{瓦窑堡一起来抗日}}\n{{洛川全面来抗战}}\n{{六届六中马中化}}\n{{六届七中整完风}}\n{{七大确定毛领导}}\n{{七届二中转城市两转变两务必}}\n{{人民政协政党立}}\n{{七届三中转经济}}\n{{八大矛盾定方针}}","back":"","tags":["一页纸","会议大观"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c164","front":"==会议大观（2）==\n十一三中改开放\n十一六中通《决议》 社初提\n十二大上中特提\n十二三中有计划\n十三阶段与路线\n十四市场经济体\n十五邓理论成指导\n十六三个代表 小康奋斗目标\n十七科学发展观\n十八全面小康新时代\n十八三中破冰","back":"","tags":["一页纸","会议大观"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c165","front":"==旧民主主义革命时期（1840-1917）==\n◉{{1840}} 鸦片战争 近代史的开端 逐步丧失关税自主权海关行政权\n◉{{1841}} 三元里人民抗英斗争 近代史上中国人民第一次大规模反侵略武装斗争\n◉{{1851}} 太平天国运动 中国旧式农民战争的最高峰\n◉{{1861}} 洋务运动 清王朝的一次自救运动\n◉{{1894}} 中日甲午战争 进一步成为半殖民地半封建社会\n◉{{1895}} 甲午战争中国战败 标志着洋务运动的失败\n◉{{1899}} 义和团从秘密反清转向公开反对列强\n◉{{1898}} 戊戌变法 资产阶级性质的改革/改良运动\n◉{{1900}} 义和团运动 在粉碎列强瓜分中国的斗争中发挥了重大的作用\n◉{{1901}} 《辛丑条约》 彻底沦为半殖民地半封建社会清政府彻底放弃了抵抗外国侵略\n◉{{1911}} 辛亥革命 结束了封建君主专制制度\n◉{{1915}} 新文化运动 空前的思想解放运动\n◉{{1917}} 俄国十月革命 推动了中国先进分子选择了马克思主义\n◉{{1917}} 护法运动 标志着中国旧民主主义革命的终结\n◉{{1919-1949}} 新民主主义革命时期\n◉{{1949-至今}} 新中国成立之后","back":"","tags":["一页纸","旧民主主义革命时期（1840-1917）"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c166","front":"==新民主主义革命时期（1919-1949）==\n◉{{1840-1919}} 旧民主主义革命时期\n◉{{1919}} 五四运动 新民主主义革命的开端\n◉{{1921}} 中共一大 标志著中国共产党的成立\n◉{{1924}} 国民党一大 标志着第一次国共合作的开端\n◉{{1925}} 五卅运动 揭开了大革命的序幕\n◉{{1926}} 北伐战争 彻底消灭了军阀势力\n◉{{1927}} 八七会议 大革命失败到土地革命战争兴起\n◉{{1927}} 南昌起义 打响了武装反抗国民党反动派的第一枪\n◉{{1931}} 九一八事变 标志着局部抗日战争的开始\n◉{{1935}} 遵义会议 中国共产党在政治上开始走向成熟\n◉{{1937}} 七七事变 标志着全民族抗日战争的开始\n◉{{1941}} 延安整风运动 一场伟大的马克思主义思想解放运动\n◉{{1945}} 抗日战争胜利 第一次取得完全胜利的民族解放斗争\n◉{{1949}} 新中国成立 标志着半殖民地半封建社会在中国的结束\n◉{{1949-至今}} 新中国成立之后","back":"","tags":["一页纸","新民主主义革命时期（1919-1949）"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c167","front":"==新中国成立之后（1949-至今）==\n◉{{1840-1919}} 旧民主主义革命时期\n◉{{1919-1949}} 新民主主义革命时期\n◉{{1949-1956}} 过渡时期 从新民主主义社会向社会主义社会转变\n◉{{1956}} 三大改造完成 实现了由新民主主义向社会主义的转变\n◉{{1964}} 爆炸了第一颗原子弹\n◉{{1967}} 爆炸了第一颗氢弹\n◉{{1970}} 第一颗人造卫星发射成功\n◉{{1971}} 恢复了在联合国的合法席位\n◉{{1978}} 十一届三中全会 进入了改革开放和社会主义现代化建设的历史新时期\n◉{{1978}}改革开放后 普遍实行“统分结合”的家庭联产承包责任制\n◉{{2012}} 十八大 中国特色社会主义进入新时代","back":"","tags":["一页纸","新中国成立之后（1949-至今）"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c168","front":"==建国初期三大外交政策==\n{{一边倒，}}\n另起炉灶，\n打扫干净屋子再请客\n{{⚠️打扫屋子倒炉灶}}","back":"","tags":["一页纸","建国初期三大外交政策"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c169","front":"==三反运动==\n反贪污，反浪费，反官僚主义","back":"","tags":["一页纸","三反运动"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c170","front":"==中国社会的阶级构成==\n{{✅工农小民}}（无产阶级也称为工人阶级）\n新民主主义时期中国社会的阶级构成：\n{{工人阶级——中国革命最基本的动力}}\n{{农}}民阶级\n{{农民是中国革命的主力军}}\n{{农民问题是中国革命的基本问题}}\n{{小}}资产阶级——{{无产阶级的可靠同盟者}}\n{{民}}族资产阶级","back":"","tags":["一页纸","中国社会的阶级构成"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c171","front":"==对个体手工业的社会主义改造的方法==\n对个体手工业的社会主义改造的方{{法}}：\n{{说}}服教育典型示范和国家帮助\n{{（说法）}}\n⚠️补充\n对手工业的社会主义改造的{{方针}}：\n{{积极领导稳步前进（针积极 针滴稳）}}\n{{🔺对农业的社会主义改造也是这个方针}}","back":"","tags":["一页纸","对个体手工业的社会主义改造的方法"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c172","front":"==中国进入社会主义社会最主要的标志==\n1956年底，随着社会主义改造的完成，\n以生产资料公有制、按劳分配和计划经济体制为特征的{{社会主义经济制度建立}}起来，\n这是中国进入社会主义社会最主要的标志。\n{{⚠️经济基础决定上层建筑}}","back":"","tags":["一页纸","中国进入社会主义社会最主要的标志"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c173","front":"==党在过渡时期的总路线==\n党在过渡时期的总路线\n党在1952年底酝酿并于{{1953年正式提出}}\n客观原因是\n民主革命遗留任务的彻底完成\n国内阶级关系、主要矛盾的变化\n国民经济的恢复、初步发展和中国社会经济成分的变化","back":"","tags":["一页纸","党在过渡时期的总路线"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c174","front":"==“一五”计划==\n“一五”计划确定的经济建设指导方针突出的{{核心要点}}是\n集中主要力量发展{{重工业}}，建立国家工业化和国防现代化的初步基础","back":"","tags":["一页纸","“一五”计划"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c175","front":"==农民生产积极性==\n1951年12月，\n中共中央印发的《关于农业生产互助合作的决议（草案）》指出，\n中国农民在土改基础上所发扬起来的生产积极性，\n{{集中地表现在两种积极性上，即个体经济的积极性和劳动互助的积极性}}","back":"","tags":["一页纸","农民生产积极性"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c176","front":"==五种经济成分（1）==\n五种经济成分：社会主义性质的国营经济、半社会主义性质的合作社经济、农民和手工业者的个体经济、私人资本主义经济、国家资本主义经济。\n主要经济成分：社会主义经济、个体经济、资本主义经济。\n过渡性质经济成分：半社会主义性质的合作社经济、国家资本主义经济。","back":"","tags":["一页纸","五种经济成分"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c177","front":"==五种经济成分（2）==\n国营经济：属于社会主义性质，居于领导地位\n合作社经济：从个体经济向社会主义集体经济过渡的形式\n{{国家资本主义经济}}：私人资本主义经济向社会主义国营经济过渡的形式\n⚠️改造资本主义工商业并向社会主义过渡的必经之路是{{国家资本主义}}\n新民主主义社会的五种经济成分中\n处于{{十字路口}}的经济成分是：\n个体经济\n✅十字路口有路标⬆️像“个”","back":"","tags":["一页纸","五种经济成分"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c178","front":"==三大改造-农业==\n(1) 道路：积极引导农民组织起来，走互助合作道路\n(2) 原则：遵循{{自愿互利典型示范 国家帮助}}的原则\n{{✅农原立典}}\n(3) 阶级政策：依靠贫下中农，团结其他中农、发展互助合作、\n由逐步限制到最后消灭富农剥削。\n(4) 方针：坚持{{积极领导、稳步前进}}的方针，采取循序渐进的步骤\n(5) 步骤：互助组；初级社；高级社。\n（社会主义萌芽性质→半社会主义性质完全→完全社会主义性质）","back":"","tags":["一页纸","三大改造-农业"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c179","front":"==社会主义改造==\n之所以说我国社会主义改造的基本完成是一个伟大的历史性胜利\n是因为如此复杂、困难和深刻的社会变革\n①没有造成生产力的破坏，反而促进了工农业和整个国民经济的发展\n③没有引起巨大的社会动荡，反而极大地加强了人民的团结","back":"","tags":["一页纸","社会主义改造"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c180","front":"==多党合作和政治协商格局的形成（1）==\n{{1️⃣喊话——}}五一口号\n得到了热烈回应；揭开了序幕；奠定了基础。\n{{2️⃣回应——}}《对时局的意见》\n各党派和无党派公开自愿接受共产党的领导。\n民主党派和无党派民主人士决心走{{人民革命}}的道路\n{{3️⃣谈话——}}毛泽东谈话（1949春）\n“积极参政，共同建设新中国”；\n标志着民主党派地位的根本变化\n4️⃣{{确立——}}1949 年人民政协\n确立了中国的新型政党制度","back":"","tags":["一页纸","多党合作和政治协商格局的形成"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c181","front":"==多党合作和政治协商格局的形成（2）==\n⚠️辨析\n{{1️⃣1946年政协会议协议还不是新民主主义性质的，}}\n但它有利于冲破蒋介石的独裁统治和实行民主政治，\n有利于和平建国，因而在相当程度上有利于人民\n2️⃣1949年人民政协是以工农联盟为基础的人民民主统一战线的组织形式","back":"","tags":["一页纸","多党合作和政治协商格局的形成"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c182","front":"==资本主义工商业改造==\n资本主义工商业改造三大步骤：\n1️⃣第一步：{{初级形式国家资本主义}}，形式为计划订货，统购包销-代工厂\n特点：国家与私人企业在{{企业外部}}的合作\n性质：社会主义萌芽性质(具有社会主义因素)\n2️⃣第二步：个人企业公私合营\n特点：生产资料归国家和资本家共同占有，公方占领导地位\n{{（一，二步都是四马分肥）}}\n性质：半社会主义性质\n3️⃣第三步：全行业公私合营\n特点：企业变成社会主义国营企业\n性质：完全的社会主义性质\n{{⚠️辨析}}\n农业:\n萌芽: 互助组\n半社会:初级农业生产合作社\n社会主义:高级农业生产合作社\n手工业:\n萌芽:手工业生产合作小组\n半社会:手工业供销合作小组\n社会主义:手工业生产合作社\n资本主义工商业：\n萌芽:初级形式的国家资本主义\n半:个别企业公私合营\n全:全行业公私合营\n⚠️ 对社会主义改造基本完成以后\n公有制经济可以和非公有制经济共同发展{{缺乏认识，是改造中的一个偏差}}","back":"","tags":["一页纸","资本主义工商业改造"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c183","front":"==邓小平理论（1）==\n1. 深刻回答了什么是社会主义、怎样建设社会主义这一根本问题。\n2. 深刻揭示社会主义本质。\n3. 为我国改革开放和社会主义现代化建设提供了行动指南。\n4. 是中国特色社会主义理论体系的奠基之作。\n邓小平理论的精髓：\n解放思想、{{实事求是}}\n⚠️辨析\n一个错误说法：\n中特理论体系——{{革命}}和建设 {{✗错误}}\n毛泽东思想——革命和建设 ✔️正确\n⚠️辨析\n邓小平理论———什么是社会主义、怎样建设社会主义\n💡看到{{邓小平}}，就想{{社会主义}}\n“三个代表”重要思想———建设什么样的党、怎样建设党\n科学发展观——实现什么样的发展、怎样发展","back":"","tags":["一页纸","邓小平理论"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c184","front":"==邓小平理论（2）==\n习思想——“新时代坚持和发展什么样的中国特色社会主义、怎样坚持和发展中国特色社会主义，建设什么样的社会主义现代化强国、怎样建设社会主义现代化强国，建设什么样的长期执政的马克思主义政党、怎样建设长期执政的马克思主义政党”。","back":"","tags":["一页纸","邓小平理论"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c185","front":"==南方谈话==\n{{计划和市场}}都是{{经济手段}}，不是{{社会主义}}与{{资本主义}}的本质区别。\n邓小平的南方谈话\n从理论上深刻回答了长期困扰和束缚人们思想的许多重大问题，\n是把改革开放和现代化建设推向新阶段的又一个解放思想、实事求是的宣言书，\n不仅对之后召开的党的十四大具有十分重要的指导作用，\n而且对中国整个社会主义现代化建设事业具有重大而深远的意义。\n邓小平理论也{{逐步走向成熟}}","back":"","tags":["一页纸","南方谈话"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c186","front":"==宣言书==\n{{1️⃣抗美援朝的胜利}}\n中国人民站起来后屹立于世界东方的宣言书\n2️⃣《解放思想 实事求是 团结一致向前看》\n开辟中国特色社会主义{{道路}}、{{开创}}中国特色社会{{理论}}的{{宣言书}}\n解放思想、开辟新时期新道路的宣言书\n3️⃣南方谈话\n推进改革开放和社会主义现代化建设{{进入新阶段}}的{{又一个}}解放思想、实事求是的{{宣言书}}","back":"","tags":["一页纸","宣言书"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c187","front":"==邓思想补充（1）==\n党际关系“四项原则”\n“独立自{{主}}、完全{{平}}等、互{{相}}尊重、互不干涉{{内部事务}}”\n{{✅ 竹坪乡的内部事务}}\n{{和平与发展}}是当今世界的两大主题的重要论断\n如果一切从本本出发思想僵化，迷信盛行，那它就不能前进\n1979党的理论工作务虚会首次提出\n“四项基本原则”\n1982十二大提出\n建设有中国特色的社会主义\n为建设中国特色社会主义提供总依据的是\n社会主义初级阶段理论\n社会主义初级阶段基本路线的核心内容\n“一个中心、两个基本点”\n以经济建设为{{中心}}，{{坚持}}四项基本原则，{{坚持}}改革开放\n⚠️党在社会主义初级阶段的基本路线体现了\n我国社会主义现代化建设的战略布局","back":"","tags":["一页纸","邓思想补充"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c188","front":"==邓思想补充（2）==\n邓小平在领导{{改革开放和现代化建设}}这一新的革命过程中\n不断提出和反复思考的{{首要的基本的理论问题}}是\n{{什么是社会主义、怎样建设社会主义}}\n搞清楚这一基本理论问题，{{关键是要}}\n{{在坚持社会主义基本制度的基础上进一步认清社会主义的本质}}","back":"","tags":["一页纸","邓思想补充"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c189","front":"==宪法==\n三大改造前，政协第一届全体会议通过的{{《中国人民政治协商会议共同纲领》}}，\n成为中国人民的大宪章，在一个时期内起着新中国临时宪法的作用。\n但它还不是社会主义类型的宪法。\n三大改造后，1954年9月，\n中华人民共和国第一届全国人民代表大会第一次会议通过的{{《中华人民共和国宪法》}}，\n{{是一部社会主义类型的宪法}}，体现了人民民主原则和社会主义原则。","back":"","tags":["一页纸","宪法"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c190","front":"==权利保障==\n{{✅县里行司前要管后}}\n{{宪}}法保障—{{前}}提和基础\n{{立}}法保障—重{{要}}条件\n{{行}}政保护—{{关}}键环节\n{{司}}法保障—最{{后}}防线","back":"","tags":["一页纸","权利保障"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c191","front":"==法律的运行==\n{{✅定期 只要 用活 手机}}\n法律制{{定}}～{{起}}始性和关键性环节\n法律{{执}}行～重{{要}}环节\n法律适{{用}}～专门{{活}}动\n法律遵{{守}}～{{基}}本途径","back":"","tags":["一页纸","法律的运行"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c192","front":"==建设中特法治体系==\n{{✅高中前辈用医保买了药膳和煎包}}\n{{高}}效的法治实施体系—{{重}}点\n完{{备}}的法律规范体系—{{前}}提\n有力的法治{{保}}障体系—重要{{依}}托\n完{{善}}的党内法规体系—本质{{要}}求\n严密的法治{{监}}督体系—重要{{保}}障","back":"","tags":["一页纸","建设中特法治体系"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c193","front":"==中国特色社会主义法治道路==\n中国特色社会主义法治道路的{{核心要义}}是\n坚持党的{{领导}}\n坚持中国特色社会主义{{制度}}\n贯彻中国特色社会主义法治{{理论}}\n🚩中国特色社会主义{{法治}}道路{{本质}}上是\n中国特色社会主义道路{{在法治领域的}}具体体现","back":"","tags":["一页纸","中国特色社会主义法治道路"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c194","front":"==全面依法治国🦋==\n{{✅李倩只管四种手机}}\n科学{{立}}法—{{前}}提\n严格{{执}}法—{{关}}键\n{{司}}法保障—{{重}}点\n全民{{守}}法—{{基}}础\n全面依法治国的一个根本问题是党和法的关系\n依法治国、依法执政、依法行政是一个有机整体，\n{{关键}}在于党要坚持依法{{执}}政、各级政府要坚持依法{{行}}政\n全面依法治国的行动指南是习近平法治思想","back":"","tags":["一页纸","全面依法治国🦋"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c195","front":"==推进全面依法治国（1）==\n{{根本目的——}}依法保障{{人民}}权益\n{{根本保证——}}坚持{{党}}对全面依法治国的{{领导}}\n{{总目标——}}建设中国特色社会主义法治体系，建设社会主义{{法治国家}}\n{{总抓手——}}中国特色社会主义法治{{体系}}\n{{基础工程——建设法治社会}}\n{{重点任务和主体工程——法治政府}}","back":"","tags":["一页纸","推进全面依法治国"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c196","front":"==推进全面依法治国（2）==\n中国特色社会主义的本质要求和重要保障：全面依法治国\n社会主义法治建设的{{灵魂}}是{{社会主义核心价值观}}\n中国特色社会主义法治区别于资本主义法治的根本所在：\n保证人民当家作主的主体地位\n扎实推进共同富裕是中国特色社会主义的本质要求\n共享是中国特色社会主义的本质要求","back":"","tags":["一页纸","推进全面依法治国"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c197","front":"==宪法==\n{{宪法的根基在于人民发自内心的拥护}}\n民主集中制是我国国家组织形式和活动方式的基本原则\n法治权威能不能{{树立}}起来，首先看宪法有没有{{权威}}\n坚持依法治国首先要坚持依宪治国\n宪法的{{力量不仅因其地位崇高}}，{{更源于}}宪法有效的{{监督}}\n加强宪法实施，党首先要坚持依宪执\n我国宪法保持生机活力的根本原因所在：坚定维护宪法尊严和权威","back":"","tags":["一页纸","宪法"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c198","front":"==法律至上==\n{{✅事事为}}\n法律至上具体表现为法律的：\n普遍{{适}}用性\n优先{{适}}用性\n不可{{违}}反性\n⚠️辨析：\n{{普遍}}适用性：\n关键词：{{所有人、所有机构、所有组织、都必须遵守}}\n{{优先}}适用性：\n多种规范矛盾{{优先考虑法律规范}}的适用\n不可违反性：\n{{不论权力大小、职位高低，只要有违法行为，就要受法律制裁}}","back":"","tags":["一页纸","法律至上"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c199","front":"==法律权利与义务（1）==\n法律权利\n1️⃣政治权利：\n选举权、表达权、民主管理权、监督权","back":"","tags":["一页纸","法律权利与义务"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c200","front":"==法律权利与义务（2）==\n2️⃣人身权利：\n人身权利是公民参加国家政治、经济与社会生活的{{基础}}\n{{第一，生命健康权}}\n{{生命权是人最基本、最原始的权利}}\n享有生命权是人享有其他各项权利的{{前提}}\n{{第二，人身自由权}}\n人身自由是人们一切行动和生活的前提条件\n{{第三，人格尊严权、住宅安全权、通信自由权}}\n{{人格尊严权：}}姓名权、肖像权、名誉权、荣誉权、{{隐私权}}\n{{住宅安全权：}}住宅不受侵犯权、非法侵入或搜查的权利\n{{通信自由权：}}根据自己的意愿进行通信\n3️⃣财产权利：\n私有财产权、继承权","back":"","tags":["一页纸","法律权利与义务"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c201","front":"==法律权利与义务（3）==\n4️⃣社会经济权利：\n第一，{{劳动权}}\n劳动权是公民赖以生存的基础，是行使其他权利的物质上的保障。\n第二，{{休息权}}\n休息权是劳动权存在和发展的基础。\n{{第三，社会保障权}}\n{{第四，物质帮助权}}\n如社会保险、社会救济和医疗卫生事业\n{{✅勿劳社经，多休息}}\n5️⃣宗教信仰自由\n公民有信与不信、何时信、信哪个宗教或教派等的自由\n同时，公民行使宗教信仰自由的权利也必须受宪法法律约束","back":"","tags":["一页纸","法律权利与义务"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c202","front":"==法律权利与义务（4）==\n6️⃣文化教育权利\n教育方面的权利主要表现为{{受教育权}}\n受教育权是公民在教育领域享有的基本权利，\n是公民接受文化、科学等方面训练的权利\n文化活动方面的权利主要表现为公民的{{文化权利}}\n主要包括科学研究的自由、文学艺术创作的自由和进行其他文化活动的自由\n权利行使的方式分为口头方式、书面方式和行为方式，\n有时口头方式和书面方式可以兼用\n{{🚩法律权利}}区别于其他权利的根本所在{{是它由}}国家强制力{{保障其实现}}\n🚩{{马克思主义权利观}}与其他权利观的根本区别：\n强调{{社会的物质生活条件}}对权利的制约和决定作用\n🚩{{法律}}权利的实现{{必须以相应法律}}义务的履行{{为条件}}\n🚩法律权利的特征：{{依法执行，不可侵犯}}\n法律义务\n🚩法律{{义务}}的履行表现形式：{{作为，不作为}}\n{{🚩}} 我国公民的最高法律义务是：\n维护国家统一和全国各民族团结","back":"","tags":["一页纸","法律权利与义务"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c203","front":"==公平==\n{{权利公平}}包括三重含义：\n一是权利{{主}}体平等；\n二是享有的权利特别是{{基}}本权利平等；\n三是权利{{保}}护和权利救济平等\n✅煮鸡煲\n{{规则公平}}\n法律规则面前人人平等\n法律内容面前人人平等\n法律保护面前人人平等\n任何人不得享有法律之外的特权；\n任何人也不会被法律排除在保护之外。","back":"","tags":["一页纸","公平"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c204","front":"==理想信念==\n{{🚩理想信念}}是{{思想认识}}问题，{{更是}}一个{{实践}}问题\n🚩公民道德建设的{{重要阵地}}是{{学校}}\n家庭是社会的基本细胞，是道德养成的起点\n互联网为道德实践提供了新的空间、新的载体务\n学雷锋和志愿服务是践行社会主义道德的重要途径\n🚩新时代中国青年{{最好的课堂}}是{{基层}}\n实践是最好的老师\n父母是孩子的第一任老师\n家庭是人生的第一个课堂","back":"","tags":["一页纸","理想信念"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c205","front":"==道德==\n🚩道德以善恶为评价方式，发挥作用主要是依靠\n{{社会舆论、传统习俗和内心信念}}\n🚩世界观决定人生观\n🚩道德{{相对独立性}}既表现为\n道德的历史继承性\n道德对社会发展具有{{能动的反作用}}\n🚩中华{{传统美德}}是社会主义道德建设的{{源头活水}}\n🚩中华民族的{{民族心、民族魂}}：{{爱国主义}}\n⚠️辨析\n社会公德：\n{{文明礼貌、助人为乐、爱护公物、保护环境、遵纪守法}}\n职业道德：\n爱岗敬业、诚实守信、{{办事公道}}、热情服务、奉献社会\n🚩我们在借鉴和吸收人类文明优秀道德成果时\n{{必须}}借鉴吸收人类{{一切}}优秀文明成果\n🚩中华传统美德的{{根本}}要求{{“公义胜私欲”}}","back":"","tags":["一页纸","道德"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c206","front":"==爱国主义（1）==\n{{✅统一团结需要力}}\n弘扬新时代爱国主义的重要着{{力}}点和落脚点是：\n维护祖国{{统一}}和民族{{团结}}","back":"","tags":["一页纸","爱国主义"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c207","front":"==爱国主义（2）==\n⚠️辨析：\n1️⃣新时代党的{{民族工作}}的{{出发点和落脚点}}是：\n{{实现中华民族伟大复兴}}\n2️⃣新时代加强{{爱国主义教育}}的{{主题}}是：\n旧提法：实现中华民族伟大复兴的中国梦\n新提法：全面建成社会主义现代化强国实现中华民族伟大{{复兴}}\n{{3️⃣}}坚持和发展中国特色社会主义{{的}}总任务：\n实现社会主义现代化和中华民族伟大{{复兴}}\n{{🚩促进中华儿女大团结}}，是新时代爱国统一战线的历史责任\n坚持爱国和爱党、爱社会主义相统一，\n{{是当代中国爱国主义精神最重要的体现}}\n{{爱国主义的本质}}，就是坚持爱国和爱党、爱社会主义高度统一。","back":"","tags":["一页纸","爱国主义"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c208","front":"==马克思主义科学理论==\n党坚定信仰信念 把握历史主动的{{根本}}所在\n党鲜明的政治品格和强大的政治优势：\n{{拥有马克思主义科学理论指导}}","back":"","tags":["一页纸","马克思主义科学理论"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c209","front":"==实现党的全面领导==\n党中央对重大工作的领导体制，\n是加强党的全面领导的制度安排，\n{{是实现党的全面领导的直接体现。}}\n加强党的全面领导，\n必须加强党中央对党和国家重大工作的领导。","back":"","tags":["一页纸","实现党的全面领导"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c210","front":"==党内监督，制度建设，纪律建设==\n{{1️⃣党内监督}}是永葆党的肌体健康的生命之源，\n在党和国家各种监督形式中是{{最根本的、第一位的}}\n{{2️⃣制度建设}}是贯穿在政治建设、思想建设、组织建设、作风建设、纪律建设之中的\n3️⃣{{加强纪律}}建设是{{全面从严治党}}的{{治本之策}}","back":"","tags":["一页纸","党内监督，制度建设，纪律建设"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c211","front":"==我们党区别于其他政党==\n1️⃣中国共产党区别于其他任何政党的显著标志：三大作风（七大）\n2️⃣我们党区别于其他政党的显著标志：勇于自我革命\n3️⃣我们党区别于其他一切政党{{根本}}的{{标志}}：{{全心全意为人民服务}}\n4️⃣我们党区别于其他政党的{{显著标志}}：{{人民立场（新大纲）}}\n{{⚠️人民立场}}\n是中国共产党的{{根本政治立场}}\n是我们党区别于其他政党的{{显著标志️}}","back":"","tags":["一页纸","我们党区别于其他政党"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c212","front":"==党的领导==\n中国特色社会主义{{最本质的特征}}是：{{党的领导}}\n中国特色社会主义制度的{{最大优势}}是：{{党的领导}}\n中国特色社会主义制度体系的{{“根”和“源”}}是：{{党的领导}}制度\n推进全面依法治国的{{根本保证}}是：{{党的领导}}\n人民当家作主的{{根本保证}}是：{{党的领导}}\n推进全面依法治国的{{根本保证}}、我国社会主义{{法治之魂}}是：{{党的领导}}\n社会主义法治{{最根本的保证}}：{{党的领导}}\n维护国家安全和社会安定的{{根本保证}}是：坚持{{党}}对国家安全工作{{的绝对领导}}\n中华民族伟大复兴的{{根本保证}}是：{{党的领导}}\n我们的法治{{同西方}}资本主义国家的法治{{最大的区别}}：{{党的领导}}\n生态文明建设的{{根本保证}}是：加强{{党}}对生态文明建设{{的全面领导}}\n进一步全面深化改革、推进中国式现代化的{{根本保证}}是：{{党的领导}}\n统一战线{{最鲜明}}的特征：{{党的领导}}\n统一战线{{最核心最根本}}的问题：坚持{{党的领导}}\n党中央集中统一领导{{是}}\n1️⃣党的领导的{{最高原则}}\n2️⃣党保持团结统一和强大战斗力 {{不断取得胜利的关键}}所在\n{{✅根本保证党领导 胜利关键党领导}}","back":"","tags":["一页纸","党的领导"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c213","front":"==全面从严治党（1）==\n{{1️⃣党内监督}}是永葆党的肌体健康的生命之源，\n在党和国家各种监督形式中是{{最根本的、第一位的}}\n{{2️⃣制度建设}}是贯穿在政治建设、思想建设、组织建设、作风建设、纪律建设之中的\n3️⃣{{加强纪律}}建设是全面从严治党的{{治本之策}}\n党的纪律是多方面的，\n其中{{政治纪律}}是最重要、最根本、最关键的纪律，\n遵守党的政治纪律是遵守党的全部纪律的重要基础。\n{{🚩作风问题的核心是党同人民群众的关系问题}}","back":"","tags":["一页纸","全面从严治党"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c214","front":"==全面从严治党（2）==\n{{🚩}}中央八项规定{{是}}\n{{新时代制定的第一部重要党内法规}}\n新时代的徙木立信之举\n改进作风的切入口和动员令\n开启新时代中国共产党人再塑自身形象的{{“第一行动”}}\n🚩党中央坚持从中央政治局做起、从领导干部抓起， 以上率下改进工作作风的{{破题点}}是{{落实中央八项规定}}\n{{✅八项破题第一动}}\n🚩锲而不舍{{落实中央八项规定}}精神，要达到的{{目的}}是\n推进作风建设常态化长效化\n✅{{八项目的}}常态化\n🚩关于跳出历史周期率问题\n{{毛泽东给出了第一个答案“让人民来监督政府”}}\n习核心找到了{{第二个}}答案{{“自我革命”}}","back":"","tags":["一页纸","全面从严治党"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c215","front":"==全面从严治党（3）==\n⚠️关于自我革命：\n1️⃣中国共产党区别于其他政党的{{显著标志}}：{{勇于自我革命}}\n2️⃣党最{{鲜明}}的{{品格}}：{{勇于自我革命}}\n3️⃣党如何跳出治乱兴衰的历史周期率给出的{{第二个答案}}：{{勇于自我革命}}\n4️⃣党{{最大}}的{{优势}}是：{{勇于自我革命}}\n🚩我们党作为马克思主义政党的{{根本要求}}是{{旗帜鲜明讲政治 ✅马+旗}}\n党的政治建设的首要任务：维护党中央权威和集中统一领导\n党的基础性建设：加强思想建设\n🚩全面从严治党的{{“必答题”}}是{{反腐败}}斗争\n标本兼治是新时代推进反腐败斗争的鲜明特征","back":"","tags":["一页纸","全面从严治党"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c216","front":"==全面从严治党（4）==\n🚩在深入推进党的自我革命实践中需要把握好九个问题，即\n党的领导—根本保证\n引领社会革命—根本目的，\n新思想—根本遵循\n以跳出历史周期率—战略目标\n解决大党独有难题—主攻方向\n健全从严治党体系—有效途径\n锻造组织建设队伍—重要着力点\n正风肃纪反腐—重要抓手\n自我监督和人民监督相结合—强大动力\n🚩坚持以党的自我革命引领社会革命，持之以恒推进全面从严治党，{{增强}}党的\n{{政}}治领导力、{{思}}想引领力、{{群}}众组织力、{{社}}会号召力\n🚩党的{{基础性建设}}是{{思想建设}}\n🚩在全面从严治党中，发挥{{统领性作用}}的是党的{{政治建设}}\n🚩做好新时代思想政治工作放在{{首位}}的是\n用党的{{创新}}理论武装头脑、统一思想、凝聚共识、指导{{实践}}","back":"","tags":["一页纸","全面从严治党"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c217","front":"==新发展理念🥷==\n{{✅宫本武藏对绿箭心动用开塞露内调}}\n{{共}}享—{{本}}质要求\n{{绿}}色—必要条{{件}}\n创{{新}}—第一{{动}}力\n{{开}}放—必由之{{路}}\n协{{调}}—{{内}}在要求","back":"","tags":["一页纸","新发展理念🥷"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c218","front":"==科学发展观==\n{{✅法医仁心在房间吃鸡}}\n推动经济社会{{发}}展—第一要{{义}}\n以{{人}}为本—核{{心}}立场\n统筹{{兼}}顾—根本{{方}}法\n全面协调可{{持}}续—{{基}}本要求","back":"","tags":["一页纸","科学发展观"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c219","front":"==新发展格局==\n{{✅店内神仙本子多房间灌肠留成绩🔞}}\n构建新发展格局\n基本立足{{点}}—满足国{{内}}需求\n战略基{{点}}—扩大{{内}}需\n主{{线}}—{{深}}化供给侧结构性改革\n最{{本}}质特征—实现高水平{{自}}立自强\n战略{{方}}向—{{坚}}持供给侧结构性改革\n{{关}}键—经济循环{{畅}}通无阻\n战略支{{撑}}—科{{技}}自立自强\n我们要构建的新发展格局：\n以{{国内}}大循环为{{主体}}、\n{{国内国际双循环相互促进}}","back":"","tags":["一页纸","新发展格局"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c220","front":"==新发展理念==\n{{✅红绿灯跟导游（根导多了就会忧患）}}\n新发展理念是指挥棒{{红绿灯}}\n是引领我国发展全局深刻变革的科学指引\n必须完整准确全面地理解和把握要从\n{{根本宗旨上}}把握新发展理念\n{{问题导向上}}把握新发展理念\n{{忧患意识上}}把握新发展理念\n🚩科学回答了中国发展面临的一系列理论和实践问题，\n为新时代中国经济的{{跨越与蝶变}}提供了{{根本指引}}的是{{新发展理念}}","back":"","tags":["一页纸","新发展理念"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c221","front":"==高质量发展（1）==\n{{✅科比公主爱打农药是歌姬没有福目}}","back":"","tags":["一页纸","高质量发展"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c222","front":"==高质量发展（2）==\n推动高质量发展的{{必}}由之路—加快实现高水平{{科}}技自立自强\n推动高质量发展的{{主}}线—深化{{供}}给侧改革\n推动高质量发展的必然{{要}}求—推进{{农}}业现代化\n推动高质量发展的战略{{基}}点—加快构建新发展{{格}}局\n推动高质量发展的最终{{目}}的—人民幸{{福}}安康\n{{✅高质量现任}}\n{{高质量发展}}\n是全面建设社会主义{{现}}代化国家的首要{{任}}务\n{{⚠️辨析}}\n解放和发展社会生产力{{是改革开放的鲜明特征和首要任务}}\n维护党中央权威和集中统一领导{{是党的政治建设的首要任务}}","back":"","tags":["一页纸","高质量发展"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c223","front":"==高质量发展（3）==\n推动经济社会发展{{绿色化低碳化}}是实现高质量发展的{{关键环节}}\n新时代我国经济社会发展的{{鲜明主题}}是{{高质量发展}}\n新时代我国经济发展{{的基本特征}}：{{由高速增长阶段}}转向高质量发展阶段\n🚩建设{{现代化产业体系}}要坚持把{{发展经济}}的{{着力点}}放在{{实体经济}}上\n🚩推动高质量发展的内在要求和重要着力点是{{发展新质生产力}}","back":"","tags":["一页纸","高质量发展"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c224","front":"==“一带一路”的原则==\n共商共建共享","back":"","tags":["一页纸","“一带一路”的原则"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c225","front":"==制度==\n{{政协制度是基本政治制度}}\n{{人大制度是根本政治制度}}\n{{⚠️易错点}}\n{{政协是组织不是制度}}\n{{政协制度是制度}}","back":"","tags":["一页纸","制度"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c226","front":"==精神核心==\n时代精神的核心：改革创新\n民族精神的核心：爱国主义\n五四精神的核心：爱国主义","back":"","tags":["一页纸","精神核心"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c227","front":"==平等==\n社会主义法律的基本属性\n社会主义法治的基本要求","back":"","tags":["一页纸","平等"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c228","front":"==人口==\n促进{{人口高质量发展}}的{{重点}}是应对老龄化、少子化","back":"","tags":["一页纸","人口"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c229","front":"==金融工作==\n{{根本宗旨—金融服务实体经济}}\n{{永恒主题—防控风险}}","back":"","tags":["一页纸","金融工作"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c230","front":"==统一战线工作==\n统战工作的本质要求-大团结大联合\n统战工作的关键-坚持求同存异","back":"","tags":["一页纸","统一战线工作"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c231","front":"==调查研究==\n{{贯彻群众路线的有效途径是调查研究}}","back":"","tags":["一页纸","调查研究"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c232","front":"==共建共治共享==\n{{✅剑姬只管橡木}}\n共{{建}}是{{基}}础\n共{{治}}是{{关}}键\n共{{享}}是{{目}}标","back":"","tags":["一页纸","共建共治共享"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c233","front":"==根基前提辨析==\n{{✅全腹肌舌吻强 弄射鸡}}\n国家安{{全}}是民族{{复}}兴的根{{基}}\n{{社}}会{{稳}}定是国家{{强}}盛的前提\n{{农}}业强国是{{社}}会主义现代化强国的根{{基}}","back":"","tags":["一页纸","根基前提辨析"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c234","front":"==共同富裕==\n🚩促进共同富裕的基础性制度是{{分配制度}}\n共同富裕是全体人民共同富裕\n是人民群众{{物质}}生活和{{精神}}生活都富裕\n{{不是}}少数人的富裕\n{{不是}}整齐划一的平均主义\n{{不是}}所有人都同时富裕\n{{也不是}}所有地区同时达到一个富裕水准","back":"","tags":["一页纸","共同富裕"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c235","front":"==改善生活==\n{{✅结合改善生活}}\n正确处理改革发展稳定关系的{{结合}}点：{{改善生活}}","back":"","tags":["一页纸","改善生活"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c236","front":"==工人阶级与工会==\n1️⃣我国{{工人阶级}}\n是中国共产党最坚实最可靠的阶级基础\n是我们社会主义国家的{{领导阶级}}\n是先进生产力和生产关系的代表\n是坚持和发展中国特色社会主义的{{主力军}}\n2️⃣我国{{工会}}\n是党联系职工群众的桥梁和纽带\n是社会主义国家政权的重要社会支柱\n是职工利益的代表者和维护者","back":"","tags":["一页纸","工人阶级与工会"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c237","front":"==摸石头过河==\n{{✅摸石头改革}}\n富有中国特色 符合中国国情的改革方法：{{摸石头过河}}","back":"","tags":["一页纸","摸石头过河"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c238","front":"==高水平对外开放==\n我国构建更高水平开放型经济体制的{{重点}}是\n{{制度型开放}}\n🚩中国接下来扩大开放的{{重点}}是\n{{降低市场准入门槛}}\n{{对外开放}}始终把国家的{{主权和安全}}放在{{第一位}}","back":"","tags":["一页纸","高水平对外开放"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c239","front":"==四个全面战略布局==\n{{全面建设社会主义现代化国家（引领地位）、}}\n全面深化改革、\n全面依法治国、\n全面从严治党","back":"","tags":["一页纸","四个全面战略布局"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c240","front":"==国有企业==\n1️⃣中国特色社会主义的重要{{物质基础}}和{{政治基础}}\n2️⃣我们党执政兴国的{{重要支柱}}和{{依靠力量}}\n3️⃣中国特色社会主义经济的“顶梁柱”\n⚠️国有资本{{不强调比重}}，而是{{控制力}}\n国有经济控制国民经济的{{命脉}}","back":"","tags":["一页纸","国有企业"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c241","front":"==科技==\n🚩我国面临的很多{{“卡脖子”}}技术问题的{{根子}}是\n{{基础理论研究跟不上}}\n科技创新的源头：{{基础研究}}\n世界科技强国竞争的着力点是{{国家战略科技力量}}\n国之重器：关键核心技术\n我们攀登世界科技高峰的必由之路：自主创新\n实施创新驱动发展战略，必须把创新摆在国家发展全局的核心位置，{{最根本的}}是要{{增强自主创新能力}}","back":"","tags":["一页纸","科技"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c242","front":"==中国特色社会主义制度==\n坚定中国特色社会主义{{制度自信}}，\n{{首先}}要坚定对中国特色社会主义{{政治制度的自信}}，\n我们坚定“四个自信”的{{理论支撑}}和根本依据是\n{{马克思主义}}深刻揭示了社会主义必然代替资本主义的客观规律\n把中国特色社会主义制度坚持好完善好，{{最重要}}的是\n不断把我国{{制度优势}}更好{{转化}}为国家{{治理效能}}","back":"","tags":["一页纸","中国特色社会主义制度"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c243","front":"==一根红线==\n贯穿中国{{革命道德}}始终的一根红线是：\n{{全心全意为人民服务}}\n贯穿习近平新时代{{中国特色社会主义思想}}的一根红线：\n{{人民至上}}","back":"","tags":["一页纸","一根红线"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c244","front":"==一国两制==\n维护国家主权 安全 发展利益是\n1️⃣我国{{对外工作}}的{{出发点和落脚点}} 中国外交的神圣使命\n2️⃣一国两制的{{最高原则}}\n⚠️一国两制的{{根本宗旨}}：\n1️⃣维护{{国家}}主权安全发展利益\n2️⃣保持{{香港澳门}}长期繁荣稳定","back":"","tags":["一页纸","一国两制"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c245","front":"==关键一步，关键一招==\n{{✅小步放大招}}\n{{全面建成小康社会}}是迈向中华民族伟大复兴的关键一{{步}}\n{{改革开放}}是决定当代中国命运的关键一{{招}}，\n也是决定实现“两个一百年”奋斗目标、\n实现中华民族伟大复兴的关键一{{招}}\n也是决定中国式现代化成败的关键一{{招}}","back":"","tags":["一页纸","关键一步，关键一招"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c246","front":"==中国特色社会主义进入新时代判断依据==\n中国特色社会主义进入新时代重大判断的基本依据是：\n我国社会{{主要矛盾}}发生新变化","back":"","tags":["一页纸","中国特色社会主义进入新时代判断依据"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c247","front":"==坚持法治国家 法治政府 法治社会一体建设==\n{{✅国标争点机会}}\n法治{{国}}家是法治建设的目{{标}}\n法治{{政}}府建设是全面依法治国的重{{点}}任务和主体工程\n法治社{{会}}是构筑法治国家的{{基}}础\n法治社{{会}}建设是{{基}}础工程","back":"","tags":["一页纸","坚持法治国家 法治政府 法治社会一体建设"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c248","front":"==两大历史任务==\n争取民族独立、人民解放和实现国家富强、人民幸福\n两大历史任务既有区别，也有联系。\n1️⃣区别在于：两大历史任务的{{主题、内容和实现方式都不一样}}。\n2️⃣联系在于：\n前一个任务为后一个任务{{扫清障碍}}，\n为实现中华民族伟大复兴的中国梦创造必要前提；\n后一个任务是前一个任务的{{最终目的和必然要求}}。","back":"","tags":["一页纸","两大历史任务"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c249","front":"==民主政治==\n基层群众自治制度有利于\n人民在基层广泛、{{直接}}、有效行使民主权利\n发展基层民主为基层群众{{直接}}参与国家事务的管理提供了更多机会 {{✗错误}}\n国家事务不能直接参与 ✔️正确\n🚩社会主义民主政治的{{本质属性}}是{{全过程人民民主}}","back":"","tags":["一页纸","民主政治"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c250","front":"==必由之路==\n1️⃣\n坚持和发展{{中}}国{{特}}色社会主义的必由之路\n—坚持党的全面{{领导}}\n坚持和发展{{中}}国{{特}}色社会主义的必由之路\n{{—改革开放}}\n2️⃣\n实现中华民族伟大{{复兴}}的必由之路\n—{{中}}国{{特}}色社会主义\n中国人民{{创造历史}}伟业的必由之路\n—团结{{奋斗}}\n新时代我国发展壮{{大}}的必由之路\n—贯彻新发展{{理}}念\n{{党永葆}}生机{{活力}}、走好新的赶考之路的必由之路\n—全面从严{{治党}}\n{{3️⃣}}\n{{国家繁荣发展的必由之路—开放}}\n➡️新发展理念\n推动高质量发展的{{必}}由之路—高水平{{科}}技自立自强\n{{➡️}}高质量发展\n4️⃣\n我们攀登世界科技高峰的必由之路\n—自主创新\n全面准确贯彻“一国两制”方针的必由之路\n—依法治港治澳","back":"","tags":["一页纸","必由之路"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c251","front":"==出发点与落脚点（1）==\n✅除了{{标红}}特殊的，一般选人民\n(进一步)全面深化改革的出发点和落脚点是：{{促进社会公平正义、增进人民福祉}}\n我们一切工作的出发点和落脚点：{{让老百姓过上好日子}}\n现代化建设的出发点和落脚点：{{实现人民对美好生活的向往}}","back":"","tags":["一页纸","出发点与落脚点"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c252","front":"==出发点与落脚点（2）==\n人民军队一切行动的根本准则和一切工作的出发点与归宿：{{全心全意为人民服务}}\n国家富强、民族振兴的根本出发点和落脚点：{{人民幸福}}\n发展的出发点和落脚点：满足人民群众对美好生活的新期待\n社会主义改革开放的出发点和落脚点：\n更好实现和维护人民利益、让老百姓过上好日子/坚持以人民为中心\n民主政治建设的出发点和落脚点：{{实现最广大人民根本利益}}\n文艺和文艺工作的出发点和落脚点：{{满足人民精神文化需求}}\n全面建设社会主义现代化国家的出发点和落脚点：{{让人民生活越过越好}}","back":"","tags":["一页纸","出发点与落脚点"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c253","front":"==出发点与落脚点（3）==\n⚠️我国对外工作的出发点和落脚点是：{{维护国家主权、安全、发展利益}}\n⚠️弘扬新时代爱国主义的重要着力点和落脚点是：{{维护祖国统一和民族团结}}\n⚠️新时代党的{{民族工作}}的出发点和落脚点是：{{实现中华民族伟大复兴}}\n⚠️全军各项建设的出发点和落脚点：{{提高战斗力}}","back":"","tags":["一页纸","出发点与落脚点"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c254","front":"==生态文明（1）==\n良好的生态环境是\n最公平的公共产品\n最普惠的民生福祉\n🚩解决生态环境问题的{{治本之策}}是{{绿色低碳发展}}","back":"","tags":["一页纸","生态文明"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c255","front":"==生态文明（2）==\n推动经济社会发展绿色化、低碳化\n{{是}}新时代党治国理政新理念新实践的重要标志，\n{{是}}实现高质量发展的关键环节，\n{{是}}解决我国资源环境生态问题的基础之策，\n{{是}}建设人与自然和谐共生现代化的内在要求。\n生态文明建设\n{{核心理念}}-绿水青山就是金山银山\n宗旨要求-良好生态环境是最普惠的民生福祉\n战略路径-绿色发展是发展观的深刻革命\n根本保证-党对生态文明建设的全面领导","back":"","tags":["一页纸","生态文明"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c256","front":"==主流舆论新格局==\n新闻舆论工作的重要性\n处在意识形态斗争前沿，是治国理政、定国安邦的大事\n积极塑造主流舆论新格局\n新闻舆论工作有鲜明的意识形态属性\n{{坚持正确的政治方向是做好新闻舆论工作的第一位要求}}\n{{党性原则}}是新闻舆论工作的{{根本原则}}\n{{新闻媒体}}，是社会舆论的{{发射器和放大器}}\n做大做强主流舆论阵地，\n对推进社会主义现代化事业的顺利发展具有重要意义。\n{{🚩互联网是意识形态工作的主阵地、主战场、最前沿}}\n{{管好用好互联网}}是新形势下做好新闻舆论工作的{{关键}}","back":"","tags":["一页纸","主流舆论新格局"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c257","front":"==外交==\n1️⃣中国外交政策的{{宗旨}}：\n维护世界和平促进共同发展\n2️⃣中国特色大国外交牢牢把握的{{主线}}是：\n服务民族复兴促进人类进步\n{{3️⃣}}周边外交\n{{理念}}—亲诚惠容\n{{方针}}—亲诚惠容和与邻为善以邻为伴\n4️⃣新型国际关系：新在相互尊重、公平正义、合作共赢\n推动构建新型国际关系就是要秉持\n相互尊重公平正义合作共赢{{原则}}（{{合作共赢}}是{{核心}}）\n走出一条对话而不对抗结伴而不结盟的国与国交往新路","back":"","tags":["一页纸","外交"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c258","front":"==军队==\n新时代加强军队建设的聚焦点和着力点是\n{{听党指挥（灵魂、政治方向）}}\n{{能打胜仗（核心、根本职能、根本指向）}}\n{{作风优良（保证、性质宗旨本色）}}\n坚持党对人民军队绝对领导的{{根本制度和根本实现形式}}是{{军委主席负责制}}","back":"","tags":["一页纸","军队"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c259","front":"==中国式现代化（1）==\n中国式现代化五个特征：\n{{✅先生奔赴出道娶媳妇球鞋特显大}}\n1️⃣中国式现代化的本质特征区别于西方现代化的显著标志：\n全体人民共同{{富}}裕的现代化{{（奔赴）}}\n2️⃣中国式现代化的显著特征：\n人口规模巨{{大}}的现代化{{（特显大）}}\n3️⃣中国式现代化的突出特征：\n走和平发展{{道}}路的现代化{{（出道）}}\n4️⃣中国式现代化的鲜明特点：\n人与自然和谐共{{生}}的现代化{{（先生）}}\n5️⃣中国式现代化的崇高追求社会主义现代化的本质要求：\n物质文明和精神文明相{{协}}调的现代化{{（球鞋）}}","back":"","tags":["一页纸","中国式现代化"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c260","front":"==中国式现代化（2）==\n中国式现代化创造了人类文明的新形态\n中国式现代化提供了一种全新的现代化模式\n中国式现代化是对西方式现代化理论和实践的重大超越\n中国式现代化为广大发展中国家提供了全新选择","back":"","tags":["一页纸","中国式现代化"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c261","front":"==中国式现代化（3）==\n{{✅关于中国式现代化的帽子总结}}\n🚩中国式现代化必须优先补上的{{最大短板}}是{{农业农村现代化}}\n{{开放}}是中国式现代化的{{鲜明标识}}\n发展全过程人民民主是中国式现代化的本质要求\n中国式现代化是强国建设、民族复兴的{{唯一}}正确道路","back":"","tags":["一页纸","中国式现代化"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c262","front":"==民族==\n民族团结之{{本}}\n{{中华民族共同体意识}}\n{{✅本-体}}\n新时代党的民族工作的{{主线}}\n民族地区各项工作的{{主线}}\n{{铸牢中华民族共同体意识}}\n{{✅主-铸}}\n{{🚩新时代新疆工作的总目标是社会稳定和长治久安}}\n治藏稳藏兴藏，首先是要保持{{西藏}}\n政治安定、{{社会稳定}}、民族团结、宗教和顺\n🚩中华民族共同体形成和发展的{{内生动力}}是{{各民族信念相同}}\n中华民族共同体意识\n是国家统一之基、民族团结之本、精神力量之魂、社会安定基石\n🚩保证全党全国各族人民思想统一的{{坚实基础}}是{{思想引领力}}","back":"","tags":["一页纸","民族"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c263","front":"==进一步全面深化改革==\n{{1️⃣自主呻吟集中重口}}\n统筹推进各领域各方面改革开放必须\n以全面{{深}}化改革总目标为{{引}}领\n以{{制}}度建设为{{主}}线\n以经{{济}}体制改革为{{重}}点{{（牵引）}}\n以{{重}}要领域和关键环节改革为突破{{口}}\n使各方面改革协同推进环环相扣形成合力\n2️⃣进一步全面深化改革主题：{{推进中国式现代化}}\n3️⃣进一步全面深化改革{{总目标}}：\n继续完善和发展中国特色社会主义制度\n推进国家治理体系和治理能力现代化；\n4️⃣进一步全面深化改革坚持的{{原则}}：\n我们必须在进一步全面深化改革中严格遵循、长期坚持六条原则，\n1.以坚持党的全面领导为根本保证【排在首位】\n2.以坚持以人民为中心为价值导向\n3.以坚持守正创新为基本原则\n4.以坚持以制度建设为主线为重要要求\n5.以坚持全面依法治国为有效途径\n6.以坚持系统观念为科学方法，\n不断推动全面深化改革向广度和深度进军\n🚩新时代全面深化改革的{{关键}}所在：{{解放和增强社会活力}}\n全面深化改革是时代坚持和发展中国特色社会主义的根本动力\n🚩当代中国最鲜明的特色是{{改革开放}}","back":"","tags":["一页纸","进一步全面深化改革"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c264","front":"==教育（1）==\n{{🚩教育强国}}\n根本保证—党对教育事业的全面领导\n根本{{任务}}—立德树人\n根本{{目标}}—为党育人 为国育才\n重要{{使命}}—服务中华民族{{伟大复兴}}\n核心{{功能}}—{{支撑}}引领中国式{{现代化}}\n🚩教育的根本问题 建设教育强国的核心课题：\n{{培养什么人 怎样培养人 为谁培养人}}\n🚩发展教育的根本尺度：{{人民满意}}\n{{🚩教育科技人才是}}\n全面建设社会主义现代化国家的{{基础性战略性支撑，先导任务}}\n{{🚩建成教育强国是}}\n近代以来中华民族梦寐以求的美好愿望，是实现以中国式现代化全面推进强国建设、民族复兴伟业的{{坚实基础，战略支撑，先导任务}}\n（仙剑斩）\n🚩必须坚持\n{{科技—第一生产力}}\n{{人才—第一资源}}\n（实现民族振兴、赢得国际竞争主动的战略资源：{{人才}}）\n{{创新—第一动力}}\n🚩办好人民满意的教育，根本在于{{深化教育综合改革}}\n{{🚩教育优先发展}}是推动党和国家各项事业发展的重要{{先手棋}}。\n🚩坚持社会主义办学方向，全面把握教育的\n政治属性、人民属性、战略属性\n干扰项：经济属性，创新属性","back":"","tags":["一页纸","教育"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c265","front":"==教育（2）==\n建设教育强国是\n全面建成社会主义现代化强国的战略先导\n实现高水平科技自立自强的重要支撑\n促进全体人民共同富裕的有效途径\n以中国式现代化全面推进中华民族伟大复兴的基础工程\n{{🚩建设教育强国最重要的基础工作}}加强教师队伍建设\n教育是\n民族振兴、社会进步的基石\n强国建设、民族复兴之基\n国之大计、党之大计，\n国家经济社会发展的支撑力量，\n在国家发展中始终具有基础性先导性全局性地位。","back":"","tags":["一页纸","教育"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c266","front":"==文化==\n中华优秀{{传统文化}}——我们坚定文化自信的{{深厚基础}}\n党带领人民在伟大斗争中孕育的{{革命文化}}和社会主义{{先进文化}}\n——我们坚定文化自信的{{坚强基石（革基）}}\n中国特色社会主义{{伟大实践}}——我们坚定文化自信的{{现实基础}}\n{{我们}}区别于其他国家和民族{{的根本特征}}：\n中华民族创造的{{优秀传统文化}}\n{{文化自信坚定到底}}\n坚定中国特色社会主义道路自信 理论自信 制度自信\n说到底是要坚定：文化自信\n🚩创新创造是\n文化的{{生命}}所在，是文化的{{本质特征}}\n繁荣发展社会主义文化的重要方针：{{坚持百花齐放、百家争鸣}}\n推动社会主义文化繁荣兴盛的{{唯一}}正确道路\n中国特色社会主义文化发展道路\n🚩决定社会主义文化事业前途命运的{{关键}}\n坚持为人民服务、为社会主义服务的{{根本方向}}\n一个国家的文化软实力，从{{根本}}上说\n取决于其{{核心价值观}}的生命力、凝聚力、感召力\n满足人民精神文化需求、保障人民文化权益的基本途径共同体意识：繁荣发展文化事业和文化产业\n🚩新形势下，{{深化文化体制机制改革}}的{{中心环节}}是：\n激发创新创造活力\n🚩中国特色社会主义的文化{{根脉}}和突出优势\n连绵不绝的中华5000多年文明\n🚩建设社会主义文化强国、推动社会主义文化繁荣兴盛，关键是\n坚定中国特色社会主义文化自信","back":"","tags":["一页纸","文化"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c267","front":"==经济==\n🚩{{市场经济}}作为资源配置手段，本身{{不具有制度属性}}\n可以和不同的社会制度结合\n它和不同的社会制度结合具有不同的性质\n🚩构建高水平社会主义市场经济体制{{关键是要处理好政府和市场的关系}}\n构建亲清政商关系{{本质上是正确处理政府和市场的关系}}\n🚩{{民营经济}}是非公有制经济，\n是推进中国式现代化的{{生力军（不等于主力军）}}\n⚠️一个重要辨析：\n• 社会主义经济：{{特指公有制经济，是制度基础与本质体现}}\n• 社会主义市场经济：\n{{在公有制为主体下，公有制与非公有制经济都是重要组成部分，共同发展}}\n外资/民营经济是社会主义经济的重要组成部分 {{✘错误}}\n外资/民营经济是社会主义{{市场}}经济的重要组成部分 {{✔️正确}}\n公有制经济和非公有制经济都是社会主义经济的重要组成部分{{✘错误}}\n公有制经济和非公有制经济都是社会主义{{市场}}经济的重要组成部分{{✔️正确}}","back":"","tags":["一页纸","经济"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c268","front":"==就业及民生==\n{{1️⃣就业（三基）}}\n① 最基本的民生\n② 最大的民生工程、民心工程、根基工程\n③ 劳动者赖以生存和发展的基础、共享经济发展成果的基本\n2️⃣收入分配\n是民生之源，是改善民生、实现发展成果由人民共享最重要最{{直接}}的方式\n3️⃣人力资源供需不匹配,是当前{{我国就业领域面临}}的{{主要矛盾}}。\n4️⃣就业是\n民生改善的{{“温度计”}}\n经济发展的{{“晴雨表”}}\n劳动者获得{{收入}}、提高生活水平的{{基本途径}}\n支撑宏观经济和微观{{经济运行}}的{{“基本盘”}}\n5️⃣我国着力解决结构性就业矛盾的主要举措是\n第一，提高教育供给与人才需求的匹配度；\n第二，健全终身职业技能培训制度；\n第三，拓宽技能人才发展通道。\n🚩时代新征程就业工作的{{新定位、新使命}}是{{促进高质量充分就业}}\n🚩保障和改善{{民生}}的重中之重：\n解决人民群众最关心最直接最现实的{{利益}}问题\n🚩解决{{民生问题}}的{{“总钥匙”}}是{{发展}}\n{{🚩}}社会主义生产的{{根本目的增进民生福祉}}","back":"","tags":["一页纸","就业及民生"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c269","front":"==中华文明的突出特性==\n中华文明突出特性对中华民族的深远影响：\n①{{连续性}}（决定1个）从根本上决定了中华民族必然走自己的{{路}}（{{陆续}}）\n②{{创新性}}（决定2个）从根本上\n决定了中华民族守正不守旧、尊古不复古的进取精神，\n决定了中华民族不惧新挑战、勇于接受新事物的无畏品格\n③{{统一性}}（决定4个）从根本上\n决定了中华民族各民族文化{{融为一体}}、即使遭遇重大挫折也牢固凝聚，\n决定了国土不可分、国家不可乱、民族不可散、{{文明不可断}}的共同信念，\n决定了国家统一永远是中国核心利益的核心，\n决定了一个坚强统一的国家是各族人民的命运所系\n易错：{{文明不可断的共同信念是统一性决定的，不是连续性。}}\n记住口诀：{{统一了就不会断}}\n④{{包容性}}（决定3个）从根本上\n决定了中华民族交往交流交融的历史取向，\n决定了中国各宗教信仰多元并存的和谐格局，\n决定了中华文化对世界文明兼收并蓄的开放胸怀\n⑤{{和平性}}（决定4个）从根本上\n决定了中国始终是世界和平的建设者、全球发展的贡献者、国际秩序的维护者，\n决定了中国不断追求文明交流互鉴而不搞文化霸权，\n决定了中国不会把自己的价值观念与政治体制强加于人，\n决定了中国坚持合作、不搞对抗，决不搞“党同伐异”的小圈子\n{{✅一连创死俩捅死包小三}}","back":"","tags":["一页纸","中华文明的突出特性"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c270","front":"==总体国家安全观（1）==\n{{✅人质在异国爆射 根治鸡精}}\n宗{{旨}}—{{人}}民安全\n{{根本—政治安全}}\n基{{础}}—{{经}}济安全\n保{{障}}—{{社}}会安全\n依{{托}}—{{国}}际安全","back":"","tags":["一页纸","总体国家安全观"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c271","front":"==总体国家安全观（2）==\n政治安全与人民安全 国家利益至上的有机统一\n确保实现党的长期执政 人民安居乐业 国家长治久安\n1️⃣政治安全是维护人民安全和国家利益的{{根本保证}}\n2️⃣人民安全居于{{中心}}地位 国家安全{{归根到底}}是保障人民利益\n3️⃣国家利益至上是实现政治安全和人民安全的{{要求和准则}}\n健全{{国家}}安全体系、加强{{国家}}安全制度建设{{（两个\"国家\"）}}\n是保障国家安全的{{治本之策}}，是维护和塑造国家安全的重要支撑。\n国土安全{{是立国之基}}（土🐔）\n构建统筹各领域安全的新安全格局，\n🚩必须把{{维护政治安全}}作为应对各领域安全风险挑战的{{首要任务}}。\n{{政治安全}}是国家安全的{{根本}}。","back":"","tags":["一页纸","总体国家安全观"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c272","front":"==总体国家安全观（3）==\n🚩{{政治安全}}是新时代中国国家安全的{{生命线}}\n政治安全{{的核心}}是政权安全和制度安全\n{{最根本}}的就是维护中国共产党的领导和执政地位、维护中国特色社会主义制度\n防范化解各类风险是平安中国建设的一项重要任务。要把捍卫国家{{政治安全}}摆在{{首位}}。\n🚩构建统筹各领域安全的新安全格局的主阵地、主战场是\n{{维护重点领域国家安全}}\n坚守维护国家利益准则\n这是新时代中国国家安全的{{基本要求}}。\n中国维护国家安全，主要是维护国家利益尤其是核心利益\n中国核心利益主要包括：\n国家政权、主权、统一和领土完整、人民福祉、经济社会可持续发展。\n防范化解国家安全风险\n这是新时代中国国家安全的{{中心任务}}\n国家安全是中国式现代化行稳致远的重要基础","back":"","tags":["一页纸","总体国家安全观"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c273","front":"==全面推进乡村振兴（1）==\n1️⃣{{乡村振兴}}\n{{前提}}：巩固脱贫攻坚成果\n{{底线：}}确保国家粮食安全、确保农村人口不发生规模性返贫致贫\n{{重中之重}}是提升农业综合生产能力和质量效益\n头等大事：{{保障粮食}}和重要农产品稳定安全{{供给}}\n{{重点：}}提升{{乡村产业发展}}水平、提升{{乡村建设}}水平、提升{{乡村治理}}水平\n全面推进{{乡村振兴}}是新时代建设农业强国的{{重要任务}}\n🚩一号文件{{首次提出}}因地制宜发展{{农业新质生产力}}\n2️⃣“三农”工作\n{{战略总纲：}}加快建设农业强国\n{{总抓手：}}推进乡村全面振兴{{（手抓面）}}\n{{中心任务：}}增加农民收入\n{{引领：}}学习运用“千万工程”经验\n3️⃣农业强国是社会主义现代化强国的{{根基}}\n全面建设社会主义现代化国\n最艰巨最繁重的任务仍然在农村\n最广泛最深厚的基础仍然在农村","back":"","tags":["一页纸","全面推进乡村振兴"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c274","front":"==全面推进乡村振兴（2）==\n4️⃣加快建设农业强国\n必须巩固和完善农村基本经营制度，牢牢守住{{底线}}：\n❶土地{{公有制}}性质不改变\n❷耕地{{红线}}不突破\n❸农民利益不受损\n{{⚠️}}我国农村土地实行使用权、承包权、经营权“三权分置”\n{{农村土地经营权是可以流转的}}\n5️⃣坚持和完善农村基本经营制度是\n党的农村政策的{{基石}}\n新形势下农村改革的{{最大的政策}}\n✅大鸡精是基石","back":"","tags":["一页纸","全面推进乡村振兴"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c275","front":"==台湾相关==\n① 必须坚持党中央对对台工作的集中统一领导，这是统一的根本保证。\n② 坚持在中华民族伟大复兴进程中推进祖国统一，这是统一的历史方位。\n③ 坚持在祖国大陆发展进步基础上解决台湾问题，这是统一的{{战略思路}}。\n④ 坚持“和平统一、一国两制”基本方针，这是统一的大政方针。\n⑤ 坚持一个中国原则和“九二共识”，这是统一的政治基础。\n⑥ 坚持推动两岸关系和平发展、融合发展，这是统一的实践途径。\n⑦ 坚持团结台湾同胞、争取台湾民心，这是统一的{{根本动力}}。\n⑧ 坚持粉碎“台独”分裂图谋，这是统一的必然要求。\n⑨ 坚持反对外部势力干涉，这是统一的外部条件。\n⑩ 坚持决不承诺放弃使用武力，这是统一的{{战略支撑}}。","back":"","tags":["一页纸","台湾相关"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c276","front":"==六个必须坚持（1）==\n习近平新时代中国特色社会主义思想的世界观方法论：\n坚持人民至上、自信自立、守正创新、问题导向、系统观念、胸怀天下","back":"","tags":["一页纸","六个必须坚持"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c277","front":"==六个必须坚持（2）==\n{{✅本人思念胸境导实的新鲜精自}}\n坚持{{人}}民至上是根{{本}}价值立场体现了{{历史唯物主义群众史观}}\n{{坚持自信自立}}是{{内在精神特征}}体现了客观规律性和主观能动性的有机结合\n{{坚持守正创新}}是{{鲜明理论品格}}体现了变与不变继承与发展的内在联系\n坚持问题{{导}}向是重要{{实}}践要求体现了{{矛盾的普遍性和客观性}}\n坚持系统观{{念}}是基本{{思}}想和工作方法体现了{{辩证唯物主义普遍联系的原理}}\n{{坚持胸怀天下}}是中国共产党人的{{境界格局}}\n体现了马克思主义追求人类进步和解放的崇高理想","back":"","tags":["一页纸","六个必须坚持"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c278","front":"==2035和2050目标（1）==\n《中共中央关于进一步全面深化改革推进中国式现代化的决定》指出，\n进一步全面深化改革的总目标是\n继续完善和发展中国特色社会主义制度，\n推进国家治理体系和治理能力现代化。\n{{到2035年，}}\n全面建成高水平社会主义市场经济体制，\n中国特色社会主义制度更加完善，\n基本实现国家治理体系和治理能力现代化，\n基本实现社会主义现代化，\n2035年基本实现社会主义现代化时，我国才成为{{先进的工业国}}\n人均国内生产总值达到中等发达国家水平，\n是2035年我国基本实现社会主义现代化的一个重要标志性指标\n现代化经济体系{{已经}}形成 {{✗错误}}\n我国{{正在}}建设现代化经济体系✔️正确\n我国经济{{始终保持高速}}增长 {{✘错误}}\n我国经济{{已}}由高速增长阶段{{转向高质量}}发展阶段 {{✔️正确}}","back":"","tags":["一页纸","2035和2050目标"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c279","front":"==2035和2050目标（2）==\n{{✅两步走战略}}\n{{1️⃣}}从2020年到2035年{{基本实现社会主义现代化}}\n2️⃣{{从2035年到本世纪中叶}}把我国建成富强民主文明和谐美丽的{{社会主义现代化强国}}\n{{到那时 全体人民共同富裕基本实现}}\n❗❗❗\n{{2035}}一般都是“{{模糊}}说法”\n{{2050}}一般都是{{确切}}性说法\n🚩2050年目标：{{全体人民共同富裕基本实现，全社会实现高质量的充分就业}}","back":"","tags":["一页纸","2035和2050目标"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c280","front":"==我国经济长期稳定发展其背后的内在逻辑==\n第一，{{党的领导}}把握方向、协调各方，为经济社会发展提供{{根本保证}}。\n第二，{{理论体系}}与时俱进、不断创新，为经济社会发展提供{{科学指南}}。\n第三，{{战略规划引领和有效宏观调控}}相结合，是经济长期稳定发展的{{独特优势}}。\n{{第四，坚持以人民为中心的发展思想、充分调动各方面积极性，是经济长期稳定发展的力量之源。}}\n第五，社会主义{{市场经济}}适应生产力发展需要，为经济长期稳定发展注入{{不竭活力}}。\n第六，{{超大规模市场和创新驱动发展}}相互促进、良性循环，是经济长期稳定发展的{{强大引擎}}。","back":"","tags":["一页纸","我国经济长期稳定发展其背后的内在逻辑"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c281","front":"==G20约翰内斯堡峰会==\n{{主题}}：“团结、平等、可持续”","back":"","tags":["一页纸","G20约翰内斯堡峰会"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c282","front":"==第二届中国—中亚峰会（1）==\n🚩本届中国—中亚峰会最重大的创举是\n{{六国元首共同签署“永久睦邻友好合作条约”}}\n最突出亮点是\n{{习近平主席宣布“中国—中亚精神 ”}}\n最鲜明主题是\n六国元首共同宣布2025至2026年为“中国中亚合作高质量{{发展年”}}","back":"","tags":["一页纸","第二届中国—中亚峰会"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c283","front":"==第二届中国—中亚峰会（2）==\n构建中国—中亚命运共同体，必须做到\n一要坚守彼此信赖、相互支持的团结初心。\n二要优化务实高效、深度融合的合作布局。\n三要打造和平安宁、休戚与共的安全格局。\n四要拉紧同心同德、相知相亲的人文纽带。\n五要维护公正合理、平等有序的国际秩序。\n❌倡导彼此认可、各国适用的{{普世}}价值\n🚩“中国—中亚精神”的{{核心要义}}是\n“互尊、互信、互利、互助，\n以高质量发展推进共同现代化”","back":"","tags":["一页纸","第二届中国—中亚峰会"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c284","front":"==东盟—中国—海合会峰会==\n建立起三方峰会这样的交流平台和合作机制，{{表明区域经济一体化进入新阶段}}","back":"","tags":["一页纸","东盟—中国—海合会峰会"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c285","front":"==联合国气候变化峰会==\n此次宣布的2035年国家自主贡献目标\n{{我国首次提出}}\n覆盖全经济范围、包括所有温室气体的{{绝对量减排目标}}","back":"","tags":["一页纸","联合国气候变化峰会"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c286","front":"==全球治理倡议（1）==\n{{🚩是继全球发展倡议、全球安全倡议、全球文明倡议后}}\n{{习近平提出的又一重大全球性倡议}}\n🚩2025年提出全球治理倡议，{{旨在}}\n推动各国携手行动，构建更加公正合理的全球治理体系","back":"","tags":["一页纸","全球治理倡议"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c287","front":"==全球治理倡议（2）==\n核心理念：\n{{奉行主权平等、遵守国际法治、践行多边主义、}}\n{{倡导以人为本、注重行动导向}}\n{{主权平等}}是全球治理的{{首要前提}}\n国际法治是全球治理的{{根本保障}}\n{{多边主义}}是全球治理的{{基本路径}}\n以人为本是全球治理的{{价值取向}}\n行动导向是全球治理的{{重要原则}}","back":"","tags":["一页纸","全球治理倡议"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c288","front":"==全球治理倡议（3）==\n是中国为引领全球治理变革贡献的新理念\n是对现行全球治理体制机制的调整改革和创新完善\n有利于促进国际社会共享发展机遇、应对全球性挑战\n推动构建更加公正合理的全球治理体系，携手迈向人类命运共同体","back":"","tags":["一页纸","全球治理倡议"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c289","front":"==《中国共产党思想政治工作条例》==\n2025年9月16日，党中央印发《中国共产党思想政治工作条例》\n{{思想政治工作}}是党的优良传统、鲜明特色和突出政治优势\n{{人民}}是党的生命之根、执政之基、力量之源\n{{政治方向}}是党生存发展第一位的问题，必须发挥政治指南针作用\n{{纪律}}是管党治党的“戒尺”，也是党员干部约束自身行为的标准和遵循\n🚩思想政治工作的{{根本任务}}：\n巩固马克思主义在意识形态领域的指导地位、\n巩固全党全国人民团结奋斗的共同思想基础","back":"","tags":["一页纸","《中国共产党思想政治工作条例》"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c290","front":"==新质生产力==\n特征—高科技、高效能、高质量\n催生—由技术革命性突破、生产要素创新性配置、产业深度转型升级\n特点—创新\n关键—质优\n本质—先进生产力\n{{核心标志—}}全要素生产率大幅提升\n{{核心要素}}—科技创新\n基本内涵—劳动者、劳动资料、劳动对象及其优化组合的跃升\n发展新质生产力的{{基本路径}}—{{科技创新和产业创新}}\n{{🚩科技创新和产业创新融合}}\n基础-增加高质量科技供给\n{{关键-}}强化企业创新主体地位\n途径-促进科技成果转化应用\n🚩不断催生新质生产力，{{首先要加强}}原始创新和关键核心技术攻关","back":"","tags":["一页纸","新质生产力"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c291","front":"==和各国关系（1）==\n《关于中美经贸关系若干问题的中方立场》白皮书表示\n{{🚩中美经贸关系}}的本质是互{{利}}共赢✅{{美丽}}\n中美唯一正确的选择是{{对话和合作}}\n🚩中{{俄}}两国关系的精神内核是\n永久睦{{邻}}友好、全面战略协{{作}}、互利合{{作}}共赢✅{{我做做零}}\n{{🚩中欧经贸关系}}的本质是{{优}}势互补、互{{利}}共赢✅{{有理欧}}\n{{中欧建交}}的重要经验和启示有\n/{{中欧关系未来发展}}应该坚持的重要原则和努力方向是\n相互尊重、求同存异、开放合作、互利共赢","back":"","tags":["一页纸","和各国关系"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c292","front":"==和各国关系（2）==\n习近平就中欧关系未来发展提出的主张是\n坚持相互尊重，巩固伙伴关系定位\n坚持开放合作，妥善处理分歧摩擦\n践行多边主义，维护国际规则秩序\n❌坚持{{亲诚惠容}}，深化{{睦邻}}友好合作\n（“亲诚惠容”是中国处理周边国家关系的核心理念）\n{{🚩中拉}}已经成为携手共进的命运共同体，其{{鲜明底色}}是平等{{相}}待✅{{想拉}}","back":"","tags":["一页纸","和各国关系"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c293","front":"==区对比==\n✅两地一支粤港澳，海南三区一中心\n1️⃣海南自由贸易港：\n促进海南高质量发展，\n助力全国构建新发展格局。\n2️⃣粤港澳大湾区：\n中国新发展格局的{{战略支点}}、\n高质量发展的{{示范地}}、\n中国式现代化的{{引领地}}。\n3️⃣海南三区一中心：\n全面深化改革开放{{试验区}}\n国家生态文明{{试验区}}\n国家重大战略服务{{保障区}}\n国际旅游{{消费中心}}\n⚠️海南的规格并没提到一个很高的高度\n对应的只能是试验区层级\n不可能是战略支点，示范引领地","back":"","tags":["一页纸","区对比"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c294","front":"==人工智能+==\n之所以要深入实施“人工智能+”行动，是因为它是\n抢抓新一轮科技革命和产业变革机遇的战略选择\n培育发展新质生产力的内在要求\n满足人民美好生活需要的重要途径\n助力{{全球}}平等参与智能化发展进程的积极举措\n🚩面对新一代人工智能技术快速演进的新形势，\n要充分发挥新型举国体制优势","back":"","tags":["一页纸","人工智能+"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c295","front":"==巴勒斯坦问题==\n🚩中东问题的{{核心}}是{{巴勒斯坦问题}}\n🚩确保中东和平与稳定的{{唯一途径}}是\n全面、公正地解决巴勒斯坦问题\n🚩解决巴勒斯坦问题的{{唯一出路}}是{{落实“两国方案”}}\n🚩“两国方案”的{{核心}}在于实现\n{{巴勒斯坦和以色列作为两个主权国家和平共存}}","back":"","tags":["一页纸","巴勒斯坦问题"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c296","front":"==现代化产业体系==\n《建议》对“十五五”经济社会发展作出了全面部署\n明确摆在战略任务{{第一条}}的是\n{{建设现代化产业体系，巩固壮大实体经济根基}}\n我国产业体系的{{“基本盘”}}是{{传统产业}}\n构建现代化产业体系的{{骨干}}是{{先进制造业}}","back":"","tags":["一页纸","现代化产业体系"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c297","front":"==“内卷式”竞争==\n“内卷式”竞争是恶性竞争\n会削弱行业整体{{竞争力}}\n会破坏产业发展{{生态}}\n会阻碍国内{{大循环}}\n破除“内卷式”竞争\n是按照经济规律办事的{{必然要求}}\n“内卷式”竞争具有鲜明的内耗性\n过多资源、要素投入低效竞争\n抑制了创新活力的释放\n阻碍了供需间高水平动态平衡的形成，\n还直接影响员工工资水平、政府税收收入、未来投资信心\n进而影响经济发展全局。\n🚩2025年《政府工作报告》提出{{综合整治“内卷式”竞争}}","back":"","tags":["一页纸","“内卷式”竞争"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c298","front":"==航天==\n🚩{{“天问二号”}}探测器发射升空开启了小行星探测与采样返回之旅\n神舟十九号载人飞行任务\n是我国载人航天工程进入空间站应用与发展阶段的第四次载人飞行任务，\n创造航天员单次出舱活动9小时时长的世界纪录，\n建成国际首个空间光晶格量子模拟实验平台，\n标志着中国航天事业高水平科技自立自强迈出新步伐","back":"","tags":["一页纸","航天"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c501","front":"==毛泽东思想形成与发展各时期著作（1）==\n1️⃣开始萌芽：{{一阶级两农民}}\n大革命时期，关于新民主主义革命基本思想的提出：《中国社会各阶级分析》《国民革命与农民运动》《湖南农民运动考察报告》\n2️⃣开始形成/初步形成：{{红星冈本}}\n土地革命时期，理论上阐述了中国革命的新道路：农村包围城市、武装夺取政权的思想\n《中国的红色政权为什么能够存在》《星星之火 可以燎原》《井冈山的斗争》《反对本本主义》\n3️⃣趋于成熟：{{三论两党改造政府}}\n遵义会议以后直至抗日战争时期，对新民主主义革命理论作了系统阐述：\n《实践论》《矛盾论》《〈共产党人〉发刊词》《中国革命和中国共产党》《新民主主义论》《改造我们的学习》《论联合政府》","back":"","tags":["一页纸","毛泽东思想形成与发展各时期著作"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c502","front":"==毛泽东思想形成与发展各时期著作（2）==\n4️⃣继续发展：{{两论两在一}}\n关于人民民主专政理论的完整论述：\n《在中国共产党第七届中央委员会第二次全体会议上的报告》《在晋绥干部会议上的讲话》《论人民民主专政》《论十大关系》《关于正确处理人民内部矛盾的问题》\n🔺毛泽东思想命名：{{中共七大}}","back":"","tags":["一页纸","毛泽东思想形成与发展各时期著作"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c503","front":"==林则徐 严复 魏源 郑观应==\n✅徐四睁眼见阎王喂海狮 郑观应是公主 💁‍♀️威海技师\n林则徐：《四洲志》——{{睁眼看世界第一人}}\n严复：{{救亡图存}}\n魏源：《海国图志》——{{“师夷长技以制夷”}}，开创了中国近代向西方学习的新风\n郑观应：《盛世危言》——{{“君民共主”}}\n郑观应《盛世危言》：大力发展民族工商业，同西方国家进行“商战”，设立议院，实行“君民共主”制度\n王韬、薛福成、马建忠、郑观应等人主张：不仅学习西方的科学技术，也要求吸纳西方的政治、经济学说\n思想：①比较强烈的反对外国侵略的爱国思想 ②追求中国独立富强的爱国思想 ③具有一定程度的反对封建专制的民主思想\n干扰项：追求实行民主共和制度的思想 ✘错误","back":"","tags":["一页纸","林则徐 严复 魏源 郑观应"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c504","front":"==我国的主要矛盾改变（1）==\n1️⃣【半殖民地半封建社会】（两半社会从属于{{资本主义世界体系}}）\n{{帝国主义和中华民族的矛盾}}（{{最主要}}的矛盾）、封建主义和人民大众的矛盾\n2️⃣【新民主主义社会】\n(1) 1949年10月～1952年年底（全国土改完成）：{{人民大众同帝国主义、封建主义和国民党反动派残余势力之间的矛盾}}\n(2) 1953年～1956年（社会主义改造完成）：{{工人阶级同资产阶级的矛盾}}","back":"","tags":["一页纸","我国的主要矛盾改变"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c505","front":"==我国的主要矛盾改变（2）==\n3️⃣【社会主义初级阶段】\n(1) 1956年～2012年：{{人民日益增长的物质文化需要同落后的社会生产之间的矛盾}}\n(2) 2012年～现在：{{人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾}}\n注：虽然主要矛盾的变化和新时代的提法都是在2017年党的十九大上提出的，但发生这些变化的时间点是十八大。即十八大以来中国特色社会主义就进入了新时代，社会的主要矛盾就发生了变化。\n补充说明\n① 1956年中共八大提出，社会主义改造完成后，我国主要矛盾为：人民对于建立先进的工业国的要求同落后的农业国的现实之间的矛盾，人民对于经济文化迅速发展的需要同当前经济文化不能满足人民需要的状况之间的矛盾。\n② 1981年十一届六中全会对八大提法作了全新表述：人民日益增长的物质文化需要同落后的社会生产之间的矛盾","back":"","tags":["一页纸","我国的主要矛盾改变"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c506","front":"==平均利润==\n平均利润的形成原因：{{不同生产部门资本家之间的竞争}}\n扩展：超额利润的形成原因 = {{同一部门内不同企业之间的竞争}}\n理解：为了得到尽可能高的利润率和尽可能多的利润，不同生产部门（通俗理解：不同“赛道”）的资本家之间必然展开激烈的竞争，大量资本必然从利润率低的部门转投到利润率高的部门，从而导致利润率平均化。\n（利润转化为平均利润，商品价值也就转化为生产价格，生产价格 = 生产成本 + 平均利润）\n🚩平均利润形成后：\n1️⃣商品价值就转化为{{生产价格}}\n2️⃣价值规律的实现形式发生了变化","back":"","tags":["一页纸","平均利润"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c509","front":"==萌芽（5）==\n(1) 1928年10月《中国的红色政权为什么能够存在？》，11月《井冈山的斗争》：①论证了红色政权能够长期存在并发展的主客观条件提出了工农武装割据的思想⚠️工农割据了红色井冈山文章明确地指出，以农业为主要经济的中国革命，以军事发展暴动，是一种特征；实行工农武装割据，就是在中国共产党领导之下，把土地革命、武装斗争与根据地建设三者结合起来。阐明工农武装割据长期存在并发展的条件非常重要，因为只有正确回答这个问题，才能同那种怀疑中国红色政权能够存在的右倾悲观思想划清界限，又同那种认为可以无条件地在农村发动武装暴动的“左〞倾盲动错误划清界限。","back":"","tags":["一页纸","萌芽"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c510","front":"==萌芽（6）==\n②这时还未解决以农村为工作中心的问题，但工农武装割据思想为解决这个问题奠定了基础。\n(2) 1930年1月《星星之火，可以燎原》：{{①进一步阐明了中国革命}}\n②红军、游击队和红色区域的建立和发展，是半殖民地中国在无产阶级领导之下的农民斗争的最高形式和半殖民地农民斗争发展的必然结果，并且无疑义的是促进全国革命高潮的最重要因素。\n③回答了“红旗到底打得多久〞的疑问。","back":"","tags":["一页纸","萌芽"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c511","front":"==萌芽（7）==\n(3) 1930年5月《反对本本主义》：{{①阐明了坚持辩证唯物主义的思想路线}}\n②初步界定了中国共产党人的思想路线的基本含义。\n③反映了毛泽东思想的三个基本点，即实事求是、群众路线和独立自主的思想雏形。\n⚠️是独立自主思想的最初的、首次明确表述④从单篇文章来看，标志毛泽东哲学思想的初步形成。","back":"","tags":["一页纸","萌芽"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c512","front":"==萌芽（8）==\n遵义会议以后至全民族抗战时期，以下著作对新民主主义革命理论作了系统的阐述，实现了马克思主义与中国革命实践相结合的历史性飞跃，标志着毛泽东思想得到多方面展开而趋于成熟。\n(1) 1935年12月《论反对日本帝国主义的策略》：{{阐明党的抗日民族统一战线的新政策}}\n科学地阐明了党的政治路线上的问题(2) 1936年12月《中国革命战争的战略问题》：总结土地革命战争中党内在军事问题上的大争论系统说明了有关中国革命战争战略方面的诸问题。","back":"","tags":["一页纸","萌芽"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c513","front":"==萌芽（9）==\n(3) 1937年《实践论》《矛盾论》：{{运用马克思主义的认识论和辩证法}}\n从马克思主义认识论的高度，总结中国共产党的历史经验，揭露和批评党内的主观主义尤其是教条主义错误，深入论证马克思列宁主义基本原理同中国具体实际相结合的原则，科学地阐明了党的马克思主义的思想路线。\n对党的思想路线作了系统的哲学论证。\n⚠️辨析：思想路线确立是在延安整风(4) 1938年5月《论持久战》：②科学地预测了抗日战争的发展进程，即抗日战争将经过战略防御、战略相持、战略反攻三个阶段。\n其中，战略相持阶段，是中国抗日战争取得最后胜利的最关键的阶段。","back":"","tags":["一页纸","萌芽"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c514","front":"==萌芽（10）==\n③驳斥了“速胜论”和“亡国论”，提出“兵民是胜利之本”的论断。\n(5) 1938年10月《论新阶段》：毛泽东在党的六届六中全会上作的政治报告《论新阶段》中，首次提出了“马克思主义中国化”的命题。\n(6) 1938年11月《战争和战略问题》：{{把经过长期武装斗争}}","back":"","tags":["一页纸","萌芽"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c515","front":"==萌芽（11）==\n(8) 1939年《中国革命和中国共产党》：{{第一次提出了新民主主义革命的科学概念和总路线的内容}}\n(9) 1940年《新民主主义论》：第一次旗帜鲜明地提出了新民主主义的完整理论(10) 1941年5月《改造我们的学习》：延安整风运动首先在党的高级干部中进行。\n(11) 1942年2月《整顿党的作风》和《反对党八股》：{{延安整风运动在全党范围普遍展开}}\n(12) 1945年4月《论联合政府》：{{毛主席在党的七大所作的政治报告《论联合政府》中}}","back":"","tags":["一页纸","萌芽"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c516","front":"==萌芽（12）==\n⚠️三纲联合✅新民主主义的经济纲领①没收封建地主阶级的土地归农民②没收官僚资本归新民主主义国家③保护民族工商业（也是新民主主义经济纲领中极具特色的一项内容）\n解放战争时期与新中国成立之后，以下著作中体现的社会主义革命和社会主义建设的重要思想，是毛泽东思想的丰富和发展。\n(1) 1948年4月《在晋绥干部会议上的讲话》：{{完整地表述了新民主主义革命总路线的内容}}","back":"","tags":["一页纸","萌芽"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c517","front":"==萌芽（13）==\n（官僚资本主义是本次讲话新增的内容）(2) 1949年6月《论人民民主专政》：总结了党成立以来领导民主革命的经验：工人阶级（经过共产党）领导的以工农联盟为基础的人民民主专政为即将成立的新中国做了政治理论准备七届二中全会的决议和毛泽东的《论人民民主专政》,构成了《中国人民政治协商会议共同纲领》的基础创造性发展了马克思列宁主义国家学说(3) 1956年4月《论十大关系》：①初步总结了我国社会主义建设的经验，明确提出了以苏为鉴、独立自主地探索适合中国情况的社会主义建设道路。\n另一种说法：明确了建设社会主义的根本思想是根据本国情况走自己的路。\n②围绕一个基本方针，即调动一切积极因素为社会主义服务。","back":"","tags":["一页纸","萌芽"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c518","front":"==萌芽（14）==\n③是以毛泽东为主要代表的中国共产党人开始探索适合中国国情的社会主义建设道路的标志/标志着党探索中国社会主义建设道路的良好开端。✅十全十美好开端它在新的历史条件下从经济和政治方面提出了新的指导方针，为中共八大的召开作了理论准备。\n④论述的第一大关系是重工业、轻工业和农业的关系。\n(4) 1957年2月《关于正确处理人民内部矛盾的问题》：{{①毛泽东明确提出了中国工业化道路的问题}}","back":"","tags":["一页纸","萌芽"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c519","front":"==萌芽（15）==\n走中国工业化道路的思想，是党探索我国社会主义建设道路的一个重要思想，强调正确处理重工业和轻工业、农业的关系，符合中国人口多、工业基础薄弱的实际，对于加快我国社会主义建设事业发展具有重要意义②形成一套系统的关于社会主义社会矛盾的学说社会主义社会的基本矛盾同以往社会的基本矛盾具有根本不同的性质和情况是：社会主义基本矛盾“又相适应又相矛盾”解决人民内部矛盾的一系列具体方针原则：1️⃣在政治思想领域上实行“团结—批评一团结”的方针2️⃣在共产党与民主党派的关系上实行“长期共存、互相监督”的方针3️⃣在科学文化工作中实行“百花齐放、百家争鸣”的方针4️⃣在物质利益分配方面中实行“统筹兼顾、适当安排”的方针5️⃣民族之间实行“民主平等，团结互助”的方针6️⃣对于人民群众和政府机关，要坚持民主集中制原则⚠️辨析“惩前毖后、治病救人”的方针，是中国共产党在延安整风运动中提出的对待犯错误同志的正确方针③关于正确处理人民内部矛盾的问题是社会主义国家政治生活的主题。这一论断的根本着眼点，在于调动一切积极因素，团结一切可以团结的力量，把全党的注意力转到社会主义建设上来。","back":"","tags":["一页纸","萌芽"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c520","front":"==萌芽（16）==\n(5) 1957年7月《一九五七年夏季的形势》：{{要造成一个又有集中又有民主}}\n这是中共八大路线的继续和发展，是党探索社会主义建设道路的新成果。","back":"","tags":["一页纸","萌芽"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c521","front":"==会议大观（3）==\n中共一大 1921(1)大会确定党的名称为“中国共产党”,通过中国共产党的第一个纲领和决议。\n(2)大会在讨论实际工作计划时，决定首先集中精力组织工人(3)大会决定设立中央局作为党的临时领导机构。","back":"","tags":["一页纸","会议大观"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c522","front":"==会议大观（4）==\n中共二大 1922(1)第一次提出了反帝反封建的民主革命的纲领(2)开始采取群众路线的方法(3)正式提出民主联合战线的主张，这是党最早提出关于统一战线的思想和主张，主要目的是实现反帝反军阀的革命目标中共三大 1923正式决定全体共产党员以个人名义加入国民党国民党一大 1924(1)对三民主义作出新的解释，即“新三民主义”事实上确认了联俄、联共、扶助农工的三大革命政策(2)新三民主义的政纲同当时中共基本一致，因而成为国共合作的政治基础(3)标志着第一次国共合作正式形成中共四大 1925(1)提出了无产阶级在民主革命中的领导权问题(2)提出了工农联盟问题(3)对民主革命的内容作了更加完整的规定中共五大 1927(1)提出争取无产阶级对革命的领导权(2)建立革命民主政权和实行土地革命等一些正确的原则⚠️但对无产阶级如何争取革命领导权、如何领导农民实行土地革命,特别是如何建立党领导的革命武装等问题,没有提出有效的具体措施,难以承担起挽救革命的任务。","back":"","tags":["一页纸","会议大观"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c523","front":"==会议大观（5）==\n八七会议 1927(1)八七会议总结了大革命失败的经验教训 ✅巴适(2)坚决纠正和结束了陈独秀的右倾主义错误(3)确定了土地革命和武装反抗国民党反动派的总方针(4)第一次提出了“政权是由枪杆子中取得的”思想。","back":"","tags":["一页纸","会议大观"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c524","front":"==会议大观（6）==\n古田会议 1929(1)立了思想建党、政治建军原则中心思想是要用无产阶级思想进行军队和党的建设(2)阐述了加强党的思想建设的极端重要性(3)规定了中国的红军是一个执行革命的政治任务的武装集团遵义会议 1935(1)党的历史上一个生死攸关的转折点(2)事实上确立了毛泽东在党中央和红军的领导地位开始确立以毛泽东同志为主要代表的马克思主义正确路线在党中央的领导地位开始形成以毛泽东同志为核心的第一代中央领导集体(3)集中解决了当时具有决定意义的军事问题和组织问题 ✅遵君主(4)遵义会议的一系列重大决策是在中国共产党同共产国际的联系中断的情况下独立自主地作出的遵义会议开启了党独立自主解决中国革命实际问题的新阶段 ✅尊嘟假嘟(5)遵义会议的鲜明特点是坚持真理、修正错误 ✅遵义修理瓦窑堡 1935(1)解决党的政治路线问题 ✅镇馆之宝(2)提出了党的抗日民族统一战线的新政策 ✅瓦罗兰特，统一战线洛川会议 1937(1)洛川会议制定了抗日救国十大纲领 强调要打倒日本帝国主义 关键在于：使已然发动的抗战成为全面的全民族的抗战(2)标志着党的全面抗战路线的正式形成✅川面/洛克王国，全面抗战","back":"","tags":["一页纸","会议大观"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c525","front":"==会议大观（7）==\n《实践论》《矛盾论》 1937(1)从马克思主义认识论的新高度总结中国共产党的历史经验(2)揭露和批判党内的主观主义 尤其是教条主义错误(3)深入论证马克思列宁主义基本原理同中国具体实际相结合的原则(4)科学阐明了党的马克思主义的思想路线六届六中 1938(1)毛泽东明确提出“马克思主义的中国化”命题(2)全会基本纠正了王明的右倾错误延安整风 1941-1945一切从实际出发 理论联系实际 实事求是的马克思主义思想路线 在全党范围确立六届七中 《关于若干历史问题的决议》1945(1)使全党特别是党的高级干部对中国革命基本问题的认识达到了一致 增强了全党团结(2)充分肯定了确立毛泽东在全党领导地位的重大意义，分清了是非(3)为七大的胜利召开在思想上做了充分准备(4)标志着延安整风运动的胜利结束七大 1945(1)毛泽东在会上作题为《论联合政府》的书面报告和《愚公移山》闭幕词✅七个小矮人联合起来愚公移山(2)把毛泽东思想确立为党的指导思想并写入党章 ✅胀气(3)中共七大把党在长期奋斗中形成的优良作风概括为三大作风(4)标志着我们党在政治上 思想上 组织上走向了成熟 ✅中共七大三成熟——在政治上 党通过延安整风 使全党团结在毛泽东的旗帜下 实现了党的空前统一和团结——在思想上 党确立了毛泽东思想在全党的指导地位 把毛泽东思想写入了党章——在组织上 党形成了一支高举毛泽东旗帜的久经考验的政治家集团(5)制定了党的政治路线，制定了新民主主义国家在政治、经济、文化方面的纲领，为建立新民主主义的新中国制定了正确路线方针政策提出实现中国工业化的宏伟任务(6)为党后来不断从胜利走向胜利指明了正确方向 开辟了正确道路七届二中 1949(1)提出了“两个务必”的思想：{{务必继续保持谦虚、谨慎、不骄、不躁的作风}}","back":"","tags":["一页纸","会议大观"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c526","front":"==会议大观（8）==\n关于真理标准问题的讨论 1978(1)真理标准问题的讨论是继五四运动和延安整风运动之后又一场马克思主义思想解放运动其实质在于是不是坚持马克思列宁主义 毛泽东思想(2)讨论明确地解决了党的思想路线问题(3)为党重新确立实事求是思想路线 纠正长期以来的左倾错误 实现历史性的转折作了思想理论准备(4)成为正本清源、拨乱反正和改革开放的思想先导十一届三中 1978(1)全会冲破长期“左”的错误的严重束缚，彻底否定了“两个凡是”的错误方针高度评价了关于真理标准问题的讨论，并且断然否定“以阶级斗争为纲”的指导思想(2)作出了把工作重点转移到社会主义现代化建设上来和实行改革开放的战略决策(3)重新确立了马克思主义的思想路线 政治路线和组织路线 ✅三线三中/重新确立解放思想，实事求是思想路线(4)全会恢复了党的民主集中制的优良传统审查解决了历史上遗留的一批重大问题和一些重要领导人的功过是非问题(5)会议形成了以邓小平为核心的党的中央领导集体揭开了社会主义改革开放的序幕(6)以这次全会为起点，中国进入了改革开放和社会主义现代化建设的历史新时期(7)实现了党的历史上具有深远意义的伟大转折十一届六中《关于建国以来党的若干历史问题的决议》（简称《决议》）1981邓小平对《决议》的起草提出三条指导原则：{{第一}}","back":"","tags":["一页纸","会议大观"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c527","front":"==会议大观（9）==\n第三，这个总结宜粗不宜细，总结过去是为了引导大家团结一致向前看。\n《关于建国以来党的若干历史问题的决议》(1)标志着党在指导思想上的拨乱反正胜利完成🚩我们党在改革开放和社会主义现代化建设新时期实现的最根本的拨乱反正：{{以经济建设为中心(2)回顾了新中国成立以前党的历史}}\n(3)彻底否定“文化大革命”，对新中国成立以来的重大历史事件和重要历史人物作出了基本结论。\n(4)科学地评价了毛泽东和毛泽东思想的历史地位。\n对毛泽东思想的科学体系和活的灵魂作了概括，强调毛泽东思想是我们党的宝贵的精神财富，它将长期指导我们的行动。","back":"","tags":["一页纸","会议大观"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c528","front":"==会议大观（10）==\n(5)对党的十一届三中全会以来逐步确立的适合中国情况的建设社会主义现代化强国的道路，从十个方面作了概括，实质上初步提出了在中国建设什么样的社会主义和怎样建设社会主义的问题。\n(6)该决议解决了两个相互联系的重大历史课题即①科学评价毛泽东的历史地位和毛泽东思想的科学体系；\n②根据新的实际和发展要求实行改革开放、确立中国社会主义现代化建设正确道路。","back":"","tags":["一页纸","会议大观"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"c529","front":"==会议大观（11）==\n(7)指出社会主义改造基本完成以后，我国所要解决的主要矛盾，是人民日益增长的物质文化需要同落后的社会生产之间的矛盾十二大 1982第一次提出了“建设有中国特色的社会主义”命题标志着邓小平理论主题的形成，标志着中特理论主题的形成从此，“中国特色社会主义”成为我们党的全部理论和实践创新的主题这一重大命题的提出具有里程碑意义，是中国共产党人对科学社会主义发展的开创性贡献十二届三中 1984指出我国社会主义经济是在公有制基础上的有计划的商品经济 ✅有计划 一二三十三大 1987社会主义初级阶段的基本路线第一次对中特理论进行系统的概括标志着邓小平理论轮廓的形成，中特理论轮廓的形成⚠️基本路线中回答了社会主义的根本任务问题的是：“以经济建设为中心”回答了社会主义的发展动力和外部条件问题：“坚持改革开放”实现奋斗目标的领导力量和依靠力量：“领导和团结各族人民”十四大 1992明确以建立社会主义市场经济体制为我国经济体制改革的目标⚠️南方谈话和十四大标志着改革开放和现代化建设事业进入从计划经济体制向社会主义市场经济体制转变的新阶段，由此打开了中国经济、政治、文化发展崭新局面十五大 1997邓小平理论确立为党的指导思想首次明确提出了社会主义初级阶段的基本纲领十六大 2002三个代表 小康奋斗目标✅二三四五六 中路经（过只）刚小乔十七大 2007科学发展观提出了“中国特色社会主义理论体系”的科学概念标志着中国特色社会主义理论和实践的进一步成熟 🔞17-18还需进一步成熟十八三中 2013实现了改革由局部探索、破冰突围到系统集成、全面深化的转变，开创了我国改革开放新局面二十三中 2024进一步全面深化改革的重点是深化经济体制改革","back":"","tags":["一页纸","会议大观"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0}]},{"id":"dpr","name":"速览 · 时间线汇总","color":"#0891b2","mode":"read","desc":"7 个专题 · 点开看","sections":[{"title":"转折点","text":"**十月革命 1917**\n推动中国先进分子把目光从西方转向东方，从资产阶级民主主义转向社会主义\n**五四运动 1919**\n中国旧民主主义革命走向新民主主义革命的转折点\n**八七会议 1927**\n中国革命开始了从大革命失败到土地革命战争兴起的历史性转变\n**井冈山农村革命根据地的建立 1928**\n成功地实现了中国革命的伟大战略转变\n点燃了工农武装割据的星星之火\n中国革命的中心开始从城市到农村战略转移\n开辟了农村包围城市、武装夺取政权的新道路\n中国革命具有决定意义的新起点是\n从进攻大城市转为向农村进军\n**遵义会议 1935**\n遵义会议是党的历史上一个生死攸关的转折点\n**长征的胜利 1936【长征】**\n是中国革命转危为安的关键\n⚠️长征实现了中国共产党和中国革命事业从挫折走向胜利的伟大转折\n**西安事变的和平解决 1936**\n成为时局转换的枢纽\n**抗日战争的胜利 1945**\n中华民族从近代以来陷入深重危机走向伟大复兴的历史转折点\n**✅1947米脂县 革命两个转折点（米帝死期🇱🇷）**\n**1947年12月 中共中央在陕北米脂县杨家沟召开会议**\n制定了夺取全国胜利的行动纲领\n毛泽东指出，中国革命已经发展到了一个历史的转折点：\n蒋介石20年反革命统治由发展到消灭的转折点\n100多年来帝国主义在中国的统治由发展到消灭的转折点\n**七届二中全会 1949.3.5—3.13**\n说明了党的工作重心必须由乡村转移到城市\n**✅1949进北平 革命重心开始变**\n**毛中央、解放军进驻北平香山 1949.3.25**\n标志着中国革命重心由乡村转移到城市\n⚠️辨析\n秋收起义—城市转农村\n进驻香山—农村转城市\n**十一届三中 1978**\n❶作出了把工作重点转移到\n社会主义现代化建设上来和实行改革开放的战略决策\n❷中国进入了改革开放和社会主义现代化建设的历史新时期\n实现了党的历史上具有深远意义的伟大转折\n**十八届三中 1978**\n改革由局部探索、破冰突围到系统集成、全面深化的转变"},{"title":"开始形成/初步形成","text":"土地革命战争时期时期，\n以下著作在理论上阐述了中国革命的新道路：\n农村包围城市、武装夺取政权的思想，\n标志着毛泽东思想初步形成（开始形成）。\n(1) 1928年10月《中国的红色政权为什么能够存在？》，11月《井冈山的斗争》：\n①论证了红色政权能够长期存在并发展的主客观条件\n提出了工农武装割据的思想⚠️工农割据了红色井冈山\n文章明确地指出，以农业为主要经济的中国革命，以军事发展暴动，是一种特征；实行工农武装割据，就是在中国共产党领导之下，把土地革命、武装斗争与根据地建设三者结合起来。阐明工农武装割据长期存在并发展的条件非常重要，因为只有正确回答这个问题，才能同那种怀疑中国红色政权能够存在的右倾悲观思想划清界限，又同那种认为可以无条件地在农村发动武装暴动的“左〞倾盲动错误划清界限。\n②这时还未解决以农村为工作中心的问题，但工农武装割据思想为解决这个问题奠定了基础。\n**(2) 1930年1月《星星之火，可以燎原》：**\n①进一步阐明了中国革命，只能走与资本主义国家不同的道路。\n②红军、游击队和红色区域的建立和发展，是半殖民地中国在无产阶级领导之下的农民斗争的最高形式和半殖民地农民斗争发展的必然结果，并且无疑义的是促进全国革命高潮的最重要因素。\n③回答了“红旗到底打得多久〞的疑问。\n**(3) 1930年5月《反对本本主义》：**\n①阐明了坚持辩证唯物主义的思想路线，即坚持理论与实际相结合的原则的极端重要性，提出了\n“没有调查，没有发言权”\n“中国革命斗争的胜利要靠中国同志了解中国情况”的重要思想，\n表现了毛泽东开辟新道路、创造新理论的革命首创精神。\n②初步界定了中国共产党人的思想路线的基本含义。\n③反映了毛泽东思想的三个基本点，即实事求是、群众路线和独立自主的思想雏形。\n⚠️是独立自主思想的最初的、首次明确表述\n④从单篇文章来看，标志毛泽东哲学思想的初步形成。"},{"title":"成熟","text":"遵义会议以后至全民族抗战时期，以下著作对新民主主义革命理论作了系统的阐述，\n实现了马克思主义与中国革命实践相结合的历史性飞跃，标志着毛泽东思想得到多方面展开而趋于成熟。\n**(1) 1935年12月《论反对日本帝国主义的策略》：**\n阐明党的抗日民族统一战线的新政策，批判党内的关门主义和对于革命的急性病，\n系统地说明了党的政治策略上的诸问题（即瓦窑堡会议的文件）。\n科学地阐明了党的政治路线上的问题\n**(2) 1936年12月《中国革命战争的战略问题》：**\n总结土地革命战争中党内在军事问题上的大争论\n系统说明了有关中国革命战争战略方面的诸问题。\n**(3) 1937年《实践论》《矛盾论》：**\n运用马克思主义的认识论和辩证法，系统分析了党内“左”的和右的错误的思想根源。\n从马克思主义认识论的高度，总结中国共产党的历史经验，揭露和批评党内的主观主义尤其是教条主义错误，\n深入论证马克思列宁主义基本原理同中国具体实际相结合的原则，科学地阐明了党的马克思主义的思想路线。\n对党的思想路线作了系统的哲学论证。\n⚠️辨析：思想路线确立是在延安整风\n**(4) 1938年5月《论持久战》：**\n②科学地预测了抗日战争的发展进程，即抗日战争将经过战略防御、战略相持、战略反攻三个阶段。\n其中，战略相持阶段，是中国抗日战争取得最后胜利的最关键的阶段。\n③驳斥了“速胜论”和“亡国论”，提出“兵民是胜利之本”的论断。\n**(5) 1938年10月《论新阶段》：**\n毛泽东在党的六届六中全会上作的政治报告《论新阶段》中，首次提出了“马克思主义中国化”的命题。\n**(6) 1938年11月《战争和战略问题》：**\n把经过长期武装斗争，先占乡村，后取城市，最后夺取全国胜利，作为革命道路确立下来\n**(7) 1939年10月《〈共产党人〉发刊词》：**\n总结了中国革命两次胜利和两次失败的经验教训，揭示了中国革命发展的客观规律，指出：\n统一战线、武装斗争、党的建设，是中国共产党在中国革命中战胜敌人的三个法宝。\n**(8) 1939年《中国革命和中国共产党》：**\n第一次提出了新民主主义革命的科学概念和总路线的内容。\n**(9) 1940年《新民主主义论》：**\n第一次旗帜鲜明地提出了新民主主义的完整理论\n**(10) 1941年5月《改造我们的学习》：**\n延安整风运动首先在党的高级干部中进行。\n**(11) 1942年2月《整顿党的作风》和《反对党八股》：**\n延安整风运动在全党范围普遍展开。\n**(12) 1945年4月《论联合政府》：**\n毛主席在党的七大所作的政治报告《论联合政府》中，\n进一步把新民主主义的政治、经济和文化与党的基本纲领联系起来，\n进行了具体阐述，形成了新民主主义的基本纲领。\n⚠️三纲联合\n✅新民主主义的经济纲领\n①没收封建地主阶级的土地归农民\n②没收官僚资本归新民主主义国家\n③保护民族工商业\n（也是新民主主义经济纲领中极具特色的一项内容）"},{"title":"继续发展","text":"解放战争时期与新中国成立之后，\n以下著作中体现的社会主义革命和社会主义建设的重要思想，是毛泽东思想的丰富和发展。\n**(1) 1948年4月《在晋绥干部会议上的讲话》：**\n完整地表述了新民主主义革命总路线的内容，\n即无产阶级领导的，人民大众的，反对帝国主义、封建主义和官僚资本主义的革命。\n（官僚资本主义是本次讲话新增的内容）\n**(2) 1949年6月《论人民民主专政》：**\n总结了党成立以来领导民主革命的经验：\n工人阶级（经过共产党）领导的以工农联盟为基础的人民民主专政\n为即将成立的新中国做了政治理论准备\n七届二中全会的决议和毛泽东的《论人民民主专政》,\n构成了《中国人民政治协商会议共同纲领》的基础\n创造性发展了马克思列宁主义国家学说\n**(3) 1956年4月《论十大关系》：**\n①初步总结了我国社会主义建设的经验，\n明确提出了以苏为鉴、独立自主地探索适合中国情况的社会主义建设道路。\n另一种说法：明确了建设社会主义的根本思想是根据本国情况走自己的路。\n②围绕一个基本方针，即调动一切积极因素为社会主义服务。\n③是以毛泽东为主要代表的中国共产党人开始探索适合中国国情的社会主义建设道路的标志\n/标志着党探索中国社会主义建设道路的良好开端。✅十全十美好开端\n它在新的历史条件下从经济和政治方面提出了新的指导方针，为中共八大的召开作了理论准备。\n④论述的第一大关系是重工业、轻工业和农业的关系。\n**(4) 1957年2月《关于正确处理人民内部矛盾的问题》：**\n①毛泽东明确提出了中国工业化道路的问题，主要是指重工业和轻工业、农业的发展关系问题，\n强调要走一条有别于苏联的中国工业化道路。\n走中国工业化道路的思想，是党探索我国社会主义建设道路的一个重要思想，\n强调正确处理重工业和轻工业、农业的关系，\n符合中国人口多、工业基础薄弱的实际，对于加快我国社会主义建设事业发展具有重要意义\n②形成一套系统的关于社会主义社会矛盾的学说\n社会主义社会的基本矛盾同以往社会的基本矛盾具有根本不同的性质和情况是：\n社会主义基本矛盾“又相适应又相矛盾”\n解决人民内部矛盾的一系列具体方针原则：\n1️⃣在政治思想领域上实行“团结—批评一团结”的方针\n2️⃣在共产党与民主党派的关系上实行“长期共存、互相监督”的方针\n3️⃣在科学文化工作中实行“百花齐放、百家争鸣”的方针\n4️⃣在物质利益分配方面中实行“统筹兼顾、适当安排”的方针\n5️⃣民族之间实行“民主平等，团结互助”的方针\n6️⃣对于人民群众和政府机关，要坚持民主集中制原则\n⚠️辨析“惩前毖后、治病救人”的方针，\n是中国共产党在延安整风运动中提出的对待犯错误同志的正确方针\n③关于正确处理人民内部矛盾的问题是社会主义国家政治生活的主题。这一论断的根本着眼点，\n在于调动一切积极因素，团结一切可以团结的力量，把全党的注意力转到社会主义建设上来。\n**(5) 1957年7月《一九五七年夏季的形势》：**\n要造成一个又有集中又有民主，又有纪律又有自由，\n又有统一意志、又有个人心情舒畅、生动活泼，那样一种政治局面的思想。\n这是中共八大路线的继续和发展，是党探索社会主义建设道路的新成果。"},{"title":"会议大观上","text":"**中共一大 1921**\n(1)大会确定党的名称为“中国共产党”,通过中国共产党的第一个纲领和决议。\n(2)大会在讨论实际工作计划时，决定首先集中精力组织工人\n(3)大会决定设立中央局作为党的临时领导机构。\n**中共二大 1922**\n(1)第一次提出了反帝反封建的民主革命的纲领\n(2)开始采取群众路线的方法\n(3)正式提出民主联合战线的主张，\n这是党最早提出关于统一战线的思想和主张，\n主要目的是实现反帝反军阀的革命目标\n**中共三大 1923**\n正式决定全体共产党员以个人名义加入国民党\n**国民党一大 1924**\n(1)对三民主义作出新的解释，即“新三民主义”\n事实上确认了联俄、联共、扶助农工的三大革命政策\n(2)新三民主义的政纲同当时中共基本一致，因而成为国共合作的政治基础\n(3)标志着第一次国共合作正式形成\n**中共四大 1925**\n(1)提出了无产阶级在民主革命中的领导权问题\n(2)提出了工农联盟问题\n(3)对民主革命的内容作了更加完整的规定\n**中共五大 1927**\n(1)提出争取无产阶级对革命的领导权\n(2)建立革命民主政权和实行土地革命等一些正确的原则\n⚠️但对无产阶级如何争取革命领导权、如何领导农民实行土地革命,\n特别是如何建立党领导的革命武装等问题,没有提出有效的具体措施,\n难以承担起挽救革命的任务。\n**八七会议 1927**\n(1)八七会议总结了大革命失败的经验教训 ✅巴适\n(2)坚决纠正和结束了陈独秀的右倾主义错误\n(3)确定了土地革命和武装反抗国民党反动派的总方针\n(4)第一次提出了“政权是由枪杆子中取得的”思想。\n**古田会议 1929**\n(1)立了思想建党、政治建军原则\n中心思想是要用无产阶级思想进行军队和党的建设\n(2)阐述了加强党的思想建设的极端重要性\n(3)规定了中国的红军是一个执行革命的政治任务的武装集团\n**遵义会议 1935**\n(1)党的历史上一个生死攸关的转折点\n(2)事实上确立了毛泽东在党中央和红军的领导地位\n开始确立以毛泽东同志为主要代表的马克思主义正确路线在党中央的领导地位\n开始形成以毛泽东同志为核心的第一代中央领导集体\n(3)集中解决了当时具有决定意义的军事问题和组织问题 ✅遵君主\n(4)遵义会议的一系列重大决策\n是在中国共产党同共产国际的联系中断的情况下独立自主地作出的\n遵义会议开启了党独立自主解决中国革命实际问题的新阶段 ✅尊嘟假嘟\n(5)遵义会议的鲜明特点是坚持真理、修正错误 ✅遵义修理\n**瓦窑堡 1935**\n(1)解决党的政治路线问题 ✅镇馆之宝\n(2)提出了党的抗日民族统一战线的新政策 ✅瓦罗兰特，统一战线\n**洛川会议 1937**\n(1)洛川会议制定了抗日救国十大纲领 强调要打倒日本帝国主义 关键在于：\n使已然发动的抗战成为全面的全民族的抗战\n(2)标志着党的全面抗战路线的正式形成\n✅川面/洛克王国，全面抗战"},{"title":"会议大观中","text":"**《实践论》《矛盾论》 1937**\n(1)从马克思主义认识论的新高度总结中国共产党的历史经验\n(2)揭露和批判党内的主观主义 尤其是教条主义错误\n(3)深入论证马克思列宁主义基本原理同中国具体实际相结合的原则\n(4)科学阐明了党的马克思主义的思想路线\n**六届六中 1938**\n(1)毛泽东明确提出“马克思主义的中国化”命题\n(2)全会基本纠正了王明的右倾错误\n**延安整风 1941-1945**\n一切从实际出发 理论联系实际 实事求是的马克思主义思想路线 在全党范围确立\n**六届七中 《关于若干历史问题的决议》1945**\n(1)使全党特别是党的高级干部对中国革命基本问题的认识达到了一致 增强了全党团结\n(2)充分肯定了确立毛泽东在全党领导地位的重大意义，分清了是非\n(3)为七大的胜利召开在思想上做了充分准备\n(4)标志着延安整风运动的胜利结束\n**七大 1945**\n(1)毛泽东在会上作题为《论联合政府》的书面报告和《愚公移山》闭幕词\n✅七个小矮人联合起来愚公移山\n(2)把毛泽东思想确立为党的指导思想并写入党章 ✅胀气\n(3)中共七大把党在长期奋斗中形成的优良作风概括为三大作风\n(4)标志着我们党在政治上 思想上 组织上走向了成熟 ✅中共七大三成熟\n——在政治上 党通过延安整风 使全党团结在毛泽东的旗帜下 实现了党的空前统一和团结\n——在思想上 党确立了毛泽东思想在全党的指导地位 把毛泽东思想写入了党章\n——在组织上 党形成了一支高举毛泽东旗帜的久经考验的政治家集团\n(5)制定了党的政治路线，\n制定了新民主主义国家在政治、经济、文化方面的纲领，\n为建立新民主主义的新中国制定了正确路线方针政策\n提出实现中国工业化的宏伟任务\n(6)为党后来不断从胜利走向胜利指明了正确方向 开辟了正确道路\n**七届二中 1949**\n(1)提出了“两个务必”的思想：\n务必继续保持谦虚、谨慎、不骄、不躁的作风，\n务必继续保持艰苦奋斗的作风\n(2)指出党的工作重心必须由乡村转移到城市\n(3)规定了党在全国胜利后在政治、经济、外交方面应当采取的基本政策\n(4)指出了中国由农业国转变为工业国、由新民主主义社会转变为社会主义社会的发展方向\n**中国人民政治协商会议第一届全体会议1949**\n(1)人民政协的召开，标志着中国的新型政党制度的确立\n——中国共产党领导的多党合作和政治协商制度\n(2)会议通过的《共同纲领》在当时是全国人民的大宪章，起着临时宪法的作用\n**七届三中 1950**\n(1)制定了党在建国初期的战略策略方针：不要四面出击 ✅不要四 那就三\n(2)确定了当时全党和全国人民的中心任务是\n要在三年左右的时间内争取国家财政经济状况的基本好转\n**八大 1956**\n(1)分析了改造完成后的主要矛盾和主要任务\n(2)在经济建设上，大会坚持既反保守又反冒进，即在综合平衡中稳步前进的方针 ✅四平八稳\n(3)陈云提出“三个主体、三个补充”的思想\n(4)对中国建设社会主义道路的探索，站在比较高的历史起点上，取得了初步成果\n**八届九中全会1961**\n对国民经济实行“调整、巩固、充实、提高”方针"},{"title":"会议大观下","text":"**关于真理标准问题的讨论 1978**\n(1)真理标准问题的讨论是继五四运动和延安整风运动之后又一场马克思主义思想解放运动\n其实质在于是不是坚持马克思列宁主义 毛泽东思想\n(2)讨论明确地解决了党的思想路线问题\n(3)为党重新确立实事求是思想路线 纠正长期以来的左倾错误 实现历史性的转折作了思想理论准备\n(4)成为正本清源、拨乱反正和改革开放的思想先导\n**十一届三中 1978**\n(1)全会冲破长期“左”的错误的严重束缚，彻底否定了“两个凡是”的错误方针\n高度评价了关于真理标准问题的讨论，并且断然否定“以阶级斗争为纲”的指导思想\n(2)作出了把工作重点转移到社会主义现代化建设上来和实行改革开放的战略决策\n(3)重新确立了马克思主义的思想路线 政治路线和组织路线  ✅三线三中\n/重新确立解放思想，实事求是思想路线\n(4)全会恢复了党的民主集中制的优良传统\n审查解决了历史上遗留的一批重大问题和一些重要领导人的功过是非问题\n(5)会议形成了以邓小平为核心的党的中央领导集体\n揭开了社会主义改革开放的序幕\n(6)以这次全会为起点，中国进入了改革开放和社会主义现代化建设的历史新时期\n(7)实现了党的历史上具有深远意义的伟大转折\n十一届六中《关于建国以来党的若干历史问题的决议》（简称《决议》）1981\n邓小平对《决议》的起草提出三条指导原则：\n第一，确立毛泽东同志的历史地位，坚持和发展毛泽东思想，这是最核心的一条\n第二，对建国30年来历史上的大事，要进行实事求是的分析，\n包括一些负责同志的功过是非，要作出公正的评价；\n第三，这个总结宜粗不宜细，总结过去是为了引导大家团结一致向前看。\n《关于建国以来党的若干历史问题的决议》\n(1)标志着党在指导思想上的拨乱反正胜利完成\n🚩我们党在改革开放和社会主义现代化建设新时期实现的最根本的拨乱反正：以经济建设为中心\n(2)回顾了新中国成立以前党的历史，总结了新中国成立以后社会主义革命和建设的历史经验。\n(3)彻底否定“文化大革命”，对新中国成立以来的重大历史事件和重要历史人物作出了基本结论。\n(4)科学地评价了毛泽东和毛泽东思想的历史地位。\n对毛泽东思想的科学体系和活的灵魂作了概括，\n强调毛泽东思想是我们党的宝贵的精神财富，它将长期指导我们的行动。\n(5)对党的十一届三中全会以来逐步确立的适合中国情况的建设社会主义现代化强国的道路，\n从十个方面作了概括，\n实质上初步提出了在中国建设什么样的社会主义和怎样建设社会主义的问题。\n(6)该决议解决了两个相互联系的重大历史课题即\n①科学评价毛泽东的历史地位和毛泽东思想的科学体系；\n②根据新的实际和发展要求实行改革开放、确立中国社会主义现代化建设正确道路。\n(7)指出社会主义改造基本完成以后，我国所要解决的主要矛盾，\n是人民日益增长的物质文化需要同落后的社会生产之间的矛盾\n**十二大 1982**\n第一次提出了“建设有中国特色的社会主义”命题\n标志着邓小平理论主题的形成，标志着中特理论主题的形成\n从此，“中国特色社会主义”成为我们党的全部理论和实践创新的主题\n这一重大命题的提出具有里程碑意义，是中国共产党人对科学社会主义发展的开创性贡献\n**十二届三中 1984**\n指出我国社会主义经济是在公有制基础上的有计划的商品经济 ✅有计划 一二三\n**十三大 1987**\n社会主义初级阶段的基本路线\n第一次对中特理论进行系统的概括\n标志着邓小平理论轮廓的形成，中特理论轮廓的形成\n⚠️基本路线中\n回答了社会主义的根本任务问题的是：“以经济建设为中心”\n回答了社会主义的发展动力和外部条件问题：“坚持改革开放”\n实现奋斗目标的领导力量和依靠力量：“领导和团结各族人民”\n**十四大 1992**\n明确以建立社会主义市场经济体制为我国经济体制改革的目标\n⚠️南方谈话和十四大标志着\n改革开放和现代化建设事业进入从计划经济体制向社会主义市场经济体制转变的新阶段，\n由此打开了中国经济、政治、文化发展崭新局面\n**十五大 1997**\n邓小平理论确立为党的指导思想\n首次明确提出了社会主义初级阶段的基本纲领\n**十六大 2002**\n三个代表 小康奋斗目标\n✅二三四五六 中路经（过只）刚小乔\n**十七大 2007**\n科学发展观\n提出了“中国特色社会主义理论体系”的科学概念\n标志着中国特色社会主义理论和实践的进一步成熟 🔞17-18还需进一步成熟\n**十八三中 2013**\n实现了改革由局部探索、破冰突围到系统集成、全面深化的转变，开创了我国改革开放新局面\n**二十三中 2024**\n进一步全面深化改革的重点是深化经济体制改革"}],"cards":[]},{"id":"d_quiz","name":"政治 · 刷题卡","desc":"大李子选择题 48 道 · 选完立刻判对错","color":"#FF3B30","cards":[{"id":"z001","type":"choice","front":"人民政协是中国共产党把马克思列宁主义统一战线理论、政党理论、民主政治理论同中国实际相结合的伟大成果，是中国共产党领导各民主党派、无党派人士、人民团体和各族各界人士在政治制度上进行的伟大创造。1949年9月21日，中国人民政治协商会议第一届全体会议在北平开幕。人民政协的召开，标志着中国","options":[{"k":"A","t":"人民代表会议制度的确立"},{"k":"B","t":"工农兵代表大会制度的确立"},{"k":"C","t":"民族区域自治制度的确立"},{"k":"D","t":"新型政党制度的确立"}],"answer":["D"],"explain":"完成创建新中国的任务，是由中国人民政治协商会议来承担的。人民政协的召开，标志着中国的新型政党制度——中国共产党领导的多党合作和政治协商制度的确立。因此，本题的正确答案是选项D","distract":"","multi":false,"back":"","tags":["刷题","重点会议","单选"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"z002","type":"choice","front":"大革命失败后，白色恐怖笼罩全国。在生死考验面前，中国共产党人坚持革命的理想信念，表现出大无畏的英雄气概。为了挽救革命，1927年8月7日，中共中央在汉口召开紧急会议，史称“八七会议”。这次会议","options":[{"k":"A","t":"批评了大革命后期存在的“左”倾错误"},{"k":"B","t":"阐明了党的工作重心由城市转移到乡村的必要性"},{"k":"C","t":"提出了组织湘、鄂、粤、赣四省农民秋收暴动"},{"k":"D","t":"确定了土地革命和武装起义的方针"}],"answer":["D"],"explain":"大革命失败以后，党在汉口召开八七会议，确立了土地革命和武装起义方针。","distract":"","multi":false,"back":"","tags":["刷题","重点会议","单选"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"z003","type":"choice","front":"坚持社会主义制度与市场经济的结合,是社会主义市场经济的特色所在、优势所在。社会主义市场经济体制是中国特色社会主义的重大理论和实践创新,是社会主义基本经济制度的重要组成部分,是推动经济发展的重要制度保障。改革开放和现代化建设事业进入从计划经济体制向社会主义市场经济体制转变的新阶段，标志是","options":[{"k":"A","t":"中共十二届三中全会"},{"k":"B","t":"中共十三届三中全会"},{"k":"C","t":"中共十四届三中全会"},{"k":"D","t":"邓小平南方谈话和中共十四大"}],"answer":["D"],"explain":"1992年年初，邓小平在南方谈话中指出：“计划多一点还是市场多一点，不是社会主义与资本主义的本质区别。计划经济不等于社会主义,资本主义也有计划；市场经济不等于资本主义,社会主义也有市场。计划和市场都是经济手段。”这一论述，从理论上突破了计划经济和市场经济是制度属性的观念，从根本上解除了把计划经济和市场经济看作属于社会基本制度范畴的思想束缚,标志着邓小平的社会主义市场经济理论的形成。1992年10月,中共十四大确定我国经济体制改革的目标是建立社会主义市场经济体制。以邓小平南方谈话和党的十四大为标志,改革开放和现代化建设事业进入从计划经济体制向社会主义市场经济体制转变的新阶段,由此打开了中国经济、政治、文化发展的崭新局面。因此，正确答案是D。","distract":"","multi":false,"back":"","tags":["刷题","重点会议","单选"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"z004","type":"choice","front":"1981年6月，中共十一届六中全会通过《关于建国以来党的若干历史问题的决议》，标志着党在指导思想上拨乱反正任务的完成。该决议对党的十一届三中全会以来逐步确立的适合中国情况的社会主义现代化强国的道路,从十个方面作了概括,实质上初步提出了","options":[{"k":"A","t":"在中国建设什么样的社会主义和怎样建设社会主义的问题"},{"k":"B","t":"党在社会主义初级阶段的基本路线"},{"k":"C","t":"党在社会主义初级阶段的基本纲领"},{"k":"D","t":"建设有中国特色的社会主义的命题"}],"answer":["A"],"explain":"1981年召开的中共十一届六中全会通过的《关于建国以来党的若干历史问题的决议》，对党的十一届三中全会以来逐步确立的适合中国情况的建设社会主义现代化强国的道路，从十个方面作了概括。其中，第一个方面就是关于新时期我国社会主义矛盾的判断。该决议指出：“在社会主义改造基本完成以后，我国所要解决的主要矛盾，是人民日益增长的物质文化需要同落后的社会生产之间的矛盾。党和国家工作的重点必须转移到以经济建设为中心的社会主义现代化建设上来，大大发展社会生产力,并在这个基础上逐步改善人民的物质文化生活。”因此,正确答案是A.","distract":"选项B，是党的十三大的内容。选项C，是党的十五大的内容。选项D，是党的十二大的内容，均不符合题意。因此，排除。","multi":false,"back":"","tags":["刷题","重点会议","单选"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"z005","type":"choice","front":"在解放战争取得全国胜利前夕，中国共产党即将成为执政党，1949年3月毛泽东在中共七届二中全会上告诫全党，夺取全国胜利，这只是万里长征走完了第一步，中国革命以后的道路更长，工作更伟大，更艰苦。据此，毛泽东提出","options":[{"k":"A","t":"统一战线、武装斗争、党的建设三大法宝"},{"k":"B","t":"理论联系实际、密切联系群众、批评和自我批评三大优良作风"},{"k":"C","t":"务必继续保持谦虚、谨慎、不骄、不躁的作风，务必继续保持艰苦奋斗的作风"},{"k":"D","t":"务必不忘初心、牢记使命，务必谦虚谨慎、艰苦奋斗，务必敢于斗争、善于斗争"}],"answer":["C"],"explain":"1949年3月召开的中共七届二中全会,规定了党在全国胜利后在政治、经济、外交方面应当采取的基本政策,指出了中国由农业国转变为工业国、由新民主主义社会转变为社会主义社会的发展方向。全会讨论确定了党的工作重心由乡村转移到城市的问题。毛泽东在会议上提出了“两个务必”的思想即“务必使同志们继续地保持谦虚、谨慎、不骄、不躁的作风，务必使同志们继续地保持艰苦奋斗的作风”。毛泽东还指出，在胜利面前，必须警惕资产阶级“糖衣炮弹”的攻击。因此，正确答案是C。","distract":"选项A，不符合题意。1939年10月,毛泽东发表《《共产党人》发刊词》，指出,统一战线、武装斗争、党的建设,是党在中国革命中的三个基本问题，是党在中国革命中战胜敌人的三大法宝；把党的建设称为“伟大的工程”，指出党的建设要紧密围绕党的政治路线进行。选项B，不符合题意。1945年4-6月，毛泽东在党的七大作《论联合政府》报告，把党在长期奋斗中形成的优良作风概括为理论联系实际、密切联系群众、批评和自我批评三大作风。选项D,不符合题意。“三个务必”是习近平总书记在党的二十大报告中提出的。因此,排除。","multi":false,"back":"","tags":["刷题","重点会议","单选"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"z006","type":"choice","front":"1947年12月，中共中央在陕北米脂县杨家沟召开会议，制定了夺取全国胜利的行动纲领。毛泽东在会上指出：“中国人民的革命战争，现在已经达到了一个转折点……这是一个历史的转折点。这是蒋介石的二十年反革命统治由发展到消灭的转折点。这是一百多年以来帝国主义在中国的统治由发展到消灭的转折点。”这个“转折点”是指","options":[{"k":"A","t":"人民解放军占领南京"},{"k":"B","t":"人民解放军转入了全国规模的战略进攻"},{"k":"C","t":"人民解放军同国民党军队进行战略决战的时机已经成熟"},{"k":"D","t":"国民党赖以维持其反动统治的主要军事力量基本上被摧毁"}],"answer":["B"],"explain":"1946年6月至1947年6月，人民军队处于战略防御阶段，战争主要在解放区进行。1947年6月底,刘伯承、邓小平率领大军强渡黄河,揭开人民解放战争战略进攻的序幕。8月底,刘邓大军千里跃进大别山。8月下旬，陈赓、谢富治率领大军挺进豫西。9月，陈毅、粟裕率领大军挺进苏鲁豫皖地区。三路大军打到外线，迫使国民党军处于被动地位。内线和外线的攻势作战,构成了人民解放战争全国规模的战略进攻的总态势。国民党军队不得不由战略进攻转变为“全面防御”,人民军队结束了长期以来在国内革命战争中所处的战略防御地位。1947年12月,中共中央在陕北米脂杨家沟召开扩大会议(十二月会议),毛泽东在会上作《目前形势和我们的任务》报告,指出：“中国人民的革命战争,现在已经达到了一个转折点。这即是中国人民解放军已经打退了美国走狗蒋介石的数百万反动军队的进攻，并使自己转入了进攻。”因此，正确答案是B。","distract":"选项A，不符合题意。1949年4月23日，人民解放军占领南京，宣告延续了22年之久的国民党反动统治的覆灭。选项C,不符合题意。1948年秋,敌我力量对比已发生根本变化,人民解放战争进入夺取全国胜利的战略决战阶段。人民解放军同国民党军队进行战略决战的时机已经成熟。选项D,不符合题意。辽沈、淮海、平津三大战役(1948年9月至1949年1月),是解放军与国民党军主力进行的战略决战，共歼敌154万余人。至此，蒋介石赖以维护其统治的主要军事力量基本上被摧毁。因此.排除。","multi":false,"back":"","tags":["刷题","重点会议","单选"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"z007","type":"choice","front":"为了从思想上认真清理主观主义、教条主义在党内的影响，1941年至1945年，中国共产党以延安为中心开展了一场整风运动。1941年5月，毛泽东作了《改造我们的学习》的报告，整风运动首先在党的高级干部中进行；1942年2月,毛泽东先后作了《整顿党的作风》和《反对党八股》的讲演,整风运动在全党范围普遍展开。1945年4月党的六届七中全会通过了《关于若干历史问题的决议》,标志着整风运动胜利结束。这个决议","options":[{"k":"A","t":"首次明确提出了“马克思主义的中国化”这个命题"},{"k":"B","t":"使全党对中国革命基本问题的认识达到一致"},{"k":"C","t":"对毛泽东思想作出了系统概括和阐述"},{"k":"D","t":"使全党在思想上政治上组织上达到空前统一和团结"}],"answer":["B"],"explain":"1944年5月一1945年4月，中共扩大的六届七中全会在延安召开。会议原则通过了《关于若干历史问题的决议》，对建党以后特别是党的六届四中全会至遵义会议前这一段党的历史及其经验教训进行了总结,对党的若干重大历史问题作出结论。《关于若干历史问题的决议》肯定了确立毛泽东在全党的领导地位的重大意义,使全党特别是党的高级干部对中国革命基本问题的认识达到了一致，增强了全党团结，为党的七大胜利召开创造了充分条件，有力促进了中国革命事业的发展。至此，整风运动胜利结束。延安整风运动使实事求是的思想路线在全党范围确立起来。因此，正确答案是B。","distract":"选项A，不符合题意。1938年召开的中共六届六中全会第一次明确提出了“马克思主义的中国化”这个命题。选项C，不符合题意。对毛泽东思想作出系统概括和阐述的党的文献主要有：①刘少奇在七大上所作的《关于修改党的章程的报告》；②《关于建国以来党的若干历史问题的决议》。选项D，不符合题意。党的七大为建立新民主主义的新中国制定了正确路线方针政策，使全党在思想上政治上组织上达到空前统一和团结。因此，排除。","multi":false,"back":"","tags":["刷题","重点会议","单选"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"z008","type":"choice","front":"在抗日战争即将进入相持阶段时,毛泽东总结了抗战以来的经验教训,对主张“一切经过统一战线”“一切服从抗日”等错误观点做了坚决抵制。这是在（）上。","options":[{"k":"A","t":"八七会议"},{"k":"B","t":"三湾改编"},{"k":"C","t":"古田会议"},{"k":"D","t":"中共六届六中全会"}],"answer":["D"],"explain":"1937年11月，王明根据共产国际和苏联领导人关于中国抗战应该依靠国民党的指示精神，主张“一切经过统一战线”“一切服从抗日”，把共产党和人民军队的活动限制在国民党允许的范围内，否认共产党在抗战中争取领导权的重要意义，否认抗日民族统一战线中的独立自主原则。这些错误观点受到毛泽东等中央领导人的坚决抵制。1938年11月，在扩大的党的六届六中全会上基本纠正了王明的右倾错误，进一步巩固了毛泽东在全党的领导地位，统一了全党的思想和步调，推动了各项工作迅速发展。毛泽东指出：“六中全会是决定中国之命运的。”因此，正确答案是D。","distract":"选项A，不符合题意。1927年8月，毛泽东在八七会议上提出：“以后要非常注意军事。须知政权是由枪杆子中取得的。”选项B,不符合题意。1927年9月,毛泽东领导起义军在江西永新县三湾村进行了著名的三湾改编，从组织上确立了党对军队的领导。三湾改编是建设无产阶级领导的新型人民军队的重要开端，是人民军队最早的政治整训。选项C，不符合题意。1929年12月召开的古田会议,确立了“思想建党、政治建军”的原则。考生需要注意,1929年12月毛泽东组织的新泉整训，是古田会议的序曲，是人民军队历史上第一次正规的军政整训，开创了我军政治整训制度化、规范化的先河。因此，排除。","multi":false,"back":"","tags":["刷题","重点会议","单选"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"z009","type":"choice","front":"1937年8月，中国共产党在陕北洛川召开政治局扩大会议，制定了抗日救国十大纲领，强调要打倒日本帝国主义，关键在于","options":[{"k":"A","t":"使已经发动的抗战成为全面的全民族抗战"},{"k":"B","t":"坚持统一战线中无产阶级的领导权"},{"k":"C","t":"在敌人后方放手发动独立自主的山地游击战争"},{"k":"D","t":"在国民党统治区放手发动抗日的群众运动"}],"answer":["A"],"explain":"1937年8月召开的洛川会议，制定了抗日救国十大纲领，强调要打倒日本帝国主义关键在于使已经发动的抗战成为全面的全民族抗战。为此，必须实行全国军事的总动员、全国人民的总动员；改革政治机构，废除国民党的一党专政，给人民以充分的抗日民主权利，适当改善工农大众的生活；实行抗日的外交政策、财政经济政策、教育政策和民族团结政策,使抗日战争成为真正的人民战争。会议强调，必须坚持统一战线中无产阶级的领导权，在敌人后方放手发动独立自主的山地游击战争,在国民党统治区放手发动抗日群众运动。会议通过了《中国共产党抗日救国十大纲领)和《中共中央关于目前形势与党的任务的决定》,标志着党的全面抗战路线的正式形成。因此,正确答案是A.","distract":"选项B、C、D，均不符合题意。因此，排除。","multi":false,"back":"","tags":["刷题","重点会议","单选"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"z010","type":"choice","front":"中国共产党确定抗日民族统一战线新政策的会议是","options":[{"k":"A","t":"八七会议"},{"k":"B","t":"遵义会议"},{"k":"C","t":"洛川会议"},{"k":"D","t":"瓦窑堡会议"}],"answer":["D"],"explain":"1935年12月，中共中央在陕北瓦窑堡召开政治局扩大会议，提出党的基本策略任务是建立广泛的抗日民族统一战线，批了党内长期存在的“左”倾冒险主义、关门主义错误倾向，并指出关门主义是党内的主要危险。会议决议规定将“工农共和国”改为“人民共和国”。瓦窑堡会议解决了遵义会议未来得及解决的党的政治路线和策略问题,确定建立抗日民族统一战线的新政策。因此,正确答案是D。","distract":"选项A、B、C，均不符合题意。因此，排除。","multi":false,"back":"","tags":["刷题","重点会议","单选"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"z011","type":"choice","front":"独立自主是中华民族精神之魂,是我们立党立国的重要原则。走自己的路,是党的全部理论和实践的立足点，更是党百年奋斗得出的历史结论。党历来坚持独立自主开拓前进道路，坚持把国家和民族发展放在自己力量的基点上，坚持中国的事情必须由中国人民自己作主张、自己来处理。在中国共产党的历史上，开启了中国共产党独立自主解决中国革命实际问题的新阶段的会议是","options":[{"k":"A","t":"中共一大"},{"k":"B","t":"中共二大"},{"k":"C","t":"八七会议"},{"k":"D","t":"遵义会议"}],"answer":["D"],"explain":"坚持独立自主，就要坚持中国的事情必须由中国人民自己作主张、自己来处理。1930年，毛泽东在《反对本本主义》中就指出：“中国革命斗争的胜利要靠中国同志了解中国情况。”这是独立自主思想的最初的明确表述。1963年，毛泽东在会见外宾时指出：“真正懂得独立自主是从遵义会议开始。”遵义会议是中国共产党第一次独立自主地运用马列主义基本原理解决自己的路线、方针和政策问题的会议。遵义会议的一系列重大决策,是在中国共产党同共产国际的联系中断的情况下，独立自主地作出的。遵义会议的鲜明特点是坚持真理、修正错误，确立党中央的正确领导，创造性地制定和实施符合中国革命特点的战略策略。遵义会议开启了中国共产党独立自主解决中国革命实际问题的新阶段。因此,正确答案是D。","distract":"选项A，不符合题意。中国共产党是在共产国际（第三国际)的指导和帮助下建立的。1921年召开的中共一大，共产国际派代表马林、尼克尔斯基参加会议，两人在会议上作了讲话和指示。中共一大通过的第一个纲领中写上了“联合第三国际”的内容。选项B,不符合题意。1922年召开的中共二大，通过了一个决议案，中国共产党正式加入共产国际。这意味着中国共产党是共产国际的一个下属支部。此后共产国际所作出的一切决议、决定和指示，中国共产党都必须无条件贯彻执行。选项C,不符合题意。1927年召开的八七会议,共产国际驻中国代表罗米那兹等参加了会议。因此，排除。","multi":false,"back":"","tags":["刷题","重点会议","单选"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"z012","type":"choice","front":"1935年1月，中央政治局在长征途中召开的遵义会议，是党的历史上一个生死攸关的转折点，标志着中国共产党在政治上走向成熟。遵义会议解决了当时具有决定意义的问题，即","options":[{"k":"A","t":"政治路线和策略问题"},{"k":"B","t":"军事和组织问题"},{"k":"C","t":"思想路线问题"},{"k":"D","t":"统一战线问题"}],"answer":["B"],"explain":"1935年1月召开的遵义会议，集中解决了当时具有决定意义的军事问题和组织问题。遵义会议明确地回答了红军的战略战术方面的是非问题，指出博古、李德军事指挥上的错误，同时改变了中央的领导特别是军事领导，解决了党内所面临的最迫切的军事问题和组织问题，结束了“左”倾教条主义错误在中央的统治，确立了毛泽东在党中央和红军的领导地位。因此，正确答案是B。","distract":"选项A，不符合题意。1935年12月召开的瓦窑堡会议，解决了遵义会议未来得及解决的党的政治路线和策略问题，确定建立抗日民族统一战线的新政策。选项C，不符合题意。延安整风运动（1941年5月一1945年4月），使实事求是的思想路线在全党范围确立起来。选项D，不符合题意。因此，排除。","multi":false,"back":"","tags":["刷题","重点会议","单选"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"z013","type":"choice","front":"1929年12月，红四军党的第九次代表大会（古田会议）在福建上杭县古田村召开。大会根据中央九月来信精神，通过了毛泽东起草的古田会议决议。决议由八个部分组成，其中最重要的是","options":[{"k":"A","t":"关于纠正党内错误思想的决议案，确立了思想建党、政治建军原则"},{"k":"B","t":"根本上清算了“左”倾教条主义的错误"},{"k":"C","t":"纠正右倾错误，开始找着革命新道路"},{"k":"D","t":"批评了“左”倾关门主义错误"}],"answer":["A"],"explain":"1929年召开的古田会议通过了毛泽东起草的古田会议决议。决议由八个部分组成，即关于纠正党内的错误思想；党的组织问题；党内教育问题；红军宣传工作问题；士兵政治训练问题；废止肉刑问题；优待伤病兵问题；红军军事系统与政治系统关系问题。其中，最重要的是关于纠正党内错误思想的决议案,确立了思想建党、政治建军原则；阐述了加强党的思想建设的极端重要性,指明党内各种非无产阶级思想的表现、来源及纠正办法；规定红军是一个执行革命的政治任务的武装集团,必须绝对服从共产党的领导,必须全心全意为党的纲领、路线和政策而奋斗；提出红军必须担负打仗、筹款和做群众工作的任务，必须加强政治工作。因此，正确答案是A。","distract":"选项B，是延安整风运动的意义；选项C，是八七会议后开始的；选项D，是瓦窑堡会议的内容。均不符合题意。因此，排除。","multi":false,"back":"","tags":["刷题","重点会议","单选"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"z014","type":"choice","front":"统一战线是党的总路线总政策的重要组成部分。建立最广泛的统一战线，是党克敌制胜的重要法宝，是党执政兴国的重要法宝，是团结海内外全体中华儿女实现中华民族伟大复兴的重要法宝。1922年中共二大通过了《关于“民主的联合战线”的议决案》，标志着中国共产党统一战线政策的正式提出。中共二大提出组成“民主主义的联合战线”，主要目的是","options":[{"k":"A","t":"坚持中国共产党在统一战线中的领导权"},{"k":"B","t":"反对封建压迫和国民党新军阀的统治"},{"k":"C","t":"为了实现反帝反军阀的革命目标"},{"k":"D","t":"为了建立新民主主义的新中国"}],"answer":["C"],"explain":"中国共产党在我国革命、建设、改革的不同历史时期，先后建立了国民革命联合战线、工农民主统一战线、抗日民族统一战线、人民民主统一战线、新时期爱国统一战线等。1922年召开的中共二大指出,为了实现反帝反军阀的革命目标,必须组成“民主主义的联合战线”。大会通过的《关于“民主的联合战线”的议决案》提出联合全国一切革命党派,联合资产阶级民主派,组织民主的联合战线,并决定邀请国民党等革命团体举行联席会议,共商具体办法。这是党最早提出关于统一战线的思想和主张。因此，正确答案是C。","distract":"选项A，不符合题意。统一战线最根本的问题是领导权问题。党的领导是统一战线最鲜明的特征,坚持党的领导是统一战线最核心最根本的问题。选项B,不符合题意。土地革命战争时期的工农民主统一战线（1927年8月—1937年7月）以反对封建压迫和国民党新军阀的统治为目标。选项D，不符合题意。解放战争时期的人民民主统一战线（1945年8月一1949年9月），以推翻蒋介石的反动政权，建立新民主主义的新中国为目标。因此，排除。","multi":false,"back":"","tags":["刷题","重点会议","单选"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"z015","type":"choice","front":"1921年7月23日，中国共产党第一次全国代表大会在上海法租界望志路106号（今兴业路76号）开幕。最后一天的会议转移到浙江嘉兴南湖的游船上举行。大会确定党的名称为“中国共产党”，通过了中国共产党的第一个纲领和决议。大会在讨论党的实际工作计划时，决定首先集中精力","options":[{"k":"A","t":"组织军队，进行武装斗争"},{"k":"B","t":"成立农民协会，开展农民运动"},{"k":"C","t":"领导工人运动，组织工会和教育工人"},{"k":"D","t":"开展青年运动和妇女运动"}],"answer":["C"],"explain":"中共一大在讨论党的实际工作计划时，“因为党员少”，关于“组织农民和军队的问题成了悬案”,决定首先集中精力组织工人。大会通过的党的第一个决议规定,党在当前的“基本任务是成立产业工会”,“党应在工会里灌输阶级斗争的精神”,要派党员到工会去工作。1921年8月,中国劳动组合书记部(党领导工人运动的第一个公开机构)在上海成立。在党的领导下,从1922年1月香港海员罢工到1923年2月京汉铁路工人罢工，掀起了中国工人运动的第一个高潮。京汉铁路工人罢工遭到反动军阀血腥镇压，造成二七惨案。此后，中国工人运动暂时转入低潮。1925年5月，以五卅运动为起点,掀起了全国范围的大革命高潮；同年6月开始的省港大罢工,是中国工人运动史上持续时间最长的一次政治大罢工,前后坚持了16个月之久。因此,正确答案是C。","distract":"选项A、B、D，均不符合题意。因此，排除。","multi":false,"back":"","tags":["刷题","重点会议","单选"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"z016","type":"choice","front":"2013年11月，党的十八届三中全会在北京举行。全会审议通过的《中共中央关于全面深化改革若干重大问题的决定》，对全面深化改革作出顶层设计和总体规划。《中共中央关于党的百年奋斗重大成就和历史经验的决议》指出，党的十一届三中全会是划时代的，党的十八届三中全会也是划时代的。党的十八届三中全会之所以也是划时代的，是因为这次全会","options":[{"k":"A","t":"实现了改革由局部探索、破冰突围到系统集成、全面深化的转变"},{"k":"B","t":"开启了改革开放和社会主义现代化建设新时期"},{"k":"C","t":"开创了我国改革开放新局面"},{"k":"D","t":"确定建立社会主义市场经济体制"}],"answer":["A","C"],"explain":"本题考查“党的十八届三中全会的意义”。《中共中央关于党的百年奋斗重大成就和历史经验的决议》指出，党的十八届三中全会也是划时代的，实现了改革由局部探索、破冰突围到系统集成、全面深化的转变，开创了我国改革开放新局面。因此，正确答案为选项A、C。","distract":"","multi":true,"back":"","tags":["刷题","重点会议","多选"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"z017","type":"choice","front":"1935年1月中共中央政治局在长征途中召开的遵义会议，是党的历史上一个生死攸关的转折点。这次会议","options":[{"k":"A","t":"全面讨论了政治路线的是非问题"},{"k":"B","t":"解决了当时党内所面临的最迫切的组织问题和军事问题"},{"k":"C","t":"结束了“左”倾教条主义错误在中央的统治"},{"k":"D","t":"开始确立毛泽东在中共中央和红军的领导地位"}],"answer":["B","C","D"],"explain":"本题考查“遵义会议与中国革命的历史性转折”。遵义会议结束了“左”倾教条主义错误在中央的统治，集中解决了当时具有决定意义的军事问题和组织问题，开始确立以毛泽东为代表的马克思主义的正确路线在中共中央的领导地位。因此，正确答案为选项B、C、D。","distract":"","multi":true,"back":"","tags":["刷题","重点会议","多选"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"z018","type":"choice","front":"党的十一届三中全会标志着中国共产党重新确立了马克思主义的思想路线、政治路线、组织路线，实现了新中国成立以来党的历史上具有深远意义的伟大转折，开启了我国改革开放和社会主义现代化建设的新时期。全会作出实行改革开放的历史性决策，是基于","options":[{"k":"A","t":"对党和国家前途命运的深刻把握"},{"k":"B","t":"对社会主义革命和建设实践的深刻总结"},{"k":"C","t":"对时代潮流的深刻洞察"},{"k":"D","t":"对人民群众期盼和需要的深刻体悟"}],"answer":["A","B","C","D"],"explain":"20世纪六七十年代，世界发展日新月异，党出于对时代潮流的深刻洞察和对党和国家前途命运的深刻把握，深刻认识到必须改变以往以阶级斗争为纲的方针；同时顺应人民期盼，基于对社会主义革命和建设实践的深刻总结，作出了实行改革开放的伟大决策。","distract":"","multi":true,"back":"","tags":["刷题","重点会议","多选"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"z019","type":"choice","front":"经过十一届三中全会以来改革开放和现代化建设的实践，党对于中国国情的认识更加深刻，对建设有中国特色社会主义的道路更加明确。1987年10月25日至11月1日，中国共产党第十三次全国代表大会在北京举行。中共十三大","options":[{"k":"A","t":"系统阐述了社会主义初级阶段理论，概括了党在社会主义初级阶段的基本路线"},{"k":"B","t":"首次对中国特色社会主义理论进行系统的概括，标志着邓小平理论轮廓的形成"},{"k":"C","t":"确定我国经济体制改革的目标是建立社会主义市场经济体制"},{"k":"D","t":"制定到21世纪中叶分三步走、实现现代化的发展战略"}],"answer":["A","B","D"],"explain":"1987年召开的中共十三大的主要内容有：第一，系统阐述社会主义初级阶段理论，明确概括了党在社会主义初级阶段“一个中心、两个基本点”的基本路线。第二,第一次对中国特色社会主义理论进行系统的概括,标志着邓小平理论轮廓的形成。大会对十一届三中全会以后开辟新道路的历史经验作了初步概括，并对改革开放和现代化建设实践中形成发展起来的一系列科学理论观点作了归纳。第三，制定了经济体制改革和政治体制改革的基本任务和奋斗目标。第四，制定到21世纪中叶分三步走、实现现代化的发展战略。因此，正确答案是ABD。","distract":"选项C，不符合题意。1992年召开的中共十四大作出了三项具有深远意义的决策。第一，抓住机遇，加快发展，集中精力把经济建设搞上去；第二，确定我国经济体制改革的目标是建立社会主义市场经济体制；第三,提出用邓小平建设有中国特色社会主义的理论武装全党。因此，排除。","multi":true,"back":"","tags":["刷题","重点会议","多选"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"z020","type":"choice","front":"1981年6月27日至29日,中共十一届六中全会召开。全会通过了《关于建国以来党的若干历史问题的决议》，这个决议","options":[{"k":"A","t":"实质上初步提出了在中国建设什么样的社会主义和怎样建设社会主义的问题"},{"k":"B","t":"概括了毛泽东思想的科学体系和活的灵魂"},{"k":"C","t":"标志着党在指导思想上拨乱反正任务的完成"},{"k":"D","t":"表明党所领导的改革开放从一开始就具有明确的社会主义方向"}],"answer":["A","B","C"],"explain":"《关于建国以来党的若干历史问题的决议》的主要内容有：第一，回顾了新中国成立以前党的历史，总结了新中国成立以后社会主义革命和建设的历史经验。第二，彻底否定“文化大革命”,对新中国成立以来的重大历史事件和重要历史人物作出了基本结论。第三,科学地评价了毛泽东和毛泽东思想的历史地位。对毛泽东思想的科学体系和活的灵魂(即实事求是、群众路线、独立自主)作了概括,强调毛泽东思想是我们党的宝贵的精神财富,它将长期指导我们的行动。第四,对党的十一届三中全会以来逐步确立的适合中国情况的建设社会主义现代化强国的道路，从十个方面作了概括,实质上初步提出了在中国建设什么样的社会主义和怎样建设社会主义的问题。该决议解决了两个相互联系的重大历史课题,即1科学评价毛泽东的历史地位和毛泽东思想的科学体系；②根据新的实际和发展要求实行改革开放、确立中国社会主义现代化建设正确道路。标志着党在指导思想上的拨乱反正胜利完成。因此，正确答案是ABC。","distract":"选项D，不符合题意。1979年3月，邓小平在党的理论工作务虚会上发表的《坚持四项基本原则》的讲话中指出：坚持四项基本原则,“是实现四个现代化的根本前提”。他还提出：“现在搞建设,也要适合中国情况,走出一条中国式的现代化道路。”“中国式的现代化,必须从中国的特点出发。”这表明，党所领导的改革开放从一开始就具有明确的社会主义方向。因此，排除。","multi":true,"back":"","tags":["刷题","重点会议","多选"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"z021","type":"choice","front":"1978年12月18日至22日,党的十一届三中全会在北京召开。全会果断结束“以阶级斗争为纲”,实现党和国家工作中心的战略转移，开启了改革开放和社会主义现代化建设新时期，实现了新中国成立以来党的历史上具有深远意义的伟大转折。这次全会","options":[{"k":"A","t":"标志着中国共产党重新确立了马克思主义的思想路线、政治路线、组织路线"},{"k":"B","t":"科学评价毛泽东并概括了毛泽东思想的科学体系和活的灵魂"},{"k":"C","t":"作出了把党和国家的工作重点转移到以经济建设为中心的社会主义现代化建设上来、实行改革开放的历史性决策"},{"k":"D","t":"形成了以邓小平为核心的党的中央领导集体"}],"answer":["A","C","D"],"explain":"中共十一届三中全会的主要内容有：①彻底否定“两个凡是”的错误方针，强调要正确对待毛泽东的历史地位和毛泽东思想的科学体系,高度评价关于真理标准的讨论；②果断地停止使用“以阶级斗争为纲”的口号，作出了把党和国家的工作重点转移到社会主义现代化建设上来、实行改革开放的历史性决策；③提出实现民主制度化、法律化的任务，决定健全党的民主集中制，健全党规党法，严肃党纪。全会增选了中央领导机构成员，成立了中央纪律检查委员会。全会的胜利召开，结束了粉碎“四人帮”后党和国家工作徘徊中前进的局面，标志着中国共产党重新确立了马克思主义的思想路线、政治路线、组织路线,形成了以邓小平为核心的党的中央领导集体，拉开了改革开放和开创中国特色社会主义的大幕，开启了我国改革开放和社会主义现代化建设新时期,实现了历史性的伟大转折。因此,正确答案是ACD.","distract":"选项B，不符合题意。1981年中共十一届六中全会通过的《关于建国以来党的若干历史问题的决议》,科学评价了毛泽东和毛泽东思想的历史地位,概括了毛泽东思想的科学体系和活的灵魂。因此，排除。","multi":true,"back":"","tags":["刷题","重点会议","多选"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"z022","type":"choice","front":"党的八大根据我国社会主义改造基本完成后的形势,提出国内主要矛盾已经不再是工人阶级和资产阶级的矛盾，而是人民对于经济文化迅速发展的需要同当前经济文化不能满足人民需要的状况之间的矛盾，全国人民的主要任务是","options":[{"k":"A","t":"集中力量发展社会生产力"},{"k":"B","t":"实现国家工业化"},{"k":"C","t":"逐步满足人民日益增长的物质和文化需要"},{"k":"D","t":"鼓足干劲、力争上游、多快好省地建设社会主义"}],"answer":["A","B","C"],"explain":"1956年召开的中共八大正确分析了国内形势和主要矛盾的变化,明确提出新形势下党和人民的主要任务,大会宣布：社会主义制度在我国已经基本上建立起来,国内主要矛盾已经是人民对于经济文化迅速发展的需要同当前经济文化不能满足人民需要的状况之间的矛盾；全国人民的主要任务是集中力量发展社会生产力,实现国家工业化,逐步满足人民日益增长的物质和文化需要；还有阶级斗争，还要加强人民民主专政，但根本任务已经是在新的生产关系下面保护和发展生产力。因此,正确答案是ABC.","distract":"选项D，不符合题意。1958年5月,党的八大二次会议通过“鼓足干劲、力争上游、多快好省地建设社会主义”的社会主义建设总路线,反映了广大人民群众迫切要求改变国家经济文化落后状况的普遍愿望,但忽视了客观的经济规律。因此,排除。","multi":true,"back":"","tags":["刷题","重点会议","多选"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"z023","type":"choice","front":"1956年生产资料所有制改造完成,标志着社会主义基本制度在中国确立,中国开始进入全面建设社会主义的历史阶段。1956年9月15日至27日，中国共产党第八次全国代表大会在北京举行。中共八大","options":[{"k":"A","t":"明确提出把马克思列宁主义基本原理同中国具体实际进行“第二次结合”"},{"k":"B","t":"分析了国内形势和主要矛盾的变化，提出新形势下党和人民的主要任务"},{"k":"C","t":"坚持党中央提出的既反保守又反冒进，即在综合平衡中稳步前进的经济建设方针"},{"k":"D","t":"标志着中国共产党开始探索适合中国国情的社会主义建设道路"}],"answer":["B","C"],"explain":"1956年中共八大的召开,标志着党对中国社会主义建设道路的探索取得初步成果。中共八大的主要内容有：第一，正确分析了国内形势和主要矛盾的变化，明确提出新形势下党和人民的主要任务。第二，坚持党中央提出的既反保守又反冒进，即在综合平衡中稳步前进的经济建设方针（1956年6月刘少奇主持的中共中央会议提出)。肯定了陈云提出的“三个主体、三个补充”思想（即以国家经营和集体经营、计划生产、国家市场三者为主体，以个体经营、自由生产、自由市场三者为补充)；第三，提出要扩大社会主义民主、健全社会主义法制，使党和政府的活动做到“有法可依”和“有法必依”；第四，提出加强执政党建设的问题，通过了新修订的党章。新党章提出全面开展社会主义建设的任务，对党的民主集中制的根本原则作出许多新规定，在党员义务方面增加“维护党的团结，巩固党的统一”“对党忠诚老实”等内容。因此，正确答案是BC。","distract":"选项A，不符合题意。1956年4月初，毛泽东明确提出把马克思列宁主义基本原理同中国具体实际进行“第二次结合”。选项D，不符合题意。1956年4月25日，毛泽东作的《论十大关系》报告,是以毛泽东为主要代表的中国共产党人开始探索适合中国国情的社会主义建设道路的标志,标志着党探索中国社会主义建设道路的良好开端,它在新的历史条件下从经济和政治方面提出了新的指导方针，为中共八大的召开作了理论准备。因此，排除。","multi":true,"back":"","tags":["刷题","重点会议","多选"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"z024","type":"choice","front":"党的七大在党的历史上具有极其重要的地位,以“团结的大会,胜利的大会”载入党的史册,为党后来不断从胜利走向胜利指明了正确方向、开辟了正确道路。党的七大在党的历史上具有重要里程碑意义，主要体现在","options":[{"k":"A","t":"实现了党的空前统一和团结"},{"k":"B","t":"确立了毛泽东思想在全党的指导地位"},{"k":"C","t":"标志着我们党在政治上思想上组织上走向了成熟"},{"k":"D","t":"开启了独立自主解决中国革命实际问题的新阶段"}],"answer":["A","B","C"],"explain":"1945年4月召开的中共七大，主要内容有：第一，制定了党的政治路线；第二，把党在长期奋斗中形成的优良作风概括为三大作风；第三，把毛泽东思想确立为党的指导思想并写入党章，是中共七大的历史性贡献。习近平总书记指出：“党的七大在党的历史上具有重要里程碑意义，标志着我们党在政治上思想上组织上走向了成熟。在政治上，党通过延安整风，使全党团结在毛泽东的旗帜下，实现了党的空前统一和团结。在思想上，党确立了毛泽东思想在全党的指导地位,把毛泽东思想写入了党章。在组织上,党形成了一支高举毛泽东旗帜的久经考验的政治家集团。”因此，正确答案是ABC。","distract":"选项D，不符合题意。遵义会议开启了我党独立自主解决中国革命实际问题的新阶段。因此，排除。","multi":true,"back":"","tags":["刷题","重点会议","多选"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"z025","type":"choice","front":"1945年4月至6月，中国共产党第七次全国代表大会在延安举行。党的七大为建立新民主主义的新中国制定了正确路线方针政策，使全党在思想上政治上组织上达到空前统一和团结。毛泽东在会上所作的题为《论联合政府》的报告中指出，中国共产党在中国人民中产生了新的工作作风，这主要的就是","options":[{"k":"A","t":"理论和实践相结合的作风"},{"k":"B","t":"和人民群众紧密联系在一起的作风"},{"k":"C","t":"艰苦奋斗的作风"},{"k":"D","t":"批评与自我批评的作风"}],"answer":["A","B","D"],"explain":"中共七大把党在长期奋斗中形成的优良作风概括为三大作风,即理论和实践相结合的作风、和人民群众紧密联系在一起的作风、批评与自我批评的作风。因此，正确答案是ABD。","distract":"选项C，不符合题意。1949年3月，中共七届二中全会在西柏坡召开。毛泽东在全会上提出“两个务必”思想，即“务必使同志们继续地保持谦虚、谨慎、不骄、不躁的作风，务必使同志们继续地保持艰苦奋斗的作风。”因此，排除。","multi":true,"back":"","tags":["刷题","重点会议","多选"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"z026","type":"choice","front":"1938年9月至11月，中共六届六中全会在延安召开。毛泽东指出：“使马克思主义在中国具体化，使之在其每一表现中带着必须有的中国的特性，即是说，按照中国的特点去应用它，成为全党亟待了解并亟须解决的问题。”为了推进马克思主义中国化的事业，毛泽东向全党提出的任务是","options":[{"k":"A","t":"普遍地深入地学习马克思列宁主义的理论"},{"k":"B","t":"把马克思主义同中国优秀传统文化和具体实际相结合"},{"k":"C","t":"学习我们的历史遗产并给以批判的总结"},{"k":"D","t":"调查研究当前运动的特点及其规律性"}],"answer":["A","C","D"],"explain":"1938年，毛泽东在中共六届六中全会上首次明确提出“马克思主义的中国化”这个重大命题。为了推进马克思主义中国化的事业，毛泽东向全党提出了普遍地深入地学习马克思列宁主义的理论、学习我们的历史遗产并给以批判的总结、调查研究当前运动的特点及其规律性的任务。毛泽东指出：“六中全会是决定中国之命运的。”这次全会基本纠正了王明的右倾错误(即“一切经过统一战线”“一切服从统一战线”，把共产党及其领导的人民军队的活动限制在国民党允许的范围内),进一步巩固了毛泽东在全党的领导地位,统一了全党的思想和步调,推动了各项工作迅速发展。因此，正确答案是ACD。","distract":"选项B,不符合题意。“两个结合”,即“把马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合”,是习近平总书记在庆祝中国共产党成立100周年大会上的重要讲话中提出的。因此，排除。","multi":true,"back":"","tags":["刷题","重点会议","多选"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"z027","type":"choice","front":"1935年1月，中央政治局在长征途中召开了遵义会议。这次会议是在红军第五次反“围剿”失败和长征初期严重受挫的历史关头召开的，是党的历史上一个生死攸关的转折点。这次会议","options":[{"k":"A","t":"事实上确立了毛泽东同志在党中央和红军的领导地位"},{"k":"B","t":"开始确立以毛泽东同志为主要代表的马克思主义正确路线在党中央的领导地位"},{"k":"C","t":"开始形成以毛泽东同志为核心的党的第一代中央领导集体"},{"k":"D","t":"开启了党独立自主解决中国革命实际问题的新阶段"}],"answer":["A","B","C","D"],"explain":"遵义会议是党的历史上一个生死攸关的转折点。这次会议事实上确立了毛泽东在党中央和红军的领导地位，开始确立以毛泽东为主要代表的马克思主义正确路线在党中央的领导地位，开始形成以毛泽东为核心的党的第一代中央领导集体，开启了党独立自主解决中国革命实际问题的新阶段，在最危急关头挽救了党、挽救了红军、挽救了中国革命，并且在这以后使党能够战胜张国焘的分裂主义，胜利完成长征，打开中国革命新局面。遵义会议的鲜明特点是坚持真理、修正错误，确立党中央的正确领导，创造性地制定和实施符合中国革命特点的战略策略。因此，正确答案是ABCD.","distract":"","multi":true,"back":"","tags":["刷题","重点会议","多选"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"z028","type":"choice","front":"1929年12月，红四军党的第九次代表大会在福建上杭县古田村召开，这次会议史称“古田会议”。古田会议确立了思想建党、政治建军原则，创造性地解决了在农村环境中、在党组织和军队以农民为主要成分的条件下","options":[{"k":"A","t":"如何进行全国军事总动员的问题"},{"k":"B","t":"如何保持党的无产阶级先锋队性质的问题"},{"k":"C","t":"如何建设党领导的新型人民军队的问题"},{"k":"D","t":"如何从进攻大城市转为向农村进军"}],"answer":["B","C"],"explain":"1929年召开的古田会议通过的古田会议决议，最重要的是关于纠正党内的错误思想的决议，确立了“思想建党、政治建军”的原则。第一，在党的建设方面，决议阐述了加强党的思想建设的极端重要性，指明了党内各种非无产阶级思想的表现、来源及纠正办法。第二，在军队建设方面，决议规定中国的红军是一个执行革命的政治任务的武装集团，必须绝对服从党的领导，必须全心全意为着党的纲领、路线和政策而奋斗；提出红军必须担负打仗、筹款和做群众工作的任务；必须加强红军政治工作，特别是政治教育工作。古田会议确立了马克思主义建党建军原则，创造性地解决了在农村环境中、在党组织和军队以农民为主要成分的条件下,如何保持党的无产阶级先锋队性质和建设党领导的新型人民军队的重大问题。因此，正确答案是BC。","distract":"选项A，不符合题意。这是1937年洛川会议《抗日救国十大纲领》的主要内容。选项D，不符合题意。从进攻大城市转为向农村进军，是中国革命具有决定意义的新起点。因此，排除。","multi":true,"back":"","tags":["刷题","重点会议","多选"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"z029","type":"choice","front":"1927年8月7日，中共中央在汉口秘密召开紧急会议，即“八七会议”。八七会议给正处在思想泯乱和组织涣散中的中国共产党指明了新的出路,这是由大革命失败到土地革命战争兴起的历史性转变。八七会议","options":[{"k":"A","t":"确定实行土地革命和武装起义的方针"},{"k":"B","t":"从组织上确立了党对军队的领导"},{"k":"C","t":"提出了“整顿改编自己的队伍，找着新的道路”的任务"},{"k":"D","t":"提出了“须知政权是由枪杆子中取得的”的论断"}],"answer":["A","C","D"],"explain":"1927年召开的八七会议的主要内容有：第一，彻底清算了大革命后期的陈独秀右倾机会主义错误。毛泽东根据大革命失败的惨痛教训，在发言中指出：“以后要非常注意军事。须知政权是由枪杆子中取得的。”第二，确定实行土地革命和武装起义的方针。第三，提出了“整顿改编自己的队伍，纠正过去严重的错误，而找着新的道路”的任务。第四，选出了以粗秋白为首的中央临时政治局。因此,正确答案是ACD.","distract":"选项B，不符合题意。1927年9月29日，毛泽东领导起义军在江西永新县三湾村进行了著名的三湾改编，将党的支部建在连上，从组织上确立了党对军队的领导。因此，排除。","multi":true,"back":"","tags":["刷题","重点会议","多选"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"z030","type":"choice","front":"1924年1月，中国国民党第一次全国代表大会由孙中山主持在广州举行。大会审议通过的《中国国民党第一次全国代表大会宜言》，对三民主义作出了新的解释，即“新三民主义”新三民主义与旧三民主义相比较，其发展表现在","options":[{"k":"A","t":"突出了反对帝国主义的内容"},{"k":"B","t":"强调了民主权利应为“一般平民所共有”"},{"k":"C","t":"概括了“平均地权”“节制资本”两大原则"},{"k":"D","t":"与中国共产党的民主革命纲领完全相同"}],"answer":["A","B","C"],"explain":"1924年召开的中国国民党一大,其主要内容有：第一,大会对三民主义作出了新的解释即“新三民主义”。①在民族主义中突出了反对帝国主义的内容；②在民权主义中强调了民主权利应为“一般平民所共有”；③把民生主义概括为“平均地权”和“节制资本”两大原则（会后不久,孙中山又提出“耕者有其田”的主张)。新三民主义的政纲同中共在民主革命阶段的纲领基本一致，因而成为国共合作的政治基础。第二，大会确认了共产党员以个人身份加入国民党的原则。第三，大会选举出中国国民党中央执行委员会。国民党一大在事实上确立了联俄、联共、扶助农工的三大革命政策,标志着第一次国共合作的正式形成。因此,正确答案是ABC。","distract":"选项D，表述错误。新三民主义与中共二大提出的民主革命纲领基本一致而非完全相同。因此，排除。","multi":true,"back":"","tags":["刷题","重点会议","多选"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"z031","type":"choice","front":"党的二大制定了民主革命的纲领,标志着党的创建工作的圆满完成,为中国人民指出了明确的斗争目标，为中国革命指明了方向。1922年7月在上海举行的中国共产党第二次全国代表大会，通过对中国社会经济政治状况的分析，揭示出中国社会的半殖民地半封建性质，指出党在这一阶段的纲领是","options":[{"k":"A","t":"消除内乱，打倒军阀，建设国内和平"},{"k":"B","t":"推翻国际帝国主义的压迫，达到中华民族完全独立"},{"k":"C","t":"统一中国为真正民主共和国"},{"k":"D","t":"实现社会主义、共产主义"}],"answer":["A","B","C"],"explain":"1922年召开的中共二大，通过了党公开发表的第一个宜言即《中国共产党宜言》，阐明了现阶段中国革命的性质、对象、动力、策略、任务和目标,指出了中国革命要分两步走,制定了党的最高纲领和最低纲领。党的最高纲领是实现社会主义、共产主义。党在现阶段的纲领(即最低纲领）是：①消除内乱，打倒军阀，建设国内和平；②推翻国际帝国主义的压迫，达到中华民族完全独立；③统一中国为真正的民主共和国。因此，正确答案是ABC。","distract":"选项D.不符合题意。“实现社会主义、共产主义”是中共二大提出的党的最高纲领。因此，排除。","multi":true,"back":"","tags":["刷题","重点会议","多选"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"z032","type":"choice","front":"1922年7月16日至23日，中国共产党第二次全国代表大会在上海举行。出席大会的代表12人，代表全国195名党员。中共二大","options":[{"k":"A","t":"首次提出了明确的反帝反封建的民主革命纲领"},{"k":"B","t":"决定共产党员以个人身份加入国民党，以实现国共合作"},{"k":"C","t":"标志着中国共产党统一战线政策的正式提出"},{"k":"D","t":"开始采取群众路线的革命方法"}],"answer":["A","C","D"],"explain":"1922年召开的中共二大的主要内容有：第一,揭示出中国社会的半殖民地半封建性质,第一次提出了反帝反封建的民主革命纲领，区分了最高纲领和最低纲领。第二，第一次提出组成“民主主义的联合战线”。这标志着中国共产党统一战线政策的正式提出。第三,开始采取群众路线的革命方法。因此,正确答案是ACD","distract":"选项B，不符合题意。1923年6月召开的中共三大，就国共合作的方针和办法作出了正式决定。大会正确地估计了孙中山的革命立场和国民党进行改组的可能性,决定共产党员以个人身份加入国民党，以实现国共合作。大会规定共产党员加入国民党时，党必须在政治上思想上组织上保持自己的独立性。因此,排除。","multi":true,"back":"","tags":["刷题","重点会议","多选"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"z033","type":"choice","front":"中国产生了共产党，这是开天辟地的大事变，深刻改变了近代以后中华民族发展的方向和进程，深刻改变了中国人民和中华民族的前途和命运，深刻改变了世界发展的趋势和格局。1921年7月23日，中国共产党第一次全国代表大会在上海法租界望志路106号开幕。中共一大","options":[{"k":"A","t":"确定党的名称为“中国共产党”，通过了中国共产党的第一个纲领和决议"},{"k":"B","t":"提出了反帝反封建的民主革命纲领"},{"k":"C","t":"在讨论党的实际工作计划时，决定集中精力组织工人"},{"k":"D","t":"开始找着了中国革命新道路"}],"answer":["A","C"],"explain":"中共一大的主要内容有：第一，大会确定党的名称为“中国共产党”，通过中国共产党的第一个纲领和决议。第二，大会在讨论党的实际工作计划时，决定集中精力组织工人。第三，大会决定设立中央局作为党的临时领导机构，选举陈独秀（书记)、张国焘、李达组成中央局。因此,正确答案是AC。","distract":"选项B，不符合题意。这是党的二大提出的。选项D,大革命失败后，以毛泽东为代表的中国共产党人才开始探索中国革命新道路。因此，排除。","multi":true,"back":"","tags":["刷题","重点会议","多选"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"z034","type":"choice","front":"1950年至1953年春，土改在新解放区进行。《中华人民共和国土地改革法》规定了这次土改的目的，是废除地主阶级封建剥削的土地所有制，实行农民的土地所有制，解放农村生产力，发展农业生产，为新中国的工业化开辟道路。与解放战争时期的土改相比，这次土改在政策上的一个大的变化是","options":[{"k":"A","t":"由对富农征收多余的土地财产改变为保存富农经济"},{"k":"B","t":"由“没收一切土地”改为“没收一切公共土地及地主阶级的土地”"},{"k":"C","t":"由实行减租减息政策改变为实现“耕者有其田”的政策"},{"k":"D","t":"由削弱封建剥削向变革封建土地关系、废除封建剥削制度过渡"}],"answer":["A"],"explain":"1950年至1953年春，土地改革在新解放区进行。土改中对待富农的政策，由解放战争时期征收富农多余土地财产的政策改变为保存富农经济的政策。A正确。将“没收一切土地”改为“没收一切公共土地及地主阶级的土地”是《兴国土地法》对《井冈山土地法》的一个原则性的改正；1946年的“五四指示”把抗日战争时期实行的减租减息政策改变为实现“耕者有其田”的政策，这一政策的提出，标志着解放区在农民土地问题上，开始由抗日战争时期的削弱封建剥削，向变革封建土地关系、废除封建剥削制度的过渡。B、C、D不符合题意。","distract":"","multi":false,"back":"","tags":["刷题","土地政策","单选"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"z035","type":"choice","front":"我国的社会主义改造是从1952年过渡时期总路线提出后全面展开的。它的主要内容是对农业、手工业、资本主义工商业进行社会主义改造。农业社会主义改造所遵循的原则是","options":[{"k":"A","t":"互助合作化"},{"k":"B","t":"自愿互利、典型示范和国家帮助"},{"k":"C","t":"积极领导、稳步前进"},{"k":"D","t":"循序渐进"}],"answer":["B"],"explain":"对农业社会主义改造采取的原则是，遵循自愿互利、典型示范和国家帮助的原则。因此正确答案是B。","distract":"","multi":false,"back":"","tags":["刷题","土地政策","单选"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"z036","type":"choice","front":"1950年6月，《中华人民共和国土地改革法》颁布。该法规定：“废除地主阶级封建剥削的土地所有制,实行农民的土地所有制,借以解放农村生产力,发展农业生产,为新中国的工业化开辟道路。”在对待富农的问题上，土地改革法提出的政策是","options":[{"k":"A","t":"征收富农多余的土地财产"},{"k":"B","t":"限制富农经济"},{"k":"C","t":"保存富农经济"},{"k":"D","t":"由限制到逐步消灭富农经济"}],"answer":["C"],"explain":"从1950年冬到1952年底,党领导广大新解放区进行了废除封建土地制度的改革。这是我国历史上规模最大,也是历次土改运动中进行得最好的一次。1950年6月,《中华人民共和国土地改革法》公布施行。该法根据全国解放后的新情况，提出保存富农经济，不动中农土地，限制没收地主财产范围等，以保护中农和分化地主阶级,减少土地改革阻力，促进生产的恢复和发展。到1952年底，除一部分少数民族地区外，土地改革在中国大陆基本完成，封建土地所有制被彻底摧毁。因此，正确答案是C。","distract":"选项A，不符合题意。征收富农多余的土地财产，是解放战争时期的政策。选项B，不符合题意。限制富农经济,是土地革命时期的政策。选项D,不符合题意。由限制到逐步消灭富农经济，是社会主义改造时期的政策。因此，排除","multi":false,"back":"","tags":["刷题","土地政策","单选"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"z037","type":"choice","front":"没收封建地主阶级的土地归农民所有，是新民主主义革命的主要内容。1948年4月，毛泽东在《在晋绥干部会议上的讲话》中明确指出：“土地改革的总路线，是依靠贫农，团结中农，有步骤地、有分别地消灭封建剥削制度,发展农业生产。”其中,土地改革的目的是","options":[{"k":"A","t":"满足贫雇农群众的要求"},{"k":"B","t":"满足某些中农的要求"},{"k":"C","t":"消灭封建剥削制度"},{"k":"D","t":"发展农业生产"}],"answer":["C"],"explain":"1948年4月，毛泽东在《在晋绥干部会议上的讲话》中明确指出：土地改革的总路线，是依靠贫农,团结中农,有步骤地、有分别地消灭封建剥削制度,发展农业生产。土地改革所依靠的基本力量，只能和必须是贫农。这个贫农阶层和雇农一起占了中国农村人口的百分之七十左右。毛泽东指出,土地改革的主要的和直接的任务,就是满足贫雇农群众的要求。土地改革的一个任务是，满足某些中农的要求。土地改革的目的是消灭封建剥削制度。发展农业生产,是土地改革的直接目的。因此，正确答案是C。","distract":"选项A、B、D，均不符合题意。因此，排除。","multi":false,"back":"","tags":["刷题","土地政策","单选"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"z038","type":"choice","front":"1946年5月4日，中共中央发出《关于土地问题的指示》（史称“五四指示”），决定将党在抗日战争时期实行的减租减息政策改变为","options":[{"k":"A","t":"“没收一切土地”的政策"},{"k":"B","t":"“保存富农经济”的政策"},{"k":"C","t":"“耕者有其田”的政策"},{"k":"D","t":"“地主不分田，富农分坏田”的政策"}],"answer":["C"],"explain":"1946年5月4日，中共中央作出《关于土地问题的指示》（史称“五四指示”），将全民族抗战时期的减租减息改变为“耕者有其田”政策（标志着解放区在农民土地问题上，开始由抗Eì的争时期的削弱封建剥削,向变革封建土地关系、废除封建剥削制度的过渡)，并指出解决解放区的土地问题是党目前最基本的历史任务。各解放区迅速开展土地改革运动。因此，正确答案是C。","distract":"选项A、B、D，均不符合题意。因此，排除。","multi":false,"back":"","tags":["刷题","土地政策","单选"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"z039","type":"choice","front":"1928年12月,毛泽东在井冈山主持制定了《井冈山土地法》,以立法的形式首次肯定了广大农民以革命的手段获得土地的权利。1929年4月，毛泽东主持制定了江西兴国县《土地法》。这部土地法对《井冈山土地法》的一个原则性纠正是","options":[{"k":"A","t":"改没收一切土地为没收一切公共土地及地主阶级的土地"},{"k":"B","t":"改土地归苏维埃政府所有为归农民自己所有"},{"k":"C","t":"改按人口平分土地为按劳动力分配土地"},{"k":"D","t":"改禁止土地买卖为农民可以自主租借买卖土地"}],"answer":["A"],"explain":"1928年12月，毛泽东在井冈山主持制定的《井冈山土地法》，首次以法律的形式否定封建土地所有制,肯定了广大农民以革命的手段获得土地的权利。但是,这部土地法也存在一些缺陷：①没收一切土地归苏维埃政府所有。②土地所有权在政府而不属农民，农民只有使用权。③禁止土地买卖。1929年4月，毛泽东主持制定了江西兴国县《土地法》，将《井冈山土地法》中规定的“没收一切土地”改为“没收一切公共土地及地主阶级的土地”。这是一个原则性的改正，保护了中农的利益不受侵犯。因此，正确答案是A。","distract":"选项B、C、D，均不符合题意。因此，排除。","multi":false,"back":"","tags":["刷题","土地政策","单选"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"z040","type":"choice","front":"近代中国半殖民地半封建社会的性质和中国革命的历史任务,决定了中国革命的性质不是无产阶级的社会主义革命，而是资产阶级民主主义革命。中国革命的基本问题是","options":[{"k":"A","t":"领导权问题"},{"k":"B","t":"分清敌友问题"},{"k":"C","t":"国家政权问题"},{"k":"D","t":"农民问题"}],"answer":["D"],"explain":"1940年，毛泽东在《新民主主义论》中指出：“中国的革命实质上是农民革命”，“农民问题，就成了中国革命的基本问题,农民的力量,是中国革命的主要力量。”农民问题是中国革命的基本问题，新民主主义革命实质上就是党领导下的农民革命，中国革命战争实质上就是党领导下的农民战争。工人阶级对农民的领导，是实现革命领导权的基础。因此，正确答案是D。","distract":"选项A，不符合题意。领导权问题，是中国革命的中心问题，是新民主主义革命理论的核心问题，也是统一战线的核心问题。选项B，不符合题意。分清敌友，是中国革命的首要问题。选项C，不符合题意。国家政权问题，是革命的根本问题。列宁指出：“一切革命的根本问题是国家政权问题。”因此，排除。","multi":false,"back":"","tags":["刷题","土地政策","单选"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"z041","type":"choice","front":"1905年11月，孙中山在中国同盟会机关报《《民报》发刊词》中，将同盟会的纲领概括为“民族主义”“民权主义”“民生主义”三大主义。在民生主义上，孙中山认为，西方资本主义发展中的诸乡社会问题,其根源在于未能解决土地问题,因此他试图探讨一种一劳永逸的办法,既使中国富强。又避免产生贫富悬殊的现象，避免社会危机。为此，孙中山主张","options":[{"k":"A","t":"中国革命必须分两步走"},{"k":"B","t":"举政治革命、社会革命毕其功于一役"},{"k":"C","t":"把民主革命和社会主义革命毕其功于一役"},{"k":"D","t":"民主革命和社会主义革命之间必须有一个资产阶级专政的阶段"}],"answer":["B"],"explain":"1905年11月，在中国同盟会机关报《《民报》发刊词》中，孙中山把同盟会的纲领概括为“民族主义”“民权主义”“民生主义”。民生主义(即社会革命),指的是“平均地权”。孙中山在《《民报》发刊词》中指出：“夫欧美社会之祸，伏之数十年，及今而后发见之，又不能使之遽去。吾国治民生主义者，发达最先，睹其祸害于未萌，诚可举政治革命、社会革命毕其功于一役。”因此，正确答案是B。","distract":"选项A,不符合题意。毛泽东指出中国革命分“两步走”：第一步是通过新民主主义革命,完成反帝反封建的任务,建立新民主主义社会;第二步是在此基础上,继续进行社会主义革命,使中国逐步过渡到社会主义社会。选项C,不符合题意。王明提出的“一次革命论”,主张把民主革命和社会主义革命\"毕基功于一役”,企图将民主革命和社会主义革命并作一步走,一步跨进社会主义，直接取得社会主义革命的胜利。其错误的根本是企图在民主革命阶段实行社会主义革命的策略和政策,从而混淆了民主革命与社会主义革命的界限。选项D,不符合题意。陈独秀提出的“二次革命论”,认为中国民主革命只能由资产阶级领导,革命胜利后建立资产阶级共和国,待资本主义发展后，无产阶级再发动第二次革命，从资产阶级手中夺取政权，建设社会主义。“二次革命论”主张中国的民主革命和社会主义革命之间必须有一个资产阶级专政的阶段。这种错误的实质是放弃无产阶级的革命领导权。因此，排除。","multi":false,"back":"","tags":["刷题","土地政策","单选"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"z042","type":"choice","front":"1931年，中国共产党在总结土地革命的经验的基础上，制定了土地革命中的阶级路线，即","options":[{"k":"A","t":"依靠贫农、雇农"},{"k":"B","t":"联合中农"},{"k":"C","t":"限制富农"},{"k":"D","t":"保护中小工商业者，消灭地主阶级"}],"answer":["A","B","C","D"],"explain":"","distract":"","multi":true,"back":"","tags":["刷题","土地政策","多选"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"z043","type":"choice","front":"毛泽东指出：“如果我们能够普遍地彻底地解决土地问题，我们就获得了足以战胜一切敌人的最基本的条件。”解放战争时期，为推动解放区土改运动进一步发展，1947年7月至9月，中国共产党在西柏坡召开全国土地会议，制定和通过了《中国土地法大纲》。土地制度改革","options":[{"k":"A","t":"是中国共产党领导广大农民从根本上摧毁中国封建制度根基的社会大变革"},{"k":"B","t":"使人民解放战争获得源源不断的人力、物力支援"},{"k":"C","t":"为打败蒋介石、建立新中国奠定了深厚的群众基础"},{"k":"D","t":"为当代中国的一切发展进步提供了根本政治保障"}],"answer":["A","B","C"],"explain":"为推动解放区土改运动进一步发展，1947年7月至9月，中国共产党在西柏坡召开全国土地会议，制定和通过了《中国土地法大纲》。《中国土地法大纲》是一个彻底反封建的土地革命纲领，它指引着在封建制度压迫下的亿万农民群众，将自己的力量汇入民主革命的洪流。经过土改运动，到1948年秋，1亿人口的解放区消灭了封建生产关系。广大农民的政治觉悟和组织程度空前提高。人民解放战争获得源源不断的人力、物力支援。土地制度改革，是中国共产党领导广大农民从根本上摧毁中国封建制度根基的社会大变革。它使占中国人口绝大多数的农民进一步认识到，中国共产党是他们自身利益的坚决维护者，因而自觉地在党的周围团结起来。这就为打败蒋介石、建立新中国奠定了深厚的群众基础。A、B、C正确。社会主义基本制度的确立为当代中国的一切发展进步提供了根本政治保障，D错误。","distract":"","multi":true,"back":"","tags":["刷题","土地政策","多选"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"z044","type":"choice","front":"人民解放军由战略防御转入战略进攻的新形势，要求在解放区更加普遍深入地开展土地制度改革，以进一步调动广大农民的革命和生产积极性，支援解放战争。1947年7月至9月，中国共产党在西柏坡召开全国土地会议，制定和通过了《中国土地法大纲》。这是一个彻底反封建的土地革命纲领。这个土地纲领明确规定","options":[{"k":"A","t":"废除封建性及半封建性剥削的土地制度，实行耕者有其田的土地制度"},{"k":"B","t":"废除地主阶级封建剥削的土地所有制，实行农民的土地所有制"},{"k":"C","t":"废除一切地主的土地所有权，废除一切乡村中在土地制度改革以前的债务"},{"k":"D","t":"乡村中一切地主的土地及公地，由乡村农会接收，按人口平均分配给无地或少地的农民"}],"answer":["A","C","D"],"explain":"1947年7—9月，在刘少奇的主持下，中共中央工委在河北省平山县召开全国土地会议，制定和通过了《中国土地法大纲》。其主要内容有：①“废除封建性及半封建性剥削的土地制度,实现耕者有其田的土地制度”。②“废除一切地主的土地所有权”，废除一切乡村中在土地制度改革以前的债务。③“乡村中一切地主的土地及公地,由乡村农会接收”,按人口平均分配给无地或少地的农民。④保护民族工商业的发展。⑤设立人民法庭。这部大纲不仅肯定和发展了1946年“五四指示”中提出的将地主土地分配给农民的原则,而且改正了其中对地主照顾过多的不彻底性,是一个彻底反封建的土地革命纲领。大纲公布后,解放区广大农村迅速掀起土地制度改革运动的热潮。因此，正确答案是ACD。","distract":"选项B，不符合题意。1950年6月颁布的《中华人民共和国土地改革法》规定：“废除地主阶级封建剥削的土地所有制,实行农民的土地所有制,借以解放农村生产力,发展农业生产，为新中国的工业化开辟道路。”因此，排除。","multi":true,"back":"","tags":["刷题","土地政策","多选"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"z045","type":"choice","front":"1937年8月，洛川会议通过的《抗日救国十大纲领》，将减租减息作为抗日战争时期解决农民问题的基本政策。1942年1月，中共中央发布的《关于抗日根据地土地政策的决定》，进一步提出“地主减租减息，农民交租交息”政策。在抗日根据地实行地主减租减息、农民交租交息的土地政策，有利于","options":[{"k":"A","t":"加强抗日根据地的政权建设"},{"k":"B","t":"提高农民抗日和生产的积极性"},{"k":"C","t":"联合地主阶级抗日"},{"k":"D","t":"巩固抗日民族统一战线"}],"answer":["B","C","D"],"explain":"1942年1月，中共中央颁布的《关于抗日根据地土地政策的决定》，提出了抗日民族统一战线的土地政策的三条基本原则：①承认农民是抗日与生产的基本力量，故应实行减租减息，借以改善农民的生活,提高农民抗日与生产的积极性。②承认地主的大多数是有抗日要求的,故于实行减租减息之后，又须实行交租交息，以便联合地主阶级一致抗日。③承认富农的生产方式带有现时中国比较进步的资本主义性质,故应奖励富农生产与联合富农。毛泽东指出：“抗日时期,中国共产党让了一大步，将‘耕者有其田’的政策，改为减租减息的政策。这个让步是正确的，推动了国民党参加抗日,又使解放区的地主减少其对我们发动农民抗日的阻力。”因此,正确答案是BCD。","distract":"选项A，不符合题意。加强政权建设是抗日根据地建设的首要的、根本的任务。根据地政权在工作人员分配上实行“三三制”原则，即共产党员、党外进步人士和中间派各占1/3。与题目意思无关。因此，排除。","multi":true,"back":"","tags":["刷题","土地政策","多选"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"z046","type":"choice","front":"随着红军和农村革命根据地的建立和发展,土地革命广泛地开展起来。在根据地内,消灭封建地主土地所有制，实现“耕者有其田”，是中国共产党在农村进行的最重大的社会变革。经过三年多的土地革命实践，1931年，毛泽东和邓子恢等一起制定了土地革命中的阶级路线和土地分配方法。其中，土地革命的土地分配方法是","options":[{"k":"A","t":"以乡为单位，按人口平分土地"},{"k":"B","t":"以劳动力为标准，能劳动者比不能劳动者多分土地一倍"},{"k":"C","t":"在原耕地的基础上，实行抽多补少、抽肥补瘦"},{"k":"D","t":"在原耕地基础上，按土地数量、质量及其位置远近，用抽补调整方法按人口统一分配"}],"answer":["A","C"],"explain":"1931年，毛泽东和邓子恢等一起制定了土地革命中的阶级路线和土地分配方法：①阶级路线：坚定地依靠贫农、雇农,联合中农,限制富农,保护中小工商业者,消灭地主阶级。②土地分配方法：以乡为单位，按人口平分土地，在原耕地的基础上，实行抽多补少、抽肥补瘦。在党的土地革命纲领和路线的指引下，根据地开展了“打土豪，分田地”的斗争，充分调动了广大农民发展生产和参军参战的积极性。因此，正确答案是AC。","distract":"选项B，不符合题意。《井冈山土地法》(1928年)规定，分配土地的数量标准：一是以人口为标准，男女老幼平均分配。二是以劳动力为标准，能劳动者比不能劳动者多分土地一倍。以上两个标准,以第一个为主体。有特殊情形的地方,得适用第二个标准。选项D,不符合题意。《中华人民共和国土地改革法》(1950年)规定：分配土地,以乡或等于乡的行政村为单位、在原耕地基础上，按土地数量、质量及其位置远近，用抽补调整方法按人口统一分配之。因此，排除。","multi":true,"back":"","tags":["刷题","土地政策","多选"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"z047","type":"choice","front":"1905年11月，孙中山在中国同盟会机关报《民报》发刊词中，把同盟会的纲领概括为“民族主义、民权主义、民生主义”（即三民主义）。其中，民生主义在当时指的是“平均地权”，也就是孙中山所说的社会革命。孙中山主张的“平均地权”是指","options":[{"k":"A","t":"废除地主阶级封建剥削的土地所有制，实行农民的土地所有制"},{"k":"B","t":"核定全国土地的地价，其现有之地价，仍属原主"},{"k":"C","t":"革命后的增价，则归国家，为国民共享"},{"k":"D","t":"在方法步骤上，主张涨价归公、按价收买"}],"answer":["B","C","D"],"explain":"三民主义中的民生主义最初指“平均地权”。1908年,孙中山在《中国同盟会革命方略》中指出，“文明之福祉，国民平等以享之。当改良社会经济组织，核定天下地价。其现有之地价，仍属原主所有；其革命后社会改良进步之增价，则归于国家，为国民所共享”。在“平均地权”的办法和步骤上,孙中山主张采取“核定地价”“照价征税”“涨价归公”“按价收买”。但是,“平均地权”的主张,没有正面触及封建土地所有制,不能满足广大农民的土地要求,在革命中难以成为发动广大工农群众的理论武器。“平均地权”是一个不彻底的资产阶级土地纲领,这种“不彻底性”主要体现在对地主阶级利益给予一定程度的保护和对封建剥削制度有所保留。因此,正确答案是BCD。","distract":"选项A，不符合题意。1950年6月颁布的《中华人民共和国土地改革法》规定，废除地主阶级封建剥削的土地所有制,实行农民的土地所有制。因此,排除。","multi":true,"back":"","tags":["刷题","土地政策","多选"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0},{"id":"z048","type":"choice","front":"太平天国运动是中国近代历史上第一次反对国内封建势力和外国侵略势力的斗争。太平天国运动是19世纪中叶中国最大的一场大规模反清运动。下列关于太平天国运动说法正确的是","options":[{"k":"A","t":"沉重打击了封建统治阶级，强烈撼动了清政府的统治根基"},{"k":"B","t":"冲击了孔子和儒家经典的正统权威，削弱了封建统治的精神支柱"},{"k":"C","t":"制定了比较完整的以解决土地问题为中心的革命纲领《天朝田亩制度》"},{"k":"D","t":"制定了中国近代史上第一个比较系统发展资本主义的方案《资政新篇》"}],"answer":["A","B","C","D"],"explain":"太平天国运动的历史意义：①沉重打击了封建统治阶级，强烈撼动了清政府的统治根基。②是中国旧式农民战争的最高峰。③冲击了孔子和儒家经典的正统权威，在一定程度上削弱了封建统治的精神支柱。④有力地打击了外国侵略势力。⑤它和19世纪中叶亚洲其他国家的民族解放运动汇合在一起,冲击了西方殖民主义者在亚洲的统治。此外,太平天国运动期间颁布的《天朝田亩制度》，比较完整地表达出了千百年来农民对拥有土地的渴望；提出的《资政新篇》是中国近代史上第一个比较系统发展资本主义的方案,反映出太平天国某些领导人试图向外国学习以寻求出路的努力。因此，正确答案是ABCD。","distract":"","multi":true,"back":"","tags":["刷题","土地政策","多选"],"st":0,"due":0,"ivl":0,"ease":2.5,"reps":0,"lapses":0,"last":0,"okN":0,"badN":0,"grad":0,"S":0,"D":0,"lastReview":0}]}];
